INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2356, 28, 633679, '5847bd02a22b9d007aad0f3c', '道德经（第二十八章）', NULL, '老子', '周', '知其雄，守其雌，为天下溪。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2357, 29, 633680, '5847bde10ce46300578d8258', '道德经（第二十九章）', NULL, '老子', '周', '将欲取天下而为之，吾见其不得已。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
