INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2360, 32, 633683, '5847bfcfac502e006bb96be5', '道德经（第三十二章）', NULL, '老子', '周', '道常无名，朴。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
