INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2378, 50, 633700, '5847d871128fe1006c603a11', '道德经（第五十章）', NULL, '老子', '周', '出生入死。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
