INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2383, 55, 633705, '5847db6a61ff4b0058a34500', '道德经（第五十五章）', NULL, '老子', '周', '含「德」之厚，比于赤子。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2384, 56, 633706, '58491fae128fe10058951639', '道德经（第五十六章）', NULL, '老子', '周', '知者不言，言者不知。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2385, 57, 633707, '5849203561ff4b006cb64360', '道德经（第五十七章）', NULL, '老子', '周', '以正治国，以奇用兵，以无事取天下，吾何以知其然哉？', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2386, 58, 633708, '584920b58e450a006aae9c2a', '道德经（第五十八章）', NULL, '老子', '周', '其政闷闷，其民淳淳；', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2387, 59, 633709, '5849212e8e450a006c4c5bec', '道德经（第五十九章）', NULL, '老子', '周', '治人事天，莫若啬。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2388, 60, 633710, '584921a58e450a006c4c5f8e', '道德经（第六十章）', NULL, '老子', '周', '治大国，若烹小鲜。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2389, 61, 633711, '584922168d6d8100543930aa', '道德经（第六十一章）', NULL, '老子', '周', '大邦者下流，天下之牝，天下之交也。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2390, 62, 633712, '5849228d8e450a006c4c6649', '道德经（第六十二章）', NULL, '老子', '周', '道者万物之奥。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2391, 63, 633713, '5849233161ff4b0058cbc5f4', '道德经（第六十三章）', NULL, '老子', '周', '为无为，事无事，味无味。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2392, 64, 633714, '584923fa128fe1006c740f08', '道德经（第六十四章）', NULL, '老子', '周', '其安易持，其未兆易谋，其脆易泮，其微易散。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2393, 65, 633715, '584925198e450a006c4c7cc6', '道德经（第六十五章）', NULL, '老子', '周', '古之善为道者，非以明民，将以愚之。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2394, 66, 633716, '58492571128fe1006c741b49', '道德经（第六十六章）', NULL, '老子', '周', '江海之所以能为百谷王者，以其善下之，故能为百谷王。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2395, 67, 633717, '584926718e450a006aaecaa7', '道德经（第六十七章）', NULL, '老子', '周', '天下皆谓我道大，似不肖。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2396, 68, 633718, '584926cb8e450a006c4c8a9d', '道德经（第六十八章）', NULL, '老子', '周', '善为士者，不武；', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2397, 70, 633721, '584927f12f301e0057172cf6', '道德经（第七十一章）', NULL, '老子', '周', '知不知，尚矣；', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2398, 72, 633722, '5849284a61ff4b006cb68968', '道德经（第七十二章）', NULL, '老子', '周', '民不畏威，则大威至。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2399, 73, 633723, '584928cd128fe10058955fd6', '道德经（第七十三章）', NULL, '老子', '周', '勇于敢则杀，勇于不敢则活。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2400, 74, 633724, '5849297d128fe100690b0ce4', '道德经（第七十四章） ', NULL, '老子', '周', '民不畏死，奈何以死惧之？', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2401, 75, 633725, '584929ddb123db0066051a0e', '道德经（第七十五章）', NULL, '老子', '周', '民之饥，以其上食税之多，是以饥。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2402, 76, 633726, '58492a462f301e0057173db0', '道德经（第七十六章）', NULL, '老子', '周', '人之生也柔弱，其死也坚强。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2403, 77, 633727, '58492ac52f301e0057174330', '道德经（第七十七章）', NULL, '老子', '周', '天之道，其犹张弓欤？', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2404, 78, 633728, '58492b7aac502e006915a903', '道德经（第七十八章）', NULL, '老子', '周', '天下莫柔弱于水，而攻坚强者莫之能胜，以其无以易之。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2405, 79, 633729, '58492bfd8d6d810054398131', '道德经（第七十九章）', NULL, '老子', '周', '和大怨，必有余怨，报怨以德，安可以为善？', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2406, 80, 633730, '58492c930ce463005c46ee07', '道德经（第八十章）', NULL, '老子', '周', '小国寡民，使有什伯之器而不用，使民重死而不远徙。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (2407, 81, 633731, '58492cf7128fe100690b2857', '道德经（第八十一章）', NULL, '老子', '周', '信言不美，美言不信。', 'wen', 81, '道德经', '', NULL, '', '', '', '');
