INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3001, 65, 95376, '585d1b561b69e60056103684', '江南旅情', NULL, '祖咏', '唐', '楚山不可极，归路但萧条。海色晴看雨，江声夜听潮。剑留南斗近，书寄北风遥。为报空潭橘，无媒寄洛桥。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3002, 66, 108710, '585d2d0b128fe10069cd15d6', '宿龙兴寺', NULL, '綦毋潜', '唐', '香刹夜忘归，松青古殿扉。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3003, 67, 10447, '57b8feb6a633bd00665d3eb0', '题破山寺后禅院', NULL, '常建', '唐', '清晨入古寺，初日照高林。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3004, 68, 101158, '585d228361ff4b006cd31b51', '题松汀驿', NULL, '张祜', '唐', '山色远含空，苍茫泽国东。海明先见日，江白迥闻风。鸟道高原去，人烟小径通。那知旧遗逸，不在五湖中。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3005, 69, 72675, '585d0364128fe1006ba12cbc', '圣果寺', NULL, '处默', '唐', '路自中峰上，盘回出薜萝。到江吴地尽，隔岸越山多。古木丛青霭，遥天浸白波。下方城郭近，钟磬杂笙歌。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3006, 70, 11113, '57b9a9a379bc4400639b9bb5', '野望', NULL, '王绩', '唐', '东皋薄暮望，徙倚欲何依。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3007, 71, 98150, '585d1f2361ff4b00580dfb76', '送著作佐郎崔融等从梁王东征', NULL, '陈子昂', '唐', '金天方肃杀，白露始专征。王师非乐战，之子慎佳兵。海气侵南部，边风扫北平。莫卖卢龙塞，归邀麟阁名。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3008, 72, 635361, '59bd2565fe88c200575be7ef', '陪诸贵公子丈八沟携妓纳凉晚际遇雨二首', NULL, '杜甫', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3009, 73, 11118, '57b9106179bc44005b9f1bb5', '秋登宣城谢脁北楼', NULL, '李白', '唐', '江城如画里，山晚望晴空。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3010, 74, 10547, '57b339db8ac247005f235d5a', '望洞庭湖赠张丞相', NULL, '孟浩然', '唐', '八月湖水平，涵虚混太清。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3011, 75, 10289, '57b997707db2a20054f79238', '过香积寺', NULL, '王维', '唐', '不知香积寺，数里入云峰。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3012, 76, 633899, '588065b9128fe10065c93bfa', '送郑侍御谪闽中', NULL, '高适', '唐', '谪去君无恨，闽中我旧过。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3013, 77, 83251, '585d0e3161ff4b00688f715e', '秦州杂诗二十首（其十九）', NULL, '杜甫', '唐', '凤林戈未息，鱼海路常难。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3014, 78, 83465, '585d0e711b69e600560fc8eb', '禹庙', NULL, '杜甫', '唐', '禹庙空山里，秋风落日斜。荒庭垂橘柚，古屋画龙蛇。云气生虚壁，江声走白沙。早知乘四载，疏凿控三巴。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3015, 79, 86575, '585d11cd128fe10069cc230c', '望秦川', NULL, '李颀', '唐', '秦川朝望迥，日出正东峰。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3016, 80, 100822, '585d2221570c3500693226f5', '同王徵君湘中有怀', NULL, '张谓', '唐', '八月洞庭秋，潇湘水北流。还家万里梦，为客五更愁。不用开书帙，偏宜上酒楼。故人京洛满，何日复同游。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3017, 81, 92111, '585d1782128fe10069cc548e', '渡扬子江', NULL, '孟浩然', '唐', '桂楫中流望，京江两畔明。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3018, 82, 142053, '585d54a41b69e60056120eae', '秋兴集古', NULL, '申佳允', '明', '明月高秋迥，徘徊只自知。凉风吹夜雨，摇荡菊花期。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3019, 83, 11165, '57b907ee128fe10054c9c240', '春日偶成', NULL, '程颢', '宋', '云淡风轻近午天，傍花随柳过前川。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3020, 84, 11033, '57b9086adf0eea0063351b26', '春日', NULL, '朱熹', '宋', '胜日寻芳泗水滨，无边光景一时新。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3021, 85, 629134, '5860fa4b128fe10069e3148d', '春宵', NULL, '苏轼', '宋', '春宵一刻值千金，花有清香月有阴。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3022, 86, 10999, '57b928855bbb50005b7976af', '城东早春', NULL, '杨巨源', '唐', '诗家清景在新春，绿柳才黄半未匀。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3023, 87, 323255, '5853da18ac502e0067df1570', '春夜', NULL, '王安石', '宋', '金炉香尽漏声残，翦翦轻风阵阵寒。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3024, 88, 11000, '57b8f0b8128fe10054c923aa', '早春呈水部张十八员外二首（其一）', NULL, '韩愈', '唐', '天街小雨润如酥，草色遥看近却无。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3025, 89, 10266, '57b902400a2b58005c924951', '元日', NULL, '王安石', '宋', '爆竹声中一岁除，春风送暖入屠苏。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3026, 90, 635561, '5a2a0e05ee920a7072fc850d', '上元侍宴', NULL, '苏轼', '宋', '淡月疏星绕建章，仙风吹下御炉香。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3027, 91, 11531, '57b96847a633bd006660fbb4', '立春偶成', NULL, '张栻', '宋', '律回岁晚冰霜少，春到人间草木知。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3028, 92, 503487, '585fc2dd1b69e6006cdae7d3', '题明王打球图', NULL, '晁说之', '宋', '阊阖千门万户开，三郎沉醉打毬回。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3029, 93, 478173, '585f86a6128fe10069da9f0b', '宫词', NULL, '王建', '唐', '金殿当头紫阁重，仙人掌上玉芙蓉。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3030, 94, 495842, '585fb051128fe1006bb13e07', '廷试', NULL, '夏竦', '宋', '殿上衮衣明日月，砚中旗影动龙蛇。纵横礼乐三千字，独对丹墀日未斜。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3031, 95, 87477, '585d12beb123db0065a758d0', '华清宫', NULL, '杜常', '宋', '行尽江南数十程，晓星残月入华清。朝元阁上西风急，都入长杨作雨声。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3032, 96, 10692, '57b93f115bbb50005b7a3a61', '清平调（其一）', NULL, '李白', '唐', '云想衣裳花想容，春风拂槛露华浓。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3033, 97, 593102, '5860931061ff4b0058215882', '题邸间壁', NULL, '郑会', '宋', '酴醾香梦怯春寒，翠掩重门燕子闲。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
