INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3110, 174, 634096, '58a661272f301e006d8d27c5', '归雁', NULL, '钱起', '唐', '潇湘何事等闲回？', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3111, 175, 635565, '5a2a13912f301e0063263e0e', '题壁', NULL, '无名氏', '宋', '一团茅草乱蓬蓬，蓦地烧天蓦地空。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3112, 176, 107512, '585d2b5261ff4b0063f1bc9c', '早朝大明宫呈两省僚友', NULL, '贾至', '唐', '银烛熏天紫陌长，禁城春色晓苍苍。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3113, 177, 83765, '585d0ed861ff4b00580d6da9', '奉和贾至舍人早朝大明宫', NULL, '杜甫', '唐', '五夜漏声催晓箭，九重春色醉仙桃。旌旗日暖龙蛇动，宫殿风微燕雀高。朝罢香烟携满袖，诗成珠玉在挥毫。欲知世掌丝纶美，池上于今有凤毛。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3114, 178, 10594, '57b9c0f35bbb500063f62a18', '和贾至舍人早朝大明宫之作', NULL, '王维', '唐', '绛帻鸡人报晓筹，尚衣方进翠云裘。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3115, 179, 10595, '57ba773ba633bd005d33e592', '奉和中书舍人贾至早朝大明宫', NULL, '岑参', '唐', '鸡鸣紫陌曙光寒，莺啭皇州春色阑。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3116, 180, 587892, '586086a9128fe10069dfb558', '上元应制', NULL, '蔡襄', '宋', '高列千峰宝炬森，端门方喜翠华临。宸游不为三元夜，乐事还同万众心。天上清光留此夕，人间和气阁春阴。要知尽庆华封祝，四十余年惠爱深。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3117, 181, 635566, '5a2a14fb2f301e006326460d', '上元应制', NULL, '王珪', '宋', '雪消华月满仙台，万烛当楼宝扇开。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3118, 182, 91448, '585d16c6da2f600065843ae7', '侍宴安乐公主新宅应制', NULL, '沈佺期', '唐', '皇家贵主好神仙，别业初开云汉边。山出尽如鸣凤岭，池成不让饮龙川。妆楼翠幌教春住，舞阁金铺借日悬。敬从乘舆来此地，称觞献寿乐钧天。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3119, 183, 11894, '58030e132e958a0055d5177f', '戏答元珍/答丁元珍', NULL, '欧阳修', '宋', '春风疑不到天涯，二月山城未见花。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3120, 184, 469108, '585f73aa570c3500693f83a6', '插花吟', NULL, '邵雍', '宋', '头上花枝照酒卮，酒卮中有好花枝。身经两世太平日，眼见四朝全盛时。况复筋骸粗康健，那堪时节正芳菲。酒涵花影红光溜，争忍花前不醉归。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3121, 185, 633942, '588887728d6d81006cfcdd9a', '无题', NULL, '晏殊', '宋', '油壁香车不再逢，峡云无迹任西东。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3122, 186, 11236, '57c2f59b6be3ff00583b177c', '寒食', NULL, '赵鼎', '宋', '寂寂柴门村落里，也教插柳记年华。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3123, 187, 12431, '585cc2b061ff4b006cd01591', '清明', NULL, '黄庭坚', '宋', '佳节清明桃李笑，野田荒冢只生愁。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3124, 188, 12423, '581f4a2a0ce46300588fc547', '清明日对酒', NULL, '高翥', '宋', '南北山头多墓田，清明祭扫各纷然。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3125, 189, 11240, '57c1a4c4c4c971006185cc74', '郊行即事', NULL, '程颢', '宋', '芳原绿野恣行时，春入遥山碧四围。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3126, 190, 635567, '5a2a15bc1579a30062d4b02c', '秋千', NULL, '释惠洪', '宋', '画架双裁翠络偏，佳人春戏小楼前。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3127, 191, 83761, '584ce879128fe1006c88349c', '曲江二首（其一）', NULL, '杜甫', '唐', '一片花飞减却春，风飘万点正愁人。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3128, 192, 83762, '584ce87a128fe10058a96a4b', '曲江二首（其二）', NULL, '杜甫', '唐', '朝回日日典春衣，每日江头尽醉归。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3129, 193, 10350, '57b8f0915bbb50005b77bd38', '黄鹤楼', NULL, '崔颢', '唐', '昔人已乘黄鹤去，此地空余黄鹤楼。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3130, 194, 11991, '580aee9c67f3560057aeb721', '春夕', NULL, '崔涂', '唐', '水流花谢两无情，送尽东风过楚城。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3131, 195, 10613, '57b97867165abd0054c42321', '寄李儋元锡', NULL, '韦应物', '唐', '去年花里逢君别，今日花开又一年。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3132, 196, 11179, '57b8de6aa633bd00665c9a87', '江村', NULL, '杜甫', '唐', '清江一曲抱村流，长夏江村事事幽。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3133, 197, 537443, '58600fe5b123db0065b9502e', '夏日三首（其一）', NULL, '张耒', '宋', '长夏村墟风日清，檐牙燕雀已生成。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3134, 198, 10597, '57b90862df0eea0063351ae2', '积雨辋川庄作', NULL, '王维', '唐', '积雨空林烟火迟，蒸藜炊黍饷东菑。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3135, 199, 523913, '585ff16c128fe1006df7a18e', '东湖新竹', NULL, '陆游', '宋', '插棘编篱谨护持，养成寒碧映沦漪。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3136, 200, 633797, '5860db3eac502e006738210e', '秋日偶成', NULL, '程颢', '宋', '闲来无事不从容，睡觉东窗日已红。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3137, 201, 117786, '585d3966128fe1006ba3021e', '夏夜宿表兄话旧', NULL, '窦叔向', '唐', '夜合花开香满庭，夜深微雨醉初醒。远书珍重何曾达，旧事凄凉不可听。去日儿童皆长大，昔年亲友半凋零。明朝又是孤舟别，愁见河桥酒幔青。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3138, 202, 562318, '586045e9128fe1006df879c7', '游月陂', NULL, '程颢', '宋', '月陂堤上四徘徊，北有中天百尺台。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3139, 203, 633764, '58591614128fe1006dcdadff', '秋兴八首', NULL, '杜甫', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3140, 204, 136035, '585d4e338d6d810065def41a', '月夜泛舟', NULL, '王元俸', '明', '满船明月浸虚空，荡漾清光一望同。半世行藏浑是梦，十年尘事只如风。参差草色迷蓑艇，狼藉蘋花上钓筒。添得五湖多少恨，夕阳江上正飞鸿。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3141, 205, 11111, '57b92cd0d342d3005ac89c9a', '长安晚秋', NULL, '赵嘏', '唐', '云物凄清拂曙流，汉家宫阙动高秋。', 'shi', 103, '千家诗', '', NULL, '', '', '', '');
