INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3373, 8, 91757, '585d171e128fe1006de625bc', '元次山居武昌之樊山', NULL, '孟彦深', '唐', '江山十日雪，雪深江雾浓。起来望樊山，但见群玉峰。林莺却不语，野兽翻有踪。山中应大寒，短褐何以完。皓气凝书帐，清著钓鱼竿。怀君欲进谒，溪滑渡舟难。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3375, 10, 226657, '585dbb4a128fe1006ba4e671', '答黄少府', NULL, '陶益', '明', '烟钓汀栖鹤梦遥，频年虚负小山招。只嫌叔度稀相见，鄙吝而今转不消。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3376, 11, 98760, '585d1fae128fe1006de672c6', '晚登虔州即事寄李侍御', NULL, '耿湋', '唐', '章溪与贡水，何事会波澜。万里归人少，孤舟行路难。春光浮曲浪，暮色隔连滩。花发从南早，江流向北宽。故交参盛府，新角耸危冠。楚剑期终割，隋珠惜未弹。酒醒愁转极，别远泪初干。愿保乔松质，青青过大寒。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3421, 13, 325223, '585e52c561ff4b006cda1cd7', '减字木兰花 · 春情', NULL, '王安国', '宋', '画桥流水，雨湿落红飞不起。', 'ci', 107, '白香词谱', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3422, 14, 438741, '585f23e28d6d810065e8ae64', '丑奴儿 · 春暮', NULL, '朱藻', '宋', '障泥油壁人归后，满院花阴，楼影沈沈，中有伤春一片心。', 'ci', 107, '白香词谱', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (3377, 12, 73449, '585d042861ff4b00580d17ef', '顾渚行寄裴方舟', NULL, '皎然', '唐', '我有云泉邻渚山，山中茶事颇相关。鶗鴂鸣时芳草死，山家渐欲收茶子。伯劳飞日芳草滋，山僧又是采茶时。繇来惯采无近远，阴岭长兮阳崖浅。大寒山下叶未生，小寒山中叶初卷。吴婉携笼上翠微，蒙蒙香㓨罥春衣。迷山乍被落花乱，度水时惊啼鸟飞。家园不远乘露摘，归时露彩犹滴沥。初看怕出欺玉英，更取煎来胜金液。昨夜西峰雨色过，朝寻新茗复如何。女宫露涩青芽老，尧市人稀紫笋多。紫笋青芽谁得识，日暮采之长太息。清泠真人待子元，贮此芳香思何极。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
