INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4074, 17, 636611, '5ab357482f301e1c2c2ac86b', '人间词话 ·  第十七则', NULL, '王国维', '清', '客观之诗人不可不多阅世，阅世愈深则材料愈丰富、愈变化，《水浒传》、《红楼梦》之作者是也。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4075, 18, 636612, '5ab3576e9f545437fe8712f0', '人间词话 ·  第十八则', NULL, '王国维', '清', '尼采谓：“一切文学，余爱以血书者。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4076, 19, 636613, '5ab357919f54541d2c3aa1d4', '人间词话 ·  第十九则', NULL, '王国维', '清', '冯正中词虽不失五代风格，而堂庑特大，开北宋一代风气。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4077, 20, 636614, '5ab357bf9f54543687b171d2', '人间词话 ·  第二十则', NULL, '王国维', '清', '正中词除《鹊踏枝》、《菩萨蛮》十数阕最煊赫外，如《醉花间》之“高树鹊衔巢，斜月明寒草”，余谓韦苏州之“流萤渡高阁”，孟襄阳之“疏雨滴梧桐”不能过也。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4078, 21, 636615, '5ab357e22f301e1c2c2acccc', '人间词话 ·  第二十一则', NULL, '王国维', '清', '欧九《浣溪沙》词“绿杨楼外出秋千”，晁补之谓只一“出”字，便后人所不能道。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4079, 22, 636616, '5ab3580f9f54543b189d5623', '人间词话 ·  第二十二则', NULL, '王国维', '清', '梅圣俞《苏幕遮》词：“落尽梨花春又了。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4080, 23, 636617, '5ab3583f2f301e1c2c2aced6', '人间词话 ·  第二十三则', NULL, '王国维', '清', '人知和靖《点绛唇》、圣俞《苏幕遮》、永叔《少年游》三阕为咏春草绝调，不知先有正中“细雨湿流光”五字，皆能摄春草之魂者也。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4081, 24, 636618, '5ab358872f301e1c2c2ad04d', '人间词话 ·  第二十四则', NULL, '王国维', '清', '《诗 · 蒹葭》一篇最得风人深致。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4082, 25, 636619, '5ab3596d9f54541d2c3aad20', '人间词话 ·  第二十五则', NULL, '王国维', '清', '“我瞻四方，蹙蹙靡所骋。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4083, 26, 636620, '5ab359dd9f54543687b17e3c', '人间词话 ·  第二十六则', NULL, '王国维', '清', '古今之成大事业、大学问者，必经过三种之境界。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4084, 27, 636621, '5ab35a1675657116a3a0ac8d', '人间词话 ·  第二十七则', NULL, '王国维', '清', '永叔“人生自是有情痴，此恨不关风与月”，“直须看尽洛城花，始与东风容易别”，于豪放之中有沉著之致，所以尤高。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4085, 28, 636622, '5ab35a33ee920a396f19e86d', '人间词话 ·  第二十八则', NULL, '王国维', '清', '冯梦华《宋六十一家词选·序例》谓：「淮海、小山，古之伤心人也，其淡语皆有味，浅语皆有致。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4086, 29, 636623, '5ab35a5c9f54541d2c3ab31c', '人间词话 ·  第二十九则', NULL, '王国维', '清', '少游词境最凄婉。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4087, 30, 636624, '5ab35a7fac502e57c93a5569', '人间词话 ·  第三十则', NULL, '王国维', '清', '“风雨如晦，鸡鸣不已”，“山峻高以蔽日兮，下幽晦以多雨。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4088, 31, 636631, '5ab4ac7017d009688770af0c', '人间词话 ·  第三十一则', NULL, '王国维', '清', '昭明太子称陶渊明诗“跌宕昭彰，独超众类。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4089, 32, 636632, '5ab4ac8e9f54541d2c425107', '人间词话 ·  第三十二则', NULL, '王国维', '清', '词之《雅》、《郑》，在神不在貌。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4090, 33, 636633, '5ab4aca8ee920a396f2198ed', '人间词话 ·  第三十三则', NULL, '王国维', '清', '美成深远之致不及欧、秦，唯言情体物，穷极工巧，故不失为一流之作者。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4091, 34, 636634, '5ab4acdb9f54543687b935d4', '人间词话 ·  第三十四则', NULL, '王国维', '清', '词忌用替代字。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4092, 35, 636635, '5ab4ad04ee920a396f219b07', '人间词话 ·  第三十五则', NULL, '王国维', '清', '沈伯时《乐府指迷》云：“说桃不可直说破桃，须用‘红雨’、‘刘郎’等字。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4093, 36, 636636, '5ab4ad229f54541326cdc16d', '人间词话 ·  第三十六则', NULL, '王国维', '清', '美成《苏幕遮》词：“叶上初阳干宿雨。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4094, 37, 636637, '5ab4ad429f545437fe8ec4e4', '人间词话 ·  第三十七则', NULL, '王国维', '清', '东坡《水龙吟·咏杨花》，和韵而似原唱。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4095, 38, 636638, '5ab4ad6fac502e57c942117a', '人间词话 ·  第三十八则', NULL, '王国维', '清', '咏物之词，自以东坡《水龙吟》为最工，邦卿《双双燕》次之。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4096, 39, 636639, '5ab4ad99756571108cd8a842', '人间词话 ·  第三十九则', NULL, '王国维', '清', '白石写景之作，如「二十四桥仍在，波心荡、冷月无声」，「数峰清苦，商略黄昏雨」，「高树晚蝉，说西风消息」，虽格韵高绝，然如雾里看花，终隔一层。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4097, 40, 636640, '5ab4adc9ac502e57c942139e', '人间词话 ·  第四十则', NULL, '王国维', '清', '问“隔”与“不隔”之别，曰：陶、谢之诗不隔，延年则稍隔矣。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4098, 41, 636641, '5ab4ae019f54541326cdc82d', '人间词话 ·  第四十一则', NULL, '王国维', '清', '“生年不满百，常怀千岁忧。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4099, 42, 636642, '5ab4ae299f545437fe8ecdeb', '人间词话 ·  第四十二则', NULL, '王国维', '清', '古今词人格调之高，无如白石。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4100, 43, 636643, '5ab4ae4544d90418a220b74f', '人间词话 ·  第四十三则', NULL, '王国维', '清', '南宋词人，白石有格而无情，剑南有气而乏韵。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4101, 44, 636644, '5ab4ae5f17d009688770bb27', '人间词话 ·  第四十四则', NULL, '王国维', '清', '东坡之词旷，稼轩之词豪。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4102, 45, 636645, '5ab4ae792f301e1c2c328bc1', '人间词话 ·  第四十五则', NULL, '王国维', '清', '读东坡、稼轩词，须观其雅量高致，有伯夷、柳下惠之风。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4302, 97, 10036, '57b8e22c79bc44005b9df7ef', '桃花源记', NULL, '陶渊明', '晋', '晋太元中，武陵人捕鱼为业。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4103, 46, 636668, '5ab5d6f99f54543687bf9590', '人间词话 · 第四十六则', NULL, '王国维', '清', '苏、辛词中之狂，白石犹不失为狷，若梦窗、梅溪、玉田、草窗、中麓辈，面目不同，同归于乡愿而已。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4104, 47, 636669, '5ab5d71a9f545437fe951341', '人间词话 · 第四十七则', NULL, '王国维', '清', '稼轩中秋饮酒达旦，用《天问》体作《木兰花慢》以送月，曰：“可怜今夕月，向何处、去悠悠？', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4105, 48, 636670, '5ab5d7429f54543b18ab4fdb', '人间词话 · 第四十八则', NULL, '王国维', '清', '周介存谓“梅溪词中喜用‘偷’字，足以定其品格。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4106, 49, 636671, '5ab5d76844d90418a2270c2f', '人间词话 · 第四十九则', NULL, '王国维', '清', '介存谓梦窗词之佳者，如“水光云影，摇荡绿波，抚玩无极，追寻已远。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4107, 50, 636672, '5ab5d78cee920a396f27ffa4', '人间词话 · 第五十则', NULL, '王国维', '清', '梦窗之词，吾得取其词中之一语以评之，曰：“映梦窗凌乱碧。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4109, 51, 636673, '5ab5d7ba44d90418a2270e06', '人间词话 · 第五十一则', NULL, '王国维', '清', '“明月照积雪”、“大江流日夜”、“中天悬明月”、“长河落日圆”，此种境界，可谓千古壮观。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4110, 52, 636674, '5ab5d7d69f545437fe951847', '人间词话 · 第五十二则', NULL, '王国维', '清', '纳兰容若以自然之眼观物，以自然之舌言情。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4111, 53, 636675, '5ab5d7faac502e57c94880ac', '人间词话 · 第五十三则', NULL, '王国维', '清', '陆放翁跋《花间集》，谓：“唐季五代，诗愈卑，而倚声者辄简古可爱。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4112, 54, 636676, '5ab5d81d756571108cdf09f6', '人间词话 · 第五十四则', NULL, '王国维', '清', '四言敝而有《楚辞》，《楚辞》敝而有五言，五言敝而有七言，古诗敝而有律绝，律绝敝而有词。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4113, 55, 636677, '5ab5d83c9f54543687bf9d8b', '人间词话 · 第五十五则', NULL, '王国维', '清', '诗之三百篇、十九首，词之五代、北宋，皆无题也。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4114, 56, 636678, '5ab5d85c9f54543687bf9e61', '人间词话 · 第五十六则', NULL, '王国维', '清', '大家之作，其言情也必沁人心脾，其写景也必豁人耳目，其词脱口而出，无矫揉妆束之态。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4115, 57, 636679, '5ab5d8749f545437fe951c1c', '人间词话 · 第五十七则', NULL, '王国维', '清', '人能于诗词中不为美刺投赠之篇，不使隶事之句，不用粉饰之字，则于此道已过半矣。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4116, 58, 636680, '5ab5d89717d0096887772a1f', '人间词话 · 第五十八则', NULL, '王国维', '清', '以《长恨歌》之壮采，而所隶之事，只“小玉双成”四字，才有余也。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4117, 59, 636681, '5ab5d8df9f54547d1c411c8f', '人间词话 · 第五十九则', NULL, '王国维', '清', '近体诗体制，以五七言绝句为最尊，律诗次之，排律最下。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4118, 60, 636682, '5ab5d90317d0096887772d20', '人间词话 · 第六十则', NULL, '王国维', '清', '诗人对宇宙人生，须入乎其内，又须出乎其外。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4119, 61, 636683, '5ab5d937ee920a396f280b1b', '人间词话 · 第六十一则', NULL, '王国维', '清', '诗人必有轻视外物之意，故能以奴仆命风月。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4120, 62, 636684, '5ab5d96217d0096887773009', '人间词话 · 第六十二则', NULL, '王国维', '清', '“昔为倡家女，今为荡子妇。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4121, 63, 636685, '5ab5d98a9f54543b18ab5f54', '人间词话 · 第六十三则', NULL, '王国维', '清', '“枯藤老树昏鸦。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4122, 64, 636686, '5ab5d9ac9f54541326d42de1', '人间词话 · 第六十四则', NULL, '王国维', '清', '白仁甫《秋夜梧桐雨》剧，沉雄悲壮，为元曲冠冕。', 'wen', 113, '人间词话', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4125, 46, 636747, '5ab8b01c17d0096887875d83', '双调 · 蟾宫曲', NULL, '卢挚', '元', '沙三伴哥来嗏！', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4126, 198, 70577, '585d0177570c350069311477', '双调 · 寿阳曲 · 答卢疏斋', NULL, '朱帘秀', '元', '山无数，烟万缕。', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
