INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4134, 201, 636755, '5ab8b54c9f54543687d006b5', '双调 · 折桂令', NULL, '鲜于必仁', '宋', '【芦沟晓月】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4135, 64, 636756, '5ab8b5aeac502e57c9590368', '正宫 · 塞鸿秋', NULL, '张养浩', '元', '春来时香雪梨花会，夏来时云锦荷花会，秋来时霜露黄花会，冬来时风月梅花会。', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4136, 203, 63575, '585cfb0e61ff4b006cd1da95', '正宫 · 塞鸿秋', NULL, '郑光祖', '元', '门前五柳侵江路，庄儿紧依白萍渡。', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4138, 206, 636758, '5ab8b70f9f5454477967b2a8', '中吕 · 山坡羊 · 讥时', NULL, '曾瑞', '元', '繁花春尽，穷途人困，太平分的清闲运。', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4139, 205, 635518, '5a19ab1617d00900638823d7', '南吕 · 骂玉郎过感皇恩采茶歌  · 闺中闻杜鹃', NULL, '曾瑞', '元', '【闺情】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4156, 35, 636808, '5abc98839f54540038d1e2a4', '国语 · 祭公谏征犬戎', NULL, '左丘明', '周', '穆王将征犬戎，祭公谋父谏曰：“不可。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4157, 36, 636814, '5abc9c019f545400443ab274', '国语 ·  邵公谏厉王弭谤', NULL, '左丘明', '周', '厉王虐，国人谤王。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4158, 37, 636812, '5abc9b229f5454003875e6b3', '国语 ·  襄王不许请隧', NULL, '左丘明', '周', '晋文公既定襄王于郏，王劳之以地，辞，请隧焉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4159, 38, 636809, '5abc9a4fa22b9d0045286f0b', '国语 ·  单子知陈必亡', NULL, '左丘明', '周', '定王使单襄公聘于宋。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4160, 39, 636810, '5abc9a87ac502e006399b4c4', '国语 ·  展禽论祀爰居', NULL, '左丘明', '周', '海鸟曰“爰居”，止于鲁东门之外二日。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4161, 40, 636811, '5abc9ab9ee920a0045f479f0', '国语 ·  里革断罟匡君', NULL, '左丘明', '周', '宣公夏滥于泗渊，里革断其罟而弃之，曰：“古者大寒降，土蛰发，水虞于是乎讲罛罶，取名鱼，登川禽，而尝之寝庙，行诸国，助宣气也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4162, 41, 636815, '5abc9c5b9f54540038d1fb72', '国语 ·  敬姜论劳逸', NULL, '左丘明', '周', '公父文伯退朝，朝其母，其母方绩，文伯曰：“以歜之家而主犹绩，惧干季孙之怒也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4163, 42, 636816, '5abc9cdc9f545400459aec12', '国语 ·  叔向贺贫', NULL, '左丘明', '周', '叔向见韩宣子，宣子忧贫，叔向贺之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4164, 43, 636817, '5abc9cfe2f301e0065e0622e', '国语 ·  王孙圉论楚宝', NULL, '左丘明', '周', '王孙圉聘于晋，定公飨之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4165, 44, 636818, '5abc9d269f5454003875f630', '国语 ·  诸稽郢行成于吴', NULL, '左丘明', '周', '吴王夫差起师伐越，越王勾践起师逆之江。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4166, 45, 636819, '5abc9d3f9f54540038d2013c', '国语 ·  申胥谏许越成', NULL, '左丘明', '周', '吴王夫差乃告诸大夫曰：“孤将有大志于齐，吾将许越成，而无拂吾虑。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4167, 46, 636820, '5abc9ef217d009006144146d', '公羊传 · 春王正月', NULL, '公羊高', '秦', '元年者何？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4168, 47, 633846, '586e4c371b69e6006307b608', '公羊传  ·  宋人及楚人平', NULL, '公羊高', '秦', '“宋人及楚人平”INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4169, 48, 636822, '5abc9f8e17d00900614418fb', '公羊传 · 吴子使札来聘', NULL, '公羊高', '秦', '吴无君，无大夫，此何以有君，有大夫？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4170, 49, 636823, '5abca0b99f54540038760dd3', '穀梁传 · 郑伯克段于鄢', NULL, '穀梁子', '周', '克者何？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4171, 50, 636844, '5abde61517d00900614b3a20', '穀梁传 · 虞师晋师灭夏阳', NULL, '穀梁子', '周', '非国而曰灭，重夏阳也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4172, 51, 636845, '5abde7052f301e0065e7b6c2', '礼记 · 檀弓 · 晋献公杀世子申生', NULL, '无名氏', '秦', '晋献公将杀其世子申生，公子重耳谓之曰：「子盍言子之志于公乎？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4173, 52, 636846, '5abde7419f54540045a23249', '礼记 · 檀弓 · 曾子易箦', NULL, '无名氏', '秦', '曾子寝疾，病。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4174, 53, 636847, '5abde7cba22b9d00452fd688', '礼记 · 檀弓 · 有子之言似夫子', NULL, '无名氏', '秦', '有子问于曾子曰：「问丧于夫子乎？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4175, 54, 636848, '5abde861a22b9d00452fdb01', '礼记 · 檀弓 · 公子重耳对秦客', NULL, '无名氏', '秦', '晋献公之丧，秦穆公使人吊公子重耳，且曰：「寡人闻之，亡国恒于斯，得国恒于斯。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4176, 55, 636849, '5abde89fee920a0045fbf729', '礼记 · 檀弓 · 杜蒉扬觯', NULL, '无名氏', '秦', '知悼子卒，未葬．平公饮酒，师旷、李调侍，鼓钟。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4177, 56, 636850, '5abde8da4773f7005d3b3ffd', '礼记 · 檀弓 · 晋献文子成室', NULL, '无名氏', '秦', '晋献文子成室，晋大夫发焉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4178, 1, 636733, '5ab89b80ac502e57c95803dc', '圆觉经 · 序分', NULL, '释迦牟尼', '周', '如是我闻。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4179, 2, 636279, '5aab6ebf75657116a373a394', '圆觉经 · 文殊师利菩萨', NULL, '释迦牟尼', '周', '于是文殊师利菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，愿为此会诸来法众，说于如来本起清净因地法行，及说菩萨于大乘中发清净心，远离诸病，能使未来末世众生求大乘者，不堕邪见。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4180, 3, 636280, '5aab6ef19f545448cf255b66', '圆觉经 · 普贤菩萨', NULL, '释迦牟尼', '周', '于是普贤菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：”大悲世尊，愿为此会诸菩萨众，及为末世一切众生修大乘者，闻此圆觉清净境界，云何修行？', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4181, 4, 636281, '5aab6f2aa22b9d0045af44cd', '圆觉经 · 普贤菩萨', NULL, '释迦牟尼', '周', '于是普贤菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：「大悲世尊，愿为此会诸菩萨众，及为末世一切众生，演说菩萨修行渐次，云何思惟？', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4182, 5, 636282, '5aab6f569f54543cc8dee208', '圆觉经 · 金刚藏菩萨', NULL, '释迦牟尼', '周', '于是金刚藏菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，善为一切诸菩萨众，宣扬如来圆觉清净大陀罗尼，因地法行，渐次方便，与诸众生开发蒙昧。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4183, 6, 636283, '5aab6f7d17d00968873c295c', '圆觉经 · 弥勒菩萨', NULL, '释迦牟尼', '周', '于是弥勒菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，广为菩萨开秘密藏，令诸大众深悟轮回，分别邪正，能施末世一切众生无畏道眼，于大涅槃生决定信，无复重随轮转境界，起循环见。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4184, 7, 636284, '5aab6fa49f54543cc8dee3b6', '圆觉经 · 清净慧菩萨', NULL, '释迦牟尼', '周', '于是清净慧菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，为我等辈广说如是不思议事，本所不见，本所不闻。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4185, 1, 636852, '5abf1d329f54541656d861d1', '山海经 · 山经 · 南山经', NULL, '无名氏', '周', '南山经之首曰鹊山。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4186, 2, 636853, '5abf1e7e9f54541656d86a0c', '山海经 · 山经 · 西山经', NULL, '无名氏', '周', '西山经华山之首，曰钱来之山，其上多松，其下多洗石。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4187, 3, 636854, '5abf203117d0090061526b73', '山海经 · 山经 · 北山经', NULL, '无名氏', '周', '北山经之首，曰单狐之山，多机木，其上多华草。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4188, 4, 636855, '5abf22039f545433515b0b01', '山海经 · 山经 · 东山经', NULL, '无名氏', '周', '东山之首，曰樕?之山。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4189, 5, 636856, '5abf237b7565710045a396bf', '山海经 · 山经 · 中山经', NULL, '无名氏', '周', '中山经薄山之首，曰甘枣之山，共水出焉，而西流注于河。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4191, 7, 636862, '5abf26d1ac502e0063a83f2a', '山海经 · 海经 · 海内西经', NULL, '无名氏', '周', '海内西南陬以北者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4193, 9, 636864, '5abf277cee920a0045031f87', '山海经 · 海经 · 海内东经', NULL, '无名氏', '周', '海内东北陬以南者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4194, 6, 636861, '5abf26539f54540038848769', '山海经 · 海经 · 海内南经', NULL, '无名氏', '周', '海内东南陬以西者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4195, 8, 636863, '5abf27259f54543001f86056', '山海经 · 海经 · 海内北经 ', NULL, '无名氏', '周', '海内西北陬以东者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4196, 10, 636857, '5abf24209f545400388477bb', '山海经 · 海经 · 海外南经', NULL, '无名氏', '周', '地之所载，六合之间，四海之内，照之以日月，经之以星辰，纪之以四时，要之以太岁，神灵所生，其物异形，或天或寿，唯圣人能通其道。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4197, 11, 636858, '5abf24d14773f7005d425487', '山海经 · 海经 · 海外西经', NULL, '无名氏', '周', '海外自西南陬西北陬者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4198, 12, 636859, '5abf25772f301e0065eefbe5', '山海经 · 海经 · 海外北经', NULL, '无名氏', '周', '海外自东北陬至西北陬者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4199, 13, 636860, '5abf25ff9f545433515b2684', '山海经 · 海经 · 海外东经', NULL, '无名氏', '周', '海外自东南陬至东北陬者。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4200, 15, 636866, '5abf28679f54543001f86888', '山海经 · 海经 · 大荒南经', NULL, '无名氏', '周', '南海之外，赤水之西，流沙之东，有兽，左右有首，名曰䟣踢。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4201, 16, 636867, '5abf28d9a22b9d0045371dca', '山海经 · 海经 · 大荒西经', NULL, '无名氏', '周', '西北海之外，大荒之隅，有山而不合，名曰不周负子，有两黄兽守之。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4202, 17, 636868, '5abf295c9f54543001f86e6c', '山海经 · 海经 · 大荒北经', NULL, '无名氏', '周', '东北海之外，大荒之中，河水之间，附禺之山，帝颛顼与九嫔葬焉。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4203, 14, 636865, '5abf27ff9f545433515b33be', '山海经 · 海经 · 大荒东经', NULL, '无名氏', '周', '东海之外大壑，少昊之国。', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4204, 18, 636869, '5abf29c8ac502e0063a853f7', '山海经 · 海经 · 海内经 ', NULL, '无名氏', '周', '东海之内，北海之隅，有国名曰朝鲜；', 'wen', 146, '山海经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4205, 57, 12044, '581197e5128fe1005ff3bf32', '战国策 · 苏秦以连横说秦', NULL, '刘向', '汉', '苏秦始将连横，说秦惠王曰：「大王之国，西有巴、蜀、汉中之利，北有胡貉、代马之用，南有巫山、黔中之限，东有肴、函之固。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4206, 58, 636871, '5abf2c3b17d009006152be70', '战国策 · 司马错论伐蜀', NULL, '刘向', '汉', '司马错与张仪争论于秦惠王前，司马错欲伐蜀，张仪曰：“不如伐韩。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4207, 59, 12046, '581197eb2e958a0055249bd5', '战国策 · 范雎说秦王', NULL, '刘向', '汉', '范雎至秦，王庭迎，谓范雎曰：“寡人宜以身受令久矣。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4208, 60, 12047, '581197eda0bb9f0061dfe27e', '战国策 · 邹忌讽齐王纳谏', NULL, '刘向', '汉', '邹忌修八尺有余，而形貌昳丽。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4209, 61, 633854, '587082fb61ff4b005c3a4fda', '战国策 · 齐宣王见颜斶', NULL, '刘向', '汉', '齐宣王见颜斶，曰：“斶前！', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4210, 62, 12048, '581197f1128fe1005ff3bf81', '战国策 · 冯谖客孟尝君', NULL, '刘向', '汉', '齐人有冯谖者，贫乏不能自存，使人属孟尝君，愿寄食门下。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4211, 63, 636873, '5abf2e06ac502e0063a872c8', '战国策 · 赵威后问齐使', NULL, '刘向', '汉', '齐王使使者问赵威后。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4212, 64, 635144, '595d17f8ac502e7589e56da2', '战国策 · 庄辛论幸臣', NULL, '刘向', '汉', '「臣闻鄙语曰：『见兔而顾犬，未为晚也；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4213, 65, 12049, '581197f62f301e005c5d318b', '战国策 · 触龙说赵太后', NULL, '刘向', '汉', '赵太后新用事，秦急攻之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4214, 66, 636874, '5abf2e74ac502e0063a875a4', '战国策 · 鲁仲连义不帝秦', NULL, '刘向', '汉', '秦围赵之邯郸，魏安釐王使将军晋鄙救赵，畏秦，止于荡阴，不进。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4215, 67, 633841, '586e15ae8d6d8100586d36e0', '战国策 · 鲁共公择言', NULL, '刘向', '汉', '梁王魏婴觞诸侯于范台。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4216, 68, 12061, '5812fbe5da2f60005db18e70', '战国策 · 唐雎说信陵君', NULL, '刘向', '汉', '信陵君杀晋鄙，救邯郸，破秦人，存赵国，赵王自郊迎。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4217, 69, 12050, '581197fabf22ec005848aaca', '战国策 · 唐雎不辱使命', NULL, '刘向', '汉', '秦王使人谓安陵君曰：“寡人欲以五百里之地易安陵，安陵君其许寡人！', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4218, 70, 12051, '581197fd0ce4630031a2b930', '战国策 · 乐毅报燕王书', NULL, '刘向', '汉', '臣不佞，不能奉承先王之教，以顺左右之心，恐抵斧质之罪，以伤先王之明，而又害于足下之义，故遁逃奔赵。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4219, 71, 11887, '57ffd31a128fe10054900425', '谏逐客书', NULL, '李斯', '秦', '臣闻吏议逐客，窃以为过矣。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4220, 72, 636875, '5abf2ef99f54543001f89715', '卜居', NULL, '屈原', '周', '屈原既放，三年不得复见。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4221, 73, 633848, '586e839161ff4b0064159281', '对楚王问', NULL, '宋玉', '周', '楚襄王问于宋玉曰：“先生其有遗行与？', 'fu', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4222, 8, 636285, '5aab6fc62f301e00365e70d3', '圆觉经 · 威德自在菩萨', NULL, '释迦牟尼', '周', '于是威德自在菩萨，在大众中即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，广为我等分别如是随顺觉性，令诸菩萨觉心光明。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4223, 9, 636286, '5aab700a9f5454303ba586d8', '圆觉经 · 辩音菩萨', NULL, '释迦牟尼', '周', '于是辩音菩萨，在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手，而白佛言：“大悲世尊，如是法门，甚为希有。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4224, 10, 636287, '5aab7033ee920a0045243f23', '圆觉经 · 净诸业障菩萨', NULL, '释迦牟尼', '周', '于是净诸业障菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，为我等辈演说如是不思议事，一切如来因地行相，令诸大众得未曾有。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4225, 1, 636910, '5ac1d71c9f5454335169b518', '鬼谷子 · 捭阖', NULL, '鬼谷子', '周', '粤若稽古，圣人之在天地间也，为众生之先。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4226, 2, 636911, '5ac1d7577565710045b24261', '鬼谷子 · 反应', NULL, '鬼谷子', '周', '古之大化者，乃与无形俱生。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4227, 3, 636912, '5ac1d77da22b9d0045458bc7', '鬼谷子 · 内揵', NULL, '鬼谷子', '周', '君臣上下之事，有远而亲，近而疏；', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4228, 4, 636913, '5ac1d7a317d0090061612326', '鬼谷子 · 抵巇', NULL, '鬼谷子', '周', '物有自然，事有合离。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4229, 5, 636914, '5ac1d7c19f54543495d24a2b', '鬼谷子 · 飞钳', NULL, '鬼谷子', '周', '凡度权量能，所以征远来近。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4230, 6, 636915, '5ac1d7dfac502e0063b6c347', '鬼谷子 · 忤合', NULL, '鬼谷子', '周', '凡趋合倍反，计有适合。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4231, 7, 636916, '5ac1d7ff4773f7005d50f55c', '鬼谷子 · 揣篇', NULL, '鬼谷子', '周', '古之善用天下者，必量天下之权，而揣诸侯之情。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4232, 8, 636917, '5ac1d81b9f5454300106ddbd', '鬼谷子 · 摩篇', NULL, '鬼谷子', '周', '摩者，揣之术也。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4233, 9, 636918, '5ac1d8392f301e0065fd7bac', '鬼谷子 · 权篇', NULL, '鬼谷子', '周', '说者，说之也；', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4234, 10, 636919, '5ac1d8589f5454300106df39', '鬼谷子 · 谋篇', NULL, '鬼谷子', '周', '为人凡谋有道，必得其所因，以求其情。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4235, 11, 636920, '5ac1d8739f5454335169c0b3', '鬼谷子 · 决篇', NULL, '鬼谷子', '周', '凡决物，必托于疑者。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4236, 12, 636921, '5ac1d8a32f301e0065fd7e51', '鬼谷子 · 符言', NULL, '鬼谷子', '周', '安徐正静，其被节先肉。', 'wen', 147, '鬼谷子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4244, 74, 636927, '5ac1de839f5454335169eb68', '史记 · 七十列传 · 管晏列传', NULL, '司马迁', '汉', '管仲夷吾者，颍上人也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4247, 75, 633502, '5831b0df8ac2470061bea3b6', '史记 · 七十列传 · 游侠列传', NULL, '司马迁', '汉', '韩子曰：「儒以文乱法，而侠以武犯禁。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4250, 76, 636931, '5ac1e20f9f54543001072fea', '史记 · 太史公自序', NULL, '司马迁', '汉', '太史公曰：“先人有言：‘自周公卒五百岁而有孔子。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4251, 77, 10249, '57b8f615df0eea00633499f2', '报任安书', NULL, '司马迁', '汉', '太史公牛马走司马迁再拜言。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4252, 11, 636288, '5aab70619f5454250d8282e9', '圆觉经 · 普觉菩萨', NULL, '释迦牟尼', '周', '于是普觉菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手，而白佛言：“大悲世尊，快说禅病，令诸大众得未曾有，心意荡然，获大安隐。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4253, 12, 636289, '5aab709075657116a373afd9', '圆觉经 · 圆觉菩萨', NULL, '释迦牟尼', '周', '于是圆觉菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，为我等辈广说净觉种种方便，令末世众生有大增益。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4254, 13, 636290, '5aab70b244d9040065453ae6', '圆觉经 · 贤善首菩萨', NULL, '释迦牟尼', '周', '于是贤善首菩萨在大众中，即从座起，顶礼佛足，右绕三匝，长跪叉手而白佛言：“大悲世尊，广为我等及末世众生，开悟如是不思议事。', 'wen', 145, '圆觉经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4271, 79, 637027, '5ac478484773f7005d5fb426', '文帝议佐百姓诏', NULL, '刘恒', '汉', '间者数年比不登，又有水旱疾疫之灾，朕甚忧之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4272, 80, 637028, '5ac478b2ee920a0045208d9c', '景帝令二千石修职诏', NULL, '刘启', '汉', '雕文刻镂，伤农事者也；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4273, 81, 637029, '5ac479012f301e00650c180c', '武帝求茂才异等诏', NULL, '刘彻', '汉', '盖有非常之功，必待非常之人，故马或奔踶而致千里，士或有负俗之累而立功名。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4274, 82, 11756, '57d6a4f25bbb50005bc9ae10', '过秦论', NULL, '贾谊', '汉', '【上篇】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4275, 83, 633941, '58887aff2f301e0069adace6', '治安策', NULL, '贾谊', '汉', '臣窃惟事势，可为痛哭者一，可为流涕者二，可为长太息者六，若其它背理而伤道者，难遍以疏举。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4277, 85, 636396, '5aacec039f5454003756bd10', '狱中上梁王书', NULL, '邹阳 ', '汉', '臣闻忠无不报，信不见疑，臣常以为然，徒虚语耳。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4278, 86, 634872, '58e77f978d6d810061777713', '上书谏猎', NULL, '司马相如', '汉', '臣闻物有同类而殊能者，故力称乌获，捷言庆忌，勇期贲、育。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4279, 87, 12452, '58232d17d2030900552054aa', '答苏武书', NULL, '李陵', '汉', '子卿足下：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4280, 88, 637032, '5ac47b564773f7005d5fc9f8', '尚德缓刑书', NULL, '路温舒 ', '汉', '昭帝崩，昌邑王贺废，宣帝初即位，路温舒上书，言宜尚德缓刑。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4281, 89, 637033, '5ac47ba6ee920a004520a261', '报孙会宗书', NULL, '杨恽', '汉', '恽材朽行秽，文质无所底，幸赖先人余业，得备宿卫。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4282, 90, 637034, '5ac47ddd4773f7005d5fdb8e', '光武帝临淄劳耿弇', NULL, '刘秀', '汉', '车驾至临淄，自劳军，群臣大会。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4283, 91, 12077, '5814afa35bbb500059a29323', '诫兄子严、敦书', NULL, '马援', '汉', '援兄子严、敦，并喜讥议，而通轻侠客。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4284, 92, 10065, '57b8e26d5bbb50005b778035', '前出师表', NULL, '诸葛亮', '三国', '先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4285, 93, 10066, '57b8f8ea128fe10054c952cd', '后出师表', NULL, '诸葛亮', '三国', '先帝深虑汉、贼不两立，王业不偏安，故托臣以讨贼也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4286, 1, 637035, '5ac47f839f54542110b67f50', '孙子兵法 · 始计篇', NULL, '孙武', '周', '孙子曰：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4287, 2, 637036, '5ac47fc69f54541656f61495', '孙子兵法 · 作战篇', NULL, '孙武', '周', '孙子曰：凡用兵之法，驰车千驷，革车千乘，带甲十万，千里馈粮。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4288, 3, 637037, '5ac48008a22b9d004554623f', '孙子兵法 · 谋攻篇', NULL, '孙武', '周', '孙子曰：夫用兵之法，全国为上，破国次之；', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4289, 4, 637038, '5ac4804e7565710045c129df', '孙子兵法 · 军形篇', NULL, '孙武', '周', '孙子曰：昔之善战者，先为不可胜，以待敌之可胜。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4290, 5, 637039, '5ac481029f54542110b6891e', '孙子兵法 · 兵势篇', NULL, '孙武', '周', '孙子曰：凡治众如治寡，分数是也；', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4291, 6, 637040, '5ac481484773f7005d5ff38e', '孙子兵法 · 虚实篇', NULL, '孙武', '周', '孙子曰：凡先处战地而待敌者佚，后处战地而趋战者劳，故善战者，致人而不致于人。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4292, 7, 637041, '5ac481b44773f7005d5ff6c9', '孙子兵法 · 军争篇', NULL, '孙武', '周', '孙子曰：凡用兵之法，将受命于君，合军聚众，交和而舍，莫难于军争。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4293, 8, 637042, '5ac481ed9f545405e7ae3406', '孙子兵法 · 九变篇', NULL, '孙武', '周', '孙子曰：凡用兵之法，将受命于君，合军聚众。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4294, 9, 637043, '5ac48242a22b9d0045547367', '孙子兵法 · 行军篇', NULL, '孙武', '周', '孙子曰：凡处军相敌：绝山依谷，视生处高，战隆无登，此处山之军也。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4295, 10, 637044, '5ac482839f545431f970c854', '孙子兵法 · 地形篇', NULL, '孙武', '周', '孙子曰：地形有通者，有挂者，有支者，有隘者，有险者，有远者。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4296, 11, 635432, '59e714d667f356003a172272', '孙子兵法 · 九地篇', NULL, '孙武', '周', '孙子曰：用兵之法，有散地，有轻地，有争地，有交地，有衢地，有重地，有圮地，有围地，有死地。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4297, 12, 637046, '5ac4837eee920a004520d8d6', '孙子兵法 · 火攻篇', NULL, '孙武', '周', '孙子曰：凡火攻有五：一曰火人，二曰火积，三曰火辎，四曰火库，五曰火队。', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4298, 13, 637047, '5ac483c02f301e00650c61dc', '孙子兵法 · 用间篇', NULL, '孙武', '周', '孙子曰：凡兴师十万，出征千里，百姓之费，公家之奉，日费千金；', 'wen', 148, '孙子兵法', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4299, 94, 11522, '57b902002e958a005fa5542c', '陈情表', NULL, '李密', '晋', '臣密言：臣以险衅，夙遭闵凶。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4300, 95, 10093, '57b8fc507db2a20054267d22', '兰亭集序', NULL, '王羲之', '晋', '永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4301, 96, 10277, '57b8fb0fc4c97100558ef7c5', '归去来兮辞', NULL, '陶渊明', '晋', '归去来兮，田园将芜胡不归？', 'fu', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4303, 98, 10092, '57b8fa275bbb50005b77f48f', '五柳先生传', NULL, '陶渊明', '晋', '先生不知何许人也，亦不详其姓字。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4304, 99, 636072, '5a8fd64cee920a0044a705e3', '北山移文', NULL, '孔稚珪', '南北朝', '锺山之英，草堂之灵，驰烟驿路，勒移山庭：　INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4305, 100, 11760, '57d6b277bf22ec005fbbc8a7', '谏太宗十思疏', NULL, '魏征', '唐', '臣闻求木之长者，必固其根本；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4306, 101, 10134, '57b90bb75bbb50005b787cae', '为徐敬业讨武曌檄', NULL, '骆宾王', '唐', '伪临朝武氏者，性非和顺，地实寒微。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4307, 102, 10094, '57af1324c4c9710054770b01', '滕王阁序', NULL, '王勃', '唐', '豫章故郡，洪都新府。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4308, 103, 633475, '582d6cad0ce463006ce8be59', '与韩荆州书', NULL, '李白', '唐', '白闻天下谈士相聚而言曰：“生不用封万户侯，但愿一识韩荆州。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4309, 104, 10313, '57b14e99a633bd0057092707', '春夜宴从弟桃花园序', NULL, '李白', '唐', '夫天地者，万物之逆旅也；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4310, 105, 634018, '589c32db86b599006b265346', '吊古战场文', NULL, '李华', '唐', '浩浩乎，平沙无垠，夐不见人。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4311, 106, 10172, '57ae026579bc440058cc0998', '陋室铭', NULL, '刘禹锡', '唐', '山不在高，有仙则名。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4312, 107, 11272, '57b901d47db2a2005426a764', '阿房宫赋', NULL, '杜牧', '唐', '六王毕，四海一，蜀山兀，阿房出。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4313, 108, 634227, '58ae88761b69e60058969f3c', '原道', NULL, '韩愈', '唐', '博爱之谓仁，行而宜之之谓义。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4314, 109, 634843, '58dd4369b123db00603cde80', '原毁', NULL, '韩愈', '唐', '古之君子，其责己也重以周，其待人也轻以约。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4315, 110, 634702, '58ceb509570c350058a83b6d', '获麟解', NULL, '韩愈', '唐', '麟之为灵，昭昭也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4316, 111, 12365, '58176aa7c4c97100555783ed', '杂说 · 其一 · 龙说', NULL, '韩愈', '唐', '龙嘘气成云，云固弗灵于龙也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4317, 112, 12368, '58176fea8ac247004fc2c7ca', '马说', NULL, '韩愈', '唐', '世有伯乐，然后有千里马。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4318, 113, 11271, '57b8d2241532bc005b9a374b', '师说', NULL, '韩愈', '唐', '古之学者必有师。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4319, 114, 11907, '58032de58ac24700580243a3', '进学解', NULL, '韩愈', '唐', '国子先生晨入太学，招诸生立馆下，诲之曰：「业精于勤，荒于嬉；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4320, 115, 634703, '58ceb9c12f301e007e504e4c', '圬者王承福传', NULL, '韩愈', '唐', '圬之为技，贱且劳者也，有业之，其色若自得者。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4321, 116, 634248, '58b03acc2f301e0068fab900', '讳辩', NULL, '韩愈', '唐', '愈与李贺书，劝贺举进士。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4322, 117, 634704, '58cec0e144d904006841ba90', '争臣论', NULL, '韩愈', '唐', '或问谏议大夫阳城于愈，可以为有道之士乎哉？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4323, 118, 634700, '58ceac1c128fe1006c95cdeb', '后十九日复上宰相书', NULL, '韩愈', '唐', '二月十六日，前乡贡进士韩愈，谨再拜言相公阁下：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4324, 119, 634701, '58ceb2dc5c497d0057c8730e', '后廿九日复上宰相书', NULL, '韩愈', '唐', '三月十六日，前乡贡进士韩愈，谨再拜言相公阁下：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4325, 120, 634692, '58ce91fc2f301e007e4f5791', '与于襄阳书', NULL, '韩愈', '唐', '七月三日，将仕郎、守国子四门博士韩愈，谨奉书尚书阁下：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4326, 121, 634691, '58ce8e11a22b9d006432292a', '与陈给事书', NULL, '韩愈', '唐', '愈再拜：愈之获见于阁下有年矣，始者亦尝辱一言之誉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4327, 122, 634699, '58cea7130ce4630057d510a0', '应科目时与人书', NULL, '韩愈', '唐', '月日，愈再拜：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4328, 123, 634247, '58b030d58d6d810057e10d5a', '送孟东野序', NULL, '韩愈', '唐', '大凡物不得其平则鸣：草木之无声，风挠之鸣；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4329, 124, 634114, '58a6840961ff4b0062ac7169', '送李愿归盘谷序', NULL, '韩愈', '唐', '太行之阳有盘谷。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4330, 125, 634306, '58b3c59b1b69e60058b55170', '送董邵南游河北序', NULL, '韩愈', '唐', '燕赵古称多慷慨悲歌之士。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4331, 126, 634689, '58ce8577b123db3f6b406cda', '送杨少尹序', NULL, '韩愈', '唐', '昔疏广、受二子以年老，一朝辞位而去，于时公卿设供张，祖道都门外，车数百两，道路观者多叹息泣下，共言其贤。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4332, 127, 634688, '58ce834a5c497d0057c73c59', '送石处士序', NULL, '韩愈', '唐', '河阳军节度、御史大夫乌公，为节度之三月，求士于从事之贤者。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4333, 128, 634687, '58ce809961ff4b006c9a684e', '送温处士赴河阳军序', NULL, '韩愈', '唐', '伯乐一过冀北之野，而马群遂空。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4334, 129, 11731, '57c5ee722e958a00698ddf84', '祭十二郎文', NULL, '韩愈', '唐', '年、月、日，季父愈闻汝丧之七日，乃能衔哀致诚，使建中远具时羞之奠，告汝十二郎之灵：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4335, 130, 634690, '58ce8b592f301e007e4f28cb', '祭鳄鱼文', NULL, '韩愈', '唐', '维年月日，潮州刺史韩愈，使军事衙推秦济，以羊一猪一投恶溪之潭水，以与鳄鱼食，而告之曰：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4336, 131, 634053, '589d683f86b599006b2e1354', '柳子厚墓志铭', NULL, '韩愈', '唐', '子厚，讳宗元。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4337, 1, 637052, '5ac601d4a22b9d00455d63e0', '茶经 · 一之源', NULL, '陆羽', '唐', '茶者，南方之嘉木也，一尺二尺，乃至数十尺。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4338, 2, 637053, '5ac6028d9f54541c8b9b46c1', '茶经 · 二之具', NULL, '陆羽', '唐', '籝，一曰篮，一曰笼，一曰筥。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4339, 3, 637054, '5ac6030d9f54541c8b9b4a7c', '茶经 · 三之造', NULL, '陆羽', '唐', '凡采茶，在二月三月四月之间。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4340, 4, 637055, '5ac603a6ac502e0063cea9cc', '茶经 · 四之器', NULL, '陆羽', '唐', '风炉：风炉以铜铁铸之，如古鼎形，厚三分，缘阔九分，令六分虚中，致其圬墁，凡三足。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4341, 5, 637056, '5ac604d52f301e0065153a43', '茶经 · 五之煮', NULL, '陆羽', '唐', '凡灸茶，慎勿于风烬间灸，熛焰如钻，使炎凉不均。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4777, 4, 10699, '57b93a24165abd0054c1b37a', '千秋岁', NULL, '张先', '宋', '数声鶗鴂，又报芳菲歇。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4342, 6, 637057, '5ac605332f301e0065153cb2', '茶经 · 六之饮', NULL, '陆羽', '唐', '翼而飞，毛而走，去而言，此三者俱生于天地间。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4343, 7, 637058, '5ac6063d17d009006179300f', '茶经 · 七之事', NULL, '陆羽', '唐', '三皇炎帝。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4344, 8, 637059, '5ac606f49f545430011ef8a6', '茶经 · 八之出', NULL, '陆羽', '唐', '山南以峡州上，襄州、荆州次，衡州下，金州、梁州又下。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4345, 9, 637060, '5ac60796ee920a2bc7d33dee', '茶经 · 九之略', NULL, '陆羽', '唐', '其造具，若方春禁火之时，于野寺山园丛手而掇，乃蒸，乃舂，乃以火干之，则又棨、朴、焙、贯、相、穿、育等七事皆废。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4346, 10, 637061, '5ac607ec9f54541c8b9b70ba', '茶经 · 十之图', NULL, '陆羽', '唐', '以绢素或四幅或六幅，分布写之，陈诸座隅，则茶之源、之具、之造、之器、之煮、之饮、之事、之出、之略，目击而存，于是《茶经》之始终备焉。', 'wen', 149, '茶经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4347, 132, 634668, '58cc003261ff4b006c8d30c6', '驳复仇议', NULL, '柳宗元', '唐', '臣伏见天后时，有同州下邽人徐元庆者，父爽为县吏赵师韫所杀，卒能手刃父仇，束身归罪。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4348, 133, 634732, '58cfdf8eb123db3f6b481b7d', '桐叶封弟辨', NULL, '柳宗元', '唐', '古之传者有言：成王以桐叶与小弱弟戏，曰：“以封汝。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4349, 134, 634733, '58cfe24eb123db3f6b483154', '箕子碑', NULL, '柳宗元', '唐', '凡大人之道有三：一曰正蒙难，二曰法授圣，三曰化及民。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4350, 135, 11730, '57c5c2e7128fe1005fe07a9f', '捕蛇者说', NULL, '柳宗元', '唐', '永州之野产异蛇，黑质而白章，触草木，尽死；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4351, 136, 12461, '58248acc2f301e005c452a6b', '种树郭橐驼传', NULL, '柳宗元', '唐', '郭橐驼，不知始何名。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4352, 137, 12459, '58236454d20309005521c052', '梓人传', NULL, '柳宗元', '唐', '裴封叔之第，在光德里。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4353, 138, 633997, '5895c0e8128fe1006caae88b', '愚溪诗序', NULL, '柳宗元', '唐', '灌水之阳有溪焉，东流入于潇水。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4354, 139, 635224, '5980bebea22b9d006d6c2d4e', '永州韦使君新堂记', NULL, '柳宗元', '唐', '将为穹谷峭岩渊池于郊邑之中，则必辇山石，沟涧壑，淩绝峰阻，疲极人力，乃可以有为也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4355, 140, 634251, '58b053e78d6d810057e22094', '永州八记 · 其三 · 钴鉧潭西小丘记', NULL, '柳宗元', '唐', '得西山后八日，寻山口西北道二百步，又得钴鉧潭。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4356, 141, 634255, '58b05e1c2f301e006cff4d1b', '永州八记 · 其八 · 小石城山记', NULL, '柳宗元', '唐', '自西山道口径北，逾黄茅岭而下，有二道：其一西出，寻之无所得；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4357, 142, 637063, '5ac723c6ac502e0063d48646', '贺进士王参元失火书', NULL, '柳宗元', '唐', '得杨八书，知足下遇火灾，家无馀储。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4358, 143, 634140, '58a9403cac502e006cd1dd9c', '待漏院记', NULL, '王禹偁', '宋', '天道不言，而品物亨，岁功成者，何谓也？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4359, 144, 633910, '5880fe56b123db0061d2928a', '黄冈竹楼记', NULL, '王禹偁', '宋', '黄冈之地多竹，大者如椽。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4360, 145, 634520, '58c4391e8ac247072001ab60', '洛阳名园记', NULL, '李格非', '宋', '洛阳处天下之中，挟崤渑之阻，当秦陇之襟喉，而赵魏之走集，盖四方必争之地也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4361, 146, 634974, '58fc1c1d0ce46300612a7e84', '严先生祠堂记', NULL, '范仲淹', '宋', '先生，汉光武之故人也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4362, 147, 10089, '57b90573165abd0054bff31c', '岳阳楼记', NULL, '范仲淹', '宋', '庆历四年春，滕子京谪守巴陵郡。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4363, 148, 635221, '5980af17fe88c20057f952b3', '谏院题名记', NULL, '司马光', '宋', '古者谏无官，自公卿大夫，至于工商，无不得谏者。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4364, 149, 635223, '5980bbf8128fe1005650b1a2', '义田记', NULL, '钱公辅', '宋', '范文正公，苏人也，平生好施与，择其亲而贫，疏而贤者，咸施之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4365, 150, 637064, '5ac724d59f5454147aa1b0f0', '袁州州学记', NULL, '李觏', '宋', '皇帝二十有三年，制诏州县立学。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4366, 151, 634935, '58ed907d8d6d8100580c73d1', '朋党论', NULL, '欧阳修', '宋', '臣闻朋党之说，自古有之，惟幸人君辨其君子小人而已。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4367, 152, 635220, '5980acecac502e0069001bd7', '纵囚论', NULL, '欧阳修', '宋', '信义行于君子，而刑戮施于小人。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4368, 153, 634265, '58b273fa570c3500692a3ec2', '释秘演诗集序', NULL, '欧阳修', '宋', '予少以进士游京师，因得尽交当世之贤豪。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4369, 1, 636295, '5aab76e19f54543cc8df18e3', '六祖坛经 · 行由 · 第一节', NULL, '慧能', '唐', '时，大师至宝林，韶州韦刺史与官僚入山，请师出，于城中大梵寺讲堂，为众开缘说法。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4370, 2, 636304, '5aab890aa22b9d0045b00b3a', '六祖坛经 · 行由 · 第二节', NULL, '慧能', '唐', '惠能严父，本贯范阳，左降流于岭南，作新州百姓。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4371, 3, 636306, '5aab896ba22b9d0045b00de3', '六祖坛经 · 行由 · 第三节', NULL, '慧能', '唐', '惠能安置母毕，即便辞违，不经三十余日，便至黄梅，礼拜五祖。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4372, 4, 636309, '5aab8d252f301e00365f542f', '六祖坛经 · 行由 · 第四节', NULL, '慧能', '唐', '祖一日忽见慧能，曰：“吾思汝之见可用，恐有恶人害汝，遂不与汝言，汝知之否？', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4373, 5, 636310, '5aab8f169f54543cc8dfbf79', '六祖坛经 · 行由 · 第五节', NULL, '慧能', '唐', '众得处分，退而递相谓曰：“我等众人，不须澄心用意作偈，将呈和尚。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4374, 6, 636312, '5aab8f4175657116a37495a4', '六祖坛经 · 行由 · 第六节', NULL, '慧能', '唐', '祖已知神秀入门未得，不见自性。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4375, 7, 636313, '5aab8f6c9f5454303ba671d4', '六祖坛经 · 行由 · 第七节', NULL, '慧能', '唐', '复两日，有一童子，于碓坊过，唱诵其偈，慧能一闻，便知此偈未见本性，虽未蒙教授，早识大意，遂问童子曰：“诵者何偈？', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4376, 8, 636314, '5aab8fa3ac502e57c90e2985', '六祖坛经 · 行由 · 第八节', NULL, '慧能', '唐', '次日，祖潜至碓坊，见能腰石舂米，语曰：“求道之人，为法忘躯，当如是乎！', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4377, 9, 636315, '5aab90072f301e00365f6ad1', '六祖坛经 · 行由 · 第九节', NULL, '慧能', '唐', '慧能辞违祖已，发足南行，两月中间，至大庾岭，逐后数百人来，欲夺衣钵。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4679, 7, 637357, '5adff3397f6fd30047ec57bb', '笠翁对韵 · 上卷 · 七虞', NULL, '李渔', '清', '红对白，有对无。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4378, 10, 636316, '5aab92b344d9040065463195', '六祖坛经 · 行由 · 第十节', NULL, '慧能', '唐', '慧能后至曹溪，又被恶人寻逐，乃于四会，避难猎人队中，凡经一十五载，时与猎人随宜说法。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4379, 11, 636317, '5aab941f9f5454250d837d36', '六祖坛经 · 般若 · 第一节', NULL, '慧能', '唐', '次日，韦使君请益。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4380, 12, 636318, '5aab9e7144d904006546804f', '六祖坛经 · 般若 · 第二节', NULL, '慧能', '唐', '善知识，迷人口念，当念之时，有妄有非。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4381, 13, 636320, '5aab9ea89f545400374edae4', '六祖坛经 · 般若 · 第三节', NULL, '慧能', '唐', '善知识，智慧观照，内外明彻，识自本心。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4382, 14, 636321, '5aab9ec9ee920a00452597cf', '六祖坛经 · 决疑 · 第一节', NULL, '慧能', '唐', '一日，韦刺史为师设大会斋，斋讫，刺史请师升座，同官僚士庶肃容再拜，问曰：“弟子闻和尚说法，实不可思议，今有少疑，愿大慈悲特为解说。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4383, 15, 636322, '5aab9ee7ac502e57c90e9238', '六祖坛经 · 决疑 · 第二节', NULL, '慧能', '唐', '师言：“大众，世人自色身是城，眼耳鼻舌是门，外有五门，内有意门。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4384, 154, 635023, '5927f777a22b9d00572a5e9f', '梅圣俞诗集序', NULL, '欧阳修', '宋', '予闻世谓诗人，少达而多穷，夫岂然哉！', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4385, 155, 634680, '58cd3e4c5c497d0057c08045', '送杨寘序', NULL, '欧阳修', '宋', '予尝有幽忧之疾，退而闲居，不能治也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4386, 156, 11661, '57b8b837165abd0054becedb', '新五代史 · 伶官传序', NULL, '欧阳修', '宋', '呜呼！', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4387, 157, 635225, '59840141a22b9d006d943c37', '新五代史 · 宦者传论', NULL, '欧阳修', '宋', '自古宦者乱人之国，其源深于女祸。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4388, 158, 11953, '5807930c2f301e006ca0b64c', '相州昼锦堂记', NULL, '欧阳修', '宋', '仕宦而至将相，富贵而归故乡，此人情之所荣，而今昔之所同也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4389, 159, 633637, '5843dd23a22b9d007a98d4bf', '丰乐亭记', NULL, '欧阳修', '宋', '修既治滁之明年，夏，始饮滁水而甘。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4390, 160, 10088, '57b5a103128fe1005650a0eb', '醉翁亭记', NULL, '欧阳修', '宋', '环滁皆山也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4391, 161, 11190, '57b92fed165abd0054c15b3d', '秋声赋', NULL, '欧阳修', '宋', '欧阳子方夜读书，闻有声自西南来者，悚然而听之，曰：“异哉！', 'fu', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4392, 162, 634670, '58ccfaf644d9040069ff40e1', '祭石曼卿文', NULL, '欧阳修', '宋', '维治平四年七月日，具官欧阳修，谨遣尚书都省令史李昜至于太清，以清酌庶羞之奠，致祭于亡友曼卿之墓下，而吊之以文曰：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4393, 163, 633473, '582c8476a22b9d006b680d0f', '泷冈阡表', NULL, '欧阳修', '宋', '呜呼！', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4394, 164, 11729, '57c5bf29efa631005ad0d467', '管仲论', NULL, '苏洵', '宋', '管仲相桓公，霸诸侯，攘夷狄，终其身齐国富强，诸侯不敢叛。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4395, 165, 12058, '5812d98c2e958a00548ac51c', '辨奸论', NULL, '苏洵', '宋', '事有必至，理有固然。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4396, 166, 11728, '57c5cec7d342d3006b3a8d8e', '心术', NULL, '苏洵', '宋', '为将之道，当先治心。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4397, 167, 634976, '58fcc1cda22b9d0065a2e739', '张益州画像记', NULL, '苏洵', '宋', '至和元年秋，蜀人传言有寇至，边军夜呼，野无居人，谣言流闻，京师震惊。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4398, 168, 633771, '5859f72c1b69e60056fc27e7', '刑赏忠厚之至论', NULL, '苏轼', '宋', '尧、舜、禹、汤、文、武、成、康之际，何其爱民之深，忧民之切，而待天下之以君子长者之道也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4399, 169, 12053, '5812a73ba0bb9f0058628248', '范增论', NULL, '苏轼', '宋', '汉用陈平计，闲疏楚君臣，项羽疑范增与汉有私，稍夺其权。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4400, 170, 11912, '5805ace4128fe10054c2c943', '留侯论', NULL, '苏轼', '宋', '古之所谓豪杰之士者，必有过人之节。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4401, 171, 12054, '5812be4c8ac247004fa66596', '贾谊论', NULL, '苏轼', '宋', '非才之难，所以自用者实难。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4402, 172, 12055, '5812c62fa0bb9f00586347c6', '晁错论', NULL, '苏轼', '宋', '天下之患，最不可为者，名为治平无事，而其实有不测之忧。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4403, 16, 636323, '5aab9f0d2f301e00365fd3af', '六祖坛经 · 定慧 · 第一节', NULL, '慧能', '唐', '师示众云：“善知识，我此法门，以定慧为本，大众勿迷，言定慧别。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4404, 17, 636324, '5aab9f349f545417b4b7f71f', '六祖坛经 · 坐禅 · 第一节', NULL, '慧能', '唐', '师示众云：“此门坐禅，元不看心，亦不看净，亦不是不动。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4405, 18, 636325, '5aab9f559f545448cf26bc35', '六祖坛经 · 忏悔 · 第一节', NULL, '慧能', '唐', '时大师见广韶洎四方士庶骈集山中听法，于是升座告众曰：“来，诸善知识，此事须从自性中起，于一切时，念念自净其心，自修其行，见自己法身，见自心佛，自度自戒，始得不假到此。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4406, 19, 636326, '5aab9f799f5454303ba6e3be', '六祖坛经 · 忏悔 · 第二节', NULL, '慧能', '唐', '“善知识，既忏悔已，与善知识发四弘誓愿，各须用心正听：自心众生无边誓愿度，自心烦恼无边誓愿断，自性法门无尽誓愿学，自性无上佛道誓愿成。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4407, 20, 636327, '5aab9f9c9f545417b4b7fa28', '六祖坛经 · 忏悔 · 第三节', NULL, '慧能', '唐', '“何名圆满报身？', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4408, 21, 636328, '5aab9fbe9f545417b4b7fbb4', '六祖坛经 · 机缘 · 第一节', NULL, '慧能', '唐', '师自黄梅得法，回至韶州曹侯村，人无知者。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4409, 22, 636329, '5aab9fe09f5454303ba6e696', '六祖坛经 · 机缘 · 第二节', NULL, '慧能', '唐', '僧法达，洪州人，七岁出家，常诵《法华经》。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4410, 23, 636330, '5aaba00e9f5454250d83ceed', '六祖坛经 · 机缘 · 第三节 ', NULL, '慧能', '唐', '僧智通，寿州安丰人。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4411, 24, 636331, '5aaba0339f545417b4b7ff20', '六祖坛经 · 机缘 · 第四节', NULL, '慧能', '唐', '僧智常，信州贵溪人，髫年出家，志求见性，一日参礼。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4412, 25, 636332, '5aaba05617d00968873d796b', '六祖坛经 · 机缘 · 第五节', NULL, '慧能', '唐', '僧志道，广州南海人也，请益曰：“学人自出家，览《涅槃经》十载有馀，未明大意，愿和尚垂诲。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4413, 26, 636333, '5aaba0769f5454250d83d1da', '六祖坛经 · 机缘 · 第六节', NULL, '慧能', '唐', '行思禅师，生吉州安城刘氏，闻曹溪法席盛化，径来参礼。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4910, 4, 10244, '57ea0e74bf22ec0058825dc1', '庄子 · 内篇 · 人间世', NULL, '庄子', '周', '颜回见仲尼，请行。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4414, 27, 636334, '5aaba09744d90400654690e3', '六祖坛经 · 机缘 · 第七节', NULL, '慧能', '唐', '永嘉玄觉禅师，温州戴氏子，少习经论，精天台止观法门，因看《维摩经》，发明心地。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4415, 28, 636335, '5aaba0baa22b9d0045b0b4a1', '六祖坛经 · 机缘 · 第八节 ', NULL, '慧能', '唐', '禅者智隍，初参五祖，自谓已得正受，庵居长坐，积二十年。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4416, 29, 636336, '5aaba0d89f5454303ba6ed30', '六祖坛经 · 顿渐 · 第一节', NULL, '慧能', '唐', '时祖师居曹溪宝林，神秀大师在荆南玉泉寺，于时两宗盛化，人皆称南能北秀，故有南北二宗顿渐之分，而学者莫知宗趣。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4417, 30, 636337, '5aaba0f7ac502e57c90ea14f', '六祖坛经 · 顿渐 · 第二节', NULL, '慧能', '唐', '僧志彻，江西人，本姓张，名行昌，少任侠。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4418, 31, 636338, '5aaba11617d00968873d7e7b', '六祖坛经 · 顿渐 · 第三节', NULL, '慧能', '唐', '有一童子，名神会，襄阳高氏子，年十三，自玉泉来参礼。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4419, 32, 636339, '5aaba13575657116a3750c48', '六祖坛经 · 护法 · 第一节', NULL, '慧能', '唐', '神龙元年上元日，则天中宗诏云：“朕请安秀二师宫中供养，万机之暇，每究一乘。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4420, 33, 636340, '5aaba1539f545448cf26c9f8', '六祖坛经 · 付嘱 · 第一节', NULL, '慧能', '唐', '师一日唤门人法海、志诚、法达、神会、智常、智通、志彻、志道、法珍、法如等，曰：“汝等不同馀人，吾灭度后，各为一方师，吾今教汝说法，不失本宗。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4421, 34, 636341, '5aaba174ac502e57c90ea486', '六祖坛经 · 付嘱 · 第二节', NULL, '慧能', '唐', '“自性动用，共人言语，外于相离相，内于空离空。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4422, 35, 636342, '5aaba1939f545417b4b808c5', '六祖坛经 · 付嘱 · 第三节', NULL, '慧能', '唐', '师于太极元年壬子，延和七月，命门人，往新州国恩寺建塔，仍令促工。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4423, 36, 636343, '5aaba1b4ac502e57c90ea617', '六祖坛经 · 付嘱 · 第四节', NULL, '慧能', '唐', '大师七月八日，忽谓门人曰：“吾欲归新州，汝等速理舟楫。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4424, 37, 636344, '5aaba1cfac502e57c90ea6a6', '六祖坛经 · 付嘱 · 第五节', NULL, '慧能', '唐', '大师先天二年癸丑岁，八月初三日，于国恩寺斋罢，谓诸徒众曰：“汝等各依位坐，吾与汝别。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4425, 38, 636345, '5aaba1e79f545417b4b80aba', '六祖坛经 · 付嘱 · 第六节', NULL, '慧能', '唐', '师入塔后，至开元十年，壬戌八月三日，夜半，忽闻塔中如拽铁索声，众僧惊起。', 'wen', 150, '六祖坛经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4426, 173, 633790, '585e55a58d6d810065e4af8d', '上梅直讲书', NULL, '苏轼', '宋', '轼每读《诗》至《鸱鸮》，读《书》至《君奭》，常窃悲周公之不遇。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4427, 174, 11868, '57ffabc1da2f60004fbfdccf', '喜雨亭记', NULL, '苏轼', '宋', '亭以雨名，志喜也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4428, 175, 633782, '585cbcf58d6d810065da6369', '凌虚台记', NULL, '苏轼', '宋', '国于南山之下，宜若起居饮食与山接也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4429, 176, 633777, '585b5d1fac502e006716f1e1', '超然台记', NULL, '苏轼', '宋', '凡物，皆有可观。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4430, 177, 633783, '585ce86761ff4b006cd1413c', '放鹤亭记', NULL, '苏轼', '宋', '熙宁十年秋，彭城大水。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4431, 178, 10333, '57b978aa5bbb50005b7c7507', '石钟山记', NULL, '苏轼', '宋', '《水经》云：「彭蠡之口有石钟山焉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4432, 179, 633775, '585ab1c4128fe1006b93a772', '潮州韩文公庙碑', NULL, '苏轼', '宋', '匹夫而为百世师，一言而为天下法，是皆有以参天地之化，关盛衰之运。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4433, 180, 637069, '5acb15ad9f54541c8bb6ab30', '乞校正陆贽奏议进御札子', NULL, '苏轼', '宋', '臣等猥以空疏，备员讲读。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4435, 182, 11697, '57b8a38c79bc44005b9d64a9', '后赤壁赋', NULL, '苏轼', '宋', '是岁十月之望，步自雪堂，将归于临皋。', 'fu', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4436, 183, 634648, '58caae20570c350058927372', '三槐堂铭', NULL, '苏轼', '宋', '天可必乎？', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4437, 184, 633784, '585cef821b69e6006cc9b7b2', '方山子传', NULL, '苏轼', '宋', '方山子，光、黄间隐人也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4438, 185, 633642, '584665cfac502e006cdee5c2', '六国论', NULL, '苏辙', '宋', '尝读六国《世家》，窃怪天下之诸侯，以五倍之地，十倍之众，发愤西向，以攻山西千里之秦，而不免于灭亡，常为之深思远虑，以为必有可以自安之计。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4439, 186, 11733, '57c5c7c6d342d3006b3a7520', '上枢密韩太尉书', NULL, '苏辙', '宋', '太尉执事：辙生好为文，思之至深。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4440, 187, 11666, '57b9a610165abd00661d0707', '黄州快哉亭记', NULL, '苏辙', '宋', '江出西陵，始得平地。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4441, 188, 634337, '58b47e255c497d0067954dfb', '寄欧阳舍人书', NULL, '曾巩', '宋', '巩顿首再拜，舍人先生：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4442, 189, 634336, '58b47c8c2f301e006c16e3d5', '赠黎安二生序', NULL, '曾巩', '宋', '赵郡苏轼，余之同年友也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4443, 190, 633931, '5886fe201b69e60058ed859f', '读《孟尝君传》', NULL, '王安石', '宋', '世皆称孟尝君能得士，士以故归之，而卒赖其力，以脱于虎豹之秦。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4444, 191, 634139, '58a93ccf1b69e6006d346f9e', '同学一首别子固', NULL, '王安石', '宋', '江之南有贤人焉，字子固，非今所谓贤人者，予慕而友之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4445, 192, 11361, '57b343d0c4c971005496cee4', '游褒禅山记', NULL, '王安石', '宋', '褒禅山亦谓之华山，唐浮图慧褒始舍于其址，而卒葬之；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4446, 193, 635237, '59874c06a22b9d006dbde972', '泰州海宁县主簿许君墓志铭', NULL, '王安石', '宋', '君讳平，字秉之，姓许氏。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4447, 194, 637070, '5acb175a9f5454052204065f', '送天台陈庭学序', NULL, '宋濂', '明', '西南山水，惟川蜀最奇，然去中州万里，陆有剑阁栈道之险，水有瞿塘、滟滪之虞。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4448, 195, 634043, '589d2bd0128fe100580bfe2d', '阅江楼记', NULL, '宋濂', '明', '金陵为帝王之州。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4449, 196, 637072, '5acb194d7565712a5ae03380', '司马季主论卜', NULL, '刘基', '明', '东陵侯既废，过司马季主而卜焉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4450, 197, 634041, '589c7b468d6d81006c824372', '卖柑者言', NULL, '刘基', '明', '杭有卖果者，善藏柑，涉寒暑不溃。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4451, 198, 633495, '58309da6d2030900671292a9', '深虑论', NULL, '方孝孺', '明', '虑天下者，常图其所难而忽其所易；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5560, 129, 89172, '585d148a570c35006931ae4e', '秦女休行', NULL, '李白', '唐', '西门秦氏女，秀色如琼花。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4452, 199, 635071, '593cb85dac502e006ced09eb', '豫让论', NULL, '方孝孺', '明', '士君子立身事主，既名知己，则当竭尽智谋，忠告善道，销患于未形，保治于未然，俾身全而主安。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4453, 200, 636239, '5aaa386775657116a36d6ad0', '亲政篇', NULL, '王鏊', '明', '《易》之《泰》：「上下交而其志同。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4454, 201, 634318, '58b40f2d8fd9c50063e30317', '尊经阁记', NULL, '王守仁', '明', '经，常道也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4455, 202, 634317, '58b40abf1b69e60058b73402', '象祠记', NULL, '王守仁', '明', '灵、博之山，有象祠焉。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4456, 203, 633492, '58306a6aa0bb9f0067bf6bf7', '瘗旅文', NULL, '王守仁', '明', '维正德四年，秋月三日，有吏目云自京来者，不知其名氏，携一子、一仆，将之任，过龙场，投宿土苗家。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4457, 204, 637073, '5acb1b4cee920a2bc7eece23', '信陵君救赵论', NULL, '唐顺之', '明', '论者以窃符为信陵君之罪，余以为此未足以罪信陵也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4458, 205, 637074, '5acb1be3a22b9d004578f859', '报刘一丈书', NULL, '宗臣', '明', '数千里外，得长者时赐一书，以慰长想，即亦甚幸矣；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4459, 206, 11657, '57baaf98a34131005b106dad', '吴山图记', NULL, '归有光', '明', '吴、长洲二县，在郡治所，分境而治；', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4460, 207, 635238, '59875121fe88c200574c44f2', '沧浪亭记', NULL, '归有光', '明', '浮图文瑛居大云庵，环水，即苏子美沧浪亭之地也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4461, 208, 637075, '5acb1c5c2f301e0ef508b22d', '青霞先生文集序', NULL, '茅坤', '明', '青霞沈君，由锦衣经历上书诋宰执，宰执深疾之。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4462, 209, 633934, '588760711b69e60058f08eaf', '蔺相如完璧归赵论', NULL, '王世贞', '明', '蔺相如之完璧，人皆称之，予未敢以为信也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4463, 210, 634526, '58c44f7aa22b9d0058a743c0', '徐文长传', NULL, '袁宏道', '明', '余少时过里肆中，见北杂剧有《四声猿》，意气豪达，与近时书生所演传奇绝异，题曰“天池生”，疑为元人作。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4464, 211, 633988, '58947097570c350062312496', '五人墓碑记', NULL, '张溥', '明', '五人者，盖当蓼洲周公之被逮，激于义而死焉者也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4495, 1, 637114, '5acdc92917d00900318c00aa', '地藏经 · 忉利天宫神通品第一', NULL, '释迦牟尼', '周', '如是我闻。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4496, 2, 637115, '5acdca059f54540044e619f5', '地藏经 · 分身集会品第二', NULL, '释迦牟尼', '周', '尔时百千万亿不可思、不可议、不可量、不可说无量阿僧祇世界，所有地狱处，分身地藏菩萨，俱来集在忉利天宫。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4497, 3, 637116, '5acdca952f301e003fc5517f', '地藏经 · 观众生业缘品第三', NULL, '释迦牟尼', '周', '尔时佛母摩耶夫人，恭敬合掌问地藏菩萨言：圣者，阎浮众生，造业差别，所受报应，其事云何？', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4498, 4, 637117, '5acdcb1f4773f70069562169', '地藏经 · 阎浮众生业感品第四', NULL, '释迦牟尼', '周', '尔时地藏菩萨摩诃萨白佛言：世尊，我承佛如来威神力故，遍百千万亿世界，分是身形，救拔一切业报众生。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4499, 5, 637118, '5acdcbef17d00900318c143a', '地藏经 · 地狱名号品第五', NULL, '释迦牟尼', '周', '尔时普贤菩萨摩诃萨白地藏菩萨言：仁者，愿为天龙四众，及未来现在一切众生，说娑婆世界，及阎浮提罪苦众生，所受报处，地狱名号，及恶报等事，使未来世末法众生，知是果报。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4500, 6, 637119, '5acdcc4317d00900318c1675', '地藏经 · 如来赞叹品第六', NULL, '释迦牟尼', '周', '尔时世尊举身放大光明，遍照百千万亿恒河沙等诸佛世界。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4501, 7, 637120, '5acdccd67f6fd3003fc1a361', '地藏经 · 利益存亡品第七', NULL, '释迦牟尼', '周', '尔时地藏菩萨摩诃萨白佛言：世尊，我观是阎浮众生，举心动念，无非是罪。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4502, 8, 637121, '5acdcd33d50eee0045cfe0ad', '地藏经 · 阎罗王众赞叹品第八', NULL, '释迦牟尼', '周', '尔时铁围山内，有无量鬼王，与阎罗天子，俱诣忉利，来到佛所。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4503, 9, 637122, '5acdcd7f4773f700695635f4', '地藏经 · 称佛名号品第九', NULL, '释迦牟尼', '周', '尔时地藏菩萨摩诃萨白佛言：世尊，我今为未来众生演利益事，于生死中，得大利益，唯愿世尊听我说之。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4504, 10, 637123, '5acdcdfc9f54540045e8fd37', '地藏经 · 校量布施功德缘品第十', NULL, '释迦牟尼', '周', '尔时地藏菩萨摩诃萨，承佛威神，从座而起，胡跪合掌白佛言：世尊，我观业道众生，校量布施，有轻有重，有一生受福，有十生受福，有百生千生受大福利者。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4505, 11, 637124, '5acdce3717d00900318c299c', '地藏经 · 地神护法品第十一', NULL, '释迦牟尼', '周', '尔时坚牢地神白佛言：世尊，我从昔来瞻视顶礼无量菩萨摩诃萨，皆是大不可思议神通智慧，广度众生。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4506, 12, 637125, '5acdcea29f54540044e6452a', '地藏经 · 见闻利益品第十二', NULL, '释迦牟尼', '周', '尔时世尊，从顶门上，放百千万亿大毫相光，所谓：白毫相光、大白毫相光、瑞毫相光、大瑞毫相光、玉毫相光、大玉毫相光、紫毫相光、大紫毫相光、青毫相光、大青毫相光、碧毫相光、大碧毫相光、红毫相光、大红毫相光、绿毫相光、大绿毫相光、金毫相光、大金毫相光、庆云毫相光、大庆云毫相光、千轮毫光、大千轮毫光、宝轮毫光、大宝轮毫光、日轮毫光、大日轮毫光、月轮毫光、大月轮毫光、宫殿毫光、大宫殿毫光、海云毫光、大海云毫光。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4507, 13, 637126, '5acdcef3d50eee0045cfedb5', '地藏经 · 嘱累人天品第十三', NULL, '释迦牟尼', '周', '尔时世尊举金色臂，又摩地藏菩萨摩诃萨顶，而作是言：地藏地藏，汝之神力不可思议、汝之慈悲不可思议、汝之智慧不可思议、汝之辩才不可思议，正使十方诸佛，赞叹宣说汝之不思议事，千万劫中，不能得尽。', 'wen', 152, '地藏经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4673, 1, 637351, '5adff276a22b9d0045326e2b', '笠翁对韵 · 上卷 · 一东', NULL, '李渔', '清', '天对地，雨对风。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
