INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4688, 1, 101308, '583ebeefac502e006eb88877', '樱桃', NULL, '张祜', '唐', '石榴未拆梅犹小，爱此山花四五株。斜日庭前风袅袅，碧油千片漏红珠。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4689, 2, 12027, '580e0e1c5bbb50005b5f53ea', '临江仙 · 樱桃落尽春归去', NULL, '李煜', '五代十国', '樱桃落尽春归去，蝶翻金粉双飞。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4690, 3, 10273, '57b339122e958a0054727e91', '一剪梅 · 舟过吴江', NULL, '蒋捷', '宋', '一片春愁待酒浇。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4691, 4, 10123, '57b8de2d0a2b58005c918a26', '一斛珠 · 晓妆初过', NULL, '李煜', '五代十国', '晓妆初过，沉檀轻注些儿个。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4692, 5, 633609, '583eab29ac502e006c36bc7d', '江城子 · 忆梦', NULL, '柳如是', '明', '梦中本是伤心路。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4693, 6, 11648, '57b9ac087db2a20068bdd07c', '菩萨蛮 · 端午日咏盆中菊', NULL, '顾太清', '清', '薰风殿阁樱桃节，碧纱窗下沉檀爇。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4694, 7, 10933, '57b9c851128fe1005f86a93f', '瑞鹤仙 · 乡城见月', NULL, '蒋捷', '宋', '绀烟迷雁迹，渐碎鼓零钟，街喧初息。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4695, 8, 11758, '57d6b886128fe100553308c3', '上林赋', NULL, '司马相如', '汉', '亡是公听然而笑曰：「楚则失矣，而齐亦未为得也。', 'fu', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4696, 9, 17998, '585cc97661ff4b0063ee9caa', '三月二十九日饮杭州路耿同知花园', NULL, '方回', '元', '巢燕春泥久已融，虞弦节近鼓薰风。枝枝烂熟樱桃紫，朵朵争妍芍药红。冠豸霁威贤御史，雕虫得隽老诗翁。十分蚕麦今年稔，我辈何妨酒一中。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4697, 10, 12921, '585cc33961ff4b006cd019a8', '赋得樱桃', NULL, '李世民', '唐', '华林满芳景，洛阳遍阳春。朱颜含远日，翠色影长津。乔柯啭娇鸟，低枝映美人。昔作园中实，今来席上珍。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4698, 11, 49503, '585cee70da2f60006582f7e4', '送华山隐之宗阳宫', NULL, '马祖常', '元', '江阁鱼龙近，山房雾雨多。地清天不暑，池曲水无波。笋箨迎书带，樱桃送锦窠。呦呦呼伴鹿，唼唼换经鹅。养素行编屦，乘闲坐织蓑。几篇餐玉法，一帙醮星科。香灺沈银叶，衣裾佩紫荷。丹光留海月，绛景出松萝。醉忆泉浮乳，幽怜石烂柯。神君攀绿桂，天女踏青莎。邀客登山顶，寻真入涧阿。洞箫吹道曲，云纸写鱼歌。予发今如此，君心可奈何！高谈见明月，为我问娑罗。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4699, 12, 77939, '585d089161ff4b00688f451b', '樱桃花', NULL, '皮日休', '唐', '婀娜枝香拂酒壶，向阳疑是不融酥。晚来嵬峨浑如醉，惟有春风独自扶。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4700, 13, 78203, '585d08cdac502e006721ee33', '同诸客携酒早看樱桃花', NULL, '白居易', '唐', '晓报樱桃发，春携酒客过。绿饧黏盏杓，红雪压枝柯。天色晴明少，人生事故多。停杯替花语，不醉拟如何。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4701, 14, 52062, '585cf0ea128fe10069cb1dc9', '恋绣衾 · 春晴中酒', NULL, '张翥', '元', '醉乡残梦莺唤醒。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4702, 15, 66836, '585cfde361ff4b0063f038ed', '黄河夜雨怀兀颜子方', NULL, '萨都剌', '元', '风流俊逸四公子，轻帽短衣过鲁城。紫陌东风闲戏马，绿窗明月醉闻莺。樱桃花下春中酒，沈水香回夜按筝。独有黄河千里客，短篷听雨到天明。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4703, 16, 66917, '585cfdfeac502e006721986a', '京口城南次集', NULL, '萨都剌', '元', '雨深绿叶樱桃肥，日长青草蝴蝶飞。江南三月春欲尽，白马王孙游不归。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4704, 17, 71157, '585d01fd8d6d810065dc6fef', '馀杭醉歌赠吴山人', NULL, '丁仙芝', '唐', '晓幕红襟燕，春城白项乌。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4705, 18, 74402, '585d051461ff4b006cd22411', '有酒十章', NULL, '元稹', '唐', '有酒有酒歌且哀，江春例早多早梅。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4706, 19, 74430, '585d051b128fe10069cbbdad', '樱桃花', NULL, '元稹', '唐', '樱桃花，一枝两枝千万朵。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4707, 20, 80033, '585d0ae3da2f60006583d780', '秦中吟十首 · 其三· 伤宅', NULL, '白居易', '唐', '谁家起甲第，朱门大道边。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4708, 21, 69640, '585d00b8da2f60006583853c', '天宝宫词十二首寓感', NULL, '顾瑛', '元', '近臣谐谑似枚皋，侍宴承恩得锦袍。扇赐方空描蛱蝶，局看双陆赌樱桃。翰林醉进《清平调》，光禄新呈玉色醪。密奏君王好将息，昨朝马上打围劳。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4709, 22, 79373, '585d0a2661ff4b00688f51f8', '思妇眉', NULL, '白居易', '唐', '春风摇荡自东来，折尽樱桃绽尽梅。惟馀思妇愁眉结，无限春风吹不开。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4710, 23, 79332, '585d0a1b1b69e600560fa6fe', '题东楼前李使君所种樱桃花', NULL, '白居易', '唐', '身入青云无见日，手栽红树又逢春。唯留花向楼前著，故故抛愁与后人。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4711, 24, 80507, '585d0b761b69e6006cca8f04', '元家花', NULL, '白居易', '唐', '今日元家宅，樱桃发几枝。稀稠与颜色，一似去年时。失却东园主，春风可得知。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4712, 25, 86713, '585d11e961ff4b00580d86af', '杂歌谣辞郑樱桃歌', NULL, '李颀', '唐', '石季龙，僭天禄。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4713, 26, 105983, '585d292e128fe1006ba26fee', '偶游', NULL, '温庭筠', '唐', '曲巷斜临一水间，小门终日不开关。红珠斗帐樱桃熟，金尾屏风孔雀闲。云髻几迷芳草蝶，额黄无限夕阳山。与君便是鸳鸯侣，休向人间觅往还。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4714, 27, 106006, '585d29371b69e6005610b3e1', '题西平王旧赐屏风', NULL, '温庭筠', '唐', '曾向金扉玉砌来，百花鲜湿隔尘埃。披香殿下樱桃熟，结绮楼前芍药开。朱鹭已随新卤簿，黄鹂犹湿旧池台。世间刚有东流水，一送恩波更不回。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4743, 27, 145057, '585d57c1128fe1006de82873', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '何须赤脚踏层冰，细嚼徐吞得未曾。枝叶消归无用处，不妨还核与山僧。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4715, 28, 106165, '585d2980b123db0065a822da', '寒食节日寄楚望二首其二', NULL, '温庭筠', '唐', '家乏两千万，时当一百五。飔飔杨柳风，穰穰樱桃雨。年芳苦沈潦，心事如摧橹。金犊近兰汀，铜龙接花坞。青葱建杨宅，隐辚端门鼓。彩素拂庭柯，轻毬落邻圃。三春谢游衍，一笑牵规矩。独有恩泽侯，归来看楚舞。', 'shi', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4716, 29, 106756, '585d2a7c8d6d810065ddcac8', '采桑子', NULL, '冯延巳', '五代十国', '小堂深静无人到，满院春风，惆怅墙东，一树樱桃带雨红。愁心似醉兼如病，欲语还慵，日暮疏钟，双燕归栖画阁中。', 'ci', 154, '樱桃', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4717, 1, 11158, '57b8fa81d342d3005ac6fdb7', '过华清宫三首', NULL, '杜牧', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4719, 3, 11762, '57d96bfb2e958a00544ba921', '成都曲', NULL, '张籍', '唐', '锦江近西烟水绿，新雨山头荔枝熟。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4720, 4, 10234, '57ea0e6ea3413100624e8395', '浮生六记 · 卷四 · 浪游记快', NULL, '沈复', '清', '余游幕三十年来，天下所未到者，蜀中、黔中与滇南耳。', 'wen', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4721, 5, 25069, '585cd2aeac502e0067203f9e', '续演雅十诗', NULL, '白珽', '元', '八珍殽龙凤，此出龙凤外。荔枝配江䖴，徒夸有风味。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4723, 7, 42620, '585ce822570c35006930479a', '送方给事中', NULL, '徐贲', '元', '南风花满荔枝林，路出湖山百嶂深。惟有白云长在眼，三千里远寄归心。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4724, 8, 78562, '585d09328d6d810065dcaa87', '重寄荔枝与杨使君时闻杨使君欲种植故有落句之戏', NULL, '白居易', '唐', '摘来正带凌晨露，寄去须凭下水船。映我绯衫浑不见，对公银印最相鲜。香连翠叶真堪画，红透青笼实可怜。闻道万州方欲种，愁君得吃是何年。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4725, 9, 47658, '585cecfe8d6d810065dbd184', '题荔枝', NULL, '陶宗仪', '元', '大唐置驿贡遐方，火齐虬珠裹蔗浆。博得玉环才一笑，教坊曲奏荔枝香。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4726, 10, 51803, '585cf0b6b123db0065a64833', '虚斋赠四明王道士', NULL, '张翥', '元', '高斋闻在荔枝林，曲几方床宴坐深。大道无形元寓器，至人于物不容心。三山云气通寥泬，一室天光入照临。我欲壶中收药去，石田瑶草共相寻。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4727, 11, 67145, '585cfe42b123db0065a6b4b6', '到闽二首', NULL, '萨都剌', '元', '朔雪蛮烟总备尝，白头才到荔枝乡。浮云不阻怀贤意，得扫寒芜拜紫阳。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4728, 12, 67221, '585cfe5661ff4b0063f03c6c', '留别同年索士岩经历', NULL, '萨都剌', '元', '欲落不落天上雪，欲去不去闽中人。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4729, 13, 66709, '585cfdbb570c35006930f978', '寄', NULL, '萨都剌', '元', '舍人楚楚好容仪，玉立清朝白玉墀。紫袖窄衫花萼绕，黄金小带荔枝垂。彩旗拂柳春班卷，宫漏穿花午仗移。朝罢太平无事日，芙蓉叶上好题诗。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4730, 14, 83461, '585d0e70128fe1006ba1849f', '宴戎州杨使君东楼', NULL, '杜甫', '唐', '胜绝惊身老，情忘发兴奇。座从歌妓密，乐任主人为。重碧拈春酒，轻红擘荔枝。楼高欲愁思，横笛未休吹。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4731, 15, 69073, '585d003d61ff4b00688f0349', '马嵬', NULL, '魏初', '元', '春草坡前万马尘，麝香犹带荔枝新。思量前日盘中舞，含笑君王是路人。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4732, 16, 84485, '585d0f9a61ff4b0063f0c5a9', '解闷十二首（其九）', NULL, '杜甫', '唐', '先帝贵妃今寂寞，荔枝还复入长安。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4733, 17, 62039, '585cf9dc128fe1006de5425f', '茶荔谣', NULL, '熊鉌', '元', '阳春播一气，着处成芳菲。闽地本荒落，山川亦何奇。嬴刘始为郡，望秩暨武夷。通仕良鲜少，贡入还稀微。晚唐得常公，文化今有遗。国初归职方，况复兵革稀。圣化溥涵育，生生浩无涯。昭陵锐图治，四夷息鞭笞。峨峨四谏官，日晏犹彤墀。君谟起南服，感知无不为。芹曝犹欲献，茶贡讵非宜。草木贵多识，荔谱何伤而。岂意成滥觞，岁献妨耕犁。当年东坡老，作诗叹荔枝。诗语似成谶，采茶武夷溪。民力固甚惫，卉木且具腓。士人作是事，兴言痛心脾。闽溪何澍湃，闽山何嵚?。彼一草木秀，不惮勤航梯。昌黎感二鸟，世道矧益漓。我思全盛际，贤书连驲驰。公卿项背望，仄席须谋惟。十家九诗书，三年下芝泥。宣靖名节著，炎绍勋业资。乾淳道学称，人物世有之。大雅日以丧，迂阔贻世讥。茫茫宇宙内，此柄伊谁司。后生无典刑，流风砭人肌。皇天岂将老，伤哉相沦彝。地气有旺歇，回斡应何迟。百卉岁发荣，英杰生无时。风气谅有开，久矣斯人疲。武夷大隐山，自有百世师。来哲倘可俟，拳拳留此诗。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4734, 18, 103705, '585d25caac502e006722e9aa', '送杜秀才归', NULL, '许浑', '唐', '桂州南去与谁同，处处山连水自通。两岸晓霞千里草，半帆斜日一江风。瘴雨欲来枫树黑，火云初起荔枝红。愁君路远销年月，莫滞三湘五岭中。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4735, 19, 126408, '585d43da61ff4b0063f290cb', '封太常陈翁八十', NULL, '王世贞', '明', '圭组离尘格，烟霞见贵人。绣盘鸂鶒旧，金蹙荔枝新。鹤骨何妨瘦，霜毛已自鬒。问年方梦猎，有子旧批鳞。为恋舞衣乐，言辞补衮臣。桃源如度索，琴水好垂纶。歌妓青油舫，新篘白葛巾。过从无约束，含鼓任天真。一效庄生颂，看君比大椿。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4736, 20, 130154, '585d48021b69e6005611bb42', '闻伦穗石归诗以迓之', NULL, '王渐逵', '明', '苦忆春曹伦穗石，三秋不见愁年华。才夸海内怜闲扃，诗满江南识大家。归来且食端午粽，别移惊见新园花。更闻云谷荔枝熟，好栖越秀餐丹霞。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4737, 21, 145034, '585d57ba570c35006933cc0a', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '安居九夏足三冬，云影溪光紫翠重。树下枯禅成法喜，碧纱笼又绛纱封。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4738, 22, 145035, '585d57baac502e0067246a8a', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '赪霞红雨暗西江，饱食归来卧北窗。午过空林喧鸟雀，馀香散入碧油幢。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4739, 23, 145036, '585d57bb61ff4b0063f30d62', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '攀枝投石笑群儿，活剥生吞不待时。时过更愁零落尽，中间消息几人知。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4740, 24, 145043, '585d57bdda2f60006586401d', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '何堪紫陌逐红尘，独抱冰心懒赠人。若使桃花知此意，门前流水即迷津。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4741, 25, 145046, '585d57be128fe10069ce525f', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '细嚼凝冰沁肺肝，人间五月有新寒。何来褦襶门前客，赠与清凉散滞丹。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4742, 26, 145053, '585d57c061ff4b0063f30d76', '荔枝词三十首寄张子白杨鬯侯', NULL, '成鹫', '明', '夏云如火煮仙砂，白雪黄芽罩绛纱。僧老空林非所羡，碧天长日送流霞。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4775, 2, 11032, '57b9935e165abd005a6d2f52', '四时田园杂兴 其二十五', NULL, '范成大', '宋', '梅子金黄杏子肥，麦花雪白菜花稀。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4744, 28, 109035, '585d2d8e1b69e6006ccbb9c0', '荔枝树', NULL, '郑谷', '唐', '二京曾见画图中，数本芳菲色不同。孤棹今来巴徼外，一枝烟雨思无穷。夜郎城近含香瘴，杜宇巢低起暝风。肠断渝泸霜霰薄，不教叶似灞陵红。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4745, 29, 134076, '585d4c3bac502e0067242d1e', '东皋诗社', NULL, '王佐', '明', '东皋诗社海南边，每到相思在眼前。山屐踏残椰子雨，墅筵开趁荔枝天。竹篱茅舍偏多景，短咏长吟又几联。近日诗盟谁独步，徐陵孙子最豪颠。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4746, 30, 138057, '585d507eda2f600065861c3e', '长歌赠别高漫士赴召天京', NULL, '王恭', '明', '故人垂钓沧浪矶，故人雄词天下稀。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4747, 1, 629003, '583075cb67f35600634bf166', '食荔支二首（其二）', NULL, '苏轼', '宋', '罗浮山下四时春，卢橘杨梅次第新。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4748, 2, 10240, '57b908022e958a005fa583ea', '秋灯琐忆', NULL, '蒋坦', '清', '道光癸卯闰秋，秋芙来归。', 'wen', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4749, 3, 11758, '57d6b886128fe100553308c3', '上林赋', NULL, '司马相如', '汉', '亡是公听然而笑曰：「楚则失矣，而齐亦未为得也。', 'fu', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4750, 4, 25866, '585cd3b6da2f600065821e7e', '题束季博山园二十首', NULL, '牟巘', '元', '落落金弹丸，飞鸟不敢下。卢橘不到吴，杨梅同过夏。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4751, 5, 132787, '585d4ac6da2f60006585f851', '广落花诗三十首', NULL, '王夫之', '明', '春王推戴诧魁功，生杀乘权速转蓬。落魄早知亏月满，取精应悔竭春忠。杨梅孔雀丹心别，金谷河阳白首同。新绿可知霜刃在，尽情还与逼残红。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4752, 6, 97966, '585d1ec161ff4b00688ffefd', '赠乌程杨苹明府', NULL, '秦系', '唐', '策杖政成时，清溪弄钓丝。当年潘子貌，避病沈侯诗。漉酒迎宾急，看花署字迟。杨梅今熟未，与我两三枝。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4753, 7, 146070, '585d58e561ff4b00580fc193', '送陆子还洞庭', NULL, '朱九江', '明', '五月江门暑气鲜，水祠箫鼓赛龙船。最怜别权当官路，不碍归云入洞天。楼阁两山摇碧落，杨梅千涧泻红泉。葛裙纱帽吟长夏，莫拟平原赴洛篇。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4754, 8, 170489, '585d74c6128fe1006de8886e', '临平道中', NULL, '贝琼', '明', '三月六日好天气，临平湖上酒船开。青山如凿自高下，白云不收时去来。道上看花多踯躅，林间伐木到杨梅。如何也趁西风燕，远过钱塘又一回。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4755, 9, 171047, '585d756ada2f600065869f68', '送友人之延平', NULL, '周是修', '明', '别路三湘北，离人五岭西。成行愁夜雨，不寐听晨鸡。弦奏添惆怅，壶觞益惨悽。江分吴地阔，山界楚天低。潘岳尘应断，陶潜路岂迷。河阳花发遍，彭泽柳生齐。藉藉征途语，萧萧去马嘶。晓亭连戍垒，春树暗蛮溪。岸转杨梅落，林深谢豹啼。瓯闽王化远，望尔作云霓。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4756, 10, 175371, '585d7a8c8d6d810065df903a', '横塘寄徐昭法', NULL, '屈大均', '清', '雨过横塘水，人家湿暮烟。湖山深竹里，鸡犬落花边。昔至杨梅熟，今来莲叶圆。相思胥口月，之子在渔船。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4757, 11, 177321, '585d7d22ac502e006724da55', '庚午仲夏承大司马吴公招同诸公奉陪京卿张公宴集城西禅院次张公元韵四首并以送行', NULL, '屈大均', '清', '一水逐潮回，临流泛羽杯。玉珂花底散，银管柳边开。六箸仙人戏，双钩草圣才。荔枝题赋罢，更咏酒杨梅。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4758, 12, 197648, '585d95bd61ff4b0058105bab', '杨梅', NULL, '徐渭', '明', '湖水烛溪环，杨梅烂木难。白眉占西域，紫气满东关。掌露千丸饱，江萍一斗翻。荔枝吾记得，只在雁行间。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4759, 13, 242513, '585dd12461ff4b0063f49768', '和何彦正春耕十一首', NULL, '梁寅', '明', '业桑树边绿草坐，刺桐花下碧瓷杯。醉和农歌乐农暇，吴盐如雪点杨梅。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4760, 14, 275684, '585e02bf1b69e6006ccff853', '都下感事口号志喜六首', NULL, '欧大任', '明', '百万军储待闸开，冰鲜飞舸内官催。鲥鱼只为供时荐，卢橘杨梅岁岁来。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4762, 16, 267816, '585df5f661ff4b00581251dd', '村居春兴秋兴各十章俱步张孟奇园居韵春兴十首', NULL, '邓云霄', '明', '和风时雨万山春，花柳无边一色匀。处处醵钱沽社酒，村村伐鼓赛田神。生当尧舜升平日，赢得巢由自在身。最爱邻翁频献果，杨梅卢橘逐时新。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4763, 17, 300433, '585e289c1b69e60056164e72', '湟川舟中', NULL, '释今无', '明', '日沈碧水气佳哉，曲折波涛吼晚雷。唽呖鸟啼山大伯，高低石长水杨梅。船因买缆经时住，花为无人尽意开。路接雁回峰较近，干戈阻绝雁应回。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4764, 18, 374697, '585eab5c128fe1006df0429a', '蝶恋花 · 咏杨梅', NULL, '徐釚', '清', '纨扇生风人衣葛。', 'ci', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4765, 19, 341650, '585e6f501b69e6006cd33896', '尸位学署岑寂无聊泛泛随流迹近渔父每有闻见辄宣讴咏因名瀛涯渔唱', NULL, '朱仕玠', '清', '空思吴下摘杨梅，不见葡萄碧映苔。齿颊溅酸差强意，台疆六月熟黄来。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4766, 20, 353459, '585e862c570c3500693ad405', '金缕歌登道场山绝顶', NULL, '李符', '清', '雨洗春山好。', 'ci', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4767, 21, 382367, '585eb89db123db0065b1c01a', '浣溪纱', NULL, '陈衍', '清', '杜宇千山不可闻。', 'ci', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4768, 22, 432006, '585f13dfac502e00672d91e3', '戏方仁声四绝句', NULL, '叶梦得', '宋', '卢橘杨梅已及时，我归先自在前期。平生不作宣明面，浪愧将军建鼓旗。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4769, 23, 471666, '585f78de1b69e600561e0b81', '晚至灵峰', NULL, '周紫芝', '宋', '绿树千枝与万枝，灵峰寺里看杨梅。青山行尽且归去，红子熟时应再来。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4770, 24, 560775, '586042c2128fe1006df87301', '初夏二首', NULL, '舒邦佐', '宋', '卢橘金珠似，杨梅火齐如。燕衔春去后，蝉噪夏阴初。药访三年艾，心凝一束书。老身仍著病，节物最关渠。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4771, 25, 572247, '58605d101b69e6006cdd60dc', '玉壶饯客独赵达明末至云迓族长于龙山且谈道中事戏为纪之二首', NULL, '杨万里', '宋', '公子从来火伞中，解衣未定语匆匆。山行触热端何事，夹路杨梅树树红。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4772, 26, 585034, '5860807b61ff4b00630425d1', '暮春东阳道中寄乡里弟兄', NULL, '赵鼎臣', '宋', '天末题诗望故乡，碧云烟树两茫茫。青山九折屡回首，杜宇一声还断肠。别后已成千万恨，书来不寄两三行。江南春尽频相忆，为有杨梅欲共尝。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4773, 27, 525990, '585ff6ab128fe1006bb3516d', '门屋纳凉', NULL, '陆游', '宋', '机裂齐纨如素月，床敷蕲簟起微澜。行人远不分眉目，过鸟高犹响羽翰。新长庭槐夹门绿，无穷陂稻际天宽。今年项里杨梅熟，火齐骊珠已满盘。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4774, 1, 11054, '57b8ef6e165abd0054bf6163', '闲居初夏午睡起二绝句（其一）', NULL, '杨万里', '宋', '梅子留酸软齿牙，芭蕉分绿与窗纱。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4776, 3, 10397, '57b8b53a2e958a005fa43d74', '青玉案', NULL, '贺铸', '宋', '凌波不过横塘路，但目送、芳尘去。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4778, 5, 633467, '582c6f89a22b9d006b675f41', '天净沙 · 夏', NULL, '朱庭玉', '明', '参差竹笋抽簪，累垂梅子攒金，旋趁庭槐翠阴。', 'qu', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4779, 6, 10779, '57b9c0b15bbb500063f6275e', '满庭芳 · 夏日溧水无想山作', NULL, '周邦彦', '宋', '风老莺雏，雨肥梅子，午阴嘉树清圆。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4780, 7, 10233, '57ea0e6da22b9d006163db4c', '浮生六记 · 卷三 · 坎坷记愁', NULL, '沈复', '清', '人生坎坷何为乎来哉？', 'wen', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4781, 8, 30451, '585cd9558d6d810065db2aeb', '春夏承湖南佥宪兀颜子中问讯敬用酬上', NULL, '吴克恭', '元', '有客湖南去，闻公宪节新。坐沾梅子雨，忆别柳条春。衡岳瞻朱鸟，湘江咏绿蘋。升车访遗逸，问俗愿清淳。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4782, 9, 63410, '585cfae31b69e6006cca12e7', '点绛唇', NULL, '刘秉忠', '元', '寂寂珠帘，凤楼人去箫声住。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4783, 10, 74708, '585d056061ff4b0063f07489', '赠夏侯评事', NULL, '方干', '唐', '傍窥盛德与高节，缅想应无前后人。讲论参同深到骨，停腾姹女立成银。棋功过却杨玄宝，易义精于梅子真。朱紫侯门犹不见，可知岐路有风尘。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4784, 11, 44119, '585ce9cc128fe1006de4c0d6', '清平乐', NULL, '郯韶', '元', '湘云微度。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4785, 12, 31693, '585cdaef128fe1006de4405a', '赠南台察院椽修敬宗管叔坚还台', NULL, '李士瞻', '元', '东风吹雨春冥冥，荔子花残梅子青。游丝千尺遍江浒，愁挂离人留不住。三山中有神仙宅，玉树亭亭照颜色。去年相逢眼未知，今日相看重离别。修郎修郎多汝贤，曾陪骢马骖后先。气岸巉巉隔秋水，皎如宝镜悬青天。穾窍洞射幽隐辟，毫末悉露生光妍。骏如天马行长空，夭矫弗与凡骨同。快如俊鹘下旷野，搏击狡兔追莽风。近时上书于主将，意气横出冲晴虹。黄金台前马价高，旧时属椽俱英豪。如公脱落定应少，我有真眼过方皋。邂逅天涯即倾倒，北方之人信然好。红颜绿发当妙年，颀而长兮富文藻。明月之扇子所遗，上有名字谁其题。似欲南薰送北客，赠之寄尔长相思。故人新峨獬豸冠，神完气固方大观。神仙中人托为侣，彩鹢西去何翩翩。我今赠子青云裾，旋当与子催荐书。中台选曹定虚左，不负堂堂八尺躯。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4786, 13, 70502, '585d016061ff4b00688f0b9e', '赠道林训上人', NULL, '惟则', '元', '角鹰一侧目，所视无穹苍，臂鞲索饱非所长。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4787, 14, 134803, '585d4cf8570c3500693393c2', '五月', NULL, '文徵明', '明', '五月雨晴梅子肥，杏花吹尽燕飞飞。时光已到青团扇，士女新裁白苎衣。黄鸟故能供寂寞，绿阴何必减芳菲。子云自得幽居乐，不恨门前辙迹稀。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4788, 15, 116916, '585d385a1b69e6005611410f', '偶见', NULL, '韩偓', '唐', '秋千打困解罗裙，指点醍醐索一尊。见客入来和笑走，手搓梅子映中门。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4789, 16, 158864, '585d67368d6d810065df60d3', '春分日梅花一树盛开期伍有开过赏', NULL, '李孙宸', '明', '春暖家家梅子肥，梅花奇绝正芳菲。醉来纵作师雄梦，不怕寒风冷客衣。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4790, 17, 162431, '585d6af461ff4b0063f35298', '和吴匏庵姚氏园池四绝', NULL, '沈周', '明', '雨后春池漫石矶，樱桃梅子两争肥。东风试暖诸生假，间就沧浪浣旧衣。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4791, 18, 171741, '585d7625128fe1006ba433a9', '沽酒', NULL, '周用', '明', '一春白发斗丝长，无奈春归唤酒尝。日晒一林梅子熟，风吹满店柳花香。汉江初泼葡萄绿，银海频浮琥珀光。消得百年三万日，不妨还醉六千场。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4793, 20, 202761, '585d9c0f1b69e6005612cb00', '马姬馆赠梅子马', NULL, '徐熥', '明', '宝剑逢人脱赠轻，平生肝胆片言倾。千秋白社工文客，半世青楼薄幸名。枕上杨花今日泪，渡头桃叶旧时情。囊中不管黄金尽，犹买娇歌夜夜声。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4794, 21, 216586, '585dad8ada2f600065871b9e', '赠别梅子马督木北上', NULL, '袁中道', '明', '名士安卑官，居然有狂意。入甲岂非龙，何必垂天翅。祝融不受职，朝廷多灾异。我上救时策，官不录一字。书生徒苦心，报国恨无地。今尔督木来，勾当公家事。奔走莫云劳，小大皆朝吏。十月茱萸湾，相牵同一醉。官散束缚轻，何妨入酒肆。一倾三百杯，陶然卧垆次。万里从兹行，天风卷雪至。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4795, 22, 221920, '585db4fa8d6d810065e01998', '月节折杨柳歌十三首正月歌', NULL, '陈恭尹', '明', '寒消时未暑，梅子欲成黄，摽落当谁取。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4796, 23, 257986, '585de72c128fe1006ba5fc33', '梅花落四首', NULL, '杨慎', '明', '梅落复梅开，流光似流水。君心在梅花，妾意怜梅子。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4797, 24, 220646, '585db31f61ff4b006892b51c', '岁暮送区鱼山归香山', NULL, '陈恭尹', '明', '长将笔舌代耕芸，海岛焉能绝世尘。百里暂归贫有母，一年将尽老催人。潮光似火船头晓，梅子如珠屋角春。乱日相期无可祝，早占熊梦慰慈亲。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4798, 25, 276137, '585e0373ac502e0067277b49', '答史叔戴见寄', NULL, '欧大任', '明', '长裾狎贤豪，史公犹未遇。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4799, 26, 277952, '585e0601570c35006936eda0', '归舟怀善鄯广海未回', NULL, '刘炳', '明', '梅子黄垂雨霁，榴花红簇风轻。天际归舟何处，日暮柴门自扃。歌忆杯痕蚁绿，鬓怜镜影鸾青。心折少年尘梦，绛囊夜照流萤。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4800, 27, 295348, '585e205561ff4b006895bc90', '美人画眉歌', NULL, '瞿佑', '明', '妆阁晓寒愁独倚，蔷薇露滴胭脂水。粉绵磨镜不闻声，彩鸾影落瑶台里。镂金小合贮灯花，轻扫双蛾映脸霞。螺黛凝香传内院，猩毫染色妒东家。眼波流断横云偃，月样弯弯山样远。郎君走马游章台，惆怅无人问深浅。含情敛恨久徘徊，一脉闲愁未放开。侍女不知心内事，手搓梅子入帘来。', 'shi', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4801, 28, 303865, '585e2e1661ff4b00689621ea', '长相思', NULL, '顾若璞', '明', '梅子青，豆子青，飞絮飘飘长短亭。', 'ci', 157, '梅子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4802, 16, 637372, '5ae138e57f6fd30047f35b9d', ' 笠翁对韵 · 下卷 · 一先', NULL, '李渔', '清', '寒对暑，日对年。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4803, 17, 637373, '5ae1391da22b9d0040252dca', '笠翁对韵 · 下卷 · 二箫', NULL, '李渔', '清', '琴对管，釜对瓢。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
