INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4814, 28, 637384, '5ae13ab6ee920a67f6f5427c', '笠翁对韵 · 下卷 · 十三覃', NULL, '李渔', '清', '宫对阙，座对龛。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4815, 29, 637385, '5ae13af2ee920a25e88f932e', '笠翁对韵 · 下卷 · 十四盐', NULL, '李渔', '清', '宽对猛，冷对炎。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4816, 30, 637386, '5ae13b17ac502e2713d0a708', '笠翁对韵 · 下卷 · 十五咸', NULL, '李渔', '清', '栽对植，薙对芟。', 'wen', 153, '笠翁对韵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4817, 1, 234991, '585dc6d71b69e60056136b2a', '茄', NULL, '曹义', '明', '本草名传是落苏，个中滋味胜膻腴。老僧也爱田家好，写作山林野趣图。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4818, 2, 224135, '585db7d6da2f600065874224', '咏茄', NULL, '区大相', '明', '紫茄时被陇，舒叶自亏蔽。登君玉盘内，得耦嘉蔬味。结花讵能芳，垂实迥连带。虽微蹲鸱用，颇胜匏瓜系。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4819, 3, 20887, '585ccd26da2f60006581ef3f', '种茄', NULL, '王冕', '元', '种植便生地，还宜去草莱。所期羞膳具，毋吝日滋培。雨露恩时及，风霜气莫摧。且令根本固，看尔实恢恢。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4820, 4, 215375, '585dac048d6d810065dff827', '答送茄瓜', NULL, '陈献章', '明', '两头肥绿压肩斜，五月江园始送瓜。童子近前与翁语，小篮瓜底是新茄。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4821, 5, 252380, '585ddf31128fe1006dea196e', '紫茄五首', NULL, '董其昌', '明', '不敢怨无诗，秋当咏菊时。封关丸可弄，覆餗印何累。槐国分阴近，僬侥假盖迟。谁知谦吉意，更好助观颐。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4822, 6, 252378, '585ddf30ac502e00672658c0', '紫茄五首', NULL, '董其昌', '明', '纂纂称天茁，离离见土毛。知非丰岁宝，聊佐野夫饕。落处宁为瓠，投来颇类桃。米家图矮树，怪尔矗云高。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4823, 7, 252379, '585ddf31b123db0065ab724a', '紫茄五首', NULL, '董其昌', '明', '卑栖性所便，尺五即为天。每带胭脂色，来登玳瑁筵。江莼下豉美，蒟酱点庖鲜。能误青鞋客，忙趋过邵田。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4824, 8, 388903, '585ec38c1b69e6006cd54f06', '金瓜茄', NULL, '张若霳', '清', '不是东陵种，篱间别弄辉。冰纨澄夏簟，黄绢剪秋衣。承露鹅儿嫩，迎风杏子肥。依稀明月下，疑自凤池归。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4825, 9, 252377, '585ddf30da2f600065883551', '紫茄五首', NULL, '董其昌', '明', '欲辨嘉蔬种，应同藿食人。累垂贪结子，低亚巧藏身。被垄千苞坼，连畦万颗匀。清斋频撷取，老圃未生嗔。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4826, 10, 145386, '585d582d61ff4b00580fbe91', '紫白茄', NULL, '成鹫', '明', '紫岂夺朱，白可受采。并蒂连花，犍椎相会。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4828, 12, 68029, '585cff2c1b69e600560f5198', '题秋茄图', NULL, '钱选', '元', '忆昔毗山爱写生，瓜茄任我笔纵横。自怜老去翻成拙，学圃今犹学不成。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4829, 13, 215376, '585dac05ac502e006725406a', '答送茄瓜', NULL, '陈献章', '明', '同将形色委人间，窃比高松一鹤闲。口腹累人都未免，茄瓜篮里又诗还。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4830, 14, 252376, '585ddf2f61ff4b006893b8e2', '紫茄五首', NULL, '董其昌', '明', '何物昆仑种，曾经御苑题。似葵能卫足，非李亦成蹊。落实寻常味，攀条径寸低。玉盘如可荐，宁复怅云泥。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4832, 16, 354198, '585e87a4ac502e00672b8acc', '小茄园杂兴', NULL, '沈承瑞', '清', '良禽在高树，对语时关关。携朋坐其下，片云南山还。来去人无心，动静物自间。浩然春已暮，窗前绿不删。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4833, 17, 354199, '585e87a4b123db0065b099fe', '小茄园杂兴', NULL, '沈承瑞', '清', '少年采三秀，同心遗所思。臭味欲常好，聚散无定时。坐我绿窗下，风雨愁鸣鸡。菜根亦有香，弹铗者何为。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4834, 18, 354200, '585e87a58d6d810065e646f4', '小茄园杂兴', NULL, '沈承瑞', '清', '疏疏天上星，淡淡池中水。潜鱼静夜澜，明珠在波底。照见素人心，上下亿万里。纤云隔不住，大风吹不起。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4835, 19, 412181, '585eeca5b123db0065b22c11', '清波引烧茄', NULL, '赵熙', '清', '紫腴乡圃。', 'ci', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4840, 24, 389697, '585ec4e461ff4b00689a2fb8', '东风第一枝 · 园中摘茄', NULL, '曹溶', '清', '老子年来，犁锄手把，满襟浑是风雨。', 'ci', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4841, 25, 576154, '586066f2ac502e0067350ad0', '谢杨履道送银茄四首', NULL, '黄庭坚', '宋', '畦丁收尽垂露实，叶底犹藏十二三。待得银包已成谷，更当乞种过江南。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4842, 26, 314299, '585e3fca128fe1006ded156f', '客饟银茄不敢送场屋士', NULL, '方岳', '宋', '秋风谁怒水中蟹，昨梦不疑杯里蛇。迸齿清寒银粟粟，不随盐酪供毗耶。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4843, 27, 576152, '586066f0ac502e0067350acb', '谢杨履道送银茄四首', NULL, '黄庭坚', '宋', '君家水茄白银色，殊胜埧里紫彭亨。蜀人生疏不下箸，吾与北人俱眼明。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4844, 28, 223124, '585db682128fe10069cf4c09', '再咏茄和董玄宰太史', NULL, '区大相', '明', '名瓜不引蔓，囊粟未经陈。虽共彤胡荐，何曾玉箸亲。助羹餐不厌，抱瓮力常勤。君问登盘实，应知学圃人。', 'shi', 158, '茄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4846, 1, 496072, '585fb0bd1b69e6006cda58bd', '杏', NULL, '孙何', '宋', '殷红鄙桃艳，淡白笑梨花。落处飘微霰，繁时叠碎霞。苑宜开帝里，坛称在儒家。丽日明珠箔，清香袭绛纱。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4847, 2, 197535, '585d958eb123db0065aa2552', '杏', NULL, '徐渭', '明', '杏有海东红，珍高百品中。色来先压市，子大欲沈笼。酿苦蜂何为，人甘蠹亦同。道旁繁李树，好去问王戎。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4848, 3, 314017, '585e3f6d61ff4b0063f7e6f2', '杏', NULL, '方岳', '宋', '马令园中本，移来村墅中。太官令却献，黄帕不来封。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4849, 4, 155182, '585d630fac502e00672497d2', '杏', NULL, '吴宽', '明', '花信风寒已早来，隔墙俄见赤云堆。并头两树长相倚，屈指三春始得开。曲水少年谁复探，公门今日要兼栽。莫言结实供人啖，破核还堪作药材。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4850, 5, 72612, '585d0357570c350069312343', '杏花', NULL, '罗隐', '唐', '暖气潜催次第春，梅花已谢杏花新。半开半落闲园里，何异荣枯世上人。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5561, 130, 637832, '5b07becefb4ffe005bec0308', '壮士篇', NULL, '张华', '晋', '天地相震荡，回薄不知穷。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4851, 6, 85852, '585d10fe61ff4b0063f0d067', '杏园', NULL, '杜牧', '唐', '夜来微雨洗芳尘，公子骅骝步贴匀。莫怪杏园憔悴去，满城多少插花人。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4852, 7, 32941, '585cdc9e128fe1006de44cfc', '杏园', NULL, '李延兴', '元', '好花红白出邻墙，竞赏何妨到夕阳。探信屡逢金榜客，看梅稀出碧鸡坊。朝霞笼日绡衣薄，晴雪翻风珠酒香。我忆城东好庭馆，几陪诗老醉琼觞。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4853, 8, 93134, '585d18c11b69e6006ccafb66', '杏殇', NULL, '孟郊', '唐', '冻手莫弄珠，弄珠珠易飞。惊霜莫剪春，剪春无光辉。零落小花乳，斓斑昔婴衣。拾之不盈把，日暮空悲归。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4854, 9, 242068, '585dd0801b69e6005613a3db', '杏隐', NULL, '张羽', '明', '绛萼竞春华，丹光照似霞。虎眠应守榖，莺过每衔花。望处疑仙岛，移来是病家。写方看子坠，曝药避阴遮。山客留仁种，贫人寄劵赊。茂陵那解此，徒说枣如瓜。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4855, 10, 340395, '585e6ce9570c35006939fce8', '杏薄', NULL, '白孕彩', '清', '杏薄作瓜架，支撑两相宜。彼无支蔓苦，此无缠束辞。虽经恶风雨，愈信相扶持。瓜老充作薪，胜燃湿花枝。', 'shi', 159, '杏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4856, 1, 600262, '5860a642128fe10069e0804d', '柿红', NULL, '刘攽', '宋', '柿红梨紫漫山熟，冷雨萧萧落乔木。东田收谷亩数斛，筑场敛积高如屋。柴车斑斑黄犊健，丁男肩涧儿指秃。烹猪漉酒乐社神，急鼓悲笳断仍续。田家此乐何所忧，闾里至老还相收。道傍滞穗如山邱，何处老翁宁有求。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4857, 2, 535740, '58600c9c1b69e6006cdcb5d2', '朱柿', NULL, '张蕴', '宋', '慈恩分种远，骈实渥如丹。垂野华星大，然云火树寒。蟹螯徵有忌，狌血讶难抟。七绝虽堪赏，无劳把核钻。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4858, 3, 489385, '585fa02c128fe10069db5519', '忆古城柿', NULL, '洪适', '宋', '果园幽僻少能知，丹柿乌椑手自移。欲学郑虔书坠叶，何人解有寄来时。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4859, 4, 535691, '58600c7cb123db0065b946fe', '椑侯柿', NULL, '张澄', '宋', '家山谬说冷糖霜，未若椑侯远擅场。甘似醍醐成蜜汁，寒于玛瑙贮冰浆。学书博士空题叶，病渴文园却屡尝。不识梁侯底处所，虎贲要是似中郎。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4860, 5, 324876, '585e5218ac502e006729cd71', '大柿行', NULL, '王之道', '宋', '君不见郑虔学书晚弥笃，岁收柿叶贮三屋。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4861, 6, 336083, '585e64ef1b69e600561819fa', '秋日游柿岩', NULL, '王启座', '清', '鳞鳞霜信染丹枫，擘絮寒云万木空。九曲溪流青嶂里，一声樵唱乱山中。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4862, 7, 536528, '58600dd11b69e6006cdcb97e', '见柿树有感', NULL, '张九成', '宋', '兹山余初来，掩冉柿叶青。相去未三月，柿花亦已零。及兹寻去路，累累满空庭。人生岂无情，眷眷不忍行。严霜八九月，百草不复荣。唯君粲丹实，独挂秋空明。寄语看园翁，勿使堕秋风。愿比樱桃春，置之大明宫。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4863, 8, 597981, '5860a029128fe1006bb5c507', '谢陈佥惠红绿柿', NULL, '刘宰', '宋', '红绿分佳果，丹青让好辞。遥怜霜落叶，岸帻坐题诗。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4864, 9, 488921, '585f9ea5ac502e00673159a2', '和景严送方蒂柿', NULL, '洪适', '宋', '万株红叶咏光华，嘉实堆盘走绀车。方蒂宁同牛奶柿，朱唇应笑鸠盘茶。园官急送须足茧，童子争观多眼花。罗列林珍生饮兴，讵思辟谷更餐霞。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4865, 10, 515263, '585fddf9b123db0065b85884', '谢人惠三峰朱柿', NULL, '陈洎', '宋', '乌椑珍果益丹名，新折红林蒂尚青。浆冷夜凝仙掌露，味甘秋割楚江萍。圆堆玉碗樱难并，剩荐金樽酒易醒。应念茂陵消渴者，整篮封贮到云扃。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4866, 11, 569823, '58605679128fe1006df8a518', '谢赵行之惠霜柿', NULL, '杨万里', '宋', '红叶曾题字，乌椑昔擅场。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4867, 12, 568332, '58605338128fe1006df89b50', '以霜柿饷郑检法', NULL, '项安世', '宋', '发毛似霜纷纷白，心地如砂炯炯丹。细数诸公谁称此，陶窗居士最宜餐。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4868, 13, 580104, '58607102b123db0065ba5064', '柿熟园夫不采可嘉', NULL, '虞俦', '宋', '飞鸣争啄赪虬卵，木杪斜阳几点鸦。红叶堪书收拾取，不妨分付郑虔家。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4869, 14, 162852, '585d6b7161ff4b006cd4fe8f', '客遗山柿绐为玉兰戏而赋此', NULL, '沈周', '明', '有遗玉兰栽，云花备清馥。戒僮植深土，殷勤养根玉。秋霜己脱叶，挺挺条肄秃。识者曰山柿，盗名饵公欲。举世好相欺，牖耳多涂目。余性易信人，指马不知鹿。凭阑祗发笑，罪遗亦何足。谓信止豚鱼，未始及草木。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4870, 15, 108242, '585d2c5961ff4b00580e7465', '寺中柿树一蒂四颗咏应制', NULL, '广宣', '唐', '珍木生奇亩，低枝拂梵宫。因开四界分，本自百花中。当夏阴涵绿，临秋色变红。君看药草喻，何减太阳功。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4871, 16, 11641, '57baf335efa631005a7ffd71', '示福孙井示喜曾', NULL, '陆游', '宋', '北商久不通，犁枣罕登盘；', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4872, 17, 10234, '57ea0e6ea3413100624e8395', '浮生六记 · 卷四 · 浪游记快', NULL, '沈复', '清', '余游幕三十年来，天下所未到者，蜀中、黔中与滇南耳。', 'wen', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4873, 18, 11758, '57d6b886128fe100553308c3', '上林赋', NULL, '司马相如', '汉', '亡是公听然而笑曰：「楚则失矣，而齐亦未为得也。', 'fu', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4874, 19, 26326, '585cd42bda2f6000658220f6', '斋居', NULL, '成廷圭', '元', '晓起坐终日，无人扣竹扉。柿因风落早，菊为雨开迟。稚子能赊酒，邻翁许借诗。白头无别计，空负圣明时。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4875, 20, 20093, '585ccc06128fe1006b9f7a89', '奉谢杨山居宣慰寄遗茧纸', NULL, '王逢', '元', '明公枉珍遗，开缄霜雪色。自非玉女春，必假天孙织。剡藤失浮薄，海苔无光泽。元是秘府藏，亲向御手得。秋风柿叶馆，笔研久荒寂。飞来一朵云，列弟厌金碧。如何上所赐，波及沧浪客。焚香再封裹，还坐翻太息。盗发唐昭陵，无复晋墨迹。顾兹抱贞素，恬阅世代易。尚怜先代时，龙翰溢邦国。蚕缫尽输征，鹑结曾不惕。吾元本恭俭，世祖膺圣德。羊鞟代白麻，遂尔混区域。侈用几何年，离乱亦以极。明星烂河岳，鸡叫扶桑白。当写大宝箴，直上玉阶侧。讵敢轻点涴，令人却湔涤。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4876, 21, 59704, '585cf7abda2f6000658343ee', '送易用昭', NULL, '虞集', '元', '诗成长是倩人书，最爱东家织翠裾。远树断云春雨外，华星明月晚凉初。满窗柿叶题都遍，短帽梅花画不如。莫向墨池成久别，鹅群还欲谢崇虚。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4877, 22, 79185, '585d09ea61ff4b0063f097cc', '寄内', NULL, '白居易', '唐', '条桑初绿即为别，柿叶半红犹未归。不如村妇知时节，解为田夫秋捣衣。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4908, 2, 10242, '57dc269ec4c97100611cf6a0', '庄子 · 内篇 · 齐物论', NULL, '庄子', '周', '南郭子綦隐机而坐，仰天而嘘，荅焉似丧其耦。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4909, 3, 10243, '57b90b76df0eea00633532de', '庄子 · 内篇 · 养生主', NULL, '庄子', '周', '吾生也有涯，而知也无涯。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4878, 23, 96544, '585d1cb761ff4b00688fec2b', '和薛先辈见寄初秋寓怀即事之作二十韵', NULL, '韦庄', '唐', '玉律初移候，清风乍远襟。一声蝉到耳，千炬火然心。岳静云堆翠，楼高日半沉。引愁憎暮角，惊梦怯残砧。露白凝湘簟，风篁韵蜀琴。鸟喧从果烂，阶净任苔侵。柿叶添红景，槐柯减绿阴。采珠逢宝窟，阅石见瑶林。鲁殿铿寒玉，苔山激碎金。郤堂流桂景，陈巷集车音。名自张华显，词因葛亮吟。水深龙易失，天远鹤难寻。鉴貌宁惭乐，论才岂谢任。义心孤剑直，学海怒涛深。既睹文兼质，翻疑古在今。惭闻纡绿绶，即候挂朝簪。晚树连秋坞，斜阳映暮岑。夜虫方唧唧，疲马正骎骎。托迹同吴燕，依仁似越禽。会随仙羽化，香蚁且同斟。', 'shi', 160, '柿子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4879, 1, 10019, '57b91bcf8ac2470062e076a0', '项脊轩志', NULL, '归有光', '明', '项脊轩，旧南阁子也。', 'wen', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4881, 3, 11758, '57d6b886128fe100553308c3', '上林赋', NULL, '司马相如', '汉', '亡是公听然而笑曰：「楚则失矣，而齐亦未为得也。', 'fu', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4882, 4, 15457, '585cc5e78d6d810065daa0c2', '五月六日晴芮君节卞西仲诸友来泛蒲和韵', NULL, '仇远', '元', '端午凄凉雨压城，忽然端六报新晴。素衣尘暗行人老，绿树阴浓曙日明。倦眼冥冥浑似雾，忧心悄悄只如酲。枇杷荐酒犹堪醉，杏子微酸尚带生。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4883, 5, 34753, '585cdeaa128fe1006de45d13', '写怀寄吴下一二知己', NULL, '周砥', '元', '朔风吹庭树，寒雨集杨园。此时怀故旧，悽怆不可言。忆向吴门道，挟书访遗老。两公即相知，把袂日倾倒。别来今几龄，白日不留停。五见枇杷树，开花拂草亭。相思乱心绪，摇摇无定处。飘若天上云，随风忽东去。知君卧紫烟，清真如晋贤。手持玉麈尾，相对谈重玄。我若不得志，岩居非本意。宝匣剑空鸣，金尊日长醉。吐气如长虹，古人敢追踪。子云天禄阁，宋玉兰台宫。奈何出门去，荆棘满中路。当伺天□□，骑龙跃云雾。君非知我深，何能说胸襟。聊兹写情素，非为庄舄吟。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4884, 6, 87988, '585d133061ff4b00688f9b8e', '赴嘉州过城固县寻永安超禅师房', NULL, '岑参', '唐', '满寺枇杷冬著花，老僧相见具袈裟。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4885, 7, 76559, '585d072d61ff4b00580d2e4f', '寄蜀中薛涛校书', NULL, '王建', '唐', '万里桥边女校书，枇杷花里闭门居。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4886, 8, 160689, '585d691d61ff4b00580ffb2f', '枇杷晚翠', NULL, '李昌祺', '明', '江南有佳植，名列果品中。仙郎乃独好，官舍亲培封。亭亭异众卉，秀茂当严冬。深绿冷逾茂，繁青寒更浓。满树叶葱茜，阴森密成丛。岁晏不改色，傲睨雪与风。所以玩物者，爱比松柏同。灌溉役舆隶，赋咏劳群公。人物两奇特，永言播无穷。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4887, 9, 168166, '585d71b31b69e600561271a4', '春日寄题崔学士后渠书屋七首', NULL, '李梦阳', '明', '赋笔多崔瑗，朋车愧吕安。碧渠何日到，云树一春看。南果枇杷活，西郊苜蓿宽。觅君终系马，舣棹是何滩。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4888, 10, 203829, '585d9d79128fe10069cf0195', '除夜', NULL, '孙蕡', '明', '大地白雪似白沙，游子况复未归家。寒云黯淡暗海曲，春风浩荡来天涯。楚山卢橘渐舒叶，故园枇杷应着花。未得乘船出江口，枯坐旅邸如春蛙。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4890, 12, 273495, '585dfeeb128fe1006deb0c05', '初夏答友人', NULL, '欧大任', '明', '辛夷花过客来稀，篱落萧然独掩扉。梅雨欲晴收药去，柘烟初起买茶归。林香山户枇杷熟，水腻池塘属玉肥。别后沈郎腰更瘦，病来浑欲不胜衣。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4891, 13, 335642, '585e6433570c35006939b575', '遇陈王', NULL, '毛奇龄', '清', '枇杷花里谁家院，近丛坛。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4892, 14, 331385, '585e5ce761ff4b0068978411', '林素园居士以诗僧见称却赋', NULL, '巨赞', '清', '枇杷树下泪如绳，柳絮沾泥只自矜。色见声求无一是，耻为人唤作诗僧。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4893, 15, 333179, '585e5fc5128fe10069d422c8', '夏云峰二首', NULL, '王时翔', '清', '淡晴天。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4894, 16, 350769, '585e811d61ff4b005816971a', '长亭怨慢悼顾莺娘为鹿潭作', NULL, '杜文澜', '清', '最凄绝、枇杷门户。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4895, 17, 355758, '585e8a8a61ff4b006899001c', '宴琼林', NULL, '汪东', '当代', '休沐遇良辰，爱第一名园，堪避炎夏。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4896, 18, 374836, '585eaba38d6d810065e739f4', '无题', NULL, '徐嘉干', '清', '凤凰枝上绿云深，甲煎香烧似水沉。鹦鹉帘栊春盎盎，枇杷门巷昼阴阴。三年有刺犹怀袖，一柱无弦欲碎琴。风断罗浮残绮梦，缟衣隐约杳难寻。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4897, 19, 358812, '585e901661ff4b0068992ae5', '望海潮 · 蜀都赋', NULL, '周岸登', '清', '江山天堑，提封天府，华阳黑水梁州。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4898, 20, 359103, '585e90b31b69e60056198a41', '南柯子 · 代元草堂诗馀王从叔', NULL, '周岸登', '清', '薄酒禁愁重，遥山压恨低。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4899, 21, 363658, '585e98fc128fe1006bab77bd', '往岁郑太夷丈居江南督幕赋枇杷诗绝爱之顷来大通督销局所见殊夥欲去乃题此', NULL, '林旭', '清', '荒洲风物见枇杷，青实茸茸指有加。欲傍小轩题晚翠，已成昨日忆天涯。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4900, 22, 349387, '585e7e938d6d810065e5f9c9', '桂枝香忆往', NULL, '李良年', '清', '粉墙如雪。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4901, 23, 355067, '585e8927128fe1006bab02e2', '吴公绅索洞庭游稿赋此寄之', NULL, '汪琬', '清', '平生爱山看不足，支颐远望西山麓。今年身似不羁鹤，竟理飞帆挈行襆。山中佳处推石公，俯视群峰皆婢仆。怪奇自是惊心魂，秀丽真能扑眉目。橘林璀灿步障锦，云峦宛转屏风绿。天风不起镜流平，展尽生绡三百幅。老僧知我非生人，炒栗煮茶频见肃。枇杷花开雪满路，点缀衣巾犹馥馥。危桥夭矫曲洞幽，别束行縢恣探逐。洞里仙人不我瞋，遍启窗棂驱蝙蝠。数堆石髓堪采吃，味美胜餐玄圃玉。从今解笑嵇叔夜，俗骨尘缘无此福。归来恍惚梦中游，欲记旋忘什五六。明春约君共长往，拂石更题招隐曲。', 'shi', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4902, 24, 354757, '585e889c128fe10069d57d9b', '夏初临怀覃九侄', NULL, '沈皞日', '清', '蟋蟀窗前，枇杷栏下，碧窗倩画蟾纱。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4903, 25, 382224, '585eb85561ff4b00689a0e2f', '满江红 · 江村夏咏', NULL, '陈维崧', '清', '天水空蒙，芦花内、茆庵一个。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4904, 26, 382749, '585eb9271b69e6006cd530c7', '水龙吟 · 枇杷词旧无传作，梁溪舟中，偶一为之', NULL, '陈锐', '清', '果林翠晚山深，梅肥时节初过了。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4905, 27, 400233, '585ed7821b69e600561ab069', '浪淘沙 · 不见', NULL, '曾廉', '清', '湖上问苏家。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4906, 28, 401449, '585ed993570c3500693c59ff', '洞仙歌', NULL, '程颂万', '清', '酒阑人并，把银筝微弄。', 'ci', 161, '枇杷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4907, 1, 10241, '57b9029bc4c97100558f32ce', '庄子 · 内篇 · 逍遥游', NULL, '庄子', '周', '北冥有鱼，其名为鲲。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4911, 5, 10245, '57ea0e758ac247005be1583b', '庄子 · 内篇 · 德充符', NULL, '庄子', '周', '鲁有兀者王骀，从之游者与仲尼相若。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4912, 6, 10246, '57ea0e75a22b9d006163de67', '庄子 · 内篇 · 大宗师', NULL, '庄子', '周', '知天之所为，知人之所为者，至矣！', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4913, 7, 10247, '57ea0e76c4c971005f80acdd', '庄子 · 内篇 · 应帝王', NULL, '庄子', '周', '啮缺问于王倪，四问而四不知。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4914, 8, 634385, '58b5c51961ff4b006cca70ed', '庄子 · 外篇 · 骈拇', NULL, '无名氏', '周', '骈拇枝指，出乎性哉！', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4915, 9, 637396, '5ae28c01fe88c2003819fd55', '庄子 · 外篇 · 马蹄', NULL, '无名氏', '周', '马，蹄可以践霜雪，毛可以御风寒，龁草饮水，翘足而陆，此马之真性也。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4916, 10, 637397, '5ae28c2e9f545400437d47b1', '庄子 · 外篇 · 胠箧', NULL, '无名氏', '周', '将为胠箧探囊发匮之盗而为守备，则必摄缄縢，固扃谲，此世俗之所谓知也。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4917, 11, 637398, '5ae28dc4a22b9d004400f3ca', '庄子 · 外篇 · 在宥', NULL, '无名氏', '周', '闻在宥天下，不闻治天下也。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4918, 12, 637399, '5ae28e31a22b9d004400f628', '庄子 · 外篇 · 天地', NULL, '无名氏', '周', '天地虽大，其化均也；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4919, 13, 637400, '5ae28e7a9f5454005ea87fa0', '庄子 · 外篇 · 天道', NULL, '无名氏', '周', '天道运而无所积，故万物成；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4920, 14, 637401, '5ae28e9f9f545400437d5931', '庄子 · 外篇 · 天运', NULL, '庄子', '周', '“天其运乎？', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4921, 15, 637402, '5ae28ee70b616000757de68d', '庄子 · 外篇 · 刻意', NULL, '无名氏', '周', '刻意尚行，离世异俗，高论怨诽，为亢而已矣；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4922, 16, 637409, '5ae3dbf80b6160007584f796', '庄子 · 外篇 · 缮性', NULL, '无名氏', '周', '缮性于俗学，以求复其初；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4923, 17, 637410, '5ae3dc2b7f6fd30038448264', '庄子 · 外篇 · 秋水', NULL, '庄子', '周', '秋水时至，百川灌河，泾流之大，两涘渚崖之间，不辨牛马。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4924, 18, 637411, '5ae3de617f6fd300384491a3', '庄子 · 外篇 · 至乐', NULL, '无名氏', '周', '天下有至乐无有哉？', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4925, 19, 637412, '5ae3dea29f5454004006a9f2', '庄子 · 外篇 · 达生', NULL, '无名氏', '周', '达生之情者，不务生之所无以为；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4926, 20, 637413, '5ae3dfc49f5454005eafb803', '庄子 · 外篇 · 山木', NULL, '无名氏', '周', '庄子行于山INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4927, 21, 637414, '5ae3dffeac502e00625fe02d', '庄子 · 外篇 · 田子方', NULL, '无名氏', '周', '田子方侍坐于魏文侯，数称溪工。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4928, 22, 637416, '5ae3e031ac502e00625fe1ae', '庄子 · 外篇 · 知北游', NULL, '庄子', '周', '知北游于玄水之上，登隐弅之丘，而适遭无为谓焉。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4929, 23, 637417, '5ae3e055ee920a00430a1c8b', '庄子 · 杂篇 · 庚桑楚', NULL, '无名氏', '周', '老聃之役有庚桑楚者，偏得老聃之道，以北居畏垒之山，其臣之画然知者去之，其妾之挈然仁者远之；', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4930, 24, 637418, '5ae3e0fea22b9d0044082886', '庄子 · 杂篇 · 徐无鬼', NULL, '无名氏', '周', '徐无鬼因女商见魏武侯，武侯劳之曰：“先生病矣，苦于山林之劳，故乃肯见于寡人。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4931, 25, 637419, '5ae3e131ee920a00430a25c2', '庄子 · 杂篇 · 则阳', NULL, '无名氏', '周', '则阳游于楚，夷节言之于王，王未之见。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4932, 26, 637420, '5ae3e1529f5454005eafc4eb', '庄子 · 杂篇 · 外物', NULL, '无名氏', '周', '外物不可必，故龙逢诛，比干戮，箕子狂，恶来死，桀纣亡。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4933, 27, 637421, '5ae3e17d9f5454004384985e', '庄子 · 杂篇 · 寓言', NULL, '无名氏', '周', '寓言十九，重言十七，卮言日出，和以天倪。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4934, 28, 637422, '5ae3e19c17d0090066f275bd', '庄子 · 杂篇 · 让王', NULL, '无名氏', '周', '尧以天下让许由，许由不受。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4935, 29, 637423, '5ae3e1bf9f5454003f108c5d', '庄子 · 杂篇 · 盗跖', NULL, '无名氏', '周', '孔子与柳下季为友，柳下季之弟，名曰盗跖。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4936, 30, 12362, '581764ec5bbb500059b21b91', '庄子 · 杂篇 · 说剑', NULL, '无名氏', '周', '昔赵文王喜剑，剑士夹门而客三千馀人，日夜相击于前，死伤者岁百馀人，好之不厌。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4937, 31, 634189, '58abd23e1b69e6006c11b646', '庄子 · 杂篇 · 渔父', NULL, '无名氏', '周', '孔子游于缁帷之林，休坐乎杏坛之上。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4938, 32, 637424, '5ae3e210ac502e00625fee89', '庄子 · 杂篇 · 列御寇', NULL, '无名氏', '周', '列御寇之齐，中道而反，遇伯昏瞀人。', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4939, 33, 637426, '5ae3e247ee920a00430a2d39', '庄子 · 杂篇 · 天下', NULL, '无名氏', '周', '天下之治方术者多矣，皆以其有为不可加矣！', 'wen', 162, '庄子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4940, 1, 637432, '5ae717bd9f5454004019a204', '史记 · 十二本纪 · 五帝本纪', NULL, '司马迁', '汉', '黄帝者，少典之子，姓公孙，名曰轩辕。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4941, 2, 637434, '5ae71831fe88c2003834426c', '史记 · 十二本纪 · 夏本纪', NULL, '司马迁', '汉', '夏禹，名曰文命。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4942, 3, 637435, '5ae718c99f5454003f237157', '史记 · 十二本纪 · 殷本纪', NULL, '司马迁', '汉', '殷契，母曰简狄，有娀氏之女，为帝喾次妃。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4943, 4, 637436, '5ae71d9aa22b9d00441b4780', '史记 · 十二本纪 · 周本纪', NULL, '司马迁', '汉', '周后稷，名弃。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4944, 5, 637444, '5ae837a69f545400439d661d', '史记 · 十二本纪 · 秦本纪', NULL, '司马迁', '汉', '造父受封INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4945, 6, 637445, '5ae8391e9f545400401f8d60', '史记 · 十二本纪 · 秦始皇本纪', NULL, '司马迁', '汉', '秦始皇帝者，秦庄襄王子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4946, 7, 637446, '5ae839e9ac502e006278b6db', '史记 · 十二本纪 · 项羽本纪', NULL, '司马迁', '汉', '项籍者，下相人也，字羽。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4948, 9, 637448, '5ae83ce22f301e003df86ebc', '史记 · 十二本纪 · 吕太后本纪 ', NULL, '司马迁', '汉', '吕太后者，高祖微时妃也，生孝惠帝、女鲁元太后。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4949, 10, 637449, '5ae83d6ca22b9d0044213e31', '史记 · 十二本纪 · 孝文本纪', NULL, '司马迁', '汉', '孝文皇帝，高祖中子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4950, 11, 637450, '5ae83dfca22b9d00442141f3', '史记 · 十二本纪 · 孝景本纪', NULL, '司马迁', '汉', '孝景皇帝者，孝文之中子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4951, 12, 637451, '5ae83f907f6fd300385dd494', '史记 · 十二本纪 · 孝武本纪', NULL, '司马迁', '汉', '孝武皇帝者，孝景中子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4952, 13, 637453, '5ae840200b616000759e2291', '史记 · 十表 · 三代世表', NULL, '司马迁', '汉', '太史公曰：五帝、三代之记，尚矣。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4953, 14, 637454, '5ae8407f9f545400401fbf83', '史记 · 十表 · 十二诸侯年表', NULL, '司马迁', '汉', '太史公读春秋历谱谍，至周厉王，未尝不废书而叹也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4954, 15, 637455, '5ae840df9f545400401fc1e1', '史记 · 十表 · 六国年表', NULL, '司马迁', '汉', '太史公读秦记，至犬戎败幽王，周东徙洛邑，秦襄公始封为诸侯，作西畤用事上帝，僭端见矣。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4955, 16, 637456, '5ae8414da22b9d004421582a', '史记 · 十表 · 秦楚之际月表', NULL, '司马迁', '汉', '太史公读秦楚之际，曰：初作难，发于陈涉；', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4956, 17, 637457, '5ae8421d17d00900660b6dc6', '史记 · 十表 · 汉兴以来诸侯王年表', NULL, '司马迁', '汉', '太史公曰：殷以前尚矣。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4957, 18, 637458, '5ae843159f5454005ec8d25b', '史记 · 十表 · 高祖功臣侯者年表', NULL, '司马迁', '汉', '太史公曰：古者人臣功有五品，以德立宗庙定社稷曰勋，以言曰劳，用力曰功，明其等曰伐，积日曰阅。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4958, 19, 637459, '5ae843922f301e003df89dfe', '史记 · 十表 · 惠景间侯者年表', NULL, '司马迁', '汉', '太史公读列封至便侯曰：有以也夫！', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4959, 1, 637460, '5ae848159f545400401feee8', '孤山月下看梅花', NULL, '高濂', '明', '孤山旧址，逋老种梅三百六十，已废；', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4960, 2, 637461, '5ae8482f2f301e003df8bb2c', '八卦田看菜花', NULL, '高濂', '明', '宋之籍田，以八卦爻画沟塍，圈布成象，迄今犹然。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4961, 3, 637462, '5ae84849fe88c200383a86c3', '虎跑泉试新茶', NULL, '高濂', '明', '西湖之泉，以虎跑为最；', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4962, 4, 637463, '5ae8486a0b616000759e574a', '保俶塔看晓山', NULL, '高濂', '明', '山翠绕湖，容态百逞，独春朝最佳。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4963, 5, 637464, '5ae848859f545400401ff17e', '西溪楼啖煨笋', NULL, '高濂', '明', '西溪竹林最多，笋产极盛。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4964, 6, 637465, '5ae8489c7f6fd300385e0f17', '登东城望桑麦', NULL, '高濂', '明', '桑麦之盛，惟东郊外最阔，田畴万顷，一望无际。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4965, 7, 637466, '5ae848b09f545400439dda74', '三塔基看春草', NULL, '高濂', '明', '湖中三塔寺基，去湖面浅尺。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4966, 8, 637467, '5ae848ca9f545400401ff2e6', '初阳台望春树', NULL, '高濂', '明', '西湖三面绕山，东为城市，春来树色新丰，登台四眺，浅深青碧，色态间呈，高下参差，面面回出。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4967, 9, 637468, '5ae848e9ee920a00432365ec', '山满楼观柳', NULL, '高濂', '明', '苏堤跨虹桥下东数步，为余小筑数椽，当湖南面，颜曰“山满楼”。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4968, 10, 10407, '57b9d22b0a2b58006cb1208a', '苏堤看桃花', NULL, '高濂', '明', '六桥桃花，人争艳赏，其幽趣数种，赏或未尽得也。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4969, 11, 637469, '5ae84913a22b9d0044218b3e', '西泠桥玩落花', NULL, '高濂', '明', '三月桃花，苏堤落瓣，因风荡漾，逐水周流，飘泊孤踪，多在西泠桥畔堆叠。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4970, 12, 637470, '5ae849290b616000759e5bf4', '天然阁上看雨', NULL, '高濂', '明', '灵雨霏霏，乍起乍歇；', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4971, 13, 637471, '5ae849812f301e003df8c299', '苏堤看新绿', NULL, '高濂', '明', '三月中旬，堤上桃柳新叶，黯黯成阴，浅翠娇青，笼烟惹湿。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4972, 14, 637472, '5ae8499a9f5454005ec8fa85', '东郊玩蚕山', NULL, '高濂', '明', '初成蚕箔，白茧团团，玉砌银铺，高下丛簇，丝联蓓蕾，俨对雪峤生寒，冰山耀日。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4973, 15, 637473, '5ae849ac17d00900660b9f70', '三生石谈月', NULL, '高濂', '明', '中竺后山，鼎分三石，居然可坐，传为泽公三生遗迹。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4974, 16, 10406, '57bc2fcba633bd005d40caff', '飞来洞避暑', NULL, '高濂', '明', '灵鹫山下，岩洞玲珑，周回虚敞，指为西域飞来一小岩也。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4975, 17, 637474, '5ae849df7f6fd300385e1631', '压堤桥夜宿', NULL, '高濂', '明', '桥据湖中，下种红白莲花，方广数亩，夏日清芬，隐隐袭人。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4976, 1, 10411, '57b910e7d342d3005ac7ab2a', '凉州词二首 · 其一', NULL, '王翰（子羽）', '唐', '葡萄美酒夜光杯，欲饮琵琶马上催。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4978, 3, 11300, '57b9a8e3c4c97100614726b3', '襄阳歌', NULL, '李白', '唐', '落日欲没岘山西，倒著接蓠花下迷。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4979, 4, 10819, '57b8af2e7db2a200542588c8', '贺新郎', NULL, '叶梦得', '宋', '睡起流莺语，掩苍苔房栊向晚，乱红无数。', 'ci', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4980, 5, 10234, '57ea0e6ea3413100624e8395', '浮生六记 · 卷四 · 浪游记快', NULL, '沈复', '清', '余游幕三十年来，天下所未到者，蜀中、黔中与滇南耳。', 'wen', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4981, 6, 28329, '585cd6ca61ff4b00688db715', '和散里平章游东安汪伯谅半山亭诗韵', NULL, '何景福', '元', '丹溪青山冠闽浙，胜游忽聚金台客。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4982, 7, 21438, '585ccddb128fe10069ca049c', '大醉歌', NULL, '王冕', '元', '明月珠，不可襦。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4983, 8, 58558, '585cf6ab8d6d810065dc20a0', '酒', NULL, '黄复圭', '元', '曲糵生香出小槽，几人耽酗日陶陶。笑吞鹦鹉杯中月，贫与鹔鹴花下袍。内府腊传红琥珀，西京秋压紫葡萄。杜康仪狄今安在，回首丘陵半是糟。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4984, 9, 28448, '585cd6f6b123db0065a57274', '赠樊秀才', NULL, '吴当', '元', '忆昨承恩乞鉴湖，几回清梦谒神都。葡萄天马来边徼，粳稻云帆出越吴。旸谷吠晨惊蜀犬，神祠乘夜托城狐。龙钟卧病空筹策，万里云霄羽翮孤。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4985, 10, 43796, '585ce9811b69e600560ea64b', '题曾省元藏温日观葡萄后用温师韵', NULL, '陆居仁', '元', '黄金台壮帝王州，我亦曾为汗漫游。不入凤池鹓鹭序，依然天地一沙鸥。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4986, 11, 62638, '585cfa5661ff4b00580ccd0c', '苏幕遮 · 春情', NULL, '赵文', '宋', '绿秧平，烟树远，村燕声喧，凫雁归来晚。', 'ci', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4988, 13, 65311, '585cfc8b61ff4b006cd1e519', '葡萄', NULL, '郑允端', '元', '满筐圆实骊珠滑，入口甘香冰玉寒。若使文园知此味，露华应不乞金盘。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4989, 14, 68889, '585d0011128fe10069cb9619', '松酿酒', NULL, '谢宗可', '元', '大夫何事亦餔糟，自恨争名爝火劳。春色未香浮蚁绿，雨声先沸老龙膏。不须琥珀供灵药，且作珍珠滴小槽。傲却岁寒消一醉，凉州空自换葡萄。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4990, 15, 72925, '585d03a3ac502e006721c406', '诗', NULL, '捧剑仆', '唐', '青鸟衔葡萄，飞上金井栏。美人恐惊去，不敢卷帘看。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4991, 16, 44977, '585ceab81b69e6006cc99144', '踏云行 · 葡萄', NULL, '马钰', '金', '根蒂蟠虬，龙须围绕。', 'ci', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5562, 131, 637833, '5b07bf0e2f301e003802fe7d', '秦女卷衣', NULL, '李白', '唐', '天子居未央，妾侍卷衣裳。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4992, 17, 45932, '585ceb858d6d810065dbc5ad', '赠叶洞春画葡萄', NULL, '陈普', '元', '引蔓牵藤寸管头，扶骊剔蚌出风流。三千龙女抛珠佩，一个儒生拥碧油。莫是前生封即墨，便堪作酒博青州。齐奴倘会清妍意，免得红裙逐翠楼。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4996, 21, 127323, '585d44ea1b69e6006ccc843e', '罢官杂言则鲍明远体十章', NULL, '王世贞', '明', '饮用葡萄九酝清泠之美酒，焚用都梁百和旖旎之妙香。骑用金錽流铃蹑恍之宛马，坐用垂苏浑银平脱之胡床。博场姬馆使意气，东郊南陌争辉光。顾谓竖儒子安用，终日仰面看屋梁。胸中贮书千万卷，两人担将瘗北邙。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4997, 22, 127262, '585d44c461ff4b006cd4476c', '金吾行赠戴锦衣', NULL, '王世贞', '明', '金吾缇骑不可当，迥若饥鹘搏大荒。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (4998, 23, 125027, '585d422f8d6d810065de99e2', '赠别于鳞还邢州', NULL, '王世贞', '明', '葡萄美酒玉壶寒，写向离筵泪并残。纵有隋珠高月色，不知中夜向谁看。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5000, 25, 166390, '585d6f9b570c350069341c28', '少年行赠李都尉', NULL, '李时行', '明', '翩翩侠气五陵豪，几过屠沽问宝刀。坐控金羁驰騕袅，笑倾玉碗醉葡萄。听莺乐处春风满，猎兔归时夜月高。还向红楼试歌舞，不知酒污锦宫袍。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5001, 26, 168424, '585d720d128fe1006de87f1c', '葡萄', NULL, '李梦阳', '明', '旧干疏曾讶，新条密更垂。苑花深悄悄，风叶漫披披。马乳秋同摘，龙须世岂知。相传自西域，种杂至今疑。', 'shi', 165, '葡萄', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5002, 1, 42720, '585ce83d128fe1006de4b35a', '菜薖为永嘉余唐卿右司赋', NULL, '徐贲', '元', '远辞华盖居，来卜山阴宅。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5003, 2, 76613, '585d073d61ff4b00688f3b1b', '宫词一百首', NULL, '王建', '唐', '鱼藻宫中锁翠娥，先皇行处不曾过。如今池底休铺锦，菱角鸡头积渐多。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5004, 3, 80646, '585d0ba01b69e6006cca9012', '咏兴五首·解印出公府', NULL, '白居易', '唐', '小庭亦有月，小院亦有花。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5005, 4, 146446, '585d5953ac502e00672471cb', '寄李德馨同年', NULL, '江源', '明', '客馆张灯拟论文，我来何事不逢君。九江道里愁听雨，五老峰前独看云。联句尚怀高阁会，探花曾逐□年群。端阳更拟洪都约，白酒红菱角忝新。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5006, 5, 159606, '585d68031b69e6006ccd31fa', '西湖竹枝歌五首', NULL, '李昱', '明', '菱角钩衣为出尖，莲心苦口却回甜。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5007, 6, 248478, '585dd98e61ff4b0058117ff4', '题刘推府湖山归隐诗卷', NULL, '童轩', '明', '湖山苍苍湖水绿，灌木垂萝远尘俗。高人小隐住湖东，坐对江南秋一幅。昔年宾兴歌鹿鸣，平步青云被推毂。一官佐郡粤南陲，才大位卑羞碌碌。晨餐束带谒官长，夜火照书谳疑狱。秋霜欺人发种种，老境渐临如缚束。便当投劾自陈乞，何事甘心累形役。路指衡阳还故乡，笑脱尘羁返初服。湖山归来故无恙，生事虽微清兴足。时时寻盟狎鸥鸟，十里荷花照人目。扁舟闲弄即南垞，菱角鸡头收百斛。蓬囱几度夕阳明，桑柘柴冲接村谷。暝色依微宿鸟静，坐见松坪上团玉。茶园烟霭树参差，风动旗鎗香簇簇。鞍山岚气欲作雨，望荡涛声正翻屋。水清沙白木岭高，渔唱樵歌断还续。此时此景貌难尽，幽趣满怀良可掬。王晞方外齐逸驾，诸葛隆中并芳躅。胡为去此趋末路，名利扰扰生忧辱。超然肥遁固始愿，不学引年思辟谷。邻僧野老日相过，旋折松茅煮溪簌。浮云世事不须问，浊酒一尊聊共漉。庙堂有政肉食谋，葵藿区区徒献曝。深源不出亦已尔，其若苍生竟谁属。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5008, 7, 254926, '585de298128fe10069d05835', '过高邮新开湖微雨有咏', NULL, '杨基', '明', '残红晓落西陂岸，雨脚斜飞鸥鹭乱。扁舟尽日画中行，荷叶荷花香不断。船头老翁一尺须，斗量菱角兼卖鱼。儿能鼓柁女荡楫，何用聪明多读书。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5009, 8, 382223, '585eb855570c3500693c0a89', '满江红 · 江村夏咏', NULL, '陈维崧', '清', '泽国人家，门以外、水田渺渺。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5010, 9, 388333, '585ec28e61ff4b006cdd159c', '望湘人', NULL, '张景祁', '清', '正疏星案户，千里送秋，碧天凉思无限。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5011, 10, 407762, '585ee4a861ff4b0058185072', '水龙吟 · 惠山酌泉', NULL, '杨玉衔', '清', '酒痕黯淡尘襟，茂陵渴抱看山病。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5012, 11, 425932, '585f06d961ff4b00689ab9f4', '台城路送李分虎', NULL, '严绳孙', '清', '秋来已是惊摇落，西风更催嘶骑。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5013, 12, 436516, '585f1e9e128fe1006df197bc', '鹧鸪天 · 题芗林', NULL, '向子諲', '宋', '莫问清江与洛阳，山林总是一般香。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5014, 13, 524623, '585ff339da2f60006595a832', '谒告归卧晚登子城', NULL, '陆游', '宋', '此身真是抱官囚，厌见长空赤日流。斋壁晓山千嶂雪，扇纨新雁一汀秋。系船空作清湘梦，御气难寻太华游。菱角藕丝还恨少，强携玉瀣醉高楼。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5015, 14, 577506, '58606aa661ff4b0068a27fd9', '送黄龙晓禅师住观音颂', NULL, '黄庭坚', '宋', '黄龙一卧十五年，搅潭惊起旧头角。张公搅潭是好心，但向西江起风雹。河阳新妇画蛾眉，老婆不可重新学。长连体上铺棘针，满钵饭饤铁菱角。有能欢喜受供养，聪明一一安排著。张公若问解何宗，食月虾蟆救月弓。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5016, 15, 618586, '5860d513128fe1006bb74a79', '醉白堂', NULL, '韩琦', '宋', '戆老新成池上堂，因忆乐天池上篇。乐天先识勇退早，凛凛万世清风传。古人中求尚难拟，自顾愚者孰可肩。但举当时池上物，愧今之有殊未全。池东无廪贮馀粟，池西无亭挥五弦。中无高桥跨三岛，下压鳌背浮清涟。其间合奏散序者，童妓百指皆婵娟。平无三石展湘簟，静无双鹤翘丁仙。雅无吴郡青版舫，游泛安便牢且坚。吾今谋退亦易足，池南大屋藏群编。一车岂若万籍富，子孙得以精覃研。夹堂修竹抱幽翠，森森拥槛竿逾千。池中所出粗可爱，芡盘菱角红白莲。芍药多名来江都，牡丹绝艳移洛川。及时花发池左右，香苞烂染朝霞鲜。戆老于此兴不浅，间会宾属陈芳筵。妖妍姬侍目嘉卉，咿哑丝竹听流泉。宜城酿法亦云美，诗酒仅可追前贤。狂吟气健薄霄汉，豪饮体放忘貂蝉。酒酣陶陶睡席上，醉乡何有但浩然。人生所适贵自适，斯适岂异白乐天。未能得谢已知此，得谢吾乐知谁先。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5017, 16, 128807, '585d4690128fe10069cdeb5d', '采菱曲', NULL, '王世贞', '明', '蜻蛉刺水去，不复畏欹斜。渠自爱菱角，侬自爱菱花。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5018, 17, 355920, '585e8adfb123db0065b0b322', '生查子', NULL, '汪东', '当代', '薄情游未归，夜坐停针语。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5019, 18, 400005, '585ed70fda2f6000658eca95', '南柯子 · 戏题', NULL, '曾廉', '清', '越女凉风喜，吴娘暮雨愁。', 'ci', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5020, 19, 162248, '585d6ab98d6d810065df69d5', '守溪', NULL, '沈周', '明', '爱是双溪故居好，百年遗泽与人俱。保雌大觉聃翁胜，改姓直嫌柳子愚。旧有一隈鱼十顷，新招六逸竹千株。买书教子非无益，菱角鸡头总入租。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5021, 20, 228682, '585dbe32da2f6000658760c9', '山居八首', NULL, '陆深', '明', '水云烟月市桥西，菱角荷钱已满溪。读罢黄庭三百首，人家茅屋午时鸡。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5022, 21, 280287, '585e09cdb123db0065acc315', '湖上曲', NULL, '刘崧', '明', '新莲乍出即昂头，叶底红菱不解浮。菱角沉泥终暗老，莲花落尽即漂流。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5023, 22, 551436, '58602e991b69e600562246d9', '护龙河', NULL, '许及之', '宋', '门题善利遏朝宗，一水何从更护龙。菱角鸡头教偪仄，可堪游女折芙蓉。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5024, 23, 530092, '586000b11b69e6005621db47', '幽居戏赠邻曲', NULL, '陆游', '宋', '暮年远屏天所借，落佩倒冠如得谢。虽无壶酒助歌呼，幸有蠹书供枕藉。市声不闻耳差静，车辙扫空身转暇。雨悭葵叶未吐甲，露重榴房初坼罅。深红菱角密覆水，烂紫蒲桃重垂架。直令掩关避世俗，未害煎茶唤邻舍。萧萧鸡犬衡门晚，寂寂灯火幽窗夜。劝君切勿纵高谈，性命如丝不禁吓。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5025, 24, 634617, '58c79d2b44d90400699c70c4', '北人食菱', NULL, '江盈科', '明', '北人生而不识菱者，仕于南方。', 'wen', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5026, 25, 124011, '585d40dd570c350069333ab6', '伯承少卿自报国寺分手二十五年矣虽讯问不废而笑谈永隔今岁初夏复有一诗见遗聊尔奉答', NULL, '王世贞', '明', '招提杯酒散词盟，华发苍颜铸此生。各负一编湖海日，不贪群少斗山名。升沉事事归陈迹，耕凿年年饱太平。见说白公禅观后，紫绡菱角对弹筝。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5027, 26, 145383, '585d582c1b69e60056121ec8', '菱角', NULL, '成鹫', '明', '苇渡凌波，囊锥脱颖。净尽锋芒，具见体性。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5028, 27, 104334, '585d26aeb123db0065a80933', '小游仙诗九十八首', NULL, '曹唐', '唐', '暂随凫伯纵闲游，饮鹿因过翠水头。宫殿寂寥人不见，碧花菱角满潭秋。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5029, 28, 256117, '585de4648d6d810065e13c45', '奉送蒲川龚先生赴湖南左辖和姚维宁', NULL, '黄衷', '明', '履素频居顺，登良遂陟明。直方堪地负，廉约即天成。气老元操简，怀虚更敛英。魏公真相器，君实足时名。京邑因河润，春皋谢木荣。人间冬日色，蛮裔古风声。乡井连吴会，山川控邓城。化行时伪戢，吏散道心清。白板馀生聚，红箱减算征。崇阶将义报，殊礼以贤旌。信节年于迈，勤功夜自程。国香迷畹亩，阳鸟渡湘衡。璧彩归仍丽，金声扣始铮。寓言齐物理，降色察民情。剖剧并刀发，摅贞汉水倾。总无私可恤，岂有宠能惊。鉴彻天潢派，词森武库兵。栖迟彭泽令，经济洛阳生。菱角新池实，莼丝晚社羹。四时如有序，桂棹五湖轻。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5030, 29, 239886, '585dcd841b69e6006cce6908', '采菱词', NULL, '张元凯', '明', '菱角何纤纤，菱叶何田田。鸳鸯与鸂鶒，对对浮清川。采菱白晰郎，荡桨后复前。偶逢西家姝，隔浦来采莲。娇容入花乱，素腕随荇牵。要住语绸缪，风动裙带偏。采采忘采角，但采叶在船。赠我双莲子，庶几不空还。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5031, 30, 323186, '585e4f07570c35006939100e', '斜径', NULL, '王安石', '宋', '斜径偶通南埭路，数家遥对北山岑。草头蛱蝶黄花晚，菱角蜻蜓翠蔓深。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5032, 20, 637475, '5aea7b819f5454005ed3fb83', '史记 · 十表 · 建元以来侯者年表', NULL, '司马迁', '汉', '太史公曰：匈奴绝和亲，攻当路塞；', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5033, 21, 637476, '5aea7bf07f6fd30038691bcf', '史记 · 十表 · 建元已来王子侯者年表', NULL, '司马迁', '汉', '制诏御史：“诸侯王或欲推私恩分子弟邑者，令各条上，朕且临定其号名。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5034, 22, 637477, '5aea7c499f5454003f34c605', '史记 · 十表 · 汉兴以来将相名臣年表', NULL, '司马迁', '汉', '索隐述赞：高祖初起，啸命群雄。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5035, 23, 637479, '5aea7d107f6fd300386921c0', '史记 · 八书 · 礼书', NULL, '司马迁', '汉', '太史公曰：洋洋美德乎！', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5036, 24, 637480, '5aea7deeac502e00628422f2', '史记 · 八书 · 乐书 ', NULL, '司马迁', '汉', '太史公曰：余每读虞书，至于君臣相敕，维是几安，而股肱不良，万事堕坏，未尝不流涕也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5037, 25, 637481, '5aea7e599f5454003f34d3a0', '史记 · 八书 · 律书', NULL, '司马迁', '汉', '王者制事立法，物度轨则，壹禀于六律，六律为万事根本焉。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5038, 26, 637482, '5aea80befe88c2003845a89b', '史记 · 八书 · 历书', NULL, '司马迁', '汉', '昔自在古，历建正作于孟春。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5039, 27, 637483, '5aea828017d009006616d114', '史记 · 八书 · 天官书', NULL, '司马迁', '汉', '中宫天极星，其一明者，太一常居也；', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5040, 28, 637484, '5aea861117d009006616ea7f', '史记 · 八书 · 封禅书', NULL, '司马迁', '汉', '自古受命帝王，曷尝不封禅？', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5041, 29, 637485, '5aea864b7f6fd30038695e5b', '史记 · 八书 · 河渠书', NULL, '司马迁', '汉', '夏书曰：禹抑洪水十三年，过家不入门，陆行载车，水行载舟，泥行蹈毳、山行即桥。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5042, 30, 637486, '5aea87d9a22b9d00442cdcf2', '史记 · 八书 · 平准书 ', NULL, '司马迁', '汉', '汉兴，接秦之弊，丈夫从军旅，老弱转粮饟，作业剧而财匮，自天子不能具钧驷，而将相或乘牛车，齐民无藏盖。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5043, 31, 637487, '5aea880e0b61600075a9b976', '史记 · 三十世家 · 吴太伯世家', NULL, '司马迁', '汉', '吴太伯，太伯弟仲雍，皆周太王之子，而王季历之兄也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5044, 32, 637488, '5aea888d9f54540043a93e94', '史记 · 三十世家 · 齐太公世家', NULL, '司马迁', '汉', '太公望吕尚者，东海上人。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5045, 33, 637489, '5aea88f49f54540043a940fd', '史记 · 三十世家 · 鲁周公世家', NULL, '司马迁', '汉', '周公旦者，周武王弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5046, 34, 637490, '5aeab58afe88c2374014afa3', '史记 · 三十世家 · 燕召公世家', NULL, '司马迁', '汉', '召公奭与周王同姓，姓姬。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5047, 35, 637491, '5aeab6320b61605533d8cf2f', '史记 · 三十世家 · 管蔡世家', NULL, '司马迁', '汉', '管叔鲜、蔡叔度者，周文王子而武王弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5050, 18, 637492, '5aeab708ee920a3e9fdfc9ee', '湖心亭采莼', NULL, '高濂', '明', '旧闻莼生越之湘湖，初夏思莼，每每 彼采食；', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5051, 19, 637493, '5aeab7c39f54544cd16f4a14', '湖晴观水面流虹', NULL, '高濂', '明', '湖山过雨，残月烘云，峦霭浮浮，林铺翠湿，浴晴鸥鹭争飞，拂袂荷风荐爽。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5052, 20, 637494, '5aeab7dfee920a3e9fdfcff4', '山晚听轻雷断雨', NULL, '高濂', '明', '山楼一枕晚凉，卧醉初足，倚栏长啸，爽豁凝眸。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5053, 21, 637495, '5aeab806a22b9d00442e184e', '乘露剖莲雪藕', NULL, '高濂', '明', '莲实之味，美在清晨，水气夜浮，斯时正足。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5094, 46, 10033, '57b959a50a2b58005c95590e', '山窗听雪敲竹', NULL, '高濂', '明', '飞雪有声，惟在竹间最雅。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5054, 22, 637496, '5aeab81bfe88c2374014c326', '空亭坐月鸣琴', NULL, '高濂', '明', '夏日山亭对月，暑气西沉，南熏习习生凉，极目遥山，盘郁冰镜，两湖隐约，何来钟盘？', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5055, 23, 637497, '5aeab8349f54544f0af14a8f', '观湖上风雨欲来', NULL, '高濂', '明', '山阁五六月间，风过生寒，溪云欲起，山色忽阴忽晴，湖光乍开乍合。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5056, 24, 637498, '5aeab8499f54544cd16f4fef', '步山径野花幽鸟', NULL, '高濂', '明', '山深幽境，真趣颇多。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5057, 25, 637499, '5aeab8679f54544f1b798236', '西泠桥畔醉红树', NULL, '高濂', '明', '西泠在湖之西，桥侧为唐一庵公墓，中有枫柏数株，秋来霜红雾紫，点缀成林，影醉夕阳，鲜艳夺目，时携小艇，扶尊登桥吟赏，或得一二新句，出携囊红叶笺书之。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5058, 26, 637500, '5aeab87c9f54544cd16f5113', '宝石山下看塔灯', NULL, '高濂', '明', '保叔为省中最高灯塔，七级燃灯，周遭百盏，星丸错落，辉煌烛天，极目高空，恍自九霄中下。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5059, 27, 637501, '5aeab8989f54544f1b798361', '满家巷赏桂花', NULL, '高濂', '明', '桂花最盛处，惟两山龙井为多，而地名满家巷者，其林若墉若栉，一村以市花为业，各省取给于此。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5060, 28, 637502, '5aeab8bb9f54544f0af14dc7', '三塔基听落雁', NULL, '高濂', '明', '秋风雁来，惟水草空阔处，择为栖止。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5061, 29, 637503, '5aeab8d79f5454481d4bebb0', '胜果寺月岩望月', NULL, '高濂', '明', '胜果寺左，山有石壁削立，中穿一窦，圆若镜然。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5062, 30, 637504, '5aeab8ed7f6fd300386aaae0', '水乐洞雨后听泉', NULL, '高濂', '明', '洞在烟霞岭下，岩石虚豁，谽 邃窈，山泉别流，从洞隙滴滴，声韵金石。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5063, 31, 637505, '5aeab90117d0090066183a2e', '资严山下看石笋', NULL, '高濂', '明', '资严在灵隐西壁。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5064, 32, 637506, '5aeab91917d0090066183b93', '北高峰顶观海云', NULL, '高濂', '明', '北高峰为湖山第一高处，绝顶环眺，目及数里。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5065, 36, 637518, '5aec1b5eee920a1e14690fe3', '史记 · 三十世家 · 陈杞世家', NULL, '司马迁', '汉', '陈胡公满者，虞帝舜之后也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5066, 37, 637519, '5aec1bf39f54546d18d855c1', '史记 · 三十世家 · 卫康叔世家', NULL, '司马迁', '汉', '卫康叔名封，周武王同母少弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5067, 38, 637520, '5aec1c20fe88c237401c5843', '史记 · 三十世家 · 宋微子世家', NULL, '司马迁', '汉', '微子开者，殷帝乙之首子而帝纣之庶兄也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5068, 39, 637521, '5aec1e5a0b61605533e08979', '史记 · 三十世家 · 晋世家 ', NULL, '司马迁', '汉', '晋唐叔虞者，周武王子而成王弟。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5070, 40, 637522, '5aec1ef37f6fd30038726086', '史记 · 三十世家 · 楚世家', NULL, '司马迁', '汉', '楚之先祖出自帝颛顼高阳。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5071, 41, 637523, '5aec1f439f54546d18d8701e', '史记 · 三十世家 · 越王勾践世家', NULL, '司马迁', '汉', '越王勾践，其先禹之苗裔，而夏后帝少康之庶子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5072, 42, 637524, '5aec1f9017d00900661feeaa', '史记 · 三十世家 · 郑世家', NULL, '司马迁', '汉', '郑桓公友者，周厉王少子而宣王庶弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5073, 43, 637525, '5aec1ff0a22b9d004435d481', '史记 · 三十世家 · 赵世家', NULL, '司马迁', '汉', '赵氏之先，与秦共祖。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5074, 44, 637526, '5aec202fac502e2f6afb24bc', '史记 · 三十世家 · 魏世家', NULL, '司马迁', '汉', '魏之先，毕公高之后也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5075, 45, 637527, '5aec2060ee920a1e14693a79', '史记 · 三十世家 · 韩世家', NULL, '司马迁', '汉', '韩之先与周同姓，姓姬氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5076, 46, 637528, '5aec209c9f54543688278609', '史记 · 三十世家 · 田敬仲完世家', NULL, '司马迁', '汉', '陈完者，陈废公（史记误为厉公）他之子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5077, 47, 637529, '5aec21429f54543688278aa2', '史记 · 三十世家 · 孔子世家', NULL, '司马迁', '汉', '孔子生鲁昌平乡陬邑。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5080, 50, 637532, '5aec23e0ee920a1e146959e4', '史记 · 三十世家 · 楚元王世家', NULL, '司马迁', '汉', '楚元王刘交者，高祖之同母（此处有误，应为异母）少弟也，字游。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5081, 33, 637533, '5aec24ae0b61605533e0c198', '策杖林园访菊', NULL, '高濂', '明', '菊为花之隐者，惟隐君子、山人家能蓻，故不多见，见亦难于丰美。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5082, 38, 637534, '5aec25292f301e437089f86c', '雪霁策蹇寻梅', NULL, '高濂', '明', '画中春郊走马，秋溪把钓，策蹇寻梅，莫不以朱为衣色，岂果无为哉？', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5083, 39, 637535, '5aec25447f6fd3003872910c', '三茅山顶望江天雪霁 ', NULL, '高濂', '明', '三茅乃郡城内山高处，襟带江湖，为胜览最欢喜地。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5084, 40, 637536, '5aec25602f301e437089fb61', '西溪道中玩雪', NULL, '高濂', '明', '往年因雪霁，偶入西溪，何意得见世外佳景。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5085, 41, 637537, '5aec25770b61605533e0c652', '山头玩赏茗花', NULL, '高濂', '明', '两山种茶颇蕃，仲冬花发，若月笼万树，每每入山寻茶胜处，对花默共色笑，忽生一种幽香，深可人意。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5086, 42, 637538, '5aec25b1a22b9d00443604a4', '登眺天目绝顶', NULL, '高濂', '明', '武林万山，皆自天目分发，故《地钤》有“天目生来两乳长”偈。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5087, 43, 637539, '5aec25db0b61605533e0c945', '山居听人说书', NULL, '高濂', '明', '老人畏寒，不涉世故，时山居曝背，茅檐看梅初放，邻友善谈，炙？', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5088, 44, 637540, '5aec25fda22b9d0044360782', '扫雪烹茶玩画', NULL, '高濂', '明', '茶以雪烹，味更清冽，所谓半天河水是也。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5089, 34, 10405, '57b90c882e958a005fa5aa52', '乘舟风雨听芦', NULL, '高濂', '明', '秋来风雨怜人，独芦中声最凄黯。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5090, 35, 10404, '57bba52879bc440063a8feb7', '保俶塔顶观海日', NULL, '高濂', '明', '保俶塔游人罕登其颠，能穷七级，四望神爽。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5091, 36, 10403, '57bec01e8ac24700632520ed', '六和塔夜玩风潮', NULL, '高濂', '明', '浙江潮汛，人多从八月昼观，鲜有知夜观者，余昔焚修寺中，燃点塔灯，夜午月色横空，江波静寂，悠悠逝水，吞吐蟾光，自是一段奇景。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5092, 37, 10402, '57b9d2287db2a20068bf5fc0', '湖冻初晴远泛', NULL, '高濂', '明', '西湖之水，非严寒不冰，冰亦不坚。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5093, 45, 637541, '5aec26212f301e437089fff8', '雪夜煨芋谈禅', NULL, '高濂', '明', '雪夜偶宿禅林，从僧拥炉，旋摘山芋，煨剥入口，味较世中美甚，欣然一饱。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5095, 47, 637542, '5aec26447f6fd3003872982b', '除夕登吴山看松盆', NULL, '高濂', '明', '除夕，惟杭城居民家户架柴燔燎，火光烛天，挝鼓鸣金，放炮起火，谓之松盆。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5096, 48, 637543, '5aec265aac502e2f6afb5822', '雪后镇海楼观晚炊', NULL, '高濂', '明', '满城雪积，万瓦铺银，鳞次高低，尽若堆玉。', 'wen', 164, '四时幽赏录', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5097, 1, 633467, '582c6f89a22b9d006b675f41', '天净沙 · 夏', NULL, '朱庭玉', '明', '参差竹笋抽簪，累垂梅子攒金，旋趁庭槐翠阴。', 'qu', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5098, 2, 49172, '585cee2a128fe1006de4e1aa', '送郑汝玉归莆关', NULL, '陈高', '元', '莆关深入海东南，日出先看曙色酣。李愿归耕盘谷土，杜陵思乐百花潭。到家三月山矾白，入馔千林竹笋甘。愧我天涯尚羁旅，乡愁因尔不能堪。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5099, 3, 66857, '585cfdebb123db0065a6b263', '寄野堂', NULL, '萨都剌', '元', '忆昔相逢春莫天，道傍杨柳尽飞绵。池鱼出水将三尺，竹笋成林又一年。高士已成招隐赋，行人未办买山钱。野堂灯火清秋夜，何日联床听雨眠。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5100, 4, 119896, '585d3bbf61ff4b00689105a1', '毛进士使边得省十二韵', NULL, '尹台', '明', '勍敌窥三辅，元戎练五兵。纡筹劳圣主，献画满神京。鸟旆黄云合，鱼书白日征。三秦忧转饷，六郡募横行。贾谊单于组，终军关吏缨。时危矜战绩，世难耻儒名。捧檄毛生志，扬舲祖逖情。未辞邛邑驭，敢问朔方旌。梦远蛟龙泽，愁深骠骑营。空怜新竹笋，徒泣旧庭荆。入里梧飘井，归朝柳媚城。葵心知抱赤，好向太阳倾。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5101, 5, 160408, '585d68d6128fe10069ce91ba', '晚春郊外七首', NULL, '李昌祺', '明', '楝花将绽艻花稀，蒲笋初生竹笋肥。山鸟唤晴相对语，园蜂趁暖作群飞。羞将艳蕊簪乌帽，笑指垂杨妒绿衣。两两牧童残照里，齐吹短笛跨牛归。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5102, 6, 231213, '585dc1ad61ff4b006cd5eb6d', '闲居', NULL, '梁以壮', '明', '看书才罢卷，习圃过前坳。辛苦方能寿，幽栖乃见嘲。土硗添竹笋，林密保鸦巢。近得池盈亩，中间结一茅。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5103, 7, 288263, '585e160a61ff4b005813588d', '盍簪楼杂咏十首', NULL, '霍与瑕', '明', '有客来何暮，芳尊日欲斜。馔分青竹笋，茗泛绿葱花。方外参玄契，时中订作家。三更山月起，更与玩清华。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5104, 8, 315937, '585e42971b69e6006cd1da7c', '阁下观竹笋图', NULL, '孔武仲', '宋', '我家庐山下，绿竹常阴阴。春雷迸狂箨，万点群玉簪。别来经岁时，肌肉尘土侵。歘见此图面，醒然豁烦襟。方幅藏万里，环以青山岑。旁飞清泠泉，下有潇洒林。恍惚如梦到，杖筇听幽禽。欲投环堵室，浩渺忽难寻。人生谅自苦，一官泳蹄涔。摇尾争光华，岂知沧海深。虞卿炫白璧，季子夸黄金。贪得以忘我，俱非贤达心。何如返乡国，坡坞穷差参。茅檐当天风，时听笙簧音。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5105, 9, 321983, '585e4cf161ff4b005814f246', '入邑', NULL, '王谌', '宋', '马踏新松影，衣沾秀麦寒。藤花缀缨珞，竹笋透琅玕。诗向闲中得，心因静处宽。一声幽鸟啭，深在翠林端。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5106, 10, 325818, '585e53afda2f6000658bb02d', '竹石屏歌谢遁泽', NULL, '王柏', '宋', '好古博雅时遁泽，往岁赠我墨图柏。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5107, 11, 286560, '585e1392da2f60006589d805', '寿欧母', NULL, '黎民表', '明', '会稽旧是梁鸿宅，邹邑今传孟母家。竹笋自能供白发，橘林应得胜丹砂。书传南岳夫人鹤，客问银河织女槎。却愧荀陈交谊重，年年来对寿筵花。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5108, 12, 301705, '585e2aa4128fe1006dec6cc0', '雪后登楼用沈西潜韵', NULL, '顾清', '明', '冻云飞散晓来天，举目青山九点全。竹笋迸阶犹带雪，柳枝低槛欲生烟。闲寻广受还乡事，偶到机云入洛年。八百里封还若此，龙阳何况木奴年。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5109, 13, 308601, '585e366861ff4b00581449e4', '赠王司寇乞养归台南四首', NULL, '顾璘', '明', '脱身霄汉赋闲居，暂息鹏风九万馀。母氏在堂思戏采，人生当路几悬车。烧丹试凿皇华井，闭户应修禹穴书。料得晨昏调鼎味，长将竹笋脍江鱼。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5110, 14, 367091, '585e9eec61ff4b00689994e1', '噶玛兰城', NULL, '柯培元', '清', '绕城修竹笋新抽，竹外弯环入海流。清浊分溪芳草界，东西对势白云浮。春晴丽日烘金面，雨过浓烟隐凤头。遥指玉山笼瑞霭，居人尽道是瀛洲。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5111, 15, 479945, '585f8ac0570c3500694030a4', '步入衡山', NULL, '范成大', '宋', '应有人家住隔溪，绿阴亭午但闻鸡。松根当路龙筋瘦，竹笋漫山凤尾齐。墨染深云犹似瘴，丝来小雨不成泥。更无骑吹喧相逐，散诞闲身信马蹄。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5112, 16, 488272, '585f9cd8ac502e0067314e09', '钟惠叔转示赵临安两山堂诸公诗刻随喜二首', NULL, '洪咨夔', '宋', '朵颐常逐逐，观复自休休。静昼青竹笋，深春黄栗留。觉圆熏穟直，梦破茗华浮。为问连山易，床头好在不。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5113, 17, 523219, '585fefaa61ff4b00630255b8', '习懒自咎', NULL, '陆游', '宋', '习懒多遗事，时能害睡眠。獾骄残竹笋，鼠横啮床毡。猧子巡篱落，狸奴护简编。人间有俊物，求买敢论钱。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5114, 18, 569796, '586056661b69e6006cdd4be8', '薛舍人母方氏太恭人挽章二首', NULL, '杨万里', '宋', '赋感东征句，诗愁陟屺篇。生前九龄梦，眼底五朝天。锦告浑无恙，云车忽杳然。不堪青竹笋，归路不迎船。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5115, 19, 75346, '585d0605b123db0065a6f124', '春日寓感', NULL, '王延彬', '五代十国', '两衙前后讼堂清，软锦披袍拥鼻行。雨后绿苔侵履迹，春深红杏锁莺声。因携久酝松醪酒，自煮新抽竹笋羹。也解为诗也为政，侬家何似谢宣城。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5116, 20, 135552, '585d4dae570c350069339844', '次韵陆佥宪病起见寄', NULL, '王守仁', '明', '一赋《归来》不愿馀，文园多病滞相如。篱边竹笋青应满，洞口桃花红自舒。荷蒉有心还击磬，周公无梦欲删《书》。云间宪伯能相慰，尺素长题问谪居。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5117, 21, 113755, '585d34398d6d810065de25ce', '送张郎中还蜀歌', NULL, '卢纶', '唐', '秦家御史汉家郎，亲专两印征殊方。功成走马朝天子，伏槛论边若流水。晓离仙署趋紫微，夜接高儒读青史。泸南五将望君还，愿以天书示百蛮。曲栈重江初过雨，前旌后骑不同山。迎车拜舞多耆老，旧卒新营遍青草。塞口云生火候迟，烟中鹤唳军行早。黄花川下水交横，远映孤霞蜀国晴。邛竹笋长椒瘴起，荔枝花发杜鹃鸣。回首岷峨半天黑，传觞接膝何由得。空令豪士仰威名，无复贫交恃颜色。垂杨不动雨纷纷，锦帐胡瓶争送君。须臾醉起箫笳发，空见红旌入白云。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5118, 22, 325190, '585e52be61ff4b006897367e', '中夏', NULL, '王安国', '宋', '朝晡广厦坐攲斜，稍觉炎天气象加。紫玉箫攒湘竹笋，赤霜袍烂海榴花。悠悠物外身无事，扰扰人闲智有涯。五鼎一瓢何必问，且凭诗句度年华。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5119, 23, 321898, '585e4cd78d6d810065e46e9c', '象州', NULL, '王安中', '宋', '孔子生阙里，居不陋九夷。象郡虽云远，王地各有宜。疏梅香度水，瘦竹笋穿篱。坐侍百卉芳，春风兼四时。惜哉此江山，顾肯游者谁。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5120, 24, 444600, '585f358a128fe10069d851fe', '题剡山所见', NULL, '李易', '宋', '剡中无数野蔷薇，黄云烂漫相因依。玉杯浅琢承坠露，金钟倒挂摇晨晖。斑竹笋行三亩地，红药花开一尺围。豆角尝新小麦秀，来禽长向樱桃肥。歌舌随风柳外啭，翠花带水烟中飞。鱼跳破浪奋赤鬣，鹤唳投松翻缟衣。乡关万里久无梦，岩壑四年今息机。叮咛杜宇往江北，为唤故人令早归。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5121, 25, 344115, '585e73faac502e00672ae300', '水沙连', NULL, '吴德功', '清', '地势高千尺，中间别有天。雌雄山互锁，清浊水交缠。凤尾兰花秀，猫儿竹笋鲜。四时多雾霭，遥望与云连。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5122, 26, 177017, '585d7cbb128fe1006de899fc', '丁卯腊月十三日恭逢家慈大人八十有四寿日喜赋五章', NULL, '屈大均', '清', '忠养无穷日，难终孝子身。三千王母岁，六十老莱春。竹笋冬方茁，梅葩腊已新。炉红烧雉熟，持作早餐频。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5123, 27, 146441, '585d5951570c35006933d405', '游惠山寺次秦方伯韵', NULL, '江源', '明', '见说山公不姓支，可人儒雅亦堪师。云霞长护占名刹，猿鹤争迎老住持。僧供旋享新竹笋，鹊巢还占旧松枝。来游此地询兴废，方伯文章即是碑。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5124, 28, 172611, '585d773f61ff4b0063f370a3', '山居秋日用杜韵八首', NULL, '邵宝', '明', '湖北湖南度夕晖，望中山影坐来微。具区泽近九龙卧，沧海云空一鹤飞。日月每将闲事遣，阴晴长与夙期违。清斋不独葵堪折，竹笋鲜新蕨本肥。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5125, 29, 176259, '585d7bbeda2f60006586ab19', '苦竹派道中', NULL, '屈大均', '清', '田随山曲折，处处水泉飞。车响知溪急，畲高识土肥。禾垂将吐穗，莲落尚留衣。竹笋从人取，青青满翠微。', 'shi', 167, '竹笋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5126, 1, 633735, '584bc1992f301e005725118b', '红豆词', NULL, '曹雪芹', '清', '滴不尽相思血泪抛红豆，开不完春柳春花满画楼。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5127, 2, 10281, '57b8dcfe128fe10054c8d401', '相思', NULL, '王维', '唐', '红豆生南国，春来发几枝？', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5128, 3, 10271, '57b5a54e8ac2470064456ee8', '新添声杨柳枝词', NULL, '温庭筠', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5129, 4, 11792, '57e2a2d50bd1d000570f6ef0', '生查子', NULL, '牛希济', '五代十国', '新月曲如眉，未有团圞意。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5130, 5, 10240, '57b908022e958a005fa583ea', '秋灯琐忆', NULL, '蒋坦', '清', '道光癸卯闰秋，秋芙来归。', 'wen', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5131, 6, 54570, '585cf31d61ff4b006cd19566', '寄天香师', NULL, '张宪', '元', '圆帽顶红毳，方袍搭绛纱。海龙邀早饭，山鹿进秋花。试墨探倭纸，寻泉斗建茶。时抛红豆粒，竹下唤频伽。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5132, 7, 67744, '585cfee2128fe1006de566a7', '感旧歌者', NULL, '戴表元', '元', '牡丹红豆艳春天，檀板朱丝锦色笺。头白江南一尊酒，无人知是李龟年。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5133, 8, 140111, '585d52bb128fe10069ce3b47', '金缕曲四首', NULL, '王彦泓', '明', '回首燕台浪寄闻，博山相约许湔裙。投符求辨驱红豆，倚醉犹能乞紫云。甘果掷来还并剖，名香窃去更同熏。市门妒女重相羡，不悔从前刺绣文。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5134, 9, 140125, '585d52c0570c35006933b447', '北行留别', NULL, '王彦泓', '明', '花时为客最难拚，恨叶情条满故园。惜别倍贫歌宛转，寻欢频见涕潺媛。情深为我留颜色，泪尽烦卿强笑言。传语同心众闺阁，莫拈红豆且栽萱。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5135, 10, 157041, '585d6504ac502e0067249ec6', '落花', NULL, '何吾驺', '明', '朝来树下问相思，红豆今年发几枝。不是愁心千万种，何缘都作泪珠垂。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5136, 11, 177591, '585d7d7d1b69e6006ccd64e1', '篁村逢朱十', NULL, '屈大均', '清', '黄木湾头月，扶胥渡口舟。日方逾北至，火已见西流。过雨收红豆，连波狎白鸥。夫君若萱车，一见即忘忧。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5137, 12, 179064, '585d7f7d1b69e6005612911c', '古意', NULL, '屈大均', '清', '不见园中树，花开只在枝。枝间结红豆，一子一相思。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5138, 13, 267273, '585df501b123db0065ac15fd', '旅夜书怀', NULL, '邓云霄', '明', '马首东风弱柳垂，关山迢递杳难期。谁知游子中宵饭，正是闺人掩泪时。红豆不须携满袖，江南何处寄相思。巡檐夜步空庭月，宿鸟双栖自一枝。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5139, 14, 251512, '585dde3e570c35006935ae34', '曲中听黄问琴歌分韵八首牙字', NULL, '程嘉燧', '明', '初学莺簧响露梢，还疑凤吹拂云霄。金屏笑剧如花女，红豆凭将记曲抛。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5140, 15, 281199, '585e0b59128fe10069d19eec', '药名闺情诗二首', NULL, '萧韶', '明', '天门冬日晓苍凉，落叶愁惊满地黄。清泪暗消轻粉面，凝尘闲锁郁金裳。石莲未嚼心先苦，红豆相看恨更长。镜里孤鸾甘遂死，引年何用觅昌阳。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5141, 16, 331548, '585e5d2f128fe1006ba98ffb', '菩萨蛮 · 春愁二首', NULL, '尤侗', '清', '六宫闹扫芙蓉镜，君王偶爱飞蓬鬓。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5142, 17, 333901, '585e6114128fe10069d42e4d', '八犯玉交枝咏寒灯用《湘瑟词》韵', NULL, '王策', '清', '萤点衔红，豆光沉黝，耿耿闪残乡梦。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5143, 18, 334141, '585e619c8d6d810065e50ae9', '悼亡诗', NULL, '王士禛', '清', '陌上莺啼细草薰，鱼鳞风皱水成纹。江南红豆相思苦，岁岁花开一忆君。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5144, 19, 333810, '585e60e2da2f6000658c187f', '虞美人 · 天竹', NULL, '王策', '清', '疏斜影傍墙东住。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5145, 20, 332985, '585e5f8dac502e00672a38c5', '踏莎行 · 三首', NULL, '王时翔', '清', '嫩嫩烟丝，轻轻风絮。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5146, 21, 347695, '585e7b06128fe1006deee4d3', '壶天晓红豆', NULL, '吴瑗（文青）', '清', '艳比鲛人泪颗，光交帝网珠丝。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5147, 22, 352722, '585e84e81b69e60056192ddc', '生查子 · 夏闺', NULL, '宋琬', '清', '二月算当归，于今将半夏。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5148, 23, 360512, '585e9350128fe1006bab5040', '洞仙歌 · 偶见丰台花谱中有山阴王眉子词三首，因用原韵，依调继声', NULL, '易顺鼎', '清', '砑笺小字，倩流莺相候。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5149, 24, 371131, '585ea58f8d6d810065e71c1f', '孙子潇先生双红豆图三首', NULL, '夏孙桐', '清', '烟月虞山百载新，自来红豆属词人。绛云楼后天真阁，占却江南一半春。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5150, 25, 371407, '585ea5e0ac502e00672c5df5', '诉衷情 · 为艺风题双红豆图', NULL, '夏孙桐', '清', '珊瑚颗颗泪生春。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5151, 26, 374738, '585eab7061ff4b005817bc5c', '菩萨蛮 · 题蝶庵词，寄阳羡史云臣', NULL, '徐釚', '清', '浓阴欲洗桐花甃。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6403, 10, 610460, '5860c0ee61ff4b006ce78d89', '渔家傲', NULL, '欧阳修', '宋', '近日门前溪水涨。', 'ci', 193, '渔家傲', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5152, 27, 344166, '585e7416570c3500693a37fe', '酬吕凤子二首', NULL, '吴研因（一作“吴妍因”）', '清', '四海知名久，三吴睹画先。如闻夫子叹，欲得美人怜。红豆叨君赠，青山为我妍。巴渝流沛地，相见各华颠。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5153, 28, 348485, '585e7cc4b123db0065b03cad', '摸鱼儿', NULL, '吴藻', '清', '是谁工、霓裳旧谱，一声声断还续。', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5154, 29, 362038, '585e960ab123db0065b1076d', '相思树', NULL, '林朝崧', '清', '红豆江南唤小名，春风叶叶总离情。鸳鸯未解相思苦，飞上枝头得意鸣。', 'shi', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5155, 30, 361385, '585e94e1128fe10069d5d8b9', '贺新郎 · 题潘星斋画梅团扇顾南雅学士所作也', NULL, '林则徐', '清', '驿使曾来否？', 'ci', 168, '红豆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5156, 1, 23796, '585cd104570c3500692f8acd', '食西瓜', NULL, '方一夔', '元', '恨无纤手削驼峰，醉嚼寒瓜一百筒。半岭花衫粘唾碧，一痕丹血搯肤红。香浮笑语牙生水，凉入衣襟骨有风。从此安心师老圃，青门何处问穷通。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5157, 2, 35169, '585cdf2761ff4b0063ef3d82', '西瓜', NULL, '周权', '元', '当年传种非东陵，蒲萄石榴来与并。碧壶深贮白沆瀣，霜刃冻割黄水晶。豪家宴客侯鲭列，浊酒鲸吞嫌内热。此时专席荐冰盆，分与风前满襟雪。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5158, 3, 36391, '585ce0bd61ff4b00580bf330', '赠高善长一百韵', NULL, '耶律楚材', '元', '君本辽阳人，家居华表傍。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5159, 4, 364613, '585e9aa6570c3500693b6f7c', '咏西瓜灯四首', NULL, '俞樾', '清', '宵深移近读书堂，伴我青灯兴更长。要使腹中无块垒，自然顶上有圆光。莫嫌焰焰膏将减，只觉荧荧火欲凉。不解朱门歌舞地，高烧红烛照红妆。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5160, 5, 338741, '585e69df61ff4b005815d494', '衡仲以西瓜见饷，兼约可园赏月', NULL, '丘逢甲', '清', '荐玉春盘海有氛，故侯门巷冷秋云。金刀欲下踌躇甚，多恐神州似此分。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5161, 6, 412063, '585eec6161ff4b00689a7b62', '满路花 · 懿丘，次美成韵', NULL, '赵熙', '清', '天晴蝶换衣，池碧鱼吹雪。', 'ci', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5162, 7, 488924, '585f9ea861ff4b00581ca24a', '答景卢报月台将毕工', NULL, '洪适', '宋', '新筑崇台款桂华，凌虚如跨白鸾车。西瓜来自余吾水，远物谁询悉里茶。不减平泉书草木，更寻南部录烟花。落成有约何时讲，舞袖还看举彩霞。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5163, 8, 556941, '58603a878d6d810065ef4e00', '值侯修学趣儒人稍急因遗莲花莲实西瓜于吾宗翔叔作诗以勉之', NULL, '曾丰', '宋', '绛玉裁花碧玉茎，亭亭香远韵逾清。群仙竞倚西风笑，为报临淮政已成。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5164, 9, 636747, '5ab8b01c17d0096887875d83', '双调 · 蟾宫曲', NULL, '卢挚', '元', '沙三伴哥来嗏！', 'qu', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5165, 10, 315353, '585e419dda2f6000658b3294', '仪真', NULL, '毛珝', '宋', '贩来北枣堪充膳，种得西瓜可析酲。总是中原旧风物，不堪今日是边城。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5166, 11, 364612, '585e9aa51b69e6005619cea1', '咏西瓜灯四首', NULL, '俞樾', '清', '剥尽层层皮与肤，此中原自费工夫。光明岂减燃脐董，空洞真成剖腹胡。笑尔烛奴无位置，比他云母略模糊。世间何物堪相拟，只有回回青亚姑。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5167, 12, 412163, '585eec9b61ff4b0058185c20', '满庭芳 · 甲子除夕感旧', NULL, '赵熙', '清', '红烛深宵，青山行客，爆竹催送年华。', 'ci', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5168, 13, 415014, '585ef235128fe10069d70ae9', '台湾杂咏', NULL, '齐体物', '清', '春盘绿玉荐西瓜，未腊先看柳长芽。地尽日南天气早，梅花才放见荷花。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5169, 14, 480468, '585f8c0f570c350069403aef', '西瓜园', NULL, '范成大', '宋', '碧蔓凌霜卧软沙，年来处处食西瓜。形模濩落淡如水，未可蒲萄苜蓿夸。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5170, 15, 489210, '585f9f69128fe1006df52e77', '杂咏下西瓜', NULL, '洪适', '宋', '万里随肤使，分留三十年。甘棠遗爱在，一见一潸然。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5171, 16, 560483, '5860421fb123db0065b9a9fc', '中伏', NULL, '董嗣杲', '宋', '五世单丁家，在家亦如客。悲欢恼客抱，每恨江海窄。今日初伏过，浴出易絺绤。树头来禽熟，隔水不可摘。明年西湖去，凉云簪藉白。此时且健饭，宁耐朱炎赫。淮童少解事，醉拾西瓜擘。强笑领其真，寓吟自成癖。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5172, 17, 28216, '585cd69f61ff4b00580ba631', '西瓜诗', NULL, '吾丘衍', '元', '萍实浮楚江，楚人乃见疑。不逢鲁中叟，谁羡耀日姿。秋风满淮甸，萦蔓络紫丝。邵圃失颜色，翠华射玻瓈。当筵鼓金刀，破此倾酒卮。玉露滴苍佩，月冰散红犀。寄言作歌人，勿咏黄台诗。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5173, 18, 198896, '585d976761ff4b0068926ac8', '昙阳', NULL, '徐渭', '明', '闻道居绵竹，看来幻落花。团团轮北斗，处处种西瓜。遍地皆祗树，何方不落伽。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5174, 19, 338740, '585e69deb123db0065af9db5', '衡仲以西瓜见饷，兼约可园赏月', NULL, '丘逢甲', '清', '蕴雪含冰泌齿凉，两团绿玉许分尝。浮瓜待作南皮会，去赴新亭看月光。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5175, 20, 410880, '585eea5261ff4b0058185931', '夏日村居杂感', NULL, '蔡碧吟', '清', '夹陇凉云刈麦天，沙堤凫母养儿眠。田家女子辛勤惯，昼出锄禾夜纺绵。豢鸭童归又饭牛，菜花拗出短篱幽。数间老屋疏林外，门对一湾溪水流。西瓜凉沁齿牙馀，争说尝浆蜜不如。莱菔松烹菘菜煮，乡间风味胜城居。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5177, 21, 32306, '585cdbd8570c3500692fdc84', '通州道中', NULL, '汪元量', '元', '一片秋云妒太虚，穷荒漠漠走群狐。西瓜黄处藤如织，北枣红时树若屠。雪塞捣砧人戍远，霜营吹角客愁孤。几回兀坐穹庐下，赖有葡萄酒熟初。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5178, 22, 318314, '585e468b128fe1006ba8e60a', '西瓜吟', NULL, '文天祥', '宋', '拔出金佩刀，斫破苍玉瓶。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5179, 23, 362734, '585e974d128fe1006defc78a', '台江杂咏', NULL, '范咸', '清', '柑子甜过橘柚瓤，西瓜亢日得新尝。因耽蕉果能清肺，酷爱番榴是别肠。辨味谁能输荔子，解饥人只食槟榔。西方移得波罗蜜，又种菩提间佛桑。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5181, 24, 19084, '585ccabc8d6d810065dac300', '秋大热上七里滩', NULL, '方回', '元', '吾生所未见，自古恐亦无。秋半不肯凉，赫日炎洪炉。沸湍七里滩，触热乘畏途。坐船汗如浆，况彼牵挽夫。一樯合众力，至数十辈俱。踏竿气欲绝，沙立僵且枯。西瓜足解渴，割裂青瑶肤。焉得大冰盘，沾丐及此徒。侥幸据势位，极意求所娱。愿回君子心，略念小人躯。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5182, 25, 417050, '585ef62361ff4b0063fbbe99', '西瓜', NULL, '郑际魁', '清', '莫将萍实异兹看，老邵当年学种难。青蔓依微缘力弱，含香独抱此心丹。', 'shi', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5183, 26, 395817, '585ecfa31b69e6006cd568ca', '清平乐 · 咏西瓜', NULL, '许淑慧', '清', '绿橘圆洁。', 'ci', 169, '西瓜', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5268, 51, 637546, '5aeda10717d009006628f600', '史记 · 三十世家 · 荆燕世家', NULL, '司马迁', '汉', '荆王刘贾者，诸刘，不知其何属初起时。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5184, 1, 90566, '585d15f961ff4b00688fb2ee', '七言', NULL, '吕岩', '唐', '欲陪仙侣得身轻，飞过蓬莱彻上清。朱顶鹤来云外接，紫鳞鱼向海中迎。姮娥月桂花先吐，王母仙桃子渐成。下瞰日轮天欲晓，定知人世久长生。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5185, 2, 142274, '585d54d3ac502e0067245d47', '寿述夫次韵', NULL, '史谨', '明', '石比心肠鹤比龄，内丹养就外丹成。三偷桃子怜方朔，重识麻姑许蔡经。细雨落花寒食节，平芜蔓草异乡情。明年此日重相庆，只恐青云足下生。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5186, 3, 197414, '585d95748d6d810065dfc1d7', '赠黄炼师', NULL, '孙炎', '明', '留侯弟子有初平，九岁从师住玉京。天与数书皆鸟迹，家传一剑是龙精。瑶池桃子无消息，海水桑田又浅清。我为紫芝歌一曲，夜深相答洞箫声。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5187, 4, 209178, '585da41f570c350069348cb0', '悲哉行', NULL, '袁宏道', '明', '石马立荆棘，荒城叫老狸。昔时冠带人，唯有鹤来?。宿志慕长生，朋党尽刺讥。父母不我容，碧海三山飞。朝牧老君龙，莫守刘安鸡。仙家岁月长，桃子三垂枝。?来见荒冢，半是孙曾碑。城池百易主，族里无从知。古人悲夜绣，今我亦似之。白骨不可语，鹤归空尔为。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5190, 5, 381821, '585eb7b061ff4b006cdcf53c', '画堂春', NULL, '陈祖绶', '清', '柳丝绿过剡溪长。', 'ci', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5192, 6, 411770, '585eebe061ff4b0063fbaab6', '陌头', NULL, '赵熙', '清', '陌头芳草绿天涯，桃子新红又作花。三月东风齐着力，不容燕子不归家。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5193, 7, 221372, '585db42ab123db0065aa7803', '送郑子源之香山二首', NULL, '陈恭尹', '明', '上林桃子洛阳梨，更向增城问荔支。海内知君行欲遍，卷中多有故人诗。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5199, 8, 207001, '585da133128fe1006ba48b88', '游仙词', NULL, '袁华', '明', '铁崖启灵秀，紫虚植仙宗。啸咏登太霞，八鸾韵雍雍。东华命考籍，玉检芝泥封。飞行帝青上，云车扶苍龙。杨君金庭彦，按部昆仑丘。左揽凤凰辔，前驱龙虎辀。轰雷喷小铁，河倾汉西流。下视臭腐辈，尸行不知休。九华有真妃，乃是安郁嫔。学真龟台馆，擢秀牛河津。丹章閟神虎，餐霞啜日根。飙轮宴七景，云辔蹑三辰。下迈杨君家，冥分缔良姻。既欣对景好，夙契心所亲。奚必轻中接，尘劳秽七神。西池蟠桃子，一实三千年。翠羽衔璚花，双飞凌紫烟。阿母启玉齿，笑顾老铁仙。铁仙青藜精，主司文昌权。不比狡狯儿，滑稽称世贤。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5200, 9, 302475, '585e2bedac502e006728ad2f', '为南村题蟠桃图寿喻守', NULL, '顾清', '明', '蟠桃子熟金累累，参差接到花开时。仙山阔远谁貌得，使君燕寝回春姿。海山千里春茫茫，东风是处桃花香。使君有意能小待，实成亦是三千霜。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5201, 10, 304582, '585e2f4fda2f6000658aa336', '同雪公游千顶纪事十首', NULL, '释函可', '明', '望见叠峰刚八里，到来门径各鲜新。不因此地禅居壮，那识长边古佛尊。蓄瓜欲比蘋婆味，见树还生桃子津。夜半犬声何足怪，山中魑魅亦亲人。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5205, 12, 281037, '585e0b1a128fe10069d19d1f', '四斤桃子歌', NULL, '刘崧', '明', '四斤桃子世所珍，雕盘献客夸轮囷。海霞红点王母颊，玉团中涵秋水色。东方娇儿偷不得，美人惜香笑怀核。由来物性系所宜，荃茆橘枳安可期。种成三年苍玉枝，开花结实君始知。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5206, 13, 537879, '586010e061ff4b006302ce98', '秋雨二首', NULL, '张耒', '宋', '南山云起满庭阴，帘幕初凉七月深。桃子压枝桐叶老，连绵风雨作愁霖。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5207, 14, 611542, '5860c36f61ff4b006ce79dc9', '偕仲退周南翁登曲岛山分韵得曲字', NULL, '黎廷瑞', '宋', '吴子精悍锦满腹，周郎英妙人如玉。凌晨樽酒惜分携，飞鞚联翩相趁逐。积雨新晴马气骄，振鬣长鸣踏平陆。村南村北枫叶赤，高田低田麦苗绿。坡陀磊落如培塿，一岛轩然立于独。平生梦寐千仞冈，第取惬心那计足。迢迢鸟道入青天，杳杳钟声出乔木。遥观疑雪复疑石，稍动始知樵与牧。传闻隋代高隐君，避世曾兹结茅屋。李菀杨枯了不闻，坐拥玉书林下读。灵君冠剑从飞龙，云雨苍茫手翻覆。瓢中但出是丰年，何惜穿崖悬一瀑。毳虫自得餐松诀，一扫四山寒翠秃。天根突兀有孤梅，道气昂藏自修竹。回看下界暗黄尘，蚁垤蜂房几陵谷。山空鸟啼尘虑绝，天寒日暮归心速。会当摆落悠悠谈，八极神游纵吾目。玉井莲花十丈开，瑶池桃子千年熟。廓然天地睹方圆，岂但山川见纡曲。已呼鸾凰作先导，岁晚期君两黄鹄。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5209, 15, 53649, '585cf23c128fe1006ba0a5e6', '送宋倬还南康', NULL, '张昱', '元', '及此青春还故乡，顺风几日到南康？峰连五老出空阔，水接二孤来渺茫。徐福楼船能共载，刘安鸡犬亦相将。山桃子落都成树，花里应迷旧草堂。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5210, 16, 177015, '585d7cbbb123db0065a9f4f0', '丁卯腊月十三日恭逢家慈大人八十有四寿日喜赋五章', NULL, '屈大均', '清', '岁岁嘉平月，诗称寿母篇。麻姑将九十，桃子定三千。养恨芝薇薄，居愁市井偏。多金辞仲子，未是许身年。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5211, 17, 264720, '585df0e1ac502e006726de39', '寿萱堂', NULL, '邓林', '明', '南极星联宝婺辉，高堂阿母诞弥时。庭前萱草花如绣，海上蟠桃子满枝。贺客填门来送酒，孩童绕膝待含饴。承欢更有青云子，奉檄还家献寿卮。', 'shi', 170, '桃子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5212, 1, 591553, '58608fb51b69e6005623c84c', '橙子四首', NULL, '刘子翚', '宋', '尚怀细雨初移日，着子已见清霜潸。绝怜面有贵人色，偶致吾侪樽俎间。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5213, 2, 25268, '585cd308128fe1006de4095d', '风入松 · 咏红梅将橙子皮作酒杯', NULL, '白朴', '元', '使君高宴出红梅。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5214, 3, 224871, '585db8e6128fe10069cf55d6', '送刘生二首', NULL, '陶安', '明', '蟹壮湖村橙子黄，秫田绕舍未全荒。双亲住在姑溪上，却望青山是故乡。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5215, 4, 525884, '585ff66761ff4b006ce42bbd', '湖上夜归', NULL, '陆游', '宋', '满镜新霜奈老何，扁舟日日醉颜酡。乐如逐兔牵黄犬，快似麾兵卷白波。霜近菊花犹未见，雨馀橙子已堪搓。湖桑小市人无数，争看山翁击楫歌。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5216, 5, 527781, '585ffb07b123db0065b90afe', '霜夜三首', NULL, '陆游', '宋', '梅花欲动梦魂狂，橙子闲搓指爪香。莫怪草堂清到骨，一梳残月伴新霜。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5217, 6, 591554, '58608fb661ff4b0058214376', '橙子四首', NULL, '刘子翚', '宋', '橙齑细缕风韵胜，我不痛饮那知音。何如金丸走衾枕，三月梦游薝卜林。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5218, 7, 62138, '585cf9ea61ff4b00688ed5e2', '水龙吟', NULL, '蔡松年', '金', '九秋白玉盘高，夜来冷射银河水。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5219, 8, 62150, '585cf9ee61ff4b0063f01b8d', '水调歌头 · 闰八月望夕有作', NULL, '蔡松年', '金', '空凉万家月，摇荡菊花期。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5269, 52, 637547, '5aeda1de9f54543688309401', '史记 · 三十世家 · 齐悼惠王世家', NULL, '司马迁', '汉', '齐悼惠王刘肥者，高祖长庶男也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5220, 9, 35831, '585cdffb128fe10069ca87e3', '又和橙子梅韵', NULL, '耶律楚材', '元', '可笑人心自短长，谁知个事不囊藏。化成橙子舌耽味，幻作梅英鼻觉香。金卵似真随变灭，冰魂元假却芬芳。唯心识破同根旨，何必临风再举扬。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5221, 10, 471562, '585f789e128fe1006bafabed', '朝盘二首', NULL, '周紫芝', '宋', '江近秋深足鲙材，半青橙子带香开。黄金鳞鬣丹砂尾，落纸看成白雪堆。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5222, 11, 563133, '586047598d6d810065ef65ec', '乌夜啼其二醉枕不能寐', NULL, '程垓', '宋', '白酒欺人易醉，黄花笑我多愁。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5223, 12, 591556, '58608fb7da2f60006597cafe', '橙子四首', NULL, '刘子翚', '宋', '花瓷泛蜜小剂供，极有痛快鏖邪功。生枝滋味虽可口，流品故应甘下风。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5224, 13, 635354, '59b6bce3a22b9d006433016c', '浣溪沙 · 武康社日', NULL, '毛滂', '宋', '碧户朱窗小洞房。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5225, 14, 315681, '585e4235128fe1006ded2746', '橙子', NULL, '孔武仲', '宋', '秋露凝浆细，朝阳入色深。冰齑不须捣，恐碎袅蹄金。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5226, 15, 349291, '585e7e69ac502e00672b3bba', '止宿王山史山馆', NULL, '李振裕', '清', '云中白鹤自高翔，有约冲寒到草堂。法物依然藏汉魏，主人自在卧羲皇。药苗入箸霏霏白，橙子垂枝的的黄。绝似江南风味好，琴书一榻枕沧浪。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5227, 16, 563207, '5860478b61ff4b00581fef04', '忆秦娥', NULL, '程垓', '宋', '情脉脉。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5228, 17, 555018, '58603667570c35006943eb31', '胜胜令声声慢寿六十一', NULL, '彭子翔', '宋', '萸房初荐，橙子新搓。', 'ci', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5229, 18, 557485, '58603bac1b69e6006cdd0e30', '橙子', NULL, '曾巩', '宋', '家林香橙有两树，根缠铁钮淩坡陀。鲜明百数见秋实，错缀众叶倾霜柯。翠羽流苏出天仗，黄金戏毬相荡摩。入苞岂数橘柚贱，芼鼎始足盐梅和。江湖苦遭俗眼慢，禁籞尚觉凡木多。谁能出口献天子，一致大树淩沧波。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5230, 19, 63079, '585cfaa461ff4b00580ccfe9', '橙', NULL, '刘因', '元', '潇湘千树暮林平，风露诗肠快一倾。蜜恋金丝仍可意，香分绿蚁最关情。洞庭春色元无恙，南国幽姿谩浊清。惟办酒船千万斛，棹歌和月卷江声。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5231, 20, 576860, '586068c2128fe1006bb47a37', '邹松滋寄苦竹泉橙曲莲子汤三首', NULL, '黄庭坚', '宋', '新收千百秋莲菂，剥尽红衣捣玉霜。不假参同成气味，跳珠碗里绿荷香。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5232, 21, 480525, '585f8c34128fe1006bb03f2f', '橙纲', NULL, '范成大', '宋', '尧舜方堪橘柚包，穹庐亦复使民劳。华清荔子沾恩幸，一骑回时万骑骚。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5234, 23, 576858, '586068c161ff4b0068a27672', '邹松滋寄苦竹泉橙曲莲子汤三首', NULL, '黄庭坚', '宋', '松滋县西竹林寺，苦竹林中甘井泉。巴人漫说虾蟆培，试裹春芽来就煎。', 'shi', 171, '橙子', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5241, 6, 43382, '585ce9111b69e6006cc98583', '思明州', NULL, '陈孚', '元', '刺竹丛丛苦笋生，山禽无数不知名。元宵已似春深后，龙眼花开蛤蚧鸣。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5242, 7, 71584, '585d025f8d6d810065dc72d7', '归闲诗二十韵', NULL, '丁儒', '唐', '漳北遥开郡，泉南久罢屯。归寻初旅寓，喜作旧乡邻。好鸟鸣檐竹，村黎爱幕臣。土音今听惯，民俗始知淳。烽火无传警，江山已净尘。天开一岁暖，花发四时春。杂卉三冬绿，嘉禾两度新。俚歌声靡曼，秫酒味温醇。锦苑来丹荔，清波出素鳞。芭蕉金剖润，龙眼玉生津。蜜取花间露，柑藏树上珍。醉宜藷蔗沥，睡稳木棉茵。茉莉香篱落，榕阴浃里闉。雪霜偏避地，风景独推闽。辞国来诸属，于兹缔六亲。追随情语好，问馈岁时频。相访朝和夕，浑忘越与秦。功成在炎域，事定有闲身。词赋聊酬和，才名任隐沦。呼童多种植，长是此方人。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5243, 8, 137388, '585d4fb08d6d810065defe0e', '夏日过周六园林因有茶瓜之会', NULL, '王恭', '明', '凤岗峰下旧荆扉，龙眼阴阴暑气微。海上云山迢递见，林间车马往来稀。风摇竹露沾纱帽，鸟蹴藤花堕客衣。不为茶能留永日，主人谈笑却忘归。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5244, 9, 144720, '585d575d8d6d810065df23aa', '寄郭蓺团', NULL, '成鹫', '明', '荔枝龙眼又花开，果熟寻僧得几回。千里主宾今李郭，三城人物旧宗雷。云山北望虚酬唱，泷水东流想溯洄。此地曾游许乘兴，石门斜日有人来。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5245, 10, 180233, '585d811a61ff4b0068923de7', '陈村口号', NULL, '屈大均', '清', '渔舟曲折只穿花，溪上人多种树家。风土更饶南北估，荔支龙眼致豪华。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5246, 11, 259425, '585de9481b69e6006ccf2e47', '喜余舅至衙家中儿孙寄来短衫龙眼等物', NULL, '黄公辅', '明', '久无消息度湘湖，一纸平安喜欲呼。乡果沾唇情似蜜，布衫适体爱如乌。一官自笑无长物，八口犹怜有宿逋。秋到疏帘蛩渐语，感时转忆沼边凫。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5247, 12, 256085, '585de457ac502e0067267de2', '野意四首', NULL, '黄衷', '明', '孤村亭午起炊烟，龙眼花繁似去年。蒿雀定应知我浅，惊飞时落涧西田。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5251, 16, 454804, '585f560b128fe1006baeaca8', '龙眼', NULL, '李刘', '宋', '绛衣摇曳绽冰肌，依约华清出浴时。何物鸦儿驱不去，前身恐是食酥儿。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5252, 17, 440136, '585f275ada2f6000658fd548', '八月十四夜对月效李长吉', NULL, '朱翌', '宋', '雨江洗出揉蓝天，结璘下铺白玉筵。尾箕斗牛珠一穿，连晖接影堕我前。整襟危坐天地默，不知夜漏下几刻。飞萤一点从外入，白露下湿桂子香。蓝桥云英正卖浆，金盘荔枝龙眼双。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5253, 18, 557002, '58603aa061ff4b006ce4cd66', '五羊食荔枝龙眼', NULL, '曾丰', '宋', '素闻岭南风，今假岭南馆。穷秋馀夏蒸，初腊借春暖。披衣汗流衣，握简汗流简。似登头痛山，而坐身热坂。谁其善解纷，荔枝杂龙眼。满盘随情堆，入手信意拣。强餐饱为期，一澡得三浣。疑吞玄冰丸，复咽飞雪散。猗欤两清姿，南多北何罕。天曾无全功，地固有偏产。犹记初客闽，厌饫腹频坦。一离馀十年，口与南味断。渴者易为饮，志得而意满。儿辈舌太饶，平章味长短。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5259, 24, 134218, '585d4c6061ff4b0068918709', '龙眼二首', NULL, '王佐', '明', '少昊车前照乘珠，祝融部下岂台舆。荔枝只为肌肤厚，买得人间佞口谀。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5263, 28, 176094, '585d7b85b123db0065a9f1dd', '蕉利村春望', NULL, '屈大均', '清', '望望烟波上，芭蕉满海天。人家龙眼国，生计荔枝田。日出莺花里，云生鸡犬边。捕鱼乘水节，一一放罛船。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5264, 29, 178623, '585d7ee961ff4b0063f37e9c', '代怨别曲', NULL, '屈大均', '清', '益智为龙眼，蠲愁是荔枝。为君空采摘，无路寄相思。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5265, 30, 42632, '585ce825ac502e006720ec7f', '广州杂咏和刘主事子高', NULL, '徐贲', '元', '绕门龙眼树森然，香蜡时来海外船。木屧蒲葵已成俗，红蕉丹荔不论钱。', 'shi', 172, '桂圆', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5270, 53, 637548, '5aeda2c77f6fd300387b80b3', '史记 · 三十世家 · 萧相国世家 ', NULL, '司马迁', '汉', '萧相国何者，沛丰人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5271, 54, 637549, '5aeda2f19f54546d18e17f01', '史记 · 三十世家 · 曹相国世家', NULL, '司马迁', '汉', '平阳侯曹参者，沛人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5272, 55, 637550, '5aeda31a9f54543688309ed6', '史记 · 三十世家 · 留侯世家', NULL, '司马迁', '汉', '留侯张良者，其先韩人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5273, 56, 637551, '5aeda508ac502e60763e413f', '史记 · 三十世家 · 陈丞相世家 ', NULL, '司马迁', '汉', '陈丞相平者，阳武户牖乡人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5274, 57, 637552, '5aeda59c17d00900662920fb', '史记 · 三十世家 · 绛侯周勃世家 ', NULL, '司马迁', '汉', '绛侯周勃者，沛人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5275, 58, 637553, '5aeda5e2fe88c2374025b26a', '史记 · 三十世家 · 梁孝王世家', NULL, '司马迁', '汉', '梁孝王武者，孝文皇帝子也，而与孝景帝同母。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5276, 59, 637554, '5aeda69117d009006629299b', '史记 · 三十世家 · 五宗世家', NULL, '司马迁', '汉', '孝景皇帝子凡十三人为王，而母五人，同母者为宗亲。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5277, 60, 637555, '5aeda6f69f54546d18e1a48b', '史记 · 三十世家 · 三王世家', NULL, '司马迁', '汉', '“大司马臣去病昧死再拜上疏皇帝陛下：陛下过听，使臣去病待罪行间。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5278, 61, 637556, '5aeda741ee920a1e147284d8', '史记 · 七十列传 · 伯夷列传', NULL, '司马迁', '汉', '夫学者载籍极博。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5280, 62, 637558, '5aeda7b79f5454368830c9ac', '史记 · 七十列传 · 老子韩非列传', NULL, '司马迁', '汉', '老子者，楚苦县厉乡曲仁里人也，姓李氏，名耳，字聃，周守藏室之史也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5281, 63, 637560, '5aeda7ef9f5454368830cb90', '史记 · 七十列传 · 司马穰苴列传', NULL, '司马迁', '汉', '司马穰苴者，田完之苗裔也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5282, 64, 637561, '5aeda81217d009006629382f', '史记 · 七十列传 · 孙子吴起列传', NULL, '司马迁', '汉', '孙子武者，齐人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5283, 65, 637575, '5af01be7fb4ffed775821746', '史记 · 七十列传 · 伍子胥列传', NULL, '司马迁', '汉', '伍子胥者，楚人也，名员。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5285, 66, 637577, '5af01c750b616030db430fab', '史记 · 七十列传 · 商君列传', NULL, '司马迁', '汉', '商君者，卫之诸庶孽公子也，名鞅，姓公孙氏，其祖本姬姓也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5286, 67, 637578, '5af01db9ee920a1e14801c81', '史记 · 七十列传 · 苏秦列传', NULL, '司马迁', '汉', '苏秦者，东周雒阳人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5287, 68, 637579, '5af01ee19f54545462b620fe', '史记 · 七十列传 · 张仪列传 ', NULL, '司马迁', '汉', '张仪者，魏人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5288, 69, 637580, '5af01f1244d90400370657d5', '史记 · 七十列传 · 樗里子甘茂列传', NULL, '司马迁', '汉', '樗里子者，名疾，秦惠王之弟也，与惠王异母。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5289, 70, 637581, '5af01f3e0b616030db43240c', '史记 · 七十列传 · 穰侯列传', NULL, '司马迁', '汉', '穰侯魏厓者，秦昭王母宣太后弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5290, 71, 637582, '5af01f679f54545462b62545', '史记 · 七十列传 · 白起王翦列传', NULL, '司马迁', '汉', '白起者，郿人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5291, 72, 637583, '5af02050a22b9d00444cc491', '史记 · 七十列传 · 孟子荀卿列传 ', NULL, '司马迁', '汉', '太史公曰：余读孟子书，至梁惠王问“何以利吾国”，未尝不废书而叹也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5292, 73, 637584, '5af0209f7f6fd300388967bd', '史记 · 七十列传 · 孟尝君列传', NULL, '司马迁', '汉', '孟尝君名文，姓田氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5293, 74, 637585, '5af020cc7f6fd300388969d9', '史记 · 七十列传 · 平原君虞卿列传', NULL, '司马迁', '汉', '平原君赵胜者，赵之诸公子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5294, 75, 637586, '5af0212044d9040037066648', '史记 · 七十列传 · 魏公子列传', NULL, '司马迁', '汉', '魏公子无忌者，魏昭王少子而魏安釐王异母弟也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5295, 76, 637587, '5af0214317d009744e58cab3', '史记 · 七十列传 · 春申君列传', NULL, '司马迁', '汉', '春申君者，楚人也，名歇，姓黄氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5296, 77, 637588, '5af021c60b616030db433821', '史记 · 七十列传 · 范睢蔡泽列传', NULL, '司马迁', '汉', '范睢者，魏人也，字叔。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5297, 78, 637589, '5af021f544d9040037066bea', '史记 · 七十列传 · 乐毅列传', NULL, '司马迁', '汉', '乐毅者，其先祖曰乐羊。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5299, 49, 637531, '5aec23802f301e437089eca5', '史记 · 三十世家 · 外戚世家', NULL, '司马迁', '汉', '自古受命帝王及继体守文之君，非独内德茂也，盖亦有外戚之助焉。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5300, 79, 637593, '5af1493117d009744e5f24d1', '史记 · 七十列传 · 廉颇蔺相如列传', NULL, '司马迁', '汉', '廉颇者，赵之良将也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5301, 80, 637594, '5af149dfac502e6076526357', '史记 · 七十列传 · 田单列传 ', NULL, '司马迁', '汉', '田单者，齐诸田疏属也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5302, 81, 637595, '5af14a4544d90400370cbd24', '史记 · 七十列传 · 鲁仲连邹阳列传', NULL, '司马迁', '汉', '鲁仲连者，齐人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5303, 82, 637596, '5af14a6f2f301e4370a75115', '史记 · 七十列传 · 屈原贾生列传 ', NULL, '司马迁', '汉', '屈原者，名平，楚之同姓也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
