INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5305, 84, 637598, '5af14c50fe88c2374039e430', '史记 · 七十列传 · 刺客列传', NULL, '司马迁', '汉', '曹沫者，鲁人也，以勇力事鲁庄公。', 'wen', 163, '史记', '', NULL, '', '', '', '');
