INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5308, 87, 637601, '5af14d89ee920a1e1486b56c', '史记 · 七十列传 · 张耳陈馀列传', NULL, '司马迁', '汉', '张耳者，大梁人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5309, 88, 637602, '5af14dad9f54545462bcbee0', '史记 · 七十列传 · 魏豹彭越列传 ', NULL, '司马迁', '汉', '魏豹者，故魏诸公子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5310, 89, 637603, '5af14dcf17d009744e5f4a88', '史记 · 七十列传 · 黥布列传', NULL, '司马迁', '汉', '黥布者，六人也，姓英氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5312, 90, 637604, '5af14e007f6fd300388fe401', '史记 · 七十列传 · 淮阴侯列传 ', NULL, '司马迁', '汉', '淮阴侯韩信者，淮阴人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5313, 91, 637605, '5af14e2a0b616030db49b7af', '史记 · 七十列传 · 韩信卢绾列传', NULL, '司马迁', '汉', '韩王信者，故韩襄王孽孙也，长八尺五寸。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5314, 92, 637606, '5af14ec8ac502e6076528632', '史记 · 七十列传 · 田儋列传', NULL, '司马迁', '汉', '田儋者，狄人也，故齐王田氏族也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5315, 93, 637607, '5af14ee89f5454747009857b', '史记 · 七十列传 · 樊郦滕灌列传', NULL, '司马迁', '汉', '舞阳侯樊哙者，沛人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5316, 94, 637612, '5af2a6739f545407fc488f24', '史记 · 七十列传 · 张丞相列传', NULL, '司马迁', '汉', '张丞相苍者，阳武人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5317, 95, 637613, '5af2a6c1ac502e60765a4c00', '史记 · 七十列传 · 郦生陆贾列传', NULL, '司马迁', '汉', '郦生食其者，陈留高阳人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5318, 96, 637614, '5af2a7042f301e4370af3b12', '史记 · 七十列传 · 傅靳蒯成列传', NULL, '司马迁', '汉', '阳陵侯傅宽，以魏五大夫骑将从，为舍人，起横阳。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5319, 97, 637615, '5af2a7efa22b9d00445b16cf', '史记 · 七十列传 · 刘敬叔孙通列传', NULL, '司马迁', '汉', '刘敬者，齐人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5320, 98, 637616, '5af2a82c7f6fd3003897bb1a', '史记 · 七十列传 · 季布栾布列传', NULL, '司马迁', '汉', '季布者，楚人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5321, 99, 637617, '5af2a850a22b9d00445b1988', '史记 · 七十列传 · 袁盎晁错列传', NULL, '司马迁', '汉', '袁盎楚人也，字丝。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5322, 100, 637618, '5af2a9b10b616030db51ab85', '史记 · 七十列传 · 张释之冯唐列传', NULL, '司马迁', '汉', '张廷尉释之者，堵阳人也，字季。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5323, 101, 637619, '5af2a9e32f301e4370af5022', '史记 · 七十列传 · 万石张叔列传 ', NULL, '司马迁', '汉', '万石君名奋，其父赵人也，姓石氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5324, 102, 637620, '5af2aa41fb4ffed77590ac41', '史记 · 七十列传 · 田叔列传', NULL, '司马迁', '汉', '田叔者，赵陉城人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5325, 103, 637621, '5af2aa79a22b9d00445b289b', '史记 · 七十列传 · 扁鹊仓公列传', NULL, '司马迁', '汉', '扁鹊者，勃海郡郑人也，姓秦氏，名越人。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5326, 104, 637622, '5af2aa9dac502e60765a6a51', '史记 · 七十列传 · 吴王濞列传', NULL, '司马迁', '汉', '吴王濞者，高帝兄刘仲之子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5327, 105, 637623, '5af2ab710b616030db51baeb', '史记 · 七十列传 · 魏其武安侯列传', NULL, '司马迁', '汉', '魏其侯窦婴者，孝文后从兄子也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5328, 106, 637624, '5af2abbb2f301e4370af5e05', '史记 · 七十列传 · 韩长孺列传 ', NULL, '司马迁', '汉', '御史大夫韩安国者，梁成安人也，后徙睢阳。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5329, 107, 637625, '5af2abdffb4ffed77590b822', '史记 · 七十列传 · 李将军列传', NULL, '司马迁', '汉', '李将军广者，陇西成纪人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5330, 108, 637626, '5af2ac17ac502e60765a7544', '史记 · 七十列传 · 匈奴列传', NULL, '司马迁', '汉', '匈奴，其先祖夏后氏之苗裔也，曰淳维。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5331, 109, 637633, '5af4034b44d90400371d1047', '史记 · 七十列传 · 卫将军骠骑列传', NULL, '司马迁', '汉', '大将军卫青者，平阳人是也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5333, 110, 637635, '5af40470a22b9d0044637369', '史记 · 七十列传 · 南越列传', NULL, '司马迁', '汉', '南越王尉佗者，真定人也，姓赵氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5334, 111, 637636, '5af405239f54545462ccf5f4', '史记 · 七十列传 · 东越列传', NULL, '司马迁', '汉', '闽越王无诸及越王海王摇者，其先皆越王勾践之后也，姓驺氏。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5335, 112, 637637, '5af405a0a22b9d0044637e4f', '史记 · 七十列传 · 朝鲜列传', NULL, '司马迁', '汉', '朝鲜王满者，故燕人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5336, 113, 637638, '5af406319f545407fc5110e6', '史记 · 七十列传 · 西南夷列传', NULL, '司马迁', '汉', '西南夷君长以什数，夜郎最大；', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5337, 114, 637639, '5af40658fb4ffed77599026d', '史记 · 七十列传 · 司马相如列传', NULL, '司马迁', '汉', '司马相如者，蜀郡成都人也，字长卿。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5338, 115, 637640, '5af407e80b616057d1b9a7c1', '史记 · 十列传 · 淮南衡山列传', NULL, '司马迁', '汉', '淮南厉王长者，高祖少子也，其母故赵王张敖美人。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5339, 116, 637641, '5af408152f301e4370b7c268', '史记 · 七十列传 · 循吏列传', NULL, '司马迁', '汉', '太史公曰：法令所以导民也，刑罚所以禁奸也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5340, 117, 637642, '5af40838ee920a1e1496fd51', '史记 · 七十列传 · 汲郑列传 ', NULL, '司马迁', '汉', '汲黯字长孺，濮阳人也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5341, 118, 637643, '5af4085944d90400371d39ab', '史记 · 七十列传 · 儒林列传', NULL, '司马迁', '汉', '太史公曰：余读功令，至于广厉学官之路，未尝不废书而叹也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5342, 119, 637644, '5af40c8f2f301e4370b7e92d', '史记 · 七十列传 · 酷吏列传', NULL, '司马迁', '汉', '孔子曰：“道之以政，齐之以刑，民免而无耻。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5343, 120, 637645, '5af40d7244d90400371d66ed', '史记 · 七十列传 · 大宛列传 ', NULL, '司马迁', '汉', '大宛之迹，见自张骞。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5345, 121, 637647, '5af40f6afe88c2200cada4ae', '史记 · 七十列传 · 佞幸列传', NULL, '司马迁', '汉', '谚曰“力田不如逢年，善仕不如遇合”，固无虚言。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5346, 122, 637650, '5af54ac49f54543ead7495b4', '史记 · 七十列传 · 滑稽列传', NULL, '司马迁', '汉', '孔子曰：“六艺于治一也。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5347, 123, 637651, '5af54af00b616057d1c16cda', '史记 · 七十列传 · 日者列传', NULL, '司马迁', '汉', '自古受命而王，王者之兴何尝不以卜筮决于天命哉！', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5348, 124, 637652, '5af54b2e9f54543ead74985a', '史记 · 七十列传 · 龟策列传', NULL, '司马迁', '汉', '太史公曰：自古圣王将建国受命，兴动事业，何尝不宝卜筮以助善！', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5349, 125, 637653, '5af54b5444d904003724e503', '史记 · 七十列传 · 货殖列传', NULL, '司马迁', '汉', '老子曰：“至治之极，邻国相望，鸡犬之声相闻，民各甘其食，美其服，安其俗，乐其业，至老死不相往来。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5350, 127, 637654, '5af54b800b616057d1c1708e', '史记 · 七十列传 · 太史公自序', NULL, '司马迁', '汉', '昔在颛顼，命南正重以司天，北正黎以司地。', 'wen', 163, '史记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5401, 1, 636472, '5aae7bb12f301e0036713397', '妙法莲华经 ·  御制大乘妙法莲华经序', NULL, '释迦牟尼', '周', '昔如来于耆阇崛山中，与大阿罗汉阿若憍陈如、摩诃迦叶无量等众，演说大乘真经，名《无量义》。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5402, 2, 636473, '5aae7c79a22b9d0045c229e1', '妙法莲华经 · 妙法莲华经弘传序', NULL, '释迦牟尼', '周', '《妙法莲华经》者，统诸佛降灵之本致也。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5403, 3, 636476, '5aae7ecaa22b9d0045c2397d', '妙法莲华经 · 序品第一', NULL, '释迦牟尼', '周', '如是我闻。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5404, 4, 636480, '5aae82959f54540037607699', '妙法莲华经 · 方便品第二', NULL, '释迦牟尼', '周', '尔时，世尊从三昧安详而起，告舍利弗：“诸佛智慧，甚深无量，其智慧门，难解难入，一切声闻、辟支佛、所不能知。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5405, 5, 636481, '5aae8bc12f301e0036719343', '妙法莲华经 · 譬喻品第三', NULL, '释迦牟尼', '周', '尔时舍利弗踊跃欢喜，即起、合掌、瞻仰尊颜、而白佛言：“今从世尊闻此法音，心怀踊跃，得未曾有。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5406, 6, 636535, '5ab1122375657116a39511e1', '妙法莲华经 · 信解品第四', NULL, '释迦牟尼', '周', '尔时慧命须菩提、摩诃迦旃延、摩诃迦叶、摩诃目犍连，从佛所、闻未曾有法，世尊授舍利弗阿耨多罗三藐三菩提记，发稀有心，欢喜踊跃，即从座起，整衣服，偏袒右肩，右膝着地，一心合掌，屈躬恭敬，瞻仰尊颜、而白佛言：“我等居僧之首，年并朽迈，自谓已得涅槃，无所堪任，不复进求阿耨多罗三藐三菩提。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5407, 7, 636539, '5ab113e12f301e0036800f42', '妙法莲华经 · 药草喻品第五', NULL, '释迦牟尼', '周', '尔时世尊告摩诃迦叶、及诸大弟子：“善哉、善哉，迦叶善说如来真实功德。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5408, 8, 636542, '5ab115caac502e57c92ed7e0', '妙法莲华经 · 授记品第六', NULL, '释迦牟尼', '周', '尔时世尊说是偈已，告诸大众，唱如是言：“我此弟子摩诃迦叶，于未来世、当得奉觐三百万亿诸佛世尊，供养、恭敬，尊重、赞叹，广宣诸佛无量大法。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5409, 9, 636544, '5ab129c79f545400376fac33', '妙法莲华经 · 化城喻品第七', NULL, '释迦牟尼', '周', '佛告诸比丘：“乃往过去无量无边不可思议阿僧祇劫，尔时有佛，名大通智胜如来、应供、正遍知、明行足、善逝世间解、无上士、调御丈夫、天人师、佛、世尊，其国名好城，劫名大相。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5410, 10, 636545, '5ab13366ac502e57c92f8a91', '妙法莲华经 · 五百弟子受记品第八', NULL, '释迦牟尼', '周', '尔时富楼那弥多罗尼子、从佛闻是智慧方便、随宜说法，又闻授诸大弟子阿耨多罗三藐三菩提记，复闻宿世因缘之事，复闻诸佛有大自在神通之力，得未曾有，心净踊跃。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5411, 11, 636546, '5ab1b4d32f301e0036825885', '妙法莲华经 · 授学无学人记品第九', NULL, '释迦牟尼', '周', '尔时阿难、罗侯罗、而作是念：“我等每自思惟，设得授记，不亦快乎。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5412, 12, 636547, '5ab1b5ada22b9d0045d33099', '妙法莲华经 · 法师品第十', NULL, '释迦牟尼', '周', '尔时世尊因药王菩萨、告八万大士：“药王，汝见是大众中，无量诸天、龙王、夜叉、乾闼婆、阿修罗、迦楼罗、紧那罗、摩侯罗伽、人与非人、及比丘、比丘尼、优婆塞、优婆夷、求声闻者，求辟支佛者，求佛道者，如是等类，咸于佛前、闻妙法华经一偈一句、乃至一念随喜者，我皆与授记，当得阿耨多罗三藐三菩提。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5413, 13, 636548, '5ab1b69644d90418a20fd155', '妙法莲华经 · 见宝塔品第十一', NULL, '释迦牟尼', '周', '尔时佛前有七宝塔，高五百由旬，纵广二百五十由旬，从地涌出，住在空中，种种宝物而庄校之。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5414, 14, 636549, '5ab1bd842f301e0036828b91', '妙法莲华经 · 提婆达多品第十二', NULL, '释迦牟尼', '周', '尔时佛告诸菩萨、及天人四众：“吾于过去无量劫中，求法华经，无有懈倦。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5415, 15, 636550, '5ab1be1fa22b9d0045d361af', '妙法莲华经 · 劝持品第十三', NULL, '释迦牟尼', '周', '尔时药王菩萨摩诃萨、及大乐说菩萨摩诃萨、与二万菩萨眷属俱，皆于佛前、作是誓言：“惟愿世尊不以为虑，我等于佛灭后，当奉持、读诵、说此经典。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5416, 16, 636551, '5ab1c87f44d90418a21047fd', '妙法莲华经 · 安乐行品第十四', NULL, '释迦牟尼', '周', '尔时文殊师利法王子菩萨摩诃萨、白佛言：“世尊，是诸菩萨，甚为稀有，敬顺佛故，发大誓愿，于后恶世、护持读说是法华经。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5417, 17, 636552, '5ab1c95c9f5454003771db6f', '妙法莲华经 · 从地踊出品第十五', NULL, '释迦牟尼', '周', '尔时他方国土诸来菩萨摩诃萨，过八恒河沙数，于大众中起，合掌作礼、而白佛言：“世尊，若听我等、于佛灭后，在此娑婆世界，勤加一精一进，护持、读诵、书写、供养、是经典者，当于此土而广说之。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5418, 18, 636646, '5ab4fe6a756571108cdb23a2', '妙法莲华经 · 如来寿量品第十六', NULL, '释迦牟尼', '周', '尔时、佛告诸菩萨及一切大众：“诸善男子，汝等当信解如来诚谛之语。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5419, 19, 636647, '5ab4ff339f54541326d043c7', '妙法莲华经 · 分别功德品第十七', NULL, '释迦牟尼', '周', '尔时大会、闻佛说寿命劫数长远如是，无量无边阿僧祇众生、得大饶益。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5420, 20, 636652, '5ab51b782f301e1c2c35b936', '妙法莲华经 · 随喜功德品第十八', NULL, '释迦牟尼', '周', '尔时、弥勒菩萨摩诃萨白佛言：「世尊，若有善男子、善女人，闻是法华经、随喜者，得几所福？', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5421, 21, 636656, '5ab525489f54547d1c3e2a15', '妙法莲华经 · 法师功德品第十九', NULL, '释迦牟尼', '周', '尔时佛告常一精一进菩萨摩诃萨：“若善男子、善女人，受持是法华经，若读、若诵，若解说、若书写，是人当得八百眼功德、千二百耳功德、八百鼻功德、千二百舌功德、八百身功德、千二百意功德，以是功德、庄严六根，皆令清净。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5422, 23, 636658, '5ab52777ee920a396f251add', '妙法莲华经 · 如来神力品第二十一', NULL, '释迦牟尼', '周', '尔时千世界微尘等菩萨摩诃萨、从地涌出者，皆于佛前、一心合掌，瞻仰尊颜，而白佛言：“世尊，我等于佛灭后，世尊分身所在国土、灭度之处，当广说此经，所以者何。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5423, 24, 636659, '5ab5282117d009688774480a', '妙法莲华经 · 嘱累品第二十二', NULL, '释迦牟尼', '周', '尔时释迦牟尼佛从法座起，现大神力，以右手摩无量菩萨摩诃萨顶，而作是言：“我于无量百千万亿阿僧祇劫、修习是难得阿耨多罗三藐三菩提法，今以付嘱汝等，汝等应当一心流布此法，广令增益。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5424, 25, 636660, '5ab528c017d0096887744a74', '妙法莲华经 · 药王菩萨本事品第二十三', NULL, '释迦牟尼', '周', '尔时宿王华菩萨白佛言：“世尊，药王菩萨、云何游于娑婆世界，世尊，是药王菩萨、有若干百千万亿那由他难行苦行，善哉、世尊，愿少解说。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5425, 26, 636663, '5ab529669f54547d1c3e401b', '妙法莲华经 · 妙音菩萨品第二十四', NULL, '释迦牟尼', '周', '尔时释迦牟尼佛放大人相、肉髻光明，及放眉间白毫相光，遍照东方百八万亿那由他恒河沙等诸佛世界。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5426, 27, 636664, '5ab52a819f54547d1c3e4446', '妙法莲华经 · 观世音菩萨普门品第二十五', NULL, '释迦牟尼', '周', '尔时无尽意菩萨、即从座起，偏袒右肩，合掌向佛、而作是言：“世尊，观世音菩萨、以何因缘、名观世音？', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5427, 28, 636665, '5ab52b359f545437fe924ae7', '妙法莲华经 · 陀罗尼品第二十六', NULL, '释迦牟尼', '周', '尔时药王菩萨、即从座起，偏袒右肩，合掌向佛、而白佛言：“世尊，若善男子、善女人，有能受持法华经者。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5428, 29, 636666, '5ab52bdbee920a396f252d2d', '妙法莲华经 · 妙庄严王本事品第二十七', NULL, '释迦牟尼', '周', '尔时佛告诸大众：“乃往古世、过无量无边不可思议阿僧祇劫，有佛、名云雷音宿王华智、多陀阿伽度、阿罗诃、三藐三佛陀，国名光明庄严，劫名喜见。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5429, 30, 636667, '5ab52c7a9f54547d1c3e4ca6', '妙法莲华经 · 普贤菩萨劝发品第二十八', NULL, '释迦牟尼', '周', '尔时普贤菩萨、以自在神通力，威德名闻，与大菩萨无量无边不可称数、从东方来，所经诸国，普皆震动，雨宝莲华，作无量百千万亿种种伎乐。', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5430, 22, 636657, '5ab526f0ac502e57c9459e1c', '妙法莲华经 · 常不轻菩萨品第二十', NULL, '释迦牟尼', '周', '尔时，佛告得大势菩萨摩诃萨：汝今当知！', 'wen', 174, '妙法莲华经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5431, 1, 636346, '5aaba47a9f545417b4b81e85', '维摩诘经 · 佛国品第一', NULL, '鸠摩罗什', '晋', '如是我闻：一时，佛在毗耶离庵罗树园，与大比丘众，八千人俱。', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5432, 2, 636347, '5aaba4e9a22b9d0045b0d408', '维摩诘经 · 方便品第二', NULL, '鸠摩罗什', '晋', '尔时，毗耶离大城中有长者，名维摩诘，已曾供养无量诸佛，深植善本，得无生忍；', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5433, 3, 636348, '5aaba55875657116a3752e31', '维摩诘经 · 弟子品第三', NULL, '鸠摩罗什', '晋', '尔时，长者维摩诘自念：寝疾于床，世尊大慈，宁不垂愍？', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
