INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5436, 6, 637764, '5b023a2844d9041d3f24997e', '维摩诘经 · 不思议品第六', NULL, '释迦牟尼', '周', '尔时，舍利弗见此室中无有床座，作是念：斯诸菩萨大弟子众，当于何坐？', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
