INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5439, 9, 637767, '5b023c8cfb4ffe005d6a133d', '维摩诘经 · 入不二法门品第九', NULL, '释迦牟尼', '周', '尔时，维摩诘谓众菩萨言：‘诸仁者！', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5440, 10, 637768, '5b023cfba22b9d0044b93333', '维摩诘经 · 香积佛品第十', NULL, '释迦牟尼', '周', '于是舍利弗心念：日时欲至，此诸菩萨当于何食？', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5441, 11, 637769, '5b023d6f7f6fd3188a68a85e', '维摩诘经 · 菩萨行品第十一', NULL, '释迦牟尼', '周', '是时，佛说法于庵罗树园，其地忽然广博严事，一切众会皆作金色。', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5442, 12, 637770, '5b023dba44d9041d3f24b03e', '维摩诘经 · 见阿佛品第十二', NULL, '释迦牟尼', '周', '尔时，世尊问维摩诘：‘汝欲见如来，为以何等观如来乎？', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5443, 13, 637771, '5b023e132f301e0062532f2b', '维摩诘经 · 法供养品第十三', NULL, '释迦牟尼', '周', '尔时，释提恒因，于大众中白佛言：‘世尊！', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5444, 14, 637773, '5b023eae2f301e00625333c2', '维摩诘经 · 嘱累品第十四', NULL, '释迦牟尼', '周', '于是，佛告弥勒菩萨言：‘弥勒！', 'wen', 175, '维摩诘经', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5445, 1, 637783, '5b052c6a2f301e0038f51727', '天地', NULL, '刘彻', '汉', '天地并况，惟予有慕，爰熙紫坛，思求厥路。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5446, 2, 637784, '5b052ce5ac502e006283f5ac', '日出入', NULL, '两汉乐府', '汉', '日出入安穷，时世不与人同。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5447, 3, 637785, '5b052dfa9f54540043aa2c91', ' 天马二首 · 其一', NULL, '刘彻', '汉', '太一况，天马下，沾赤汗，沫流赭。', 'shi', 74, '乐府诗集', '', NULL, '', '', '', '');
