INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5784, 10, 637869, '5b0e7775d50eee00893b558f', '红楼梦 · 第十回 · 金寡妇贪利权受辱 张太医论病细穷源', NULL, '曹雪芹', '清', '话说金荣因人多势众，又兼贾瑞勒令，赔了不是，给秦钟磕了头，宝玉方才不吵闹了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5785, 11, 637870, '5b0e77a79f5454008841cb5c', '红楼梦 · 第十一回 · 庆寿辰宁府排家宴 见熙凤贾瑞起淫心', NULL, '曹雪芹', '清', '话说是日贾敬的寿辰，贾珍先将上等可吃的东西，稀奇些的果品，装了十六大捧盒，着贾蓉带领家下人等与贾敬送去，向贾蓉说道：“你留神看太爷喜欢不喜欢，你就行了礼来。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5786, 12, 637871, '5b0e77d844d9040068182377', '红楼梦 · 第十二回 · 王熙凤毒设相思局 贾天祥正照风月鉴', NULL, '曹雪芹', '清', '话说凤姐正与平儿说话，只见有人回说：“瑞大爷来了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5787, 13, 637872, '5b0e780c44d90400681824f1', '红楼梦 · 第十三回 · 秦可卿死封龙禁尉 王熙凤协理宁国府', NULL, '曹雪芹', '清', '话说凤姐儿自贾琏送黛玉往扬州去后，心中实在无趣，每到晚间，不过和平儿说笑一回，就胡乱睡了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5788, 14, 637873, '5b0e7840d50eee00893b5ac1', '红楼梦 · 第十四回 · 林如海捐馆扬州城 贾宝玉路谒北静王', NULL, '曹雪芹', '清', '话说宁国府中都总管来升闻得里面委请了凤姐，因传齐同事人等说道：“如今请了西府里琏二奶奶管理内事，倘或他来支取东西，或是说话，我们须要比往日小心些。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5789, 15, 637874, '5b0e7875ee920a0044a3fc9f', '红楼梦 · 第十五回 · 王凤姐弄权铁槛寺 秦鲸卿得趣馒头庵', NULL, '曹雪芹', '清', '话说宝玉举目见北静王水溶头上戴着洁白簪缨银翅王帽，穿着江牙海水五爪坐龙白蟒袍，系着碧玉红鞓带，面如美玉，目似明星，真好秀丽人物。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
