INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5840, 16, 637877, '5b0fa57467f356003b89bef2', '红楼梦 · 第十六回 · 贾元春才选凤藻宫 秦鲸卿夭逝黄泉路', NULL, '曹雪芹', '清', '话说宝玉见收拾了外书房，约定与秦钟读夜书。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5841, 17, 637878, '5b0fa5a9d50eee4e5b52a2d9', '红楼梦 · 第十七回 · 大观园试才题对额 荣国府归省庆元宵', NULL, '曹雪芹', '清', '话说秦钟既死，宝玉痛哭不已，李贵等好容易劝解半日方住，归时犹是凄恻哀痛。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5842, 18, 637879, '5b0fa5e3a22b9d00327581dd', '红楼梦 · 第十八回 · 皇恩重元妃省父母  天伦乐宝玉呈才藻', NULL, '曹雪芹', '清', '话说宝玉来至院外，就有跟贾政的几个小厮上来拦腰抱住，都说：“今儿亏我们，老爷才喜欢，老太太打发人出来问了几遍，都亏我们回说喜欢，不然，若老太太叫你进去，就不得展才了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5843, 19, 637880, '5b0fa6152f301e00382ebe12', '红楼梦 · 第十九回 · 情切切良宵花解语 意绵绵静日玉生香', NULL, '曹雪芹', '清', '话说贾妃回宫，次日见驾谢恩，并回奏归省之事，龙颜甚悦。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5844, 20, 637881, '5b0fa65644d90400681e6e43', '红楼梦 · 第二十回 · 王熙凤正言弹妒意 林黛玉俏语谑娇音', NULL, '曹雪芹', '清', '话说宝玉在林黛玉房中说“耗子精”，宝钗撞来，讽刺宝玉元宵不知“绿蜡”之典，三人正在房中互相讥刺取笑。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5845, 21, 637882, '5b0fa686ac502e0062212877', '红楼梦 · 第二十一回 · 贤袭人娇嗔箴宝玉 俏平儿软语救贾琏', NULL, '曹雪芹', '清', '话说史湘云跑了出来，怕林黛玉赶上，宝玉在后忙说：“仔细绊跌了！', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5846, 22, 637883, '5b0fa6da67f356003b89c7c7', '红楼梦 · 第二十二回 · 听曲文宝玉悟禅机 制灯谜贾政悲谶语', NULL, '曹雪芹', '清', '话说贾琏听凤姐儿说有话商量，因止步问是何话。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5847, 23, 637884, '5b0fa7069f54545e3adf4f68', '红楼梦 · 第二十三回 · 西厢记妙词通戏语 牡丹亭艳曲警芳心', NULL, '曹雪芹', '清', '话说贾元春自那日幸大观园回宫去后，便命将那日所有的题咏，命探春依次抄录妥协，自己编次，叙其优劣，又命在大观园勒石，为千古风流雅事。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5848, 24, 637885, '5b0fa748fb4ffe005b17b3e1', '红楼梦 · 第二十四回 · 醉金刚轻财尚义侠 痴女儿遗帕惹相思', NULL, '曹雪芹', '清', '话说林黛玉正自情思萦逗，缠绵固结之时，忽有人从背后击了一掌，说道：“你作什么一个人在这里？', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5849, 25, 637886, '5b0fa7f6d50eee4e5b52b4ee', '红楼梦 · 第二十五回 · 魇魔法姊弟逢五鬼 红楼梦通灵遇双真', NULL, '曹雪芹', '清', '话说红玉心神恍惚，情思缠绵，忽朦胧睡去，遇见贾芸要拉他，却回身一跑，被门槛绊了一跤，唬醒过来，方知是梦。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5850, 26, 637887, '5b0fa8259f54545e3adf5896', '红楼梦 · 第二十六回 · 蜂腰桥设言传心事 潇湘馆春困发幽情', NULL, '曹雪芹', '清', '话说宝玉养过了三十三天之后，不但身体强壮，亦且连脸上疮痕平服，仍回大观园内去。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5852, 28, 637889, '5b0fa881a22b9d0032759710', '红楼梦 · 第二十八回 · 蒋玉菡情赠茜香罗 薛宝钗羞笼红麝串', NULL, '曹雪芹', '清', '话说林黛玉只因昨夜晴雯不开门一事，错疑在宝玉身上。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5853, 29, 637890, '5b0fa8c0fb4ffe005b17be13', '红楼梦 · 第二十九回 · 享福人福深还祷福 痴情女情重愈斟情', NULL, '曹雪芹', '清', '话说宝玉正自发怔，不想黛玉将手帕子甩了来，正碰在眼睛上，倒唬了一跳，问是谁。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5854, 30, 637891, '5b0fa8ec9f5454617c3fda51', '红楼梦 · 第三十回 · 宝钗借扇机带双敲 龄官划蔷痴及局外', NULL, '曹雪芹', '清', '话说林黛玉与宝玉角口后，也自后悔，但又无去就他之理，因此日夜闷闷，如有所失。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
