INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5907, 31, 637901, '5b10bf05d50eee4e5b588fa6', '红楼梦 · 第三十一回 · 撕扇子作千金一笑 因麒麟伏白首双星', NULL, '曹雪芹', '清', '话说袭人见了自己吐的鲜血在地，也就冷了半截，想着往日常听人说：“少年吐血，年月不保，纵然命长，终是废人了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5908, 32, 637902, '5b10bf33ac502e0062319350', '红楼梦 · 第三十二回 · 诉肺腑心迷活宝玉 含耻辱情烈死金钏', NULL, '曹雪芹', '清', '话说宝玉见那麒麟，心中甚是欢喜，便伸手来拿，笑道：“亏你拣着了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5909, 33, 637903, '5b10bf66ac502e0062319718', '红楼梦 · 第三十三回 · 手足耽耽小动唇舌 不肖种种大承笞挞', NULL, '曹雪芹', '清', '却说王夫人唤他母亲上来，拿几件簪环当面赏与，又吩咐请几众僧人念经超度。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5910, 34, 637904, '5b10bf95d50eee4e5b589556', '红楼梦 · 第三十四回 · 情中情因情感妹妹 错里错以错劝哥哥', NULL, '曹雪芹', '清', '话说袭人见贾母王夫人等去后，便走来宝玉身边坐下，含泪问他：“怎么就打到这步田地？', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5911, 35, 637905, '5b10bfc99f5454617c45ad6f', '红楼梦 · 第三十五回 · 白玉钏亲尝莲叶羹 黄金莺巧结梅花络', NULL, '曹雪芹', '清', '话说宝钗分明听见林黛玉刻薄他，因记挂着母亲哥哥，并不回头，一径去了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5912, 36, 637906, '5b10c0009f5454564990433f', '红楼梦 · 第三十六回 · 绣鸳鸯梦兆绛芸轩 识分定情悟梨香院', NULL, '曹雪芹', '清', '话说贾母自王夫人处回来，见宝玉一日好似一日，心中自是欢喜。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5913, 37, 637907, '5b10c02d2f301e003834b0a9', '红楼梦 · 第三十七回 · 秋爽斋偶结海棠社 蘅芜苑夜拟菊花题', NULL, '曹雪芹', '清', '这年贾政又点了学差，择于八月二十日起身。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5914, 38, 637908, '5b10c05dd50eee4e5b589b50', '红楼梦 · 第三十八回 · 林潇湘魁夺菊花诗 薛蘅芜讽和螃蟹咏', NULL, '曹雪芹', '清', '话说宝钗湘云二人计议已妥，一宿无话。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5915, 39, 637909, '5b10c08afb4ffe005b1da676', '红楼梦 · 第三十九回 · 村姥姥是信口开合 情哥哥偏寻根究底', NULL, '曹雪芹', '清', '话说众人见平儿来了，都说：“你们奶奶作什么呢，怎么不来了？', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5916, 40, 637910, '5b10c0c22f301e003834b436', '红楼梦 · 第四十回 · 史太君两宴大观园 金鸳鸯三宣牙牌令', NULL, '曹雪芹', '清', '话说宝玉听了，忙进来看时，只见琥珀站在屏风跟前说：“快去吧，立等你说话呢。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5917, 41, 637911, '5b10c0f867f356003b8fbffd', '红楼梦 · 第四十一回 · 栊翠庵茶品梅花雪 怡红院劫遇母蝗虫', NULL, '曹雪芹', '清', '话说刘姥姥两只手比着说道：“花儿落了结个大倭瓜。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5918, 42, 637912, '5b10c12667f356003b8fc0f9', '红楼梦 · 第四十二回 · 蘅芜君兰言解疑癖 潇湘子雅谑补余香', NULL, '曹雪芹', '清', '话说他姊妹复进园来，吃过饭，大家散出，都无别话。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5919, 43, 637913, '5b10c16267f356003b8fc28e', '红楼梦 · 第四十三回 · 闲取乐偶攒金庆寿 不了情暂撮土为香', NULL, '曹雪芹', '清', '话说王夫人因见贾母那日在大观园不过着了些风寒，不是什么大病，请医生吃了两剂药也就好了，便放了心，因命凤姐来吩咐他预备给贾政带送东西。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
