INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5974, 47, 637923, '5b14a1f4d50eee4e5b6dbe98', '红楼梦 · 第四十七回 · 呆霸王调情遭苦打 冷郎君惧祸走他乡', NULL, '曹雪芹', '清', '话说王夫人听见邢夫人来了，连忙迎了出去。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
