INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5977, 50, 637926, '5b14a295fb4ffe005b32dc34', '红楼梦 · 第五十回 · 芦雪庵争联即景诗 暖香坞雅制春灯谜', NULL, '曹雪芹', '清', '话说薛宝钗道：「到底分个次序，让我写出来。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5978, 51, 637927, '5b14a2ee2f301e0038de8e01', '红楼梦 · 第五十一回 · 薛小妹新编怀古诗 胡庸医乱用虎狼药', NULL, '曹雪芹', '清', '众人闻得宝琴将素习所经过各省内的古迹为题，作了十首怀古绝句，内隐十物，皆说这自然新巧。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5979, 52, 637928, '5b14a32b9f54545649a59844', '红楼梦 · 第五十二回 · 俏平儿情掩虾须镯 勇晴雯病补雀金裘', NULL, '曹雪芹', '清', '贾母道：“正是这话了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5980, 53, 637929, '5b14a365d50eee4e5b6dcc4d', '红楼梦 · 第五十三回 · 宁国府除夕祭宗祠 荣国府元宵开夜宴', NULL, '曹雪芹', '清', '话说宝玉见晴雯将雀裘补完，已使的力尽神危，忙命小丫头子来替他捶着，彼此捶打了一会歇下。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5981, 54, 637930, '5b14a39a2f301e003849ee39', '红楼梦 · 第五十四回 · 史太君破陈腐旧套 王熙凤效戏彩斑衣', NULL, '曹雪芹', '清', '却说贾珍贾琏暗暗预备下大簸箩的钱，听见贾母说“赏”，他们也忙命小厮们快撒钱。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5982, 55, 637931, '5b14a3d5ee920a253fce3c46', '红楼梦 · 第五十五回 · 辱亲女愚妾争闲气 欺幼主刁奴蓄险心', NULL, '曹雪芹', '清', '且说元宵已过，只因当今以孝治天下，目下宫中有一位太妃欠安，故各嫔妃皆为之减膳谢妆，不独不能省亲，亦且将宴乐俱免。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5983, 56, 637932, '5b14a42c7f6fd30063c0601e', '红楼梦 · 第五十六回 · 敏探春兴利除宿弊 时宝钗小惠全大体', NULL, '曹雪芹', '清', '话说平儿陪着凤姐儿吃了饭，伏侍盥漱毕，方往探春处来。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5984, 57, 637933, '5b14a4572f301e003849f3bf', '红楼梦 · 第五十七回 · 慧紫鹃情辞试忙玉 慈姨妈爱语慰痴颦', NULL, '曹雪芹', '清', '话说宝玉听王夫人唤他，忙至前边来，原来是王夫人要带他拜甄夫人去。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5985, 58, 637934, '5b14a48544d9040068504530', '红楼梦 · 第五十八回 · 杏子阴假凤泣虚凰 茜纱窗真情揆痴理', NULL, '曹雪芹', '清', '话说他三人因见探春等进来，忙将此话掩住不提。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (5986, 59, 637935, '5b14a4b22f301e003849f64c', '红楼梦 · 第五十九回 · 柳叶渚边嗔莺咤燕 绛云轩里召将飞符', NULL, '曹雪芹', '清', '话说宝玉听说贾母等回来，遂多添了一件衣服，拄杖前边来，都见过了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
