INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6030, 38, 440425, '585f289fb123db0065b31cc8', '西江月', NULL, '朱敦儒', '宋', '澹澹薰风庭院，青青过雨园林。', 'ci', 183, '西江月', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6031, 39, 634869, '58e5c77c61ff4b0061880d1a', '西江月 · 念念欲归未得', NULL, '李之仪', '宋', '念念欲归未得，迢迢此去何求。', 'ci', 183, '西江月', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6032, 40, 577614, '58606aeb61ff4b006303aa8e', '西江月 · 老夫既戒酒不饮，遇宴集，独醒其旁。坐客欲得小词，援笔为赋', NULL, '黄庭坚', '宋', '断送一生惟有，破除万事无过。', 'ci', 183, '西江月', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6033, 66, 637958, '5b15f92b9f54545649ad155d', '红楼梦 · 第六十六回 · 情小妹耻情归地府 冷二郎一冷入空门', NULL, '曹雪芹', '清', '话说鲍二家的打他一下子，笑道：“原有些真的，叫你又编了这混话，越发没了捆儿。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6034, 67, 637959, '5b15f9609f54545a72d3b378', '红楼梦 · 第六十七回 · 见土仪颦卿思故里 闻秘事凤姐讯家童', NULL, '曹雪芹', '清', '话说尤三姐自尽之后，尤老娘和二姐儿，贾珍，贾琏等俱不胜悲恸，自不必说，忙令人盛殓，送往城外埋葬。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6035, 68, 637960, '5b15f98fac502e2d45cad982', '红楼梦 · 第六十八回 · 苦尤娘赚入大观园 酸凤姐大闹宁国府', NULL, '曹雪芹', '清', '话说贾琏起身去后，偏值平安节度巡边在外，约一个月方回。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6036, 69, 637961, '5b15f9d8a22b9d0032981d81', '红楼梦 · 第六十九回 · 弄小巧用借剑杀人 觉大限吞生金自逝', NULL, '曹雪芹', '清', '话说尤二姐听了，又感谢不尽，只得跟了他来。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6037, 70, 637962, '5b15fa14ac502e2d45cae0e7', '红楼梦 · 第七十回 · 林黛玉重建桃花社 史湘云偶填柳絮词', NULL, '曹雪芹', '清', '话说贾琏自在梨香院伴宿七日夜，天天僧道不断做佛事。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6038, 71, 637963, '5b15fa432f301e0038e61f16', '红楼梦 · 第七十一回 · 嫌隙人有心生嫌隙 鸳鸯女无意遇鸳鸯', NULL, '曹雪芹', '清', '话说贾政回京之后，诸事完毕，赐假一月在家歇息。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6039, 73, 637965, '5b15fa94fb4ffe005b3a7203', '红楼梦 · 第七十三回 · 痴丫头误拾绣春囊 懦小姐不问累金凤', NULL, '曹雪芹', '清', '话说那赵姨娘和贾政说话，忽听外面一声响，不知何物。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6040, 74, 637966, '5b15fabfa22b9d0032982354', '红楼梦 · 第七十四回 · 惑奸谗抄检大观园 矢孤介杜绝宁国府', NULL, '曹雪芹', '清', '话说平儿听迎春说了正自好笑，忽见宝玉也来了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6041, 75, 637967, '5b15faf12f301e0038e624a7', '红楼梦 · 第七十五回 · 开夜宴异兆发悲音 赏中秋新词得佳谶', NULL, '曹雪芹', '清', '话说尤氏从惜春处赌气出来，正欲往王夫人处去。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6042, 76, 637968, '5b15fb2944d904006864a5ec', '红楼梦 · 第七十六回 · 凸碧堂品笛感凄清 凹晶馆联诗悲寂寞', NULL, '曹雪芹', '清', '话说贾赦贾政带领贾珍等散去不提。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6043, 77, 637969, '5b15fb5c2f301e0038517f02', '红楼梦 · 第七十七回 · 俏丫鬟抱屈夭风流 美优伶斩情归水月', NULL, '曹雪芹', '清', '话说王夫人见中秋已过，凤姐病已比先减了，虽未大愈，可以出入行走得了，仍命大夫每日诊脉服药，又开了丸药方子来配调经养荣丸。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6044, 78, 637970, '5b15fb8fd50eee4e5b755df5', '红楼梦 · 第七十八回 · 老学士闲征姽婳词 痴公子杜撰芙蓉诔', NULL, '曹雪芹', '清', '话说两个尼姑领了芳官等去后，王夫人便往贾母处来省晨，见贾母喜欢，便趁便回道：“宝玉屋里有个晴雯，那个丫头也大了，而且一年之间，病不离身，我常见他比别人分外淘气，也懒，前日又病倒了十几天，叫大夫瞧，说是女儿痨，所以我就赶着叫他下去了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6045, 79, 637972, '5b15fbf89f54545649ad284b', '红楼梦 · 第七十九回 · 薛文龙悔娶河东狮 贾迎春误嫁中山狼', NULL, '曹雪芹', '清', '话说宝玉祭完了晴雯，只听花影中有人声，倒唬了一跳。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6046, 80, 637974, '5b15fc4e2f301e00385184ce', '红楼梦 · 第八十回 · 美香菱屈受贪夫棒 王道士胡诌妒妇方', NULL, '曹雪芹', '清', '话说金桂听了，将脖项一扭，嘴唇一撇，鼻孔里哧了两声，拍着掌冷笑道：“菱角花谁闻见香来着？', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6047, 81, 637975, '5b15fc837f6fd30063c7e02d', '红楼梦 · 第八十一回 · 占旺相四美钓游鱼 奉严词两番入家塾', NULL, '曹雪芹', '清', '且说迎春归去之后，邢夫人像没有这事，倒是王夫人抚养了一场，却甚实伤感，在房中自己叹息了一回。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6048, 82, 637977, '5b15fd2244d904006864c414', '红楼梦 · 第八十二回 · 老学究讲义警顽心 病潇湘痴魂惊恶梦', NULL, '曹雪芹', '清', '话说宝玉下学回来，见了贾母。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6049, 83, 637978, '5b15fd4d2f301e0038e63334', '红楼梦 · 第八十三回 · 省宫闱贾元妃染恙 闹闺阃薛宝钗吞声', NULL, '曹雪芹', '清', '话说探春湘云才要走时，忽听外面一个人嚷道：“你这不成人的小蹄子！', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6050, 84, 637979, '5b15fd747f6fd30063c7e5c8', '红楼梦 · 第八十四回 · 试文字宝玉始提亲 探惊风贾环重结怨', NULL, '曹雪芹', '清', '却说薛姨妈一时因被金桂这场气怄得肝气上逆，左肋作痛。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6051, 85, 637980, '5b15fda9ee920a253fd5c32d', '红楼梦 · 第八十五回 · 贾存周报升郎中任 薛文起复惹放流刑', NULL, '曹雪芹', '清', '话说赵姨娘正在屋里抱怨贾环，只听贾环在外间屋里发话道：“我不过弄倒了药铞子，洒了一点子药，那丫头子又没就死了，值的他也骂我，你也骂我，赖我心坏，把我往死里糟蹋。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6052, 72, 637964, '5b15fa6d67f356003bac9426', '红楼梦 · 第七十二回 · 王熙凤恃强羞说病 来旺妇倚势霸成亲', NULL, '曹雪芹', '清', '且说鸳鸯出了角门，脸上犹红，心内突突的，真是意外之事。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6053, 1, 634830, '58d7c995a22b9d006467bdb6', '减字木兰花 · 卖花担上', NULL, '李清照', '宋', '卖花担上，买得一枝春欲放。', 'ci', 184, '减字木兰花', '', NULL, '', '', '', '');
