INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6141, 108, 638021, '5b18edd167f356003185b05f', '红楼梦 · 第一百零八回 · 强欢笑蘅芜庆生辰 死缠绵潇湘闻鬼哭', NULL, '曹雪芹', '清', '却说贾政先前曾将房产并大观园奏请入官，内廷不收，又无人居住，只好封锁。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6142, 109, 638022, '5b18ee3ffb4ffe0031280da8', '红楼梦 · 第一百零九回 · 候芳魂五儿承错爱 还孽债迎女返真元', NULL, '曹雪芹', '清', '话说宝钗叫袭人问出原故，恐宝玉悲伤成疾，便将黛玉临死的话与袭人假作闲谈，说是：“人生在世，有意有情，到了死后各自干各自的去了，并不是生前那样个人死后还是这样。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6143, 110, 638023, '5b18f0eda22b9d0034a0fe35', '红楼梦 · 第一百一十回 · 史太君寿终归地府 王凤姐力诎失人心', NULL, '曹雪芹', '清', '却说贾母坐起说道：“我到你们家已经六十多年了。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6144, 111, 638024, '5b18f21b17d009005b941c30', '红楼梦 · 第一百一十一回 · 鸳鸯女殉主登太虚 狗彘奴欺天招伙盗', NULL, '曹雪芹', '清', '话说凤姐听了小丫头的话，又气又急又伤心，不觉吐了一口血，便昏晕过去，坐在地下。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6145, 112, 638025, '5b18f25fac502e003426b394', '红楼梦 · 第一百一十二回 · 活冤孽妙尼遭大劫 死雠仇赵妾赴冥曹', NULL, '曹雪芹', '清', '话说凤姐命捆起上夜众女人送营审问，女人跪地哀求。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6146, 113, 638026, '5b18f2f167f356003185f172', '红楼梦 · 第一百一十三回 · 忏宿冤凤姐托村妪 释旧憾情婢感痴郎', NULL, '曹雪芹', '清', '话说赵姨娘在寺内得了暴病，见人少了，更加混说起来，唬得众人都恨，就有两个女人搀着。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6147, 114, 638027, '5b18f46cd50eee0031dd8f74', '红楼梦 · 第一百一十四回 · 王熙凤历幻返金陵 甄应嘉蒙恩还玉阙', NULL, '曹雪芹', '清', '却说宝玉宝钗听说凤姐病的危急，赶忙起来。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6148, 115, 638028, '5b18f5499f5454003bff64cb', '红楼梦 · 第一百一十五回 · 惑偏私惜春矢素志　证同类宝玉失相知', NULL, '曹雪芹', '清', '话说宝玉为自己失言被宝钗问住，想要掩饰过去，只见秋纹进来说：“外头老爷叫二爷呢。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6149, 116, 638029, '5b18f6092f301e0038a26409', '红楼梦 · 第一百一十六回 · 得通灵幻境悟仙缘 送慈柩故乡全孝道', NULL, '曹雪芹', '清', '话说宝玉一听麝月的话，身往后仰，复又死去，急得王夫人等哭叫不止。', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (6150, 117, 638030, '5b18f728d50eee0031dda9ae', '红楼梦 · 第一百一十七回 · 阻超凡佳人双护玉 欣聚党恶子独承家', NULL, '曹雪芹', '清', '话说王夫人打发人来叫宝钗过去商量，宝玉听见说是和尚在外头，赶忙的独自一人走到前头，嘴里乱嚷道：“我的师父在那里？', 'wen', 179, '红楼梦', '', NULL, '', '', '', '');
