INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8991, 1, 638769, '5b861369d50eee003902bab3', '世说新语 · 德行第一', NULL, '刘义庆', '南北朝', '陈仲举言为士则，行为世范，登车揽辔，有澄清天下之志。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
