INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8993, 3, 638771, '5b8646b3a22b9d0037d8d7a2', '世说新语 · 政事第三', NULL, '刘义庆', '南北朝', '陈仲弓为太丘长，时吏有诈称母病求假。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8994, 4, 638772, '5b865204ee920a003b8d7824', '世说新语 · 文学第四', NULL, '刘义庆', '南北朝', '郑玄在马融门下，三年不得相见，高足弟子传授而已。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8995, 5, 638773, '5b8652e7a22b9d0037d95451', '世说新语 · 方正第五', NULL, '刘义庆', '南北朝', '陈太丘与友期行，期日中。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8996, 6, 638774, '5b86550bfb4ffe0031dcdddb', '世说新语 · 雅量第六', NULL, '刘义庆', '南北朝', '豫章太守顾邵，是雍之子。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8997, 7, 638775, '5b8655750b616000630d99fa', '世说新语 · 识鉴第七', NULL, '刘义庆', '南北朝', '曹公少时见乔玄，玄谓曰：“天下方乱，群雄虎争，拨而理之，非君乎？', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8998, 8, 638776, '5b865638808ca4003d90f2f5', '世说新语 · 赏誉第八', NULL, '刘义庆', '南北朝', '陈仲举尝叹曰：“若周子居者，真治国之器。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (8999, 9, 638777, '5b865746570c35003838f62c', '世说新语 · 品藻第九', NULL, '刘义庆', '南北朝', '汝南陈仲举，颍川李元礼二人，共论其功德，不能定先后。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9000, 10, 638778, '5b8658ea67f3560034572060', '世说新语 · 规箴第十', NULL, '刘义庆', '南北朝', '汉武帝乳母尝于外犯事，帝欲申宪，乳母求救东方朔。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9038, 118, 638846, '5b88f81f9f545400312db6f0', '正宫 · 小梁州 · 春怀', NULL, '任昱', '元', '落花无数满汀洲，转眼春休。', 'qu', 109, '元曲三百首', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9001, 11, 638779, '5b865980a22b9d0037d99989', '世说新语 · 捷悟第十一', NULL, '刘义庆', '南北朝', '杨德祖为魏武主簿，时作相国门，始构榱桷，魏武自出看，使人题门作「活」字，便去。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9002, 12, 638780, '5b8659d5d50eee0039055a59', '世说新语 · 夙惠第十二', NULL, '刘义庆', '南北朝', '宾客诣陈太丘宿，太丘使元方、季方炊。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9003, 13, 638781, '5b865a4167f3560034572e1f', '世说新语 · 豪爽第十三', NULL, '刘义庆', '南北朝', '王大将军年少时，旧有田舍名，语音亦楚。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9004, 14, 638782, '5b865aa967f356003457318e', '世说新语 · 容止第十四', NULL, '刘义庆', '南北朝', '魏武将见匈奴使，自以形陋，不足雄远国，使崔季圭代，帝自捉刀立床头。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9005, 15, 638783, '5b865aebd50eee0039056392', '世说新语 · 自新第十五', NULL, '刘义庆', '南北朝', '周处年少时，凶彊侠气，为乡里所患；', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9006, 16, 638784, '5b865b3bd50eee0039056677', '世说新语 · 企羡第十六', NULL, '刘义庆', '南北朝', '王丞相拜司空，桓廷尉作两髻、葛群、策杖，路边窥之，叹曰：“人言阿龙超，阿龙故自超。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9007, 17, 638786, '5b865c5fd50eee003905756d', '世说新语 · 伤逝第十七', NULL, '刘义庆', '南北朝', '王仲宣好驴鸣。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9008, 18, 638787, '5b865cf1a22b9d0037d9bcb6', '世说新语 · 栖逸第十八', NULL, '刘义庆', '南北朝', '阮步兵啸，闻数百步。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9009, 19, 638788, '5b865d5a808ca4003d913d28', '世说新语 · 贤媛第十九', NULL, '刘义庆', '南北朝', '陈婴者，东阳人。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9010, 20, 638789, '5b865db80b616000630de692', '世说新语 · 术解第二十', NULL, '刘义庆', '南北朝', '荀勖善解音声，时论谓之闇解。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9011, 21, 638807, '5b87b001808ca4003d9b7a57', '世说新语 · 巧艺第二十一', NULL, '刘义庆', '南北朝', '弹棋始自魏宫内，用妆奁戏。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9012, 22, 638808, '5b87b07ea22b9d0037e3febc', '世说新语 · 宠礼第二十二', NULL, '刘义庆', '南北朝', '元帝正会，引王丞相登御床，王公固辞，中宗引之弥苦。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9013, 23, 638809, '5b87b0fcfb4ffe0031e79b6d', '世说新语 · 任诞第二十三', NULL, '刘义庆', '南北朝', '陈留阮籍，谯国嵇康，河内山涛，三人年皆相比，康年少亚之。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9014, 24, 638810, '5b87b17b67f3560034619957', '世说新语 · 简傲第二十四', NULL, '刘义庆', '南北朝', '晋文王功德盛大，坐席严敬，拟于王者。', 'wen', 301, '世说新语', '', NULL, '', '', '', '');
