INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9299, 17, 639050, '5b96300c67f356005c5805d1', '西游记 · 第十七回 · 孙行者大闹黑风山 观世音收伏熊罴怪', NULL, '吴承恩', '明', '话说孙行者一筋斗跳将起去，唬得那观音院大小和尚并头陀、幸童、道人等一个个朝天礼拜道：“爷爷呀！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9300, 18, 639051, '5b9630411b69e6005b6c67e2', ' 西游记 · 第十八回 · 观音院唐僧脱难 高老庄行者降魔', NULL, '吴承恩', '明', '行者辞了菩萨，按落云头，将袈裟挂在香楠树上，掣出棒来，打入黑风洞里。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9301, 19, 639052, '5b96307dfb4ffe005c7a03a9', '西游记 · 第十九回 · 云栈洞悟空收八戒 浮屠山玄奘受心经', NULL, '吴承恩', '明', '却说那怪的火光前走，这大圣的彩霞随跟。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9302, 20, 639053, '5b9630a5570c350063fa0b36', '西游记 · 第二十回 · 黄风岭唐僧有难 半山中八戒争先', NULL, '吴承恩', '明', '偈曰：“法本从心生，还是从心灭。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9303, 21, 639054, '5b9630d0808ca43cd2ecdfae', '西游记 · 第二十一回 · 护法设庄留大圣 须弥灵吉定风魔', NULL, '吴承恩', '明', '却说那五十个败残的小妖，拿着些破旗破鼓，撞入洞里，报道：“大王，虎先锋战不过那毛脸和尚，被他赶下东山坡去了。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9304, 22, 639055, '5b9630f91b69e6005b6c746e', '西游记 · 第二十二回 · 八戒大战流沙河 木叉奉法收悟净', NULL, '吴承恩', '明', '话说唐僧师徒三众，脱难前来，不一日，行过了八百黄风岭，进西却是一脉平阳之地。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9305, 23, 639056, '5b963122fb4ffe005c7a0dd3', '西游记 · 第二十三回 · 三藏不忘本 四圣试禅心', NULL, '吴承恩', '明', '诗曰：奉法西来道路赊，秋风渐浙落霜花。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9306, 24, 639057, '5b9631501b69e6005b6c7aa1', '西游记 · 第二十四回 · 万寿山大仙留故友 五庄观行者窃人参', NULL, '吴承恩', '明', '却说那三人穿林入里，只见那呆子绷在树上，声声叫喊，痛苦难禁。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9307, 25, 639058, '5b96317afb4ffe005c7a1413', '西游记 · 第二十五回 · 镇元仙赶捉取经僧 孙行者大闹五庄观', NULL, '吴承恩', '明', '却说他兄弟三众，到了殿上，对师父道：“饭将熟了，叫我们怎的？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9308, 26, 639059, '5b96319f808ca43cd2eced52', '西游记 · 第二十六回 · 孙悟空三岛求方 观世音甘泉活树', NULL, '吴承恩', '明', '诗曰：处世须存心上刃，修身切记寸边而。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9309, 27, 639060, '5b9631c9570c350063fa28b0', '西游记 · 第二十七回 · 尸魔三戏唐三藏 圣僧恨逐美猴王', NULL, '吴承恩', '明', '却说三藏师徒，次日天明，收拾前进。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9310, 28, 639061, '5b9631eefb4ffe005c7a1b04', '西游记 · 第二十八回 · 花果山群妖聚义 黑松林三藏逢魔', NULL, '吴承恩', '明', '却说那大圣虽被唐僧逐赶，然犹思念，感叹不已，早望见东洋大海，道：“我不走此路者，已五百年矣！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9311, 29, 639062, '5b963212570c350063fa30d0', '西游记 · 第二十九回 · 脱难江流来国土 承恩八戒转山林', NULL, '吴承恩', '明', '诗曰：妄想不复强灭，真如何必希求？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9312, 30, 639063, '5b96323c808ca43cd2ecf8ad', '西游记 · 第三十回 · 邪魔侵正法 意马忆心猿', NULL, '吴承恩', '明', '却说那怪把沙僧捆住，也不来杀他，也不曾打他，骂也不曾骂他一句，绰起钢刀，心中暗想道：“唐僧乃上邦人物，必知礼义，终不然我饶了他性命，又着他徒弟拿我不成？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9313, 31, 639064, '5b9632641579a3003a19f626', '西游记 · 第三十一回 · 猪八戒义激猴王 孙行者智降妖怪', NULL, '吴承恩', '明', '义结孔怀，法归本性。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9314, 32, 639065, '5b9632941579a3003a19f8fa', '西游记 · 第三十二回 · 平顶山功曹传信 莲花洞木母逢灾', NULL, '吴承恩', '明', '话说唐僧复得了孙行者，师徒们一心同体，共诣西方。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9315, 33, 639066, '5b9632bd9f5454003982cfc8', '西游记 · 第三十三回 · 外道迷真性 元神助本心', NULL, '吴承恩', '明', '却说那怪将八戒拿进洞去道：“哥哥啊，拿将一个来了。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9316, 34, 639067, '5b9632e3570c350063fa45eb', '西游记 · 第三十四回 · 魔王巧算困心猿 大圣腾那骗宝贝', NULL, '吴承恩', '明', '却说那两个小妖，将假葫芦拿在手中，争看一会，忽抬头不见了行者。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9317, 35, 639068, '5b96331017d0090034e1bf9d', '西游记 · 第三十五回 · 外道施威欺正性 心猿获宝伏邪魔', NULL, '吴承恩', '明', '“本性圆明道自通，翻身跳出网罗中。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9318, 36, 639069, '5b9633359f5454003982d818', '西游记 · 第三十六回 · 心猿正处诸缘伏 劈破旁门见月明', NULL, '吴承恩', '明', '却说孙行者按落云头，对师父备言菩萨借童子、老君收去宝贝之事。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9319, 37, 639070, '5b96335e808ca43cd2ed0b8f', '西游记 · 第三十七回 · 鬼王夜谒唐三藏 悟空神化引婴儿', NULL, '吴承恩', '明', '却说三藏坐于宝林寺禅堂中，灯下念一会《梁皇水忏》，看一会《孔雀真经》，只坐到三更时候，却才把经本包在囊里，正欲起身去睡，只听得门外扑剌剌一声响-，淅零零刮阵狂风。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9320, 38, 639071, '5b963383fb4ffe005c7a34f0', '西游记 · 第三十八回 · 婴儿问母知邪正 金木参玄见假真', NULL, '吴承恩', '明', '逢君只说受生因，便作如来会上人。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9321, 39, 639072, '5b9633b4570c350063fa5a81', '西游记 · 第三十九回 · 一粒金丹天上得 三年故主世间生', NULL, '吴承恩', '明', '话说那孙大圣头痛难禁，哀告道：“师父，莫念！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9322, 40, 639073, '5b9633eb808ca43cd2ed14c9', '西游记 · 第四十回 · 婴儿戏化禅心乱 猿马刀归木母空', NULL, '吴承恩', '明', '却说那孙大圣兄弟三人，按下云头，径至朝内，只见那君臣储后，几班儿拜接谢恩。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9323, 41, 639075, '5b9783e81579a3003a27a647', '西游记 · 第四十一回 · 心猿遭火败 木母被魔擒', NULL, '吴承恩', '明', '善恶一时忘念，荣枯都不关心。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9324, 42, 639076, '5b978414fb4ffe005c87eade', '西游记 · 第四十二回 · 大圣殷勤拜南海 观音慈善缚红孩', NULL, '吴承恩', '明', '话说那六健将出洞门，径往西南上，依路而走。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9325, 43, 639077, '5b97844767f356005c65ddb0', '西游记· 第四十三回 · 黑河妖孽擒僧去 西洋龙子捉鼍回', NULL, '吴承恩', '明', '却说那菩萨念了几遍，却才住口，那妖精就不疼了。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9326, 44, 639078, '5b97847367f356005c65dfbb', '西游记 · 第四十四回 · 法身元运逢车力 心正妖邪度脊关', NULL, '吴承恩', '明', '诗曰：求经脱障向西游，无数名山不尽休。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9327, 45, 639079, '5b97849f1579a3003a27afbe', '西游记 · 第四十五回 · 三清观大圣留名 车迟国猴王显法', NULL, '吴承恩', '明', '却说孙大圣左手把沙和尚捻一把，右手把猪八戒捻一把，他二人却就省悟，坐在高处，倥着脸，不言不语，凭那些道士点灯着火，前后照看，他三个就如泥塑金装一般模样。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9328, 46, 639080, '5b9784c31579a3003a27b11b', '西游记 · 第四十六回 · 外道弄强欺正法 心猿显圣灭诸邪', NULL, '吴承恩', '明', '话说那国王见孙行者有呼龙使圣之法，即将关文用了宝印，便要递与唐僧，放行西路。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9329, 47, 639081, '5b9784eafb4ffe005c87f51c', '西游记 · 第四十七回 · 圣僧夜阻通天水 金木垂慈救小童', NULL, '吴承恩', '明', '却说那国王倚着龙床，泪如泉涌，只哭到天晚不住。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9330, 48, 639082, '5b97851817d0090034ef64bf', '西游记 · 第四十八回 · 魔弄寒风飘大雪 僧思拜佛履层冰', NULL, '吴承恩', '明', '话说陈家庄众信人等，将猪羊牲醴与行者八戒，喧喧嚷嚷，直抬至灵感庙里排下，将童男女设在上首。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9331, 49, 639083, '5b97853d67f356005c65e955', '西游记 · 第四十九回 · 三藏有灾沉水宅 观音救难现鱼篮', NULL, '吴承恩', '明', '却说孙大圣与八戒、沙僧辞陈老来至河边，道：“兄弟，你两个议定，那一个先下水。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9332, 50, 639084, '5b97862417d0090034ef7285', '西游记 · 第五十回 · 情乱性从因爱欲 神昏心动遇魔头', NULL, '吴承恩', '明', '词曰：心地频频扫，尘情细细除，莫教坑堑陷毗卢。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9333, 51, 639085, '5b97864b9f545400399093f3', '西游记 · 第五十一回 · 心猿空用千般计 水火无功难炼魔', NULL, '吴承恩', '明', '话说齐天大圣，空着手败了阵，来坐于金-山后，扑梭梭两眼滴泪，叫道：“师父啊！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9334, 52, 639086, '5b978679570c3500631482c0', '西游记 · 第五十二回 · 悟空大闹金山兜洞 如来暗示主人公', NULL, '吴承恩', '明', '话说孙大圣得了金箍棒，打出门前，跳上高峰，对众神满心欢喜。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9335, 53, 639087, '5b9786a59f54540039909989', '西游记 · 第五十三回 · 禅主吞餐怀鬼孕 黄婆运水解邪胎', NULL, '吴承恩', '明', '    德行要修八百，阴功须积三千。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9336, 54, 639088, '5b9786ce570c35006314895d', '西游记 · 第五十四回 · 法性西来逢女国 心猿定计脱烟花', NULL, '吴承恩', '明', '话说三藏师徒别了村舍人家，依路西进，不上三四十里，早到西梁国界。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9337, 55, 639089, '5b9787031579a3003a27d224', '西游记 · 第五十五回 · 色邪淫戏唐三藏 性正修持不坏身', NULL, '吴承恩', '明', '却说孙大圣与猪八戒正要使法定那些妇女，忽闻得风响处，沙僧嚷闹，急回头时，不见了唐僧。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9338, 56, 639090, '5b97872a1579a3003a27d3b4', '西游记 · 第五十六回 · 神狂诛草寇 道昧放心猿', NULL, '吴承恩', '明', '诗曰：灵台无物谓之清，寂寂全无一念生。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9339, 57, 639091, '5b97874e1b69e6005b7a75a6', '西游记 · 第五十七回 · 真行者落伽山诉苦 假猴王水帘洞誊文', NULL, '吴承恩', '明', '却说孙大圣恼恼闷闷，起在空中，欲待回花果山水帘洞，恐本洞小妖见笑，笑我出乎尔反乎尔，不是个大丈夫之器；', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9340, 58, 639092, '5b9787731579a3003a27d6bb', '西游记 · 第五十八回 · 二心搅乱大乾坤 一体难修真寂灭', NULL, '吴承恩', '明', '这行者与沙僧拜辞了菩萨，纵起两道祥光，离了南海。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9341, 59, 639093, '5b97879afb4ffe005c881932', '西游记 · 第五十九回 · 唐三藏路阻火焰山 孙行者一调芭蕉扇', NULL, '吴承恩', '明', '若干种性本来同，海纳无穷。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9342, 60, 639094, '5b9788fe1b69e6005b7a8caf', '西游记 · 第六十回 · 牛魔王罢战赴华筵 孙行者二调芭蕉扇', NULL, '吴承恩', '明', '土地说：“大力王即牛魔王也。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9343, 61, 639095, '5b978925808ca43cd2fadde1', '西游记 · 第六十一回 · 猪八戒助力败魔王 孙行者三调芭蕉扇', NULL, '吴承恩', '明', '话表牛魔王赶上孙大圣，只见他肩膊上掮着那柄芭蕉扇，怡颜悦色而行。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9344, 62, 639096, '5b9789511b69e6005b7a903b', '西游记 · 第六十二回 · 涤垢洗心惟扫塔 缚魔归正乃修身', NULL, '吴承恩', '明', '十二时中忘不得，行功百刻全收。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9345, 63, 639097, '5b9789731579a3003a27ee7a', '西游记 · 第六十三回 · 二僧荡怪闹龙宫 群圣除邪获宝贝', NULL, '吴承恩', '明', '却说祭赛国王与大小公卿，见孙大圣与八戒腾云驾雾，提着两个小妖，飘然而去，一个个朝天礼拜道：“话不虚传！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9346, 64, 639098, '5b9789911579a3003a27efd8', '西游记 · 第六十四回 · 荆棘岭悟能努力 木仙庵三藏谈诗', NULL, '吴承恩', '明', '话表祭赛国王谢了唐三藏师徒获宝擒怪之恩，所赠金玉，分毫不受，却命当驾官照依四位常穿的衣服，各做两套，鞋袜各做两双，绦环各做两条，外备干粮烘炒，倒换了通关文牒，大排銮驾，并文武多官，满城百姓，伏龙寺僧人，大吹大打，送四众出城。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9347, 65, 639099, '5b9789affb4ffe005c88323d', '西游记 · 第六十五回 · 妖邪假设小雷音 四众皆遭大厄难', NULL, '吴承恩', '明', '这回因果，劝人为善，切休作恶。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9376, 94, 639128, '5b98bcbb808ca43cd206536e', '西游记 · 第九十四回 · 四僧宴乐御花园 一怪空怀情欲喜', NULL, '吴承恩', '明', '话表孙行者三人，随着宣召官至午门外，黄门官即时传奏宣进。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9348, 66, 639100, '5b9789cc9f5454003990be13', '西游记 · 第六十六回 · 诸神遭毒手 弥勒缚妖魔', NULL, '吴承恩', '明', '话表孙大圣无计可施，纵一朵祥云，驾筋斗，径转南赡部洲去拜武当山，参请荡魔天尊，解释三藏、八戒、沙僧、天兵等众之灾。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9349, 67, 639101, '5b9789eb9f5454003990bfb7', '西游记 · 第六十七回 · 拯救驼罗禅性稳 脱离秽污道心清', NULL, '吴承恩', '明', '话说三藏四众，躲离了小西天，欣然上路。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9350, 68, 639102, '5b978a0f67f356005c6627f4', '西游记 · 第六十八回 · 朱紫国唐僧论前世 孙行者施为三折肱', NULL, '吴承恩', '明', '善正万缘收，名誉传扬四部洲。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9351, 69, 639103, '5b978a321579a3003a27f6a8', '西游记 · 第六十九回 · 心主夜间修药物　君王筵上论妖邪', NULL, '吴承恩', '明', '话表孙大圣同近侍宦官，到于皇宫内院，直至寝宫门外立定。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9352, 70, 639104, '5b978a529f5454003990c43c', '西游记 · 第七十回 · 妖魔宝放烟沙火 悟空计盗紫金铃', NULL, '吴承恩', '明', '却说那孙行者抖擞神威，持着铁棒，踏祥光起在空中，迎面喝道：“你是那里来的邪魔，待往何方猖獗！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9353, 71, 639105, '5b978a70570c35006314d76d', '西游记 · 第七十一回 · 行者假名降怪犼 观音现象伏妖王', NULL, '吴承恩', '明', '色即空兮自古，空言是色如然。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9354, 72, 639106, '5b978a8e67f356005c662e86', '西游记 · 第七十二回 · 盘丝洞七情迷本 濯垢泉八戒忘形', NULL, '吴承恩', '明', '话表三藏别了朱紫国王，整顿鞍马西进。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9355, 73, 639107, '5b978ab21b69e6005b7aa323', '西游记 · 第七十三回 · 情因旧恨生灾毒 心主遭魔幸破光', NULL, '吴承恩', '明', '话说孙大圣扶持着唐僧，与八戒、沙僧奔上大路，一直西来。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9356, 74, 639108, '5b978ae21579a3003a28032f', '西游记 · 第七十四回 · 长庚传报魔头狠 行者施为变化能', NULL, '吴承恩', '明', '情欲原因总一般，有情有欲自如然。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9357, 75, 639109, '5b978b00fb4ffe005c884798', '西游记 · 第七十五回 · 心猿钻透阴阳窍 魔王还归大道真', NULL, '吴承恩', '明', '却说孙大圣进于洞口，两边观看。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9358, 76, 639110, '5b98b9e81579a3003a334ffb', '西游记 · 第七十六回 · 心神居舍魔归性 木母同降怪体真', NULL, '吴承恩', '明', '话表孙大圣在老魔肚里支吾一会，那魔头倒在尘埃，无声无气，若不言语，想是死了，却又把手放放。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9359, 77, 639111, '5b98ba0dfb4ffe005c939f99', '西游记 · 第七十七回 · 群魔欺本性 一体拜真如', NULL, '吴承恩', '明', '且不言唐长老困苦，却说那三个魔头齐心竭力，与大圣兄弟三人，在城东半山内努力争持。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9360, 78, 639112, '5b98ba2d9f545400399c185f', '西游记 · 第七十八回 · 比丘怜子遣阴神 金殿识魔谈道德', NULL, '吴承恩', '明', ' 一念才生动百魔，修持最苦奈他何！', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9361, 79, 639113, '5b98ba5c67f356005c719944', '西游记 · 第七十九回 · 寻洞擒妖逢老寿 当朝正主救婴儿', NULL, '吴承恩', '明', '却说那锦衣官把假唐僧扯出馆驿，与羽林军围围绕绕，直至朝门外，对黄门官言：“我等已请唐僧到此，烦为转奏。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9362, 80, 639114, '5b98ba7b9f545400399c1d38', '西游记 · 第八十回 · 姹女育阳求配偶 心猿护主识妖邪', NULL, '吴承恩', '明', '却说比丘国君臣黎庶，送唐僧四众出城，有二十里之远，还不肯舍。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9363, 81, 639115, '5b98ba9a808ca43cd2063ac0', '西游记 · 第八十一回 · 镇海寺心猿知怪 黑松林三众寻师', NULL, '吴承恩', '明', '话表三藏师徒到镇海禅林寺，众僧相见，安排斋供。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9364, 82, 639116, '5b98babb9f545400399c2015', '西游记 · 第八十二回 · 姹女求阳 元神护道', NULL, '吴承恩', '明', '却说八戒跳下山，寻着一条小路，依路前行，有五六里远近，忽见二个女怪，在那井上打水。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9365, 83, 639117, '5b98baec570c3500632b6ae3', '西游记 · 第八十三回 · 心猿识得丹头 姹女还归本性', NULL, '吴承恩', '明', '却说三藏著妖精送出洞外，沙和尚近前问曰：「师父出来，师兄何在？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9366, 84, 639118, '5b98bb0d9f545400399c2565', '西游记 · 第八十四回 · 难灭伽持圆大觉 法王成正体天然', NULL, '吴承恩', '明', '话说唐三藏固住元阳，出离了烟花苦套，随行者投西前进。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9367, 85, 639119, '5b98bb2b1b69e6005b86725c', '西游记 · 第八十五回 · 心猿妒木母 魔主计吞禅', NULL, '吴承恩', '明', '话说那国王早朝，文武多官俱执表章启奏道：“主公，望赦臣等失仪之罪。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9368, 86, 639120, '5b98bbc1808ca43cd2064905', '西游记 · 第八十六回 · 木母助威征怪物 金公施法灭妖邪', NULL, '吴承恩', '明', ' 话说孙大圣牵着马，挑着担，满山头寻叫师父，忽见猪八戒气呼呼的跑将来道：“哥哥，你喊怎的？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9369, 87, 639121, '5b98bbdf67f356005c71aa41', '西游记 · 第八十七回 · 凤仙郡冒天止雨 孙大圣劝善施霖', NULL, '吴承恩', '明', '大道幽深，如何消息，说破鬼神惊骇。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9370, 88, 639122, '5b98bbfd17d0090034fb2840', '西游记 · 第八十八回 · 禅到玉华施法会 心猿木母授门人', NULL, '吴承恩', '明', '话说唐僧喜喜欢欢别了郡侯，在马上向行者道：“贤徒，这一场善果，真胜似比丘国搭救儿童，皆尔之功也。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9371, 89, 639123, '5b98bc189f545400399c3456', '西游记 · 第八十九回 · 黄狮精虚设钉钯宴 金木土计闹豹头山', NULL, '吴承恩', '明', '却说那院中几个铁匠，因连日辛苦，夜间俱自睡了。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9372, 90, 639124, '5b98bc3a17d0090034fb2b5e', '西游记 · 第九十回 · 师狮授受同归一 盗道缠禅静九灵', NULL, '吴承恩', '明', '却说孙大圣同八戒、沙僧出城头，觌面相迎，见那伙妖精都是些杂毛狮子：黄狮精在前引领，狻猊狮、抟象狮在左，白泽狮、伏狸狮在右，猱狮、雪狮在后，中间却是一个九头狮子。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9373, 91, 639125, '5b98bc5817d0090034fb2c8a', '西游记 · 第九十一回 · 金平府元夜观灯 玄英洞唐僧供状', NULL, '吴承恩', '明', '修禅何处用工夫？', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9374, 92, 639126, '5b98bc7617d0090034fb2d61', '西游记 · 第九十二回 · 三僧大战青龙山 四星挟捉犀牛怪', NULL, '吴承恩', '明', '却说孙大圣挟同二弟滚着风，驾着云，向东北艮地上，顷刻至青龙山玄英洞口，按落云头。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9375, 93, 639127, '5b98bc9817d0090034fb2ebd', '西游记 · 第九十三回 · 给孤园问古谈因 天竺国朝王遇偶', NULL, '吴承恩', '明', '起念断然有爱，留情必定生灾。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
