INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9377, 95, 639129, '5b98bcd817d0090034fb315f', '西游记 · 第九十五回 · 假合真形擒玉兔 真阴归正会灵元', NULL, '吴承恩', '明', '却说那唐僧忧忧愁愁，随着国王至后宫，只听得鼓乐喧天，随闻得异香扑鼻，低着头，不敢仰视。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9378, 96, 639130, '5b98bcfc17d0090034fb339a', '西游记 · 第九十六回 · 寇员外喜待高僧 唐长老不贪富贵', NULL, '吴承恩', '明', '色色原无色，空空亦非空。', 'wen', 304, '西游记', '', NULL, '', '', '', '');
