INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9468, 86, 639225, '5b9b72bc1579a3003a4fcf6e', '三国演义 · 第八十六回 · 难张温秦宓逞天辩 破曹丕徐盛用火攻', NULL, '罗贯中', '明', '却说东吴陆逊，自退魏兵之后，吴王拜逊为辅国将军，江陵侯，领荆州牧，自此军权皆归于逊。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9469, 87, 639226, '5b9b72f8fb4ffe005cb029d7', '三国演义 · 第八十七回 · 征南寇丞相大兴师 抗天兵蛮王初受执', NULL, '罗贯中', '明', '却说诸葛丞相在于成都，事无大小，皆亲自从公决断。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9470, 88, 639227, '5b9b7313fb4ffe005cb02af0', '三国演义 · 第八十八回 · 渡泸水再缚番王 识诈降三擒孟获', NULL, '罗贯中', '明', '却说孔明放了孟获，众将上帐问曰：“孟获乃南蛮渠魁，今幸被擒，南方便定；', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9471, 89, 639228, '5b9b7329808ca43cd222ca17', '三国演义 · 第八十九回 · 武乡侯四番用计 南蛮王五次遭擒', NULL, '罗贯中', '明', '却说孔明自驾小车，引数百骑前来探路。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9472, 90, 639229, '5b9b7344570c350063547c3f', '三国演义 · 第九十回 · 驱巨善六破蛮兵 烧藤甲七擒孟获', NULL, '罗贯中', '明', '却说孔明放了孟获等一干人，杨锋父子皆封官爵，重赏洞兵。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9473, 91, 639230, '5b9b735b1579a3003a4fd71b', '三国演义 · 第九十一回 · 祭泸水汉相班师 伐中原武侯上表', NULL, '罗贯中', '明', '却说孔明班师回国，孟获率引大小洞主酋长，及诸部落，罗拜相送。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9474, 92, 639231, '5b9b7387808ca43cd222cef8', '三国演义 · 第九十二回 · 赵子龙力斩五将 诸葛亮智取三城', NULL, '罗贯中', '明', '却说孔明率兵前至沔阳，经过马超坟墓，乃令其弟马岱挂孝，孔明亲自祭之。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9475, 93, 639232, '5b9b73b2570c3500635481cf', '三国演义 · 第九十三回 · 姜伯约归降孔明 武乡侯骂死王朗', NULL, '罗贯中', '明', '却说姜维献计于马遵曰：“诸葛亮必伏兵于郡后，赚我兵出城，乘虚袭我。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9476, 94, 639233, '5b9b73cd17d009003417abb2', '三国演义 · 第九十四回 · 诸葛亮乘雪破羌兵 司马懿克日擒孟达', NULL, '罗贯中', '明', '却说郭淮谓曹真曰：“西羌之人，自太祖时连年入贡，文皇帝亦有恩惠加之；', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9477, 95, 639234, '5b9b73e6fb4ffe005cb035f7', '三国演义· 第九十五回 · 马谡拒谏失街亭 武侯弹琴退仲达', NULL, '罗贯中', '明', ' 却说魏主曹睿令张郃为先锋，与司马懿一同征进；', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9478, 96, 639235, '5b9b73ff17d009003417ae1c', '三国演义 · 第九十六回 · 孔明挥泪斩马谡 周鲂断发赚曹休', NULL, '罗贯中', '明', '却说献计者，乃尚书孙资也。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9479, 97, 639236, '5b9b741317d009003417af08', '三国演义 · 第九十七回 · 讨魏国武侯再上表 破曹兵姜维诈献书', NULL, '罗贯中', '明', '却说蜀汉建兴六年秋九月，魏都督曹休被东吴陆逊大破于石亭，车仗马匹，军资器械，并皆罄尽，休惶恐之甚，气忧成病，到洛阳，疽发背而死。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9480, 98, 639237, '5b9b742a808ca43cd222d741', '三国演义 · 第九十八回 · 追汉军王双受诛 袭陈仓武侯取胜', NULL, '罗贯中', '明', '却说司马懿奏曰：“臣尝奏陛下，言孔明必出陈仓，故以郝昭守之，今果然矣。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9481, 99, 639238, '5b9b743f808ca43cd222d819', '三国演义 · 第九十九回 · 诸葛亮大破魏兵 司马懿入寇西蜀', NULL, '罗贯中', '明', '蜀汉建兴七年夏四月，孔明兵在祁山，分作三寨，专候魏兵。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9482, 100, 639239, '5b9b745d570c35006354899a', '三国演义 · 第一百回 · 汉兵劫寨破曹真 武侯斗阵辱仲达', NULL, '罗贯中', '明', ' 却说众将闻孔明不追魏兵，俱入帐告曰：“魏兵苦雨，不能屯扎，因此回去，正好乘势追之。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9483, 101, 639240, '5b9b747c9f54540039b8bda8', '三国演义 · 第一百十一回 · 出陇上诸葛妆神 奔剑阁张郃中计', NULL, '罗贯中', '明', '却说孔明用减兵添灶之法，退兵到汉中；', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
