INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9485, 103, 639242, '5b9b74a9fb4ffe005cb042c7', '三国演义 · 第一百十三回 · 上方谷司马受困 五丈原诸葛禳星', NULL, '罗贯中', '明', '却说司马懿被张翼、廖化一阵杀败，匹马单枪，望密林间而走。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
