INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (9491, 109, 639248, '5b9b7567570c3500635495e8', '三国演义 · 第一百十九回 · 困司马汉将奇谋 废曹芳魏家果报', NULL, '罗贯中', '明', '蜀汉延熙十六年秋，将军姜维起兵二十万，令廖化、张翼为左右先锋，夏侯霸为参谋，张嶷为运粮使，大兵出阳平关伐魏。', 'wen', 305, '三国演义', '', NULL, '', '', '', '');
