INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11556, 6, 640755, '5c1a5d7f9f545400665cd23d', '晏子春秋 · 内篇 · 杂下第六', NULL, '无名氏', '周', '　灵公禁妇人为丈夫饰不止晏子请先内勿服第一灵公好妇人而丈夫饰者，国人尽服之，公使吏禁之，曰：“女子而男子饰者，裂其衣，断其带。', 'wen', 379, '晏子春秋', '', NULL, '', '', '', '');
