INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11598, 7, 559718, '5860406bb123db0065b9a5ec', '初到书局以万七千钱得一老马盲右目戏作古句自嘲一首', NULL, '程俱', '宋', '蹄间三寻汗流赭，九逵雷雹争飞洒。我穷那得骋追风，正拟虺尵行果下。平生畏途饱经历，夜半临深无驭者。故应造物巧相戏，却比盲人骑瞎马。李南知音当促步，广汉腾嘲不相假。执鞭良称塞翁儿，并辔聊从杜陵夏。庞然病颡岂其类，老矣问途那可舍。径烦一夫事刷秣，似桂新刍不盈把。向来伯厚亦安在，结驷鸡栖同土苴。他年东去把撩风，纵尔逍遥汴东野。', 'shi', 375, '文学篇', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11599, 8, 12246, '58173a6367f35600586a3e3b', '小雅 · 斯干', NULL, '无名氏', '周', '秩秩斯干，幽幽南山。', 'shi', 375, '文学篇', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11600, 9, 10386, '57b19776128fe10055c7c6a5', '古诗十九首 · 行行重行行', NULL, '无名氏', '汉', '行行重行行，与君生别离。', 'shi', 375, '文学篇', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11601, 10, 11189, '57b9131cc4c97100558fbf41', '秋词（其二）', NULL, '刘禹锡', '唐', '山明水净夜来霜，数树深红出浅黄。', 'shi', 375, '文学篇', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11602, 11, 11878, '57ffc70c8ac2470058e10b4d', '山中与裴秀才迪书', NULL, '王维', '唐', '近腊月下，景气和畅，故山殊可过。', 'wen', 375, '文学篇', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11603, 12, 61293, '585cf927da2f600065834f32', '太山高', NULL, '杨维桢', '元', '巍乎高哉，太山之山三万八千丈兮，五岳之伯，万山之宗。上有云官、霞伯、明星、玉女、金堂、石室高重重。三十六天第一洞，是为蓬玄太空之上穹。上帝赐以金箧之玉策，司命下土开群蒙。自从崇伯子，受命告厥功。至今七十二君，坛壝留遗踪。触石之云可以一朝雨，天下封突起，化作海岛十二金芙蓉。三神尚有刘郎记，五官不受秦皇封。东方有岩名日观，羊角而上千万盘屈，始窥大门小户之天聪。黄河西来如线走其下，齐州九点烟灭蒙。秦观见长安，吴观见会稽，周观见洛嵩，圣人登之天下小似东龟蒙。夜闻巨灵荡踏西华峰，流血下染洪河红。嵩高不生帝王佐，常山蛇怪两首而三瞳。天上金乌下倒景，大星僣晓芒角流妖锋。铁道人，手持一雌一雄双铁龙。骑龙天关叩天语，夜拜日驾五色披祥虹。天封地禅礼数绝，徵兵三度谣嵩童。博陆侯，狄梁公，虞渊取日扶桑东。太阳当天天下白，照见地下虮虱金头虫。金头虫，如蠛蠓。', 'shi', 375, '文学篇', '', NULL, '', '', '', '');
