INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11617, 1, 370493, '585ea469ac502e00672c559d', '宣府中元夜即事', NULL, '计东', '清', '边月新秋夜，哀音四面齐。战场多旧鬼，野祭有遗黎。柝乱愁人听，风惊倦鸟栖。遥遥天汉上，河鼓渐垂西。', 'shi', 370, '天下篇', '', NULL, '', '', '', '');
