INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11998, 2, 78479, '585d0917b123db0065a70b0c', '卢侍御与崔评事为予于黄鹤楼置宴宴罢同望', NULL, '白居易', '唐', '江边黄鹤古时楼，劳置华筵待我游。楚思淼茫云水冷，商声清脆管弦秋。白花浪溅头陀寺，红叶林笼鹦鹉洲。总是平生未行处，醉来堪赏醒堪愁。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12064, 22, 641908, '5cad583a0237d700681a4961', '赠赵侍御', NULL, '张说', '唐', '禄放迹异端，偏荒事同蹇。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (11999, 3, 111255, '585d30f2ac502e0067235005', '武昌老人说笛歌', NULL, '刘禹锡', '唐', '武昌老人七十馀，手把庾令相问书。自言少小学吹笛，早事曹王曾赏激。往年镇戍到蕲州，楚山萧萧笛竹秋。当时买材恣搜索，典却身上乌貂裘。古苔苍苍封老节，石上孤生饱风雪。商声五音随指发，水中龙应行云绝。曾将黄鹤楼上吹，一声占尽秋江月。如今老去语尤迟，音韵高低耳不知。气力已微心尚在，时时一曲梦中吹。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12000, 4, 111321, '585d310c8d6d810065de0851', '出鄂州界怀表臣二首', NULL, '刘禹锡', '唐', '梦觉疑连榻，舟行忽千里。不见黄鹤楼，寒沙雪相似。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12001, 5, 110467, '585d2fc6b123db0065a85cd5', '中秋夜泊武昌', NULL, '刘淑柔', '唐', '两城相对峙，一水向东流。今夜素娥月，何年黄鹤楼。悠悠兰棹晚，渺渺荻花秋。无奈柔肠断，关山总是愁。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
