INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12013, 17, 88876, '585d1425b123db0065a764ec', '江夏送友人', NULL, '李白', '唐', '雪点翠云裘，送君黄鹤楼。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12014, 18, 88904, '585d142eb123db0065a7651b', '醉后答丁十八以诗讥余捶碎黄鹤楼', NULL, '李白', '唐', '黄鹤高楼已槌碎，黄鹤仙人无所依。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12015, 19, 88905, '585d142e61ff4b006cd29d1f', '答裴侍御先行至石头驿以书见招期月满泛洞庭', NULL, '李白', '唐', '君至石头驿，寄书黄鹤楼。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12016, 20, 641885, '5cac0e57a3180b0068215dc9', '送王侍御赴夏口座主幕', NULL, '杜牧', '唐', '君为珠履三千客，我是青衿七十徒。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12017, 21, 92220, '585d17a08d6d810065dd2148', '江上别流人', NULL, '孟浩然', '唐', '以我越乡客，逢君谪居者。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12018, 22, 92254, '585d17a61b69e6006ccaf25b', '鹦鹉洲送王九之', NULL, '孟浩然', '唐', '昔登江上黄鹤楼，遥爱江中鹦鹉洲。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12019, 23, 93423, '585d191561ff4b006cd2c68d', '送田三端公还鄂州', NULL, '武元衡', '唐', '孤云迢遰恋沧洲，劝酒梨花对白头。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12020, 24, 641886, '5cac11aca3180b0068219531', '黄鹤楼', NULL, '贾岛', '唐', '高槛危檐势若飞，孤云野水共依依。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12021, 25, 10350, '57b8f0915bbb50005b77bd38', '黄鹤楼', NULL, '崔颢', '唐', '昔人已乘黄鹤去，此地空余黄鹤楼。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12022, 26, 311770, '585e3b868d6d810065e3ee77', '和经父登黄鹤楼', NULL, '孔平仲', '宋', '复霭重沙望不穷，坐收千里一樽中。天边江汉波涛阔，地下神仙窟宅通。窗影偷来湓浦白，檐光飞入沔城红。豁然已尽登临兴，云阁章亭谩在东。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12023, 27, 319431, '585e4893ac502e0067298b09', '黄鹤楼', NULL, '王十朋', '宋', '云锁吕公洞，月明黄鹤楼。抱关非故卒，谁见羽衣游。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12025, 28, 641887, '5cac126aa91c932819c0de6a', '吊祢正平', NULL, '王炎（双溪）', '宋', '曹瞒忍杀杨德祖，不敢复害祢正平。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12026, 29, 641888, '5cac129ea91c932819c0e1cb', '余过荆州张安国已请祠先行', NULL, '王质', '宋', '心事何曾吐一分，鼓严早已报三声。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12027, 30, 321033, '585e4b83128fe10069d389de', '送頔子还庐陵', NULL, '王庭圭', '宋', '东归未办武陵舟，送汝翻成一段愁。雪点敝裘骑瘦马，春寒几日到荆州。湖山天阔洞庭野，吴楚月明黄鹤楼。莫苦回瞻白云岭，是行聊学子长游。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12028, 31, 321501, '585e4c51b123db0065aeb857', '李真狂过卢溪卢溪虑其狂之无所归作狂语箴之', NULL, '王庭圭', '宋', '江南有狂客，气欲横九州。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12029, 32, 330172, '585e5ada570c350069396abf', '诗三首其三', NULL, '王得臣', '宋', '故人隔阔在东州，烟波渺漫使人愁。朝朝眼望头陀寺，夜夜魂飞黄鹤楼。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12030, 33, 330173, '585e5adb128fe1006ba97e6e', '黄鹤楼', NULL, '王得臣', '宋', '昔人已乘白云去，旧国连天不知处。思量费子真仙子，从他浮世悲生死。黄鹤一去不复返，光阴流转忽已晚。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12031, 34, 575263, '586064d961ff4b0058204ca0', '鄂州南楼其下为黄鹤楼故基', NULL, '冯时行', '宋', '今日南楼独上时，西风无复片云飞。天连江水去不尽，云傍远山闲自归。鹦鹉巧言终掇祸，麒麟高举亦知几。诗翁仙子今何在，徙倚栏干送落晖。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12032, 35, 613502, '5860c80c8d6d810065f23e69', '黄鹤楼', NULL, '卢郢', '宋', '黄鹤何年去杳冥，高楼千载倚江城。碧云朝卷四山景，流水夜传三峡声。柳暗西州供骋望，草芳南浦遍离情。登临一晌须回首，看却乡心万感生。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12033, 36, 641889, '5cac12fd0237d70068086f7a', '读翰林集', NULL, '田锡（表圣）', '宋', ' 太白谪仙人，换酒鹔鹴裘。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12034, 37, 435308, '585f1aca128fe1006df17fbe', '  武昌怀古十咏 · 黄鹤楼', NULL, '白玉蟾', '宋', '白云黄鹤迹成遗，何独当年丁令威。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12061, 19, 89483, '585d14d9ac502e00672250bb', '离岐下题西湖', NULL, '吴融', '唐', '送夏迎秋几醉来，不堪行色被蝉催。身随渭水看归远，梦挂秦云约自回。雨细若为抛钓艇，月明谁复上歌台。千波万浪西风急，更为红蕖把一杯。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12035, 38, 436320, '585f1e081b69e6006cd6488b', '赠城西谢知堂', NULL, '白玉蟾', '宋', '蓬莱山上神仙翁，道貌挺挺乔如松。双眸炯炯黑于漆，脸边隐隐如桃红。有时仰天笑开口，撮起昆仑归右手。忽然虚空跌落地，不觉满腹藏星斗。有时惊起老龙号，一口汲尽沧浪波。打破混沌揣出骨，拈起芥子贮山河。偃月炉中煮天地，煎炼日魄并月髓。笑把葫芦禁鬼神，杖头挑起山和水。栾巴噀饭飞成蜂，左慈剪艾化为龙。夏月梅花冬月电，似此伎俩问吕钟。撮土为香犹是假，水底麒麟取作酢。鬼神眼睛突出外，无根树下骑铁马。工夫到处戏极时，拈弄造化如儿嬉。大虫舌上翻筋斗，却笑金刚学画眉。女皇要补西天窍，炼石不得羲皇笑。秦皇凿山通四溟，汉帝掣之一长笑。先生手持没底篮，出有入无犹不凡。携此道术问四海，洞宾今正觅同参。盏里绵包或聚散，火里游鱼水里雁。黄鹤楼前大醉时，撑眼撮与钟离看。水盆搅散五色沙，满地写出龙蛇花。自将一盏逡巡酒，敢向人前化作茶。笊篱里面一条路，透入青霄云外去。十字街头开铺席，翻手覆手成云雨。如今天下觅无人，似君道术真入神。踏遍江湖今几春，都来一个云水身。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12036, 39, 641890, '5cac1415c05a800073ed9240', '湖学别苏召叟', NULL, '刘过', '宋', '失学老无成，宁不心自慊。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12037, 40, 601384, '5860a90b128fe1006bb60124', '浣溪沙 · 赠妓徐楚楚', NULL, '刘过', '宋', '黄鹤楼前识楚卿。', 'ci', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12038, 41, 605922, '5860b5bc1b69e6005624c85e', '村居即事六言十首', NULL, '刘克庄', '宋', '有时散发松风，有时一剑秋空。讲易白牛溪上，题诗黄鹤楼中。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12039, 42, 436980, '585f1fac128fe10069d7b9f8', '上赵总领', NULL, '危稹', '宋', '一见烦公道眼明，悬知彻底五湖清。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12040, 43, 493761, '585fab6c128fe10069dba76a', '榴皮题壁', NULL, '孙子光', '宋', '黄鹤楼中吹笛罢，洞庭湖畔醉吟馀。剑光如宝无人识，却记榴皮几字书。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12041, 44, 438792, '585f242661ff4b0063fc856a', '题黄鹤楼', NULL, '江万里', '宋', '黄鹤楼高倚半天，楼中黄鹤去千年。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12042, 45, 550409, '58602c661b69e60056224210', '次允杰五首', NULL, '许月卿', '宋', '瓣香曾侍鹤山俦，蜀有鹤林殊匪优。蜕作婴儿生我室，化为道士掠予舟。相同龟寿□鹏鴳，自混鸡群狎鹭鸥。仙子已骑黄鹤去，此地空馀黄鹤楼。', 'shi', 384, '黄鹤楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12043, 1, 633534, '5834321a8ac247006392122a', '采莲童曲', NULL, '无名氏', '南北朝', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12044, 2, 641905, '5cad56eea3180b0068336d69', '治西湖诗', NULL, '范雲', '南北朝', '史氏导漳水，西门溉河潮。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12045, 3, 74830, '585d0594570c350069313604', '侯郎中新置西湖', NULL, '方干', '唐', '远近利民因智力，周回润物像心源。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12046, 4, 78601, '585d093d1b69e6006cca7e0e', '西湖晚归回望孤山寺赠诸客', NULL, '白居易', '唐', '柳湖松岛莲花寺，晚动归桡出道场。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12047, 5, 78615, '585d0941128fe10069cbde5b', '湖上醉中代诸妓寄严郎中', NULL, '白居易', '唐', '笙歌杯酒正欢娱，忽忆仙郎望帝都。借问连宵直南省，何如尽日醉西湖。蛾眉别久心知否，鸡舌含多口厌无。还有些些惆怅事，春来山路见蘼芜。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12048, 6, 78635, '585d0947128fe1006ba15ac4', '西湖留别', NULL, '白居易', '唐', '征途行色惨风烟，祖帐离声咽管弦。翠黛不须留五马，皇恩只许住三年。绿藤阴下铺歌席，红藕花中泊妓船。处处回头尽堪恋，就中难别是湖边。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12049, 7, 79416, '585d0a34128fe10069cbe5fa', '杭州回舫', NULL, '白居易', '唐', '自别钱塘山水后，不多饮酒懒吟诗。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12050, 8, 79823, '585d0aa6ac502e006721fda6', '早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之', NULL, '白居易', '唐', '上马复呼宾，湖边景气新。管弦三数事，骑从十馀人。立换登山屐，行携漉酒巾。逢花看当妓，遇草坐为茵。西日笼黄柳，东风荡白蘋。小桥装雁齿，轻浪甃鱼鳞。画舫牵徐转，银船酌慢巡。野情遗世累，醉态任天真。彼此年将老，平生分最亲。高天从所愿，远地得为邻。云树分三驿，烟波限一津。翻嗟寸步隔，却厌尺书频。浙右称雄镇，山阴委重臣。贵垂长紫绶，荣驾大朱轮。出动刀枪队，归生道路尘。雁惊弓易散，鸥怕鼓难驯。百吏瞻相面，千夫捧拥身。自然闲兴少，应负镜湖春。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12051, 9, 79915, '585d0ac38d6d810065dcb7b0', '寄题馀杭郡楼兼呈裴使君', NULL, '白居易', '唐', '官历二十政，宦游三十秋。江山与风月，最忆是杭州。北郭沙堤尾，西湖石岸头。绿觞春送客，红烛夜回舟。不敢言遗爱，空知念旧游。凭君吟此句，题向望涛楼。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12052, 10, 112130, '585d31ecac502e006723591f', '赴江西湖上赠皇甫曾之宣州', NULL, '刘长卿', '唐', '莫恨扁舟去，川途我更遥。东西潮渺渺，离别雨萧萧。流水通春谷，青山过板桥。天涯有来客，迟尔访渔樵。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12053, 11, 112138, '585d31ef128fe1006ba2bf2f', '将赴湖南湖上别皇甫曾', NULL, '刘长卿', '唐', '此去君何恨，南行我更遥。东西湖渺渺，离别雨潇潇。绿水通春谷，青山过板桥。浔阳如枉棹，千里有归潮。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12054, 12, 110740, '585d3016128fe1006ba2ae6a', '和西川李尚书汉州微月游房太尉西湖', NULL, '刘禹锡', '唐', '木落汉川夜，西湖悬玉钩。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12055, 13, 81084, '585d0c17da2f60006583e086', '送唐中丞开淘西湖夏日游泛因书示郡人', NULL, '朱庆馀', '唐', '萍岸新淘见碧霄，中流相去忽成遥。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12056, 14, 103628, '585d25b3128fe1006de6ac0e', '颍州从事西湖亭宴饯', NULL, '许浑', '唐', '西湖清宴不知回，一曲离歌酒一杯。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12057, 15, 110278, '585d2f91128fe1006de7040c', '移居西湖作二首', NULL, '齐己', '唐', '火云阳焰欲烧空，小槛幽窗想旧峰。白汗此时流枕簟，清风何处动杉松。残更正好眠凉月，远寺俄闻报晓钟。只待秋声涤心地，衲衣新洗健形容。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12058, 16, 110279, '585d2f92128fe1006de70418', '移居西湖作二首', NULL, '齐己', '唐', '官园树影昼阴阴，咫尺清凉莫浣心。桃李别教人主掌，烟花不称我追寻。蜩螗晚噪风枝稳，翡翠闲眠宿处深。争似出尘地行止，东林苔径入西林。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12059, 17, 110358, '585d2fa78d6d810065ddfc4d', '春日西湖作', NULL, '齐己', '唐', '一水绕孤岛，闲门掩春草。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12060, 18, 116216, '585d37441b69e6006ccc154a', '题汉州西湖', NULL, '严公贶', '唐', '凤沼才难尽，馀思凿西湖。珍木罗修岸，冰光映坐隅。琴台今寂寞，竹岛尚萦纡。犹蕴济川志，芳名终不渝。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12062, 20, 641906, '5cad57bea3180b0068337b20', '陪杭州郡使燕西湖亭', NULL, '张祜', '唐', '小亭移宴近云端，十里山图马上看。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12065, 23, 90399, '585d15caac502e00672257c6', '重别西湖', NULL, '李绅', '唐', '浦边梅叶看凋落，波上双禽去寂寥。吹管曲传花易失，织文机学羽难飘。雪欺春早摧芳萼，隼励秋深拂翠翘。繁艳彩毛无处所，尽成愁叹别溪桥。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12066, 24, 90454, '585d15da128fe1006ba1c254', '过梅里七首家于无锡四十载今敝庐数堵犹存今列题于后忆西湖双鸂鶒', NULL, '李绅', '唐', '双鸂鶒，锦毛斓斑长比翼，戏绕莲丛回锦臆。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12067, 25, 90283, '585d15b0da2f60006584328f', '冬至后西湖泛舟看断冰偶成长句', NULL, '李郢', '唐', '一阳生后阴飙竭，湖上层冰看折时。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12068, 26, 85078, '585d10391b69e6006ccab388', '汉州月夕游房太尉西湖', NULL, '李德裕', '唐', '丞相鸣琴地，何年闭玉徽。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12069, 27, 83444, '585d0e6bb123db0065a734aa', '陪王汉州留杜绵州泛房公西湖', NULL, '杜甫', '唐', '旧相恩追后，春池赏不稀。阙庭分未到，舟楫有光辉。豉化莼丝熟，刀鸣鲙缕飞。使君双皂盖，滩浅正相依。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12070, 28, 85735, '585d10da8d6d810065dce6c0', '道一大尹存之庭美二学士简于圣明自致霄汉皆与舍弟昔年还往牧支离穷悴窃于一麾书美歌诗兼自言志因成长句四韵呈上三君子', NULL, '杜牧', '唐', '九金神鼎重丘山，五玉诸侯杂佩环。星座通霄狼鬣暗，戍楼吹笛虎牙闲。斗间紫气龙埋狱，天上洪炉帝铸颜。若念西河旧交友，鱼符应许出函关。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12071, 29, 91278, '585d169a128fe10069cc4ce2', '游西湖', NULL, '沈韬文', '五代十国', '□□□□□□□，菰米蘋花似故乡。不是不归归未得，好风明月一思量。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12072, 30, 93251, '585d18deac502e00672271f6', '题汉州西湖', NULL, '房琯', '唐', '高流缠峻隅，城下缅丘墟。决渠信浩荡，潭岛成江湖。结宇依回渚，水中信可居。三伏气不蒸，四达暑自徂。同人千里驾，邻国五马车。月出共登舟，风生随所如。举麾指极浦，欲极更盘纡。缭绕各殊致，夜尽情有馀。遭乱意不开，即理还暂祛。安得长晤语，使我忧更除。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12073, 31, 72609, '585d03568d6d810065dc7ad0', '题磻溪垂钓图', NULL, '罗隐', '唐', '吕望当年展庙谟，直钩钓国更谁如。若教生在西湖上，也是须供使宅鱼。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12074, 32, 109282, '585d2de061ff4b00580e8219', '乐游曲', NULL, '闽后陈氏', '唐', '西湖南湖斗彩舟，青蒲紫蓼满中洲。波渺渺，水悠悠，长奉君王万岁游。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12075, 33, 114027, '585d3495ac502e00672372c7', '平阳寓怀', NULL, '薛能', '唐', '晋国风流阻洳川，家家弦管路岐边。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12076, 34, 641909, '5cad58b6c05a800073ff4df2', '题汉州西湖', NULL, '薛能', '唐', '西湖天下名，可以濯吾缨。', 'shi', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12077, 35, 641910, '5cad59690237d700681a5c88', '蓦山溪 · 其九', NULL, '无名氏', '宋', '重黎默运，可意萦人处。', 'ci', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12078, 36, 641911, '5cad5987a91c932819d2d636', '蓦山溪 · 其十一', NULL, '无名氏', '宋', '竹篱茆舍，底是藏春处。', 'ci', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12079, 37, 641912, '5cad59b7c05a800073ff5f54', '醉花阴 · 其一', NULL, '无名氏', '宋', '粉妆一捻和香聚。', 'ci', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12080, 38, 641913, '5cad59e0a3180b0068339f26', '点绛唇 · 其八', NULL, '无名氏', '宋', '赋雪归来，绿窗一夜霜风紧。', 'ci', 385, '西湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12081, 1, 73742, '585d0470ac502e006721cadf', '洞庭湖', NULL, '元稹', '唐', '人生除泛海，便到洞庭波。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12082, 2, 73949, '585d049fb123db0065a6e64a', '梦成之', NULL, '元稹', '唐', '烛暗船风独梦惊，梦君频问向南行。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12083, 3, 641914, '5caea5b1eaa375007444196a', '题君山', NULL, '方干', '唐', ' 曾于方外见麻姑，闻说君山自古无。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12084, 4, 76878, '585d078461ff4b0063f08515', '中秋月', NULL, '可朋', '五代十国', '登楼仍喜此宵晴，圆魄才观思便清。海面乍浮犹隐映，天心高挂最分明。片云想有神仙出，回野应无鬼魅形。曾向洞庭湖上看，君山半雾水初平。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12085, 5, 80239, '585d0b24570c35006931623f', '自蜀江至洞庭湖口有感而作', NULL, '白居易', '唐', '江从西南来，浩浩无旦夕。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12086, 6, 641915, '5caea60c0237d700682db139', '秋晚自洞庭湖别业寄穆秀才', NULL, '皮日休', '唐', '破村寥落过重阳，独自撄宁葺草房。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12087, 7, 112000, '585d31c18d6d810065de0f41', '岳阳馆中望洞庭湖', NULL, '刘长卿', '唐', '万古巴丘戍，平湖此望长。问人何淼淼，愁暮更苍苍。叠浪浮元气，中流没太阳。孤舟有归客，早晚达潇湘。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12088, 8, 90635, '585d16141b69e6006ccae514', '洞庭湖君山颂', NULL, '吕岩', '唐', '午夜君山玩月回，西邻小圃碧莲开。天香风露苍华冷，云在青霄鹤未来。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12089, 9, 641916, '5caea78dc8959c0073d265d6', '绝句 · 其十六', NULL, '吕岩', '唐', '朝游北越暮苍梧，袖里青蛇胆气粗。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12090, 10, 104366, '585d26b9128fe1006ba25a95', '过洞庭湖', NULL, '许棠', '唐', '惊波常不定，半日鬓堪斑。四顾疑无地，中流忽有山。鸟高恒畏坠，帆远却如闲。渔父闲相引，时歌浩渺间。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12091, 11, 82776, '585d0dae128fe10069cbffa2', '洞庭湖', NULL, '宋之问', '唐', '地尽天水合，朝及洞庭湖。初日当中涌，莫辨东西隅。晶耀目何在，滢荧心欲无。灵光晏海若，游气耿天吴。张乐轩皇至，征苗夏禹徂。楚臣悲落叶，尧女泣苍梧。野积九江润，山通五岳图。风恬鱼自跃，云夕雁相呼。独此临泛漾，浩将人代殊。永言洗氛浊，卒岁为清娱。要使功成退，徒劳越大夫。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12092, 12, 101647, '585d231a61ff4b00580e2072', '游洞庭湖', NULL, '张说', '唐', '平湖晓望分，仙峤气氛氲。鼓枻乘清渚，寻峰弄白云。江寒天一色，日静水重纹。树坐参猿啸，沙行入鹭群。缘源斑筱密，罥径绿萝纷。洞穴传虚应，枫林觉自熏。双童有灵药，愿取献明君。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12093, 13, 634652, '58cb4c3d1b69e6006b705359', '游洞庭湖湘', NULL, '张说', '唐', '缅邈洞庭岫，葱蒙水雾色。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12095, 14, 641917, '5caea86ec8959c0073d27431', '中秋夜君山台望月', NULL, '李涉', '唐', '大堤花里锦江前，诗酒同游四十年。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12096, 15, 87073, '585d1252da2f600065841485', '荆门西下', NULL, '李商隐', '唐', '一夕南风一叶危，荆云回望夏云时。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12097, 16, 87210, '585d1275b123db0065a7558f', '岳阳楼', NULL, '李商隐', '唐', '欲为平生一散愁，洞庭湖上岳阳楼。可怜万里堪乘兴，枉是蛟龙解覆舟。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12150, 5, 10098, '57b9658c0a2b58005c95d2a7', '戏为六绝句', NULL, '杜甫', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12151, 6, 10100, '57b8f7127db2a20054265cb7', '闻官军收河南河北', NULL, '杜甫', '唐', '剑外忽传收蓟北，初闻涕泪满衣裳。', 'shi', 388, '黄河', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12098, 17, 84036, '585d0f16128fe1006ba189b4', '过南岳入洞庭湖', NULL, '杜甫', '唐', '洪波忽争道，岸转异江湖。鄂渚分云树，衡山引舳舻。翠牙穿裛桨，碧节上寒蒲。病渴身何去，春生力更无。壤童犁雨雪，渔屋架泥涂。欹侧风帆满，微冥水驿孤。悠悠回赤壁，浩浩略苍梧。帝子留遗恨，曹公屈壮图。圣朝光御极，残孽驻艰虞。才淑随厮养，名贤隐锻炉。邵平元入汉，张翰后归吴。莫怪啼痕数，危樯逐夜乌。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12099, 18, 84037, '585d0f16570c3500693180f4', '北风', NULL, '杜甫', '唐', '春生南国瘴，气待北风苏。向晚霾残日，初宵鼓大炉。爽携卑湿地，声拔洞庭湖。万里鱼龙伏，三更鸟兽呼。涤除贪破浪，愁绝付摧枯。执热沈沈在，凌寒往往须。且知宽疾肺，不敢恨危途。再宿烦舟子，衰容问仆夫。今晨非盛怒，便道即长驱。隐几看帆席，云州涌坐隅。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12100, 19, 84370, '585d0f7a61ff4b00688f7c54', '寄薛三郎中', NULL, '杜甫', '唐', '人生无贤愚，飘飖若埃尘。自非得神仙，谁免危其身。与子俱白头，役役常苦辛。虽为尚书郎，不及村野人。忆昔村野人，其乐难具陈。蔼蔼桑麻交，公侯为等伦。天未厌戎马，我辈本常贫。子尚客荆州，我亦滞江滨。峡中一卧病，疟疠终冬春。春复加肺气，此病盖有因。早岁与苏郑，痛饮情相亲。二公化为土，嗜酒不失真。余今委修短，岂得恨命屯。闻子心甚壮，所遇信席珍。上马不用扶，每扶必怒嗔。赋诗宾客间，挥洒动八垠。乃知盖代手，才力老益神。青草洞庭湖，东浮沧海漘。君山可避暑，况足采白蘋。子岂无扁舟，往复江汉津。我未下瞿塘，空念禹功勤。听说松门峡，吐药揽衣巾。高秋却束带，鼓枻视青旻。凤池日澄碧，济济多士新。余病不能起，健者勿逡巡。上有明哲君，下有行化臣。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12101, 20, 10547, '57b339db8ac247005f235d5a', '望洞庭湖赠张丞相', NULL, '孟浩然', '唐', '八月湖水平，涵虚混太清。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12102, 21, 92008, '585d176b570c35006931c712', '洞庭湖寄阎九', NULL, '孟浩然', '唐', '洞庭秋正阔，余欲泛归船。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12103, 22, 107507, '585d2b51b123db0065a832e7', '送王员外赴长沙', NULL, '贾至', '唐', '携手登临处，巴陵天一隅。春生云梦泽，水溢洞庭湖。共叹虞翻枉，同悲阮籍途。长沙旧卑湿，今古不应殊。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12104, 23, 107541, '585d2b5fda2f60006584f4ca', '初至巴陵与李十二白裴九同泛洞庭湖三首', NULL, '贾至', '唐', '江上相逢皆旧游，湘山永望不堪愁。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12105, 24, 107542, '585d2b6061ff4b00689073ae', '初至巴陵与李十二白裴九同泛洞庭湖三首其二', NULL, '贾至', '唐', '枫岸纷纷落叶多，洞庭秋水晚来波。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12106, 25, 107543, '585d2b60b123db0065a83389', '初至巴陵与李十二白裴九同泛洞庭湖三首', NULL, '贾至', '唐', '江畔枫叶初带霜，渚边菊花亦已黄。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12107, 26, 107842, '585d2bc2ac502e0067231fc1', '送惠雅法师归玉泉', NULL, '贾岛', '唐', '只到潇湘水，洞庭湖未游。饮泉看月别，下峡听猿愁。讲不停雷雨，吟当近海流。降霜归楚夕，星冷玉泉秋。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12108, 27, 641001, '5c3613fb9f54540070d52b4a', '江行无题一百首', NULL, '钱起', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12109, 28, 104115, '585d266e1b69e60056109b7e', '洞庭湖', NULL, '曹松', '唐', '东西南北各连空，波上唯留小朵峰。长与岳阳翻鼓角，不离云梦转鱼龙。吸回日月过千顷，铺尽星河剩一重。直到劫馀还作陆，是时应有羽人逢。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12110, 29, 116734, '585d37d361ff4b006890e4e3', '洞庭玩月', NULL, '韩偓', '唐', '洞庭湖上清秋月，月皎湖宽万顷霜。玉碗深沉潭底白，金杯细碎浪头光。寒惊乌鹊离巢噪，冷射蛟螭换窟藏。更忆瑶台逢此夜，水晶宫殿挹琼浆。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12111, 30, 117371, '585d38de61ff4b0063f239fb', '洞庭湖阻风赠张十一署', NULL, '韩愈', '唐', '十月阴气盛，北风无时休。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12112, 31, 641918, '5caea911c05a80007312aa84', '题洞庭湖', NULL, '蔡押衙', '唐', '可怜洞庭湖，恰到三冬无髭须。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12113, 32, 641919, '5caea945eaa3750074445a1a', '过洞庭湖', NULL, '裴说', '五代十国', '浪高风力大，挂席亦言迟。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12114, 33, 641920, '5caea979a673f50068cf86db', '上岳守', NULL, '裴说', '五代十国', '入郭宽万里，岳阳堪画图。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12115, 34, 108844, '585d2d3b128fe10069cd17d7', '岳阳兵火后题僧舍', NULL, '裴说', '五代十国', '十年兵火真多事，再到禅扉却破颜。唯有两般烧不得，洞庭湖水老僧闲。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12116, 35, 108845, '585d2d3b570c350069328d10', '游洞庭湖', NULL, '裴说', '五代十国', '楚云团翠八百里，澧兰吹香堕春水。白头渔子摇苍烟，鸂鶒眠沙晓惊起。沙头龙叟夜叹忧，铁笛未响春风羞。露寒紫藟结新愁，城角泣断关河秋。谪仙欲识雷斧手，刬却古今愁共丑。鲸游碧落杳无踪，作诗三叹君知否。瀛洲一棹何时还，满江宫锦看湖山。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12117, 36, 115456, '585d366261ff4b00580ed2d7', '吟', NULL, '衡州舟子', '唐', '野鹊滩西一棹孤，月光遥接洞庭湖。堪嗟回雁峰前过，望断家山一字无。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12118, 37, 102550, '585d242d1b69e600561088a5', '洞庭湖', NULL, '张泌（佖）', '五代十国', '空江浩荡景萧然，尽日菰蒲泊钓船。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12119, 38, 88422, '585d139f1b69e600560ff363', '陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 · 其一', NULL, '李白', '唐', '洞庭西望楚江分，水尽南天不见云。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12120, 39, 88423, '585d139f128fe10069cc33c8', '陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 · 其二', NULL, '李白', '唐', '南湖秋水夜无烟，耐可乘流直上天。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12121, 40, 88424, '585d139f8d6d810065dcfec4', '陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 · 其三', NULL, '李白', '唐', '洛阳才子谪湘川，元礼同舟月下仙。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12122, 41, 12013, '580df6a2d2030900659070c2', '陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首', NULL, '李白', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12123, 42, 88426, '585d13a0ac502e0067224606', '陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 · 其五', NULL, '李白', '唐', '帝子潇湘去不还，空馀秋草洞庭间。', 'shi', 386, '洞庭湖', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12146, 1, 10284, '57b9018b128fe10054c99053', '使至塞上', NULL, '王维', '唐', '单车欲问边，属国过居延。', 'shi', 388, '黄河', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12147, 2, 10351, '57adf967a341310060ebf751', '登鹳雀楼', NULL, '王之涣', '唐', '白日依山尽，黄河入海流。', 'shi', 388, '黄河', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12148, 3, 10352, '57b911ed8ac2470062e01ff3', '凉州词二首 · 其一', NULL, '王之涣', '唐', '黄河远上白云间，一片孤城万仞山。', 'shi', 388, '黄河', '', NULL, '', '', '', '');
