INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12216, 5, 577654, '58606b11128fe1006df8f4bb', '菩萨蛮 · 淹泊平山堂。寒食节，固陵绿事参军表弟周元固惠酒，为作此词', NULL, '黄庭坚', '宋', '细腰宫外清明雨。', 'ci', 389, '平山堂', '', NULL, '', '', '', '');
