INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12218, 7, 625544, '5860ed9c570c350069480886', '扬州五咏九曲池', NULL, '苏辙', '宋', '堂上平看江上山，晴光千里对凭栏。海门仅可一二数，云梦犹吞八九宽。檐外小棠阴蔽芾，壁间遗墨涕汍澜。人亡坐使风流尽，遗构仍须子细观。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12219, 8, 585779, '5860825d1b69e6006cde20d3', '平山堂', NULL, '蔡戡', '宋', '平山堂上略从容，笑拍栏干万事空。因念醉翁行乐地，不知还又几春风。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12220, 9, 501396, '585fbdff128fe10069dc3442', '招缙云守关彦远教授曾彦和集平山堂次关韵', NULL, '晁补之', '宋', '蜀冈势与蜀山通，龙虎盘挐上紫空。小语还忧惊太一，高堂元自在天中。少师杨柳无遗迹，承旨歌谣有旧风。斜日芜城易兴感，忘怀犹喜故人同。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12221, 10, 503689, '585fc367b123db0065b782a8', '因观刘侍读姚秘丞孙处士平山堂诗寄欧阳公唱和作绝句', NULL, '晁说之', '宋', '醉公认得扬州路，堂上平山列酒樽。后日公荣来酩酊，赋诗可但属姚孙。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12222, 11, 515878, '585fdf7561ff4b00581ea1ab', '次韵赵帅登平山堂', NULL, '陈造', '宋', '东皇未憗养花功，远近娇红乱老红。胜赏已容陪隽轨，凭虚仍喜受雄风。小?蜀井寒冰齿，旋俯波光碧蘸空。更看诗翁落椽笔，弹丸句法许谁同。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12223, 12, 515879, '585fdf75da2f600065952579', '次韵赵帅登平山堂', NULL, '陈造', '宋', '平章景物我何功，犹博宾筵醉颊红。欢甚锐戈思却日，吟馀豪兴欲凌风。急觞泛滟春浮渌，掺鼓喧轰雁堕空。白雪拜嘉仍袖手，汗颜终恐坐雷同。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12224, 13, 515880, '585fdf7661ff4b006ce39866', '次韵赵帅登平山堂', NULL, '陈造', '宋', '修月于今第一功，后车九万蜀笺红。诗供寒食莺花课，袖拂平山杨柳风。匝坐蕙兰歌似剪，生香笑语酒如空。胡床不减南楼兴，今古风流正自同。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12225, 14, 515669, '585fdeed8d6d810065ee0db8', '登平山堂', NULL, '陈造', '宋', '平山堂上命琴樽，前辈风流肯见分。恋客懒斜当槛日，藏山不断隔江云。吟笺得意窥天巧，醉面禁凉减缬纹。杖策归来新月上，落梅如雪点风裙。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12226, 15, 627904, '5860f68161ff4b00582449e1', '平山堂次王居卿祠部韵', NULL, '苏轼', '宋', '高会日陪山简醉，狂言屡发次公醒。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12227, 16, 322729, '585e4e1a128fe10069d39ac2', '平山堂', NULL, '王安石', '宋', '城北横冈走翠虬，一堂高视两三州。淮岑日对朱栏出，江岫云齐碧瓦浮。墟落耕桑公恺悌，杯觞谈笑客风流。不知岘首登临处，壮观当时有此不。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12228, 17, 465464, '585f6c6fda2f60006591c2f9', '平山堂', NULL, '杜东', '宋', '平山堂下水云重，孤笛凄凉淡月中。不见龙蛇飞素壁，只馀狐兔戍离宫。仙翁已逐风流尽，世事俱随梦幻空。广武无人同此意，慨然止有泪临风。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12229, 18, 313649, '585e3eb8b123db0065ae54e9', '官满将归与同幕别平山堂', NULL, '方岳', '宋', '鸥未寒盟傥可寻，归与雅不负登临。江南山作故人面，云北雁知游子心。淮海三年双鬓短，乾坤万里一杯深。秋风正惬莼羹腹，松菊犹存月满林。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12230, 19, 313650, '585e3eb8570c350069389e59', '官满将归与同幕别平山堂', NULL, '方岳', '宋', '貂敝那禁塞上寒，所成何事许悲酸。雪深茅屋归巢冷，月老芦洲雁影单。官薄偶书三考满，客怀已受一分宽。秋帆但趁好风便，酒在不愁行路难。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12231, 20, 546675, '58602404128fe1006df83c86', '大明寺平山堂', NULL, '梅尧臣', '宋', '陆羽烹茶处，为堂备宴娱。冈形来自蜀，山色去连吴。毫发开明镜，阴晴改画图。翰林能忆否，此景大梁无。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12260, 6, 10489, '57b95210d342d3005ac9f181', '塞下曲 · 其二', NULL, '王昌龄', '唐', '饮马渡秋水，水寒风似刀。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12232, 21, 546956, '586024be1b69e6005622336b', '和永叔答刘原甫游平山堂寄', NULL, '梅尧臣', '宋', '黄土坡陁冈顶寺，青烟幂历浙西山。半荒樵牧旧城下，一月阴晴连屿间。人指废兴都莫问，眼看今古总输闲。刘郎寄咏公酬处，夜对金銮步辇还。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12233, 22, 548704, '586028db8d6d810065ef30fb', '平山堂留题', NULL, '梅尧臣', '宋', '蜀冈莽苍临大邦，雄雄太守驻旌幢。相基树楹气势厖，千山飞影横过江。峰峤俯仰如奔降，雷塘坡小鸂鶒双。陆羽井苔黏瓦缸，煎铛泻鼎声淙淙。雨牙鸟爪不易得，碾雪恨无居士庞。已见宣城谢公陋，吟看远岫通高窗。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12234, 23, 548614, '586028a5570c35006943d596', '平山堂杂言', NULL, '梅尧臣', '宋', '芜城之北大明寺，辟堂高爽趣广而意厖。欧阳公经始曰平山，山之迤逦苍翠隔大江。天清日明了了见峰岭，已胜谢朓龊龊远视于一窗。亦笑炀帝造楼摘星放萤火，锦帆落樯旗建杠。我今乃来偶同二三友，得句欲霜钟撞。却思公之文字世莫双，举酒一使长咽慢肌高揭鼓笛腔，万古有作心胸降。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12235, 24, 504455, '585fc5148d6d810065ed4418', '广陵五题次韵子由题九曲池', NULL, '秦观', '宋', '栋宇高开古寺间，尽收佳处入雕栏。山浮海上青螺远，天转江南碧玉宽。雨槛幽花滋浅泪，风卮清酒涨微澜。游人若论登临美，须作淮东第一观。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12236, 25, 326093, '585e543c1b69e600561798e3', '平山堂', NULL, '王令', '宋', '豁豁虚堂巧架成，地平相与远山平。横岩积翠檐边出，度陇浮苍瓦上生。春入壶觞分蜀井，风回谈笑落芜城。谢公已去人怀想，向此还留召伯名。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12237, 26, 326089, '585e543a128fe10069d3c823', '平山堂寄欧阳公', NULL, '王令', '宋', '废苑繁华未可寻，孤城西北路嵚崟。檐边月过峰峦顶，柱下云回草树阴。宾客日随千骑乐，管弦风入万家深。知公白玉堂中梦，未负当时壮观心。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12238, 27, 641947, '5cb3ebcd7b968a0075f5a9ac', ' 平山堂 ', NULL, '吴潜', '宋', '昔日西风卷地狂，只堪吹雁过潇湘。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12239, 28, 506659, '585fc9f91b69e60056207989', '过扬州平山堂邂逅许深父主漕', NULL, '袁说友', '宋', '平生踪迹半江湖，岁晚淮乡识旧都。小却车尘行复止，要看山色有还无。关山回首嗟何限，风景于人岂不殊。犹得故人谈世事，金城方略政堪图。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12240, 29, 641948, '5cb3ec81c8959c007591c478', '平山堂吊古 ', NULL, '张蕴', '宋', '隔江山色画图中，故址荒来与庙通。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12241, 30, 641949, '5cb3ecb0a91c930067e49b69', ' 平山堂 ', NULL, '赵善括', '宋', '平山堂对妙高峰，极目郊原万里同。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12242, 31, 458497, '585f5e5d61ff4b00581acb96', '同狼山印老早饭建隆遂登平山堂', NULL, '吕本中', '宋', '尘埃障西风，草木被朝日。篮舆郭北门，未厌来往疾。僮奴懒不进，颇复费呵叱。道人先我行，宴坐已一室。殷勤劝客住，午饭当促膝。炉烟窗纸明，鸟语树叶密。却上平山堂，晚景更萧瑟。澄江渺天际，妙句不容乞。平生泉石念，固自有遗失。何能从儿曹，十事九不实。兹游岂不快，此老固坦率。尚从文殊师，一往问摩诘。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12243, 32, 451758, '585f4de1570c3500693e6f9c', '同似表叔易置酒平山堂', NULL, '李纲', '宋', '暂停征棹此从容，叹息前贤结构雄。心眼乍随天宇阔，笑谈不觉酒樽空。江光隐见轩楹里，山色虚无烟雨中。种柳仙翁何处去，年年疏翠自春风。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12244, 33, 550761, '58602d0e61ff4b00581fc37f', '观新堡寨因登平山堂次接伴袁同年韵', NULL, '许及之', '宋', '换得玻瓈千顷湖，醉翁遗胜在江都。登临山色依然在，拂略秋容澹欲无。新堡似云屯戍久，旧臣何日策勋殊。王人按垒非寻胜，归报前游有远图。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12245, 34, 551469, '58602eaf61ff4b006ce4bd1c', '望平山堂', NULL, '许及之', '宋', '霏微晚雨湿疏钟，仿佛浮图出半空。回首江南山色远，平山却在有无中。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12246, 35, 599325, '5860a37a570c35006945d6b6', '平山堂', NULL, '刘攽', '宋', '吴山不过楚，江水限中间。此地一回首，众峰如可攀。俯看孤鸟没，平视白云还。行子厌长路，秋风聊解颜。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12247, 36, 599605, '5860a4571b69e6006cdefd28', '平山堂', NULL, '刘攽', '宋', '危栋层轩不易攀，万峰犹在户庭间。长空未省浮云碍，积翠如遮去鸟还。寡和阳春随白雪，知音流水与高山。吴中辩士嗤枚叟，漫说观涛可慰颜。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12248, 37, 596225, '58609b3161ff4b0068a3ac25', '再游平山堂', NULL, '刘敞', '宋', '背城历历才十里，经岁悠悠能一来。可惜薄书捐白日，强从宾客宴平台。暮云自与千山合，醉眼时令万宇开。老子谁怜兴不浅，黄花欲落更添杯。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12249, 38, 609574, '5860beac1b69e60056250a60', '和刘原甫平山堂见寄', NULL, '欧阳修', '宋', '督府繁华久已阑，至今形胜可跻攀。山横天地苍茫外，花发池台草莽间。万井笙歌遗俗在，一樽风月属君闲。遥知为我留真赏，恨不相随暂解颜。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12250, 39, 641950, '5cb3efa6a673f5006814a5e2', '平山堂观雨 ', NULL, '释道潜', '宋', '午枕藜床梦忽惊，柳边雷送雨如倾。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12251, 40, 641951, '5cb3efc5c8959c007592038b', '登平山堂故址 ', NULL, '李孝光', '元', '蜀山有堂已改作，骑马出门西北行。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12252, 41, 43516, '585ce93261ff4b0063ef97eb', '平山堂', NULL, '陈孚', '元', '堂上醉翁仙去，芦花雪满汀洲。二十四桥烟水，为谁流下扬州。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12253, 42, 57317, '585cf58961ff4b006cd1acbc', '维扬十咏', NULL, '舒頔', '元', '平山山上构高堂，堂下青芜接大荒。堂废山空人不见，冷云秋草卧横冈。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12254, 43, 64702, '585cfc0a61ff4b00580cd9bd', '题平山堂次黄先生韵', NULL, '赵汸', '元', '虚堂眄平冈，积翠淩天半。彷像识瑶台，熹微窥玉案。颇疑巨灵力，刬削非一旦。森森古树齐，奕奕朝霞烂。地近巘易陟，池清莲不蔓。莺啼午梦残，客至琴声断。胜境契中襟，雅怀知弗畔。翛然忘物我，讵肯存崖岸。马迹遍幽燕，华颠乐村闬。居夷非矫曲，悼猛得前算。巇崄世所趋，真淳日雕散。跬步视安危，片言几理乱。苟能领斯会，未觉身为患。嘉谋谅贻厥，岂曰夸殊观。', 'shi', 389, '平山堂', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12255, 1, 10185, '57b8b1f7c4c97100558e0d45', '出塞', NULL, '王昌龄', '唐', '秦时明月汉时关，万里长征人未还。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12256, 2, 13202, '585cc394b123db0065a4e224', '咏饮马应诏', NULL, '杨师道', '隋', '清晨控龙马，弄影出花林。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12257, 3, 113196, '585d3367128fe1006de72644', '横吹曲辞紫骝马', NULL, '卢照邻', '唐', '骝马照金鞍，转战入皋兰。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12258, 4, 113075, '585d334f1b69e6006ccbf04f', '雨雪曲', NULL, '卢照邻', '唐', '虏骑三秋入，关云万里平。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12259, 5, 106490, '585d2a11570c3500693270bc', '送人之军', NULL, '贺知章', '唐', '常经绝脉塞，复见断肠流。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12261, 7, 10186, '57b8f482128fe10054c9395d', '从军行', NULL, '王昌龄', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12262, 8, 101001, '585d225bda2f60006584a31c', '塞下曲四首', NULL, '常建', '唐', '北海阴风动地来，明君祠上望龙堆。髑髅皆是长城卒，日暮沙场飞作灰。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12263, 9, 106410, '585d29da128fe10069ccf978', '骢马', NULL, '万楚', '唐', '金络青骢白玉鞍，长鞭紫陌野游盘。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12264, 10, 112141, '585d31f061ff4b0063f1f9d7', '送子婿崔真父归长城', NULL, '刘长卿', '唐', '送君卮酒不成欢，幼女辞家事伯鸾。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12265, 11, 97106, '585d1d65128fe1006de65db6', '关山月', NULL, '徐九皋', '唐', '玉塞抵长城，金徽映高阙。遥心万馀里，直望三边月。霜静影逾悬，露晞光渐没。思君不可见，空叹将焉歇。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12266, 12, 97104, '585d1d6561ff4b00688ff194', '送部四镇人往单于别知故', NULL, '徐九皋', '唐', '天下今无事，云中独未宁。忝驱更戍卒，方远送边庭。马饮长城水，军占太白星。国恩行可报，何必守经营。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12267, 13, 82569, '585d0d8161ff4b0063f0b466', '奉酬路五郎中院长新除工部员外见简', NULL, '李嘉祐', '唐', '一门同秘省，万里作长城。问绢莲花府，扬旗细柳营。词锋偏却敌，草奏直论兵。何幸新诗赠，真输小谢名。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12268, 14, 99265, '585d203cda2f600065848fc2', '杂曲歌辞 · 蓟门行五首', NULL, '高适', '唐', '黯黯长城外，日没更烟尘。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12269, 15, 111576, '585d315d1b69e600561100c5', '横吹曲辞梅花落', NULL, '刘方平', '唐', '新岁芳梅树，繁苞四面同。春风吹渐落，一夜几枝空。小妇今如此，长城恨不穷。莫将辽海雪，来比后庭中。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12270, 16, 641961, '5cb542c8a91c930067f83f09', '送刘判官赴丰州', NULL, '卢纶', '唐', '衔杯吹急管，满眼起风砂。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12271, 17, 85563, '585d10af1b69e600560fd9b1', '登长城', NULL, '李益', '唐', '汉家今上郡，秦塞古长城。有日云长惨，无风沙自惊。当今圣天子，不战四夷平。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12272, 18, 635013, '59217f918d6d810058db9387', '塞下曲四首', NULL, '李益', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12273, 19, 85539, '585d10a61b69e600560fd96f', '统汉峰', NULL, '李益', '唐', '统汉峰西降户营，黄河战骨拥长城。只今已勒燕然石，北地无人空月明。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12274, 20, 82924, '585d0de0570c35006931776d', '度关山', NULL, '李端', '唐', '雁塞日初晴，狐关雪复平。危楼缘广漠，古窦傍长城。拂剑金星出，弯弧玉羽鸣。谁知系虏者，贾谊是书生。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12275, 21, 93479, '585d191f128fe1006de636e2', '塞外月夜寄荆南熊侍御', NULL, '武元衡', '唐', '南依刘表北刘琨，征战年年箫鼓喧。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12276, 22, 107174, '585d2afc61ff4b00580e66a0', '长城闻笛', NULL, '杨巨源', '唐', '孤城笛满林，断续共霜砧。夜月降羌泪，秋风老将心。静过寒垒遍，暗入故关深。惆怅梅花落，山川不可寻。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12277, 23, 110959, '585d307861ff4b006cd399a5', '经檀道济故垒', NULL, '刘禹锡', '唐', '万里长城坏，荒营野草秋。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12278, 24, 641962, '5cb54308a673f5006827ff18', '送流人', NULL, '张籍', '唐', '独向长城北，黄云暗塞天。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12279, 25, 84630, '585d0fc1128fe1006ba18efd', '邠州词献高尚书三首', NULL, '李涉', '唐', '将家难立是威声，不见多传卫霍名。一自元和平蜀后，马头行处即长城。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12280, 26, 100252, '585d2159128fe1006de6811f', '题悟公禅室', NULL, '陆畅', '唐', '临坛付法十三春，家本长城若下人。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12281, 27, 94319, '585d1a1c8d6d810065dd3877', '送邢郎中赴太原', NULL, '姚合', '唐', '上将得良策，恩威作长城。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12282, 28, 98856, '585d1fcb128fe1006ba21ad3', '饮马长城窟', NULL, '陈标', '唐', '日日风吹虏骑尘，年年饮马汉营人。千堆战骨那知主，万里枯沙不辨春。浴谷气寒愁坠指，断崖冰滑恐伤神。金鞍玉勒无颜色，泪满征衣怨暴秦。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12283, 29, 101273, '585d22a3128fe10069ccb8d4', '听筝', NULL, '张祜', '唐', '十指纤纤玉笋红，雁行轻遏翠弦中。分明似说长城苦，水咽云寒一夜风。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12284, 30, 81075, '585d0c141b69e600560fb656', '长城', NULL, '朱庆馀', '唐', '秦帝防胡虏，关心倍可嗟。一人如有德，四海尽为家。往事乾坤在，荒基草木遮。至今徒者骨，犹自哭风沙。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12285, 31, 108615, '585d2ce21b69e6006ccbb246', '送从翁中丞奉使黠戛斯六首', NULL, '赵嘏', '唐', '秦皇无策建长城，刘氏仍穷北路兵。若遇单于旧牙帐，却应伤叹汉公卿。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12286, 32, 81980, '585d0ce861ff4b006cd26150', '赋得长城斑竹杖', NULL, '李频', '唐', '秦兴版筑时，剪伐不知谁。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12287, 33, 103860, '585d26008d6d810065dda2c4', '长城下', NULL, '曹邺', '唐', '远水犹归壑，征人合忆乡。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12288, 34, 90129, '585d158c61ff4b00688fafa1', '杞梁墓', NULL, '汪遵', '唐', '一叫长城万仞摧，杞梁遗骨逐妻回。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12289, 35, 90177, '585d1597da2f6000658431b6', '咏长城', NULL, '汪遵', '唐', '秦筑长城比铁牢，蕃戎不敢过临洮。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12290, 36, 104441, '585d26cd1b69e6006ccb7cc2', '失题', NULL, '许棠', '唐', '独夜长城下，孤吟近北辰。半天初去雁，穷碛远来人。月黯氛埃积，风膻帐幕邻。惟闻防虏寇，不语暗伤神。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12291, 37, 116223, '585d374861ff4b006cd3da22', '长城', NULL, '罗邺', '唐', '当时无德御乾坤，广筑徒劳万古存。谩役生民防极塞，不知血刃起中原。珠玑旋见陪陵寝，社稷何曾保子孙。降虏至今犹自说，冤声夜夜傍城根。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12292, 38, 91785, '585d172661ff4b00688fbc2a', '秋深', NULL, '周朴', '唐', '柳色尚沈沈，风吹秋更深。山河空远道，乡国自鸣砧。巷有千家月，人无万里心。长城哭崩后，寂绝至如今。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12293, 39, 112953, '585d332bb123db0065a87bec', '和李秀才边庭四时怨', NULL, '卢汝弼', '唐', '朔风吹雪透刀瘢，饮马长城窟更寒。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12294, 40, 641963, '5cb543bfa673f50068280a68', '续古二十九首', NULL, '陈陶', '唐', '大尧登宝位，麟凤焕宸居。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12295, 41, 526863, '585ff8d0570c3500694359d5', '古筑城曲四首', NULL, '陆游', '宋', '长城高际天，三十万人守。一日诏书来，扶苏先授首。', 'shi', 390, '长城', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12296, 42, 526977, '585ff8fd128fe1006bb35b28', '古意二首', NULL, '陆游', '宋', '千金募战士，万里筑长城。何时青冢月，却照汉家营。', 'shi', 390, '长城', '', NULL, '', '', '', '');
