INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12298, 44, 641964, '5cb54449c8959c0075a59f0a', '登八达岭', NULL, '沈用济', '清', '策马出居庸，盘回上碧峰。', 'shi', 390, '长城', '', NULL, '', '', '', '');
