INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12302, 47, 97171, '585d1d77128fe10069cc8902', '阮公体', NULL, '徐晶', '唐', '秦王按剑怒，发卒戍龙沙。雄图尚未毕，海内已纷拿。黄尘暗天起，白日敛精华。唯见长城外，僵尸如乱麻。', 'shi', 390, '长城', '', NULL, '', '', '', '');
