INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12304, 2, 10771, '57b19b55165abd00542eafca', '卜算子', NULL, '李之仪', '宋', '我住长江头，君住长江尾。', 'ci', 391, '长江', '', NULL, '', '', '', '');
