INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12353, 49, 107079, '585d2adfb123db0065a82e71', '过长江', NULL, '黄滔', '唐', '曾搜景象恐通神，地下还应有主人。若把长江比湘浦，离骚不合自灵均。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12354, 50, 82139, '585d0d1561ff4b0063f0b160', '过长江伤贾岛', NULL, '李频', '唐', '忽从一宦远流离，无罪无人子细知。到得长江闻杜宇，想君魂魄也相随。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12355, 51, 108028, '585d2c2a1b69e6006ccbac90', '寄令狐相公', NULL, '贾岛', '唐', '策杖驰山驿，逢人问梓州。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12356, 52, 107857, '585d2bc8ac502e006723200c', '题长江', NULL, '贾岛', '唐', '言心俱好静，廨署落晖空。归吏封宵钥，行蛇入古桐。长江频雨后，明月众星中。若任迁人去，西溪与剡通。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12357, 53, 109183, '585d2dbb128fe10069cd1ca9', '长江县经贾岛墓', NULL, '郑谷', '唐', '水绕荒坟县路斜，耕人讶我久咨嗟。重来兼恐无寻处，落日风吹鼓子花。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12358, 54, 86768, '585d11fc61ff4b00580d8766', '赋得送贾岛谪长江', NULL, '李洞', '唐', '敲驴吟雪月，谪出国西门。行傍长江影，愁深汨水魂。筇携过竹寺，琴典在花村。饥拾山松子，谁知贾傅孙。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12359, 55, 632224, '5861034161ff4b006307f2e6', '长江二首', NULL, '苏泂', '宋', '处暑无三日，新凉直万金。白头更世事，青草印禅心。放鹤婆娑舞，听蛩断续吟。极知仁者寿，未必海之深。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12360, 56, 325631, '585e5377ac502e006729d7a0', '题长江图三绝', NULL, '王柏', '宋', '一目长江万里长，几多兴废要商量。时人莫作画图看，说着源头正可伤。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12361, 57, 325632, '585e53771b69e600561792de', '题长江图三绝', NULL, '王柏', '宋', '鱼腹江边八阵图，嶙峋于此岂良谟。后来浪道长蛇势，用势还须烈丈夫。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12362, 58, 325633, '585e5378128fe10069d3c21b', '题长江图三绝', NULL, '王柏', '宋', '瓜步洲前水最深，几人恃此纵荒淫。谁云天意分南北，自是人无混一心。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12363, 59, 641970, '5cb68f45a91c9300670ae4cf', ' 长江 ', NULL, '赵蕃（昌父）', '宋', '长江滚滚来无尽，顺流逆挽纷成阵。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12364, 60, 68294, '585cff7a1b69e600560f53bf', '题顾氏长江图', NULL, '戴良', '元', '天下几人画山水，虎头子孙世莫比。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12365, 61, 165135, '585d6e2e61ff4b0058100823', '长江险', NULL, '李东阳', '明', '长江险，天可恃。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12366, 62, 165225, '585d6e4bb123db0065a9d1b6', '长江行', NULL, '李东阳', '明', '大江西来是何年，奔流直下岷山巅。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12367, 63, 287881, '585e1597570c3500693765c5', '天官冢宰第一', NULL, '周公旦', '周', '惟王建宫以捂方正位，体国经野，设官分职，以为民极。', 'wen', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12368, 64, 254921, '585de2968d6d810065e12f71', '长江万里图', NULL, '杨基', '明', '我家岷山更西住，正见岷江发源处。三巴春霁雪初消，百折千回向东去。江水东流万里长，人今漂泊尚他乡。烟波草色时牵恨，风雨猿声欲断肠。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12371, 65, 318634, '585e4716128fe10069d36803', '解缆南浦初溯长江江流出鄂渚汉阳两山之间云霭横之如一山然', NULL, '王十朋', '宋', '解缆长江口，回头思黯然。封疆一川隔，烟霭两州连。水鸟飞沿渚，江豚跃傍船。好风知几苇，送我上青天。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12373, 66, 326398, '585e54b561ff4b0063f87f3e', '长江万顷明如镜', NULL, '王令', '宋', '长江万顷明如镜，江面无风江水静。白日当空照江底，蛟穴龙居难隐映。乱山影落碧波寒，渔翁醉卧愁不醒。迟暮东南见海门，海门目断烟云暝。几度狂涛日月低，舟师鼓枻歌相庆。长江虽长缯网多，纤鳞何处逃生命。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12374, 67, 328307, '585e57c0da2f6000658bcfd7', '送祖道师赴长江', NULL, '王灼', '宋', '山林与城市，何地非隐沦。子意亦易败，径投寂寞滨。楞严有奥章，试为识者陈。归思落烟艇，尚及秋风新。', 'shi', 391, '长江', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12401, 1, 10270, '57b8d9ae5bbb50005b776383', '枫桥夜泊', NULL, '张继', '唐', '月落乌啼霜满天，江枫渔火对愁眠。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12402, 2, 66568, '585cfd9b8d6d810065dc50f6', '苏台竹枝词十首', NULL, '薛兰英、蕙英', '元', '门泊东吴万里船，乌啼月落水如烟。', 'ci', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12403, 3, 641997, '5cb7e3daa3180b7832863161', '再游蒋山', NULL, '李流谦', '宋', '寒山寺里立斜晖，只有垂杨自在垂。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12404, 4, 254880, '585de291b123db0065ab89d6', '潇湘八景', NULL, '杨基', '明', '右渔村夕照。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12405, 5, 95732, '585d1bb8ac502e0067228bed', '寄恒璨', NULL, '韦应物', '唐', '心绝去来缘，迹顺人间事。独寻秋草径，夜宿寒山寺。今日郡斋闲，思问楞伽字。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12406, 6, 74737, '585d056bda2f60006583abcd', '途中言事寄居远上人', NULL, '方干', '唐', '举目时时似故园，乡心自动向谁言。白云晓湿寒山寺，红叶夜飞明月村。震泽风帆归橘岸，钱塘水府抵城根。羡师了达无牵束，竹径生苔掩竹门。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12407, 7, 540138, '586015f7ac502e0067344dd7', '赠相僧杨懒散', NULL, '张嵲', '宋', '野鹤本长生，孤云无定意。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12408, 8, 112454, '585d3261570c35006932be05', '送僧归山', NULL, '刘言史', '唐', '楚俗翻花自送迎，密人来往岂知情。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12409, 9, 612770, '5860c650128fe1006bb6d5b0', '寒山寺坏庄产尽为势家所夺余游天台甚为贤惜', NULL, '薛师石', '宋', '寒山寺废佛灯寒，有客来游欲住难。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12410, 10, 641998, '5cb7e41c7b968a0075306526', '泊阊门', NULL, '顾瑛', '元', '枫叶芦花暗画船，银筝断绝十三弦。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12411, 11, 203733, '585d9d6061ff4b0058106c24', '枫桥夜泊', NULL, '孙华孙', '清', '画船夜泊寒山寺，不信江枫有客愁。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12476, 34, 525249, '585ff4cdda2f60006595afde', '书愤二首', NULL, '陆游', '宋', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12412, 12, 209514, '585da47a128fe10069cf11e8', '过寒山寺寄道上人', NULL, '陈宗', '明', '归舟欲住更匆匆，晚色苍苍迫下舂。两岸杏花寒食雨，数株杨柳酒旗风。江边尚说寒山寺，城外犹听半夜钟。溪水自流人自老，渔歌长伴月明中。', 'shi', 393, '寒山寺', '', NULL, '', '', '', '');
