INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12436, 4, 100741, '585d220761ff4b0068901ee7', '题河中鹳雀楼', NULL, '张乔', '唐', '高楼怀古动悲歌，鹳雀今无野燕过。树隔五陵秋色早，水连三晋夕阳多。渔人遗火成寒烧，牧笛吹风起夜波。十载重来值摇落，天涯归计欲如何。', 'shi', 395, '鹳雀楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12437, 5, 77139, '585d07cd1b69e6006cca736b', '登河中鹳雀楼', NULL, '司马扎', '唐', '楼中见千里，楼影入通津。烟树遥分陕，山河曲向秦。兴亡留白日，今古共红尘。鹳雀飞何处，城隅草自春。', 'shi', 395, '鹳雀楼', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12438, 6, 642005, '5cb93548a91c9377aa65a25a', '和赵相公登鹳雀楼', NULL, '殷尧藩', '唐', '危楼高架泬寥天，上相闲登立彩旃。', 'shi', 395, '鹳雀楼', '', NULL, '', '', '', '');
