INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (12501, 9, 317682, '585e457a61ff4b006cd9bd9b', '读赤壁赋前后二首', NULL, '文天祥', '宋', '一笑沧波浩浩流，只鸡斗酒更扁舟。八龙写作诗中案，孤鹤来为梦里游。杨柳远烟连北府，芦花新月对南楼。玉仙来往清风夜，还识江山似旧不。', 'shi', 397, '赤壁', '', NULL, '', '', '', '');
