INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13750, 11, 643556, '5dbd28af12215f00711ca520', '西厢记 · 第三本 · 楔子', NULL, '王实甫', '元', '[旦上云]自那夜听琴后，闻说张生有病，我如今着红娘去书院里，看他说甚么。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13751, 12, 643557, '5dbd28eef884af0073380dcd', '西厢记 · 第三本 · 第一折', NULL, '王实甫', '元', '[末上云]害杀小生也。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13752, 13, 643558, '5dbd2930f884af0073381093', '西厢记 · 第三本 · 第二折', NULL, '王实甫', '元', '[旦上云]红娘伏侍老夫人不得空便，偌早晚敢待来也。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13753, 14, 643559, '5dbd2983a3180b0068e71ae7', '西厢记 · 第三本 · 第三折', NULL, '王实甫', '元', '[红上云]今日小姐着我寄书与张生，当面偌多般假意儿，原来诗内暗约着他来。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13754, 15, 643560, '5dbd29e56e9ba1006d61ce14', '西厢记 · 第三本 · 第四折', NULL, '王实甫', '元', '[夫人上云]早间长老使人来，说张生病重。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13755, 16, 643561, '5dbd2a1d17b54d006c7b50d9', '西厢记 · 第四本 · 楔子', NULL, '王实甫', '元', '[旦上云]昨夜红娘传简去与张生，约今夕和他相见，等红娘来做个商量。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13756, 17, 643562, '5dbd2a48c05a8000684d31b3', '西厢记 · 第四本 · 第一折', NULL, '王实甫', '元', '[末上云]昨红娘所遗之简，约小生今夜成就。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13757, 18, 643563, '5dbd2a71eaa375006c490c7c', '西厢记 · 第四本 · 第二折', NULL, '王实甫', '元', '[夫人引俫上云]这几日窃见莺莺语言恍惚，神思加倍，腰肢体态，比向日不同；', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13758, 19, 643564, '5dbd2a9ec05a8000684d35f0', '西厢记 · 第四本 · 第三折', NULL, '王实甫', '元', '〔正宫·端正好〕碧云天，黄花地，西风紧，北雁南飞。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13759, 20, 643565, '5dbd2ad530863b006c42d258', '西厢记 · 第四本 · 第四折', NULL, '王实甫', '元', '[末引仆骑马上开]离了蒲东早三十里也。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13760, 21, 643566, '5dbd2c2ac05a8000684d47da', '西厢记 · 第五本 · 楔子', NULL, '王实甫', '元', '[末引仆人上开云]自暮秋与小姐相别，倏经半载之际。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13761, 22, 643567, '5dbd2c5412215f00711cd123', '西厢记 · 第五本 · 第一折', NULL, '王实甫', '元', '[旦引红娘上开云]自张生去京师，不觉半年，杳无音信。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13762, 23, 643568, '5dbd2c86c05a8000684d4c0d', '西厢记 · 第五本 · 第二折', NULL, '王实甫', '元', '[末云]“画虎未成君莫笑，安排牙爪始惊人。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13763, 24, 643569, '5dbd2caca3180b0068e742c5', '西厢记 · 第五本 · 第三折', NULL, '王实甫', '元', '[净扮郑恒上开云]自家姓郑名恒，字伯常。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13764, 25, 643570, '5dbd2ce317b54d006c7b721e', '西厢记 · 第五本 · 第四折', NULL, '王实甫', '元', '[夫人上云]谁想张生负了俺家，去卫尚书家做女婿去，今日不负老相公遗言，还招郑恒为婿。', 'wen', 410, '西厢记', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13785, 6, 11896, '58030f40a22b9d005b46f03b', '立冬即事二首', NULL, '仇远', '元', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13786, 7, 521498, '585feb77128fe1006bb30f92', '立冬', NULL, '高登', '宋', '黄茅时节瘴烟浓，人在山凹第几重。梁竦负才徒感慨，嵇康赋性本疏慵。此生自断天休问，吾道频年世不容。会脱帻巾还自隐，鹿门妻子惯相从。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13787, 8, 47795, '585ced1b61ff4b00688e6f50', '立冬', NULL, '陆文圭', '元', '早久何当雨，秋深渐入冬。黄花犹带露，红叶已随风。边思吹寒角，村歌相晚舂。篱门日高卧，衰懒愧无功。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13788, 9, 238447, '585dcba2da2f60006587ab77', '立冬舟中即事', NULL, '张以宁', '明', '一滩一滩复一滩，轻舟荡桨上曾湍。三秋岭外雨全少，十月邕南天未寒。露岸苇花明白羽，风林橘子动金丸。如何连夜还乡梦，不怕关山行路难。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13789, 10, 479796, '585f8a5e8d6d810065eb8ebf', '立冬夜舟中作', NULL, '范成大', '宋', '人逐年华老，寒随雨意增。山头望樵火，水底见渔灯。浪影生千叠，沙痕没几棱。峨眉欲还观，须待到晨兴。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13790, 11, 259275, '585de90b1b69e600561455ba', '朝天曲立冬', NULL, '黄淮', '明', '晓风啸空，报道冬初动。', 'qu', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13791, 14, 10784, '57b92f49d342d3005ac8b147', '绿头鸭 · 咏月', NULL, '晁端礼', '宋', '晚云收，淡天一片琉璃。', 'ci', 21, '中秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13792, 15, 638166, '5b31e4ffee920a003b351cc9', '洞仙歌 · 中秋', NULL, '向子諲', '宋', '碧天如水，一洗秋容净。', 'ci', 21, '中秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13793, 16, 468545, '582b08a6da2f600063d0f01f', '一剪梅 · 中秋无月', NULL, '辛弃疾', '宋', '忆对中秋丹桂丛。', 'ci', 21, '中秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13794, 17, 197275, '585d954bb123db0065aa24f3', '中秋月 · 中秋月', NULL, '徐有贞', '明', '中秋月。', 'shi', 21, '中秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13795, 36, 210335, '585da570b123db0065aa48f2', '急雨', NULL, '郭之奇', '明', '秋云犹作夏峰奇，急雨衔山过水湄。长浦斜阳从望失，夹堤流电向襟麾。丹林绿霭初回互，碧野澄川忽骤驰。此际孤篷依落叶，萧萧一任晚风吹。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13796, 37, 399493, '585ed633128fe1006bac61c3', '残雨', NULL, '彭泰来', '清', '残雨如人语，无声复有声。为谁写幽怨，竟夕不分明。地僻秋心早，梦寒江水生。江波一双鲤，应到越王城。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13797, 38, 10287, '57b910fac4c97100558faa8c', '送元二使安西', NULL, '王维', '唐', '渭城朝雨浥轻尘，客舍青青柳色新。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13798, 39, 524993, '585ff429128fe10069ddd1e7', '雨夜', NULL, '陆游', '宋', '岁晚茆茨劣自容，齿摇将脱发将童。心游万里关河外，身卧一窗风雨中。医不可招惟忍病，书犹能读足忘穷。夜阑睡觉蛩声里，时见灯花落碎红。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13799, 40, 62535, '585cfa49b123db0065a697b9', '秋雨', NULL, '赵文', '宋', '秋雨沉沉酒醒迟，小窗灯火对唐诗。是谁隔屋鸣弦管，恰似吴山梦觉时。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13800, 41, 11651, '57b915427db2a2005427482b', '秋雨夜眠', NULL, '白居易', '唐', '凉冷三秋夜，安闲一老翁。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13801, 42, 12417, '581f428e5bbb500059e91ef4', '溪上遇雨二首', NULL, '崔道融', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13802, 43, 78132, '585d08b9128fe10069cbd9ea', '阴雨', NULL, '白居易', '唐', '岚雾今朝重，江山此地深。滩声秋更急，峡气晓多阴。望阙云遮眼，思乡雨滴心。将何慰幽独，赖此北窗琴。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13803, 44, 152843, '585d6089ac502e0067248ecd', '草店雨行', NULL, '何景明', '明', '山馆夏阴澹，雨行寒色凄。奔湍回白石，折坂下青泥。栈道常通北，江流却向西。千峰问来路，烟雾使人迷。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13804, 45, 505849, '583d5ac061ff4b007edad84c', '木兰花 · 雨中', NULL, '莫将', '宋', '花时人道多风雨。', 'ci', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13805, 46, 530290, '5860012d1b69e6005621dca4', '夜雨', NULL, '陆游', '宋', '浓云如泼墨，急雨如飞镞。激电光入牖，奔雷势掀屋。漏湿恐败书，起视自秉烛。移床顾未暇，盆盎苦不足。不如卷茵席，少忍待其复。飞萤方得意，熠熠相追逐。姑恶独何怨，菰丛声若哭。吾歌亦已悲，老死终碌碌。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13806, 47, 525976, '585ff6a2128fe10069dddd06', '细雨', NULL, '陆游', '宋', '细雨重云渐入梅，阴阴门巷长新槐。壮心已与年俱逝，脱发应无术可栽。美睡常嫌莺唤起，清愁却要酒阑回。年来百事非平昔，信手题诗懒剪裁。', 'shi', 28, '雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (13807, 48, 11053, '57b9bb322e958a006932c07b', '小雨', NULL, '杨万里', '宋', '雨来细细复疏疏，纵不能多不肯无。', 'shi', 28, '雨', '', NULL, '', '', '', '');
