INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14138, 32, 643664, '5de769e65620710076adee32', '子革对灵王', NULL, '左丘明', '周', '楚子狩于州来，次于颍尾，使荡侯、潘子、司马督、嚣尹午、陵尹喜帅师围徐以惧吴。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
