INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14140, 34, 643666, '5de773ad43c25700686b2278', '吴许越成', NULL, '左丘明', '周', '吴王夫差败越于夫椒，报槜李也。', 'wen', 87, '古文观止', '', NULL, '', '', '', '');
