INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14143, 13, 103796, '585d25ee61ff4b00580e3a93', '南海使院对菊怀丁卯别墅', NULL, '许浑', '唐', '何处曾移菊，溪桥鹤岭东。篱疏还有艳，园小亦无丛。日晚秋烟里，星繁晓露中。影摇金涧水，香染玉潭风。罢酒惭陶令，题诗答谢公。朝来数花发，身在尉佗宫。', 'shi', 34, '菊', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14144, 32, 633995, '5895bec42f301e00694b4537', '荔枝图序', NULL, '白居易', '唐', '荔枝生巴峡间，树形团团如帷盖。', 'wen', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14145, 33, 231474, '585dc206128fe1006de95c4e', '荔支', NULL, '梁以壮', '明', '海角南风五月微，荔支沿岸夹村扉。清含碧玉圆珠体，内著红绡外赤衣。味似蜜深招鸟啄，气兼兰静逐蝉飞。从来百果皆臣妾，龙眼为奴信不非。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14146, 34, 171941, '585d76588d6d810065df8759', '谢生荔次友人', NULL, '邵宝', '明', '有客传闽荔，怀君我更携。时和成地胜，物论待人齐。蜜荐连龙眼，尘封谢马蹄。因思南极贡，航海复山梯。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14147, 35, 630126, '5860fd7a128fe10069e32dfb', '荔支叹', NULL, '苏轼', '宋', '十里一置飞尘灰，五里一堠兵火催。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14148, 36, 634893, '58e78e01a0bb9f006913eadf', '荔枝赋', NULL, '张九龄', '唐', '南海郡出荔枝焉，每至季夏，其实乃熟，状甚环诡，味特甘滋，百果之中，无一可比。', 'wen', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14149, 37, 42632, '585ce825ac502e006720ec7f', '广州杂咏和刘主事子高', NULL, '徐贲', '元', '绕门龙眼树森然，香蜡时来海外船。木屧蒲葵已成俗，红蕉丹荔不论钱。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14150, 38, 557002, '58603aa061ff4b006ce4cd66', '五羊食荔枝龙眼', NULL, '曾丰', '宋', '素闻岭南风，今假岭南馆。穷秋馀夏蒸，初腊借春暖。披衣汗流衣，握简汗流简。似登头痛山，而坐身热坂。谁其善解纷，荔枝杂龙眼。满盘随情堆，入手信意拣。强餐饱为期，一澡得三浣。疑吞玄冰丸，复咽飞雪散。猗欤两清姿，南多北何罕。天曾无全功，地固有偏产。犹记初客闽，厌饫腹频坦。一离馀十年，口与南味断。渴者易为饮，志得而意满。儿辈舌太饶，平章味长短。', 'shi', 155, '荔枝', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14151, 28, 528748, '585ffd7b1b69e6005621cff3', '醉归二首', NULL, '陆游', '宋', '乌桕阴中把酒杯，山园处处熟杨梅。', 'shi', 156, '杨梅', '', NULL, '', '', '', '');
