INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14158, 19, 642554, '5cd8d12d30863b00705a7147', '孟子 · 第二卷 · 梁惠王下 · 第四节', NULL, '孟子', '周', '齐宣王见孟子于雪宫。', 'wen', 365, '敬民篇', '', NULL, '', '', '', '');
