INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14186, 31, 598891, '5860a252128fe1006dfa4af4', '菱角', NULL, '刘挚', '宋', '洪池富水物，擘波收紫菱。春华杂青黄，夏蔓相牵仍。迨彼风露足，芒角秋实登。刚铦事利觜，扶挟如有朋。双锋尚可嘬，四出尤足憎。昌歜固有嗜，蒺莉非所凭。外观乏婉软，中质韬玉冰。取物取诸内，惟彼识者能。', 'shi', 166, '菱角', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14187, 42, 643627, '5de29f38562071007685ec3b', '吴江垂虹亭作', NULL, '米芾', '宋', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14188, 5, 135549, '585d4dad128fe1006de7f47c', '冬至', NULL, '王守仁', '明', '客床无寐听潜雷，珍重初阳夜半回。', 'shi', 70, '冬至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14189, 6, 626911, '5860f37c8d6d810065f39f87', '冬至日作', NULL, '苏辙', '宋', '羲和飞辔留不住，小儿逢节喜欲舞。', 'shi', 70, '冬至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14190, 12, 635499, '5a0113b4ee920a00460fd394', '立冬', NULL, '王稚登', '明', '秋风吹尽旧庭柯，黄叶丹枫客里过。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14191, 3, 260738, '585deb64128fe1006ba61c2c', '小寒节有感', NULL, '黄佐', '明', '雨霁风恬始见花，野梅含笑正横斜。', 'shi', 71, '小寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14230, 7, 244810, '585dd42d61ff4b0058115a66', '至日偶然走笔', NULL, '许宗鲁', '明', '去年冬至尧母城，城头较射角弓鸣。', 'shi', 70, '冬至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14291, 13, 237833, '585dcaba61ff4b0068932c2e', '山居大寒雪', NULL, '张嗣纲', '明', '山居逢岁腊，衣薄觉严寒。折竹声催听，飞禽影断看。僮仆痴环户，牛羊懒出栏。最疑天气极，指日转春官。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14292, 14, 509994, '585fd1e661ff4b006ce3338a', '游慈云', NULL, '陈著', '宋', '老怀不与世情便，才说闲行兴翼然。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14293, 15, 177415, '585d7d40128fe1006de89ae2', '大寒', NULL, '屈大均', '清', '穷阴天外积，寒绝逼春来。尚苦连朝雾，南风湿不开。已新长至柳，重吐小年梅。腊酒谁家早，莺知为我催。', 'shi', 72, '大寒', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14294, 12, 486628, '585f993d128fe1006df50579', '迎新春', NULL, '柳永', '宋', '嶰管变青律，帝里阳和新布。', 'ci', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14295, 33, 579702, '58606febac502e006735360b', '岁除', NULL, '虞俦', '宋', '除日催人不奈频，那堪月小不圆旬。谁能椒颂花如锦，自写桃符笔有神。通夕留连分岁客，明朝多少贺年人。寿觞举处慈颜喜，却是萱堂剩得春。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14296, 34, 634070, '589f1ca15c497d00563196de', '辛丑除日寄子瞻', NULL, '苏辙', '宋', '一岁不复居，一日安足惜。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14297, 35, 262158, '585ded69128fe1006ba62b44', '除日言怀一首', NULL, '黄省曾', '明', '大地已春转，今朝岁为除。绿酒樽屡空，清霜镜何馀。自隐吴宫前，十载芳萝居。节抱齐鲁连，辞探楚三闾。千金赋不买，当垆困相如。囊无一文钱，徒诵万卷书。萧条扬雄宅，颇有问字车。昨解学士雁，今剖英王鱼。四海雄豪人，投札问草芦。凤览不可缚，鸿情讵能羁。九州一何隘，丈夫气安舒。叹息成烟虹，浩荡横高虚。时著白纶巾，远驾蓝田舆。明月来青山，流辉特欢予。手持七斗剑，身披紫霞裾。人生不得意，去去渭川渔。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14298, 36, 268730, '585df757b123db0065ac262e', '小除日大雨雪', NULL, '邓云霄', '明', '谁散天花乱打窗，高斋风味宛禅房。问君诗骨清如许，扫雪烹茶坐竹床。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14299, 37, 140307, '585d52ea570c35006933b511', '岁除日即事', NULL, '王彦泓', '明', '浮尘扰扰一身闲，独看城南雪后山。却笑孤鸿也辛苦，晓云飞出暮云还。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14300, 38, 63752, '585cfb2f128fe1006de54c21', '除日试笔', NULL, '刘鹗', '元', '桃红酣雨更精神，久客俄惊节序新。好是一年将尽夜，喜看万物又回春。元正纪朔还逢甲，榖日祈丰复得辛。泰运昭回消劫运，峤南同作太平民。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14301, 39, 625878, '5860ef581b69e6006ce13e6e', '除日', NULL, '苏辙', '宋', '年年最后饮屠酥，不觉年来七十馀。十二春秋新罢讲，五千道德适亲书。木经霜雪根无蠹，船出风波载本虚。自怪多年客箕颍，每因吾党赋归欤。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14302, 40, 95845, '585d1bda128fe1006de65115', '除日', NULL, '韦应物', '唐', '思怀耿如昨，季月已云暮。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14303, 41, 439070, '585f2529b123db0065b3073a', '除日', NULL, '朱淑真', '宋', '爆竹声中腊已残，酴酥酒暖烛花寒。朦胧晓色笼春色，便觉春光不一般。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14304, 42, 313609, '585e3ea5570c350069389dc9', '除夜', NULL, '方岳', '宋', '年华三百六十日，尘劳八万四千门。高眠茅屋人亦老，相对梅花灯欲昏。静中颇窥造物意，极处是为天地根。生菜春盘一杯酒，明朝花柳又村村。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14305, 43, 203829, '585d9d79128fe10069cf0195', '除夜', NULL, '孙蕡', '明', '大地白雪似白沙，游子况复未归家。寒云黯淡暗海曲，春风浩荡来天涯。楚山卢橘渐舒叶，故园枇杷应着花。未得乘船出江口，枯坐旅邸如春蛙。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14306, 44, 438928, '585f24e361ff4b0063fc89fa', '除夜', NULL, '朱淑真', '宋', '穷冬欲去尚徘徊，独坐频斟守岁杯。一夜腊寒随漏尽，十分春色破朝来。桃符自写新翻句，玉律谁吹定等灰。且是作诗人未老，换年添岁莫相催。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14307, 45, 296626, '585e226dac502e0067286986', '除夕', NULL, '苏葵', '明', '坐看童子放花筒，又是乾坤一岁终。缓酌壶觞延夜雨，大开门户领春风。百年分在忘他老，四品官清送甚穷。闲染彩毫题短咏，烛花光射砚池红。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14308, 46, 290172, '585e187261ff4b006cd86f85', '元日新春试笔', NULL, '蓝智', '明', '西山积雪未全消，又送东风上柳条。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14309, 47, 161985, '585d6a61b123db0065a9c774', '元日', NULL, '沈周', '明', '今日之日一年始，三百六十年之终。云物昭回天杲杲，风光澹荡气融融。商量柳色绿少许，烂漫梅花白大同。无事此杯椒柏酒，老夫不觉笑颜红。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14310, 13, 634067, '589f0f702f301e00694676a0', '元夕于通衢建灯夜升南楼', NULL, '杨广', '隋', '法轮天上转，梵声天上来。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14311, 6, 579930, '58607097128fe10069df34a8', '立春', NULL, '虞俦', '宋', '彩胜华灯共一回，新年乐事并相催。天公预借今宵景，更放团圆好月来。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14312, 7, 35015, '585cdf0561ff4b00688df58e', '立春', NULL, '周权', '元', '宴罢春盘转晓风，乾坤生意浩无穷。宿云新卷山前雨，元气淋漓万木中。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14313, 8, 423901, '585f03038d6d810065e80932', '立春', NULL, '戴梓', '清', '腊尽春回际此辰，异乡烟景又重新。山承暖日将舒柳，面拂寒风尚畏人。凤历争看新节序，龙钟愧说老精神。相思南国今宵梦，策杖西溪路不真。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14314, 9, 429125, '585f0d7a570c3500693ccd76', '立春', NULL, '胤禛', '清', '晴光当户映，淑气逐人来。冻草苏先觉，枯条暖自催。荐新红菜甲，应候绿英梅。为问迎春吏，农畴几处开？', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14315, 10, 500469, '585fbb9f61ff4b00689f94dc', '立春', NULL, '晁公溯', '宋', '我来伫立望晴空，目极苍茫万壑中。树色昏昏酣霁雾，江纹细细织柔风。一行殊俗犹为吏，三揖今年拟送穷。闻道东田耕帝藉，惭无赋奏大明宫。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14316, 11, 575948, '58606692128fe1006df8dfdc', '立春', NULL, '黄庭坚', '宋', '韭苗香煮饼，野老不知春。看镜道如咫，倚楼梅照人。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14317, 12, 545003, '5860203761ff4b006302ef21', '立春', NULL, '曹勋', '宋', '初信东风入彩幡，自挑雪荠饤春盘。土牛又送一年老，野鹤不知三径寒。筋力尚堪耕绿野，鬓毛并欲挂黄冠。无人共跨南山犊，更作寻花问柳看。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14318, 13, 542570, '58601ad1128fe10069de51e8', '立春', NULL, '强至', '宋', '鱼寻细脉上轻澌，鸟趁微和哢好枝。多病强倾春日酒，苦吟还接暮冬诗。江南信息梅应蕊，京国风流柳未丝。最有佳人随节序，钗头彩胜竞垂垂。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14319, 14, 15910, '585cc67061ff4b00688d490a', '立春', NULL, '仇远', '元', '山城历日到每迟，新春残腊俱不知。若非一鞭醒寒梦，梅柳争春无了时。牛刀小试东风手，目中全牛果何有。勾芒舁归古庙中，官吏升堂酌春酒。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14320, 15, 579932, '586070991b69e60056230711', '立春', NULL, '虞俦', '宋', '腊雪初消柳眼寒，春风才入酒杯宽。一年佳节知多少，屈指从今是履端。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14321, 16, 512771, '585fd8b2128fe1006df6f8ad', '立春', NULL, '郭印', '宋', '颇恨东风巧入帘，不论朱户与茅檐。青春处处为谁好，白发年年空自嫌。市酒岂能供燕笑，官娃无复问秾纤。强随儿辈追时节，菜压香盘未损廉。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14322, 17, 456728, '585f5a801b69e6006cd7e709', '立春', NULL, '宋祁', '宋', '春晓灵旗画尾斜，汉官青帻待晨霞。宫中彩树纷无算，不待东风已作花。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14323, 18, 313671, '585e3ec2ac502e0067294124', '立春', NULL, '方岳', '宋', '诗傥穷人莫送穷，但穷诗亦不须工。银幡雪柳人何似，翠缕琼丝菜则同。百事到头惟早白，一年弹指又春红。渔溪亦喜溪冰泮，新绿生肥撼钓筒。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14324, 19, 259436, '585de94e61ff4b005811f62a', '立春', NULL, '黄公辅', '明', '令转三阳雪势降，烟花明媚卷旌幢。凭将弱柳舒青眼，度却和风到碧窗。游踏香尘人两两，鸣流清韵鸟双双。乡心忽觉随花发，谩把辛盘载酒缸。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14325, 20, 304864, '585e2fc3570c3500693826bc', '立春', NULL, '释函可', '明', '清晓开门泪已披，梅花一别永无期。寒冰到死为朋友，便是春来也不知。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14326, 21, 375092, '585eac1c8d6d810065e73be0', '立春', NULL, '书山', '清', '阳和回驭岁更新，人物雍熙岛屿春。澥谷条风吹彩仗，青郊小雨浥纤尘。梅花竹叶闲中味，柑酒辛盘客底身。不效东坡戴幡胜，肯教辜负度良辰。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14327, 22, 352359, '585e844aac502e00672b6ffd', '踏莎行 · 立春', NULL, '李雯', '清', '芳草回心，平沙转翠。', 'ci', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14328, 23, 427739, '585f0a3461ff4b006cddaada', '蟾宫曲 · 立春', NULL, '顾太清', '清', '畅晴和、好是今朝。', 'ci', 47, '立春', '', NULL, '', '', '', '');
