INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14334, 19, 101425, '585d22da61ff4b0063f16f74', '上元夜六首', NULL, '崔液', '唐', '公子王孙意气骄，不论相识也相邀。最怜长袖风前弱，更赏新弦暗里调。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14335, 20, 101426, '585d22da128fe1006de69018', '上元夜六首', NULL, '崔液', '唐', '星移汉转月将微，露洒烟飘灯渐稀。犹惜路傍歌舞处，踌蹰相顾不能归。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14336, 21, 610342, '5860c094128fe1006bb6af65', '御带花', NULL, '欧阳修', '宋', '青春何处风光好，帝里偏爱元夕。', 'ci', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14337, 22, 170458, '585d74bb61ff4b0063f36b65', '元夕', NULL, '贝琼', '明', '夜醉城南酒百缸，春来端使客愁降。障开云母东西一，灯射琉璃日月双。铁笛仙人传丽藻，金钗小妾度新腔。归来误作三山梦，月色如冰白满江。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14338, 48, 641129, '5c57916117b54d00576f21cb', '共内人夜坐守岁', NULL, '徐君倩', '南北朝', '欢多情未极，赏至莫停杯。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14339, 24, 83814, '585d0ee88d6d810065dcd7fc', '立春', NULL, '杜甫', '唐', '春日春盘细生菜，忽忆两京梅发时。盘出高门行白玉，菜传纤手送青丝。巫峡寒江那对眼，杜陵远客不胜悲。此身未知归定处，呼儿觅纸一题诗。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14340, 49, 11934, '58078248da2f60004f00afd2', '元日述怀', NULL, '卢照邻', '唐', '筮仕无中秩，归耕有外臣。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14341, 50, 588382, '586087c1128fe10069dfbc1b', '满庭芳 · 元日', NULL, '赵长卿', '宋', '爆竹声飞，屠苏香钿，华堂歌舞催春。', 'ci', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14342, 25, 524594, '585ff32661ff4b00630268c9', '立春日送客郊外', NULL, '陆游', '宋', '短鬓那禁岁月催，胜边花底又春回。雪消渐暖青鸳日，冰解初横玉鉴梅。江驿轩窗临古道，市楼弦管卖新醅。自怜病守无欢意，一笑常因送客来。', 'shi', 47, '立春', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14343, 23, 225508, '585db9b9128fe10069cf592a', '元夕漫兴', NULL, '区元晋', '明', '水郭山楼淑气匀，东风随处咽桃唇。千灯分彩凝坤轴，万象涵光拱极辰。笑语再逢熙穆世，讴歌齐效舜尧人。回思宋室鳌峰乐，翠管青娥未算春。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14344, 24, 239333, '585dccb3128fe1006de99a25', '元夕灯宴', NULL, '张元凯', '明', '公子留宾锦作筵，却怜欢赏动韶年。琼枝照夜无双艳，璧月临春第一圆。幕里仙姝怜紫玉，座中词客重青莲。醉归不问金吾禁，鱼钥天明恰已传。', 'shi', 17, '元宵', '', NULL, '', '', '', '');
