INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14354, 26, 134764, '585d4cf38d6d810065deebfc', '初夏遣兴', NULL, '文徵明', '明', '雨浥浮埃绿满庭，晚花初试水冬青。小窗团扇春寒尽，竹榻茶杯午困醒。惭愧饥年还饱食，蹉跎贫业尚残经。燕闲自觉难消受，赖得经时病未宁。', 'shi', 25, '夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14355, 27, 364509, '585e9a6eac502e00672c1514', '初夏', NULL, '金逸', '清', '绣帘风影警花铃，庄蝶才分梦亦醒。一缕茶烟人不到，绿阴如水漾空庭。', 'shi', 25, '夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14356, 28, 576235, '5860672b1b69e6005622d9e3', '鄂州南楼书事 · 其一', NULL, '黄庭坚', '宋', '四顾山光接水光，凭栏十里芰荷香。', 'shi', 25, '夏', '', NULL, '', '', '', '');
