INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14383, 13, 165665, '585d6ebc61ff4b0063f35bd9', '十四日立冬雨夜过宿黄茂才君甫书馆', NULL, '李英', '明', '一夜初冬雨，萧萧枕上鸣。故人同大被，信宿见高情。蝴蝶三更梦，烟霞百岁盟。天明桡钓艇，别向海门行。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14384, 14, 523250, '585fefbc61ff4b00581f1077', '雪中二首', NULL, '陆游', '宋', '春昼雪如筛，清羸病起时。迹深惊虎过，烟绝闵僧饥。地冻萱芽短，林寒鸟哢迟。西窗斜日晚，呵手敛残棋。', 'shi', 67, '立冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14385, 21, 10399, '57ac9baf165abd0054097f12', '江城梅花引 · 荆溪阻雪', NULL, '蒋捷', '宋', '白鸥问我泊孤舟，是身留，是心留？', 'ci', 35, '雪', '', NULL, '', '', '', '');
