INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14387, 8, 640865, '5c1d94d3fb4ffe005f276bcf', '冬至', NULL, '龙辅', '明', '冬至宵难短，孤眠恨自长。', 'shi', 70, '冬至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14388, 23, 18572, '585cca2461ff4b00580b4ac1', '二月朔大雪已五日三首', NULL, '方回', '元', '燕山雪花大如席，岂料江南亦见之。腊前六出知焉往，却在春风二月时。', 'shi', 35, '雪', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14389, 22, 634023, '589c4881b123db16a3c29fcc', '南乡子 · 冬夜', NULL, '黄昇', '宋', '万籁寂无声，衾铁稜稜近五更。', 'ci', 27, '冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14390, 52, 260527, '585deb07da2f600065888ed3', '丁亥除夕', NULL, '黄佐', '明', '旅馆频年过岁除，莱衣今夕乐何如。摇摇蜡炬轻风里，浅浅霞杯细雨馀。江海只便鱼入馔，烟霞惟恐鹤传书。等闲又被梅花恼，漏泄春光满敝庐。', 'shi', 16, '春节', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14391, 23, 615733, '5860cdbc128fe10069e1a73a', '初冬梅花偷放颇多', NULL, '戴炳', '宋', '清樽才了黄花债，又被梅花恼杀人。碎点南枝无数雪，探支东帝几分春。精神全向疏中足，标格端于瘦处真。彻夜苦吟无好语，梦随双月步溪漘。', 'shi', 27, '冬', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (14392, 53, 228332, '585dbdb7b123db0065aaa44e', '后乐堂家宴守岁', NULL, '陆深', '明', '歌管声喧饯岁除，大江东下抱闲居。夜筵椒酒元随量，春帖桃符手自书。老去何妨髫鹤发，归来犹及馔鲈鱼。十年万里风和雨，此夕团圞画不如。', 'shi', 16, '春节', '', NULL, '', '', '', '');
