INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15046, 9, 215724, '585dac7a128fe1006de90153', '正月二日雨雹', NULL, '陈献章', '明', '雨水不雨水，雨雹胡乃然。小者如莲实，大者如弹丸。仍闻隔江言，有雹大如拳。吾君古帝尧，神功格皇天。雹往而霰来，无乃为丰年。', 'shi', 48, '雨水', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15047, 10, 132346, '585d4a3fac502e0067241ddb', '弘治十六年十二月二十五日午大雪二十九日寅止正月三日晚又雪至十六日或雪或止惟十五日尤异其雪花大者约广二三寸长亦如之见者莫不惊骇余时奉命在镇是日雨水节寒如冬至沿河冻合舟不能行屋檐积雪弥月不消不知天道竟何如', NULL, '王缜', '明', '我生三十九，半在燕京走。不见京师冬，有此雨雪久。而况润之地，江南京之口。正直三阳春，大寒如数九。黄云四塞迷，雪花大于手。楼阁耸冰山，檐溜缀琼玖。路绝鸟不飞，河合车可守。弥月势不休，占岁宁复有。悠悠者苍天，不知有意否。', 'shi', 48, '雨水', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15049, 15, 643757, '5e4bb0d57796d9006abfd280', '生于忧患，死于安乐', NULL, '孟子', '周', '舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。', 'wen', 128, '初二上册', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15051, 11, 375585, '585ead001b69e600561a39ac', '浣溪沙', NULL, '纳兰性德', '清', '身向云山那畔行，北风吹断马嘶声，深秋远塞若为情！', 'ci', 132, '初三下册', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15082, 10, 643761, '5e4bbff5fc36ed006acd649d', '苏武传（节选）', NULL, '班固', '汉', '武，字子卿。', 'wen', 136, '高二下册', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15085, 4, 640908, '5c25f1731579a3005f3989bc', '前赤壁赋', NULL, '苏轼', '宋', '壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15086, 1, 641181, '5c5ff63ea91c930054dbd230', '劝学', NULL, '荀子', '周', '君子曰：学不可以已。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15087, 10, 643649, '5de5cc6b21b47e006ca81d01', '烛之武退秦师', NULL, '左丘明', '周', '晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15089, 56, 11361, '57b343d0c4c971005496cee4', '游褒禅山记', NULL, '王安石', '宋', '褒禅山亦谓之华山，唐浮图慧褒始舍于其址，而卒葬之；', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15090, 52, 643758, '5e4bb6fc21b47e006b0df132', '荆轲刺秦王', NULL, '刘向', '汉', '秦将王翦破赵，虏赵王，尽收其地，进兵北略地，至燕南界。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15091, 53, 643760, '5e4bbef47796d9006ac062c3', '廉颇蔺相如列传', NULL, '司马迁', '汉', '廉颇者，赵之良将也。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15092, 39, 11731, '57c5ee722e958a00698ddf84', '祭十二郎文', NULL, '韩愈', '唐', '年、月、日，季父愈闻汝丧之七日，乃能衔哀致诚，使建中远具时羞之奠，告汝十二郎之灵：INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15093, 54, 636722, '5ab862e5a22b9d0045f8a8f6', '论语 · 季氏篇', NULL, '孔子', '周', '季氏将伐颛臾，冉有、季路见于孔子，曰：「季氏将有事于颛臾。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15094, 55, 11878, '57ffc70c8ac2470058e10b4d', '山中与裴秀才迪书', NULL, '王维', '唐', '近腊月下，景气和畅，故山殊可过。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15096, 57, 10197, '57b972dd165abd0054c3ef2b', '永州八记 · 其一 · 始得西山宴游记', NULL, '柳宗元', '唐', '自余为僇人，居是州，恒惴慄。', 'wen', 93, '高中文言文', '', NULL, '', '', '', '');
