INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15145, 19, 615474, '5860cd30da2f600065998324', '兰', NULL, '钱时', '宋', '绕亭埋石种兰芽，生怕花开不在家。此日溶溶春满院，柔风初破一枝花。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15146, 20, 398032, '585ed381128fe1006df0b75b', '兰', NULL, '章甫', '清', '幽人雅佩美人魂，韵致天然谢俗喧。清露滴来微有息，好风吟去了无痕。与居善室浑双美，独占王香第一尊。相赏弹琴心并素，知音此外为谁言。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15147, 1, 11276, '57b6ad718ac2470062d0fb44', '琴操十首·猗兰操', NULL, '韩愈', '唐', '兰之猗猗，扬扬其香。', 'shi', 414, '兰', '', NULL, '', '', '', '');
