INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15149, 3, 634268, '58b27dcc1b69e60058ae540b', '秋兰赋', NULL, '袁枚', '清', '秋林空兮百草逝，若有香兮林中至。', 'fu', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15150, 4, 637658, '5af55901fb4ffed775a13eda', '幽兰赋', NULL, '韩伯庸', '唐', '阳和布气兮，动植齐光；', 'fu', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15151, 9, 11040, '57b954ea7db2a20054298729', '花', NULL, '张羽', '明', '能白更兼黄，无人亦自芳。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15152, 21, 309017, '585e3713570c350069385f0b', '兰', NULL, '顾璘', '明', '幽兰两三花，清香暗中起。日暮望美人，盈盈隔湘水。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15153, 22, 438172, '585f226d61ff4b00689b4a23', '兰', NULL, '朱熹', '宋', '谩种秋兰四五茎，疏帘底事太关情。可能不作凉风计，护得幽香到晚清。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15154, 18, 179192, '585d7fa661ff4b0068923be3', '兰', NULL, '屈大均', '清', '花香不出林，谁识蕙兰心。幸得微风起，吹来满素襟。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15155, 8, 11814, '580775df67f3560058dd5866', '感遇（其二）', NULL, '陈子昂', '唐', '兰若生春夏，芊蔚何青青。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15156, 16, 530219, '586001021b69e6006cdc8fd9', '兰', NULL, '陆游', '宋', '南岩路最近，饭已时散策。香来知有兰，遽求乃弗获。生世本幽谷，岂愿为世娱。无心托阶庭，当门任君锄。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15157, 23, 502948, '585fc18961ff4b006ce2a653', '兰', NULL, '徐集孙', '宋', '淡淡九畹质，雅好住山林。幽香不求知，伯夷叔齐心。世道不复古，纫佩取骚吟。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15158, 17, 413036, '585eee51128fe1006bac8705', '兰', NULL, '郑燮', '清', '此是幽贞一种花，不求闻达只烟霞。采樵或恐通来径，更写高山一片遮。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15159, 1, 633577, '583d9634128fe1006bf4b094', '青松', NULL, '陈毅', '当代', '大雪压青松，青松挺且直。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15160, 17, 204000, '585d9db98d6d810065dfd487', '松', NULL, '孙蕡', '明', '双松如盖倚云长，曾忆匡山问草堂。拂石坐来龙影湿，半陂春雨茯苓香。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15161, 2, 634277, '58b2ba755c497d00678b1b6c', '寒松赋', NULL, '李绅', '唐', '松之生也，于岩之侧。', 'fu', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15162, 3, 634283, '58b2be4c8fd9c50063dba2a9', '涧底寒松赋', NULL, '王勃', '唐', '惟松之植，于涧之幽。', 'fu', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15163, 11, 635117, '5948e5ef8d6d81cc72feda63', '殿前欢 · 观音山眠松', NULL, '徐再思', '元', '老苍龙，避乖高卧此山中。', 'qu', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15164, 12, 33108, '585cdcca1b69e6006cc918ae', '风入松 · 壁间画松', NULL, '沈禧', '元', '白云堆里奋苍虬。', 'ci', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15165, 5, 94456, '585d1a36570c35006931e0c0', '松', NULL, '修睦', '唐', '细韵飕飕入骨凉，影兼巢鹤过高墙。盘根一种依平地，自是梧桐不久长。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15166, 7, 112939, '585d332761ff4b006cd3b2cf', '松', NULL, '卢士衡', '唐', '云外千寻好性灵，伴杉陪柏事孤贞。招呼暑气终无分，应和凉风别有声。细雨洒时花旋落，道人食处叶重生。如逢郢匠垂搜采，为栋为梁力不轻。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15167, 21, 187986, '585d89e51b69e6005612a84d', '松', NULL, '胡居仁', '明', '一夜风霜万木枯，岁寒惟见老松孤。秦皇不识清高操，强欲烦君作大夫。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15168, 16, 446815, '585f3be861ff4b0063fd2e06', '松', NULL, '吕陶', '宋', '游人何事种芳菲，试把庭松较盛衰。得地不将天质改，有心惟与岁寒期。一轩野色栽培后，十月霜华秀茂时。造化果能周及物，亦须千丈引乔枝。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15169, 6, 634878, '58e7884944d904006d3c0f0d', '养兰说', NULL, '陶望龄', '明', '会稽多兰，而闽产者贵。', 'wen', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15170, 7, 634637, '58ca7d825c497d0057b16157', '书幽芳亭记', NULL, '黄庭坚', '宋', '士之才德盖一国，则曰国士；', 'wen', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15171, 3, 638253, '5b3ee2332f301e00341d7c23', '幽兰赋', NULL, '颜师古', '隋', '惟奇卉之灵德，禀国香于自然。', 'wen', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15172, 12, 225887, '585dba34da2f600065874cc6', '蕙兰芳引 · 兰', NULL, '高濂', '明', '绮石幽香，自一种、天然标格。', 'ci', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15173, 11, 355185, '585e895b61ff4b006cdbdc9f', '澡兰 · 香兰', NULL, '汪东', '当代', '纤翘弄羽，巧箭舒心，不掩澹姿秀躅。', 'ci', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15174, 10, 643320, '5d6beefbc05a8000733f93b4', '幽兰', NULL, '陈毅', '当代', '幽兰在山谷，本自无人识。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15175, 24, 235028, '585dc6e6b123db0065aad379', '题幽兰', NULL, '曹义', '明', '露叶含曦迥绝尘，花开岩壑殿芳春。书窗读罢清吟处，爱尔幽香自可人。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15176, 14, 626170, '5860f06d61ff4b00582417c3', '幽兰花', NULL, '苏辙', '宋', '珍重幽兰开一枝，清香耿耿听犹疑。定应欲较香高下，故取群芳竞发时。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15177, 15, 21516, '585ccdf2128fe10069ca0519', '幽兰咏', NULL, '王冕', '元', '光风吹香洗游尘，兰花隐芳莸笑人。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15178, 13, 626169, '5860f06d128fe1006dfca944', '幽兰花', NULL, '苏辙', '宋', '李径桃蹊次第开，秾香百和袭人来。春风欲擅秋风巧，催出幽兰继落梅。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15179, 25, 641786, '5ca59765c05a8000738c74d5', '兰花', NULL, '刘基', '明', '幽兰花，在空山，美人爱之不可见，裂素写之明窗间。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15180, 26, 279603, '585e089bda2f600065897ef5', '题墨兰', NULL, '刘崧', '明', '何日春风来，幽兰绿如剪。细雨山气凉，秋香入苔藓。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15181, 4, 86453, '585d11adda2f600065840e49', '小松', NULL, '杜荀鹤', '唐', '自小刺头深草里，而今渐觉出蓬蒿。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15182, 8, 76477, '585d071d61ff4b0063f081ba', '小松', NULL, '王建', '唐', '小松初数尺，未有直生枝。闲即傍边立，看多长却迟。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15183, 10, 104576, '585d26f81b69e6005610a05d', '小松', NULL, '章孝标', '唐', '爪叶鳞条龙不盘，梳风幕翠一庭寒。莫言只是人长短，须作浮云向上看。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15184, 9, 104580, '585d26fa1b69e6005610a069', '僧院小松', NULL, '章孝标', '唐', '抛杉背柏冷僧帘，锁月梳风出殿檐。还似天台新雨后，小峰云外碧尖尖。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15185, 15, 483397, '585f92381b69e600561eca66', '种松吟', NULL, '金朋说', '宋', '人皆爱桃李，我爱种青松。桃李易凋谢，青松却耐寒。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15186, 20, 308979, '585e37018d6d810065e3c980', '咏扇画寄诸故人八首咏松寄乔白岩光禄', NULL, '顾璘', '明', '青松高千尺，知是何年栽。独有憩阴者，时为清风来。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15187, 18, 210608, '585da5ca8d6d810065dfe76e', '孤松', NULL, '郭之奇', '明', '孤松拔秀出幽山，色可餐人气莫攀。只许云霞依翠盖，不随风雨落苍颜。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15188, 23, 350704, '585e810361ff4b00581695c2', '孤松', NULL, '李景祥', '清', '向阳花木并含滋，蟠郁空留岁暮姿。小草托根欣得所，风霜独受有谁知。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15189, 13, 60779, '585cf899da2f600065834ac8', '渊明抚松图', NULL, '杨维桢', '元', '孤松手自植，保此贞且固。微微岁寒心，孰乐我迟暮。留侯报韩仇，还寻赤松去。后生同一心，成败顾随遇。归来抚孤松，犹是晋时树。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15190, 19, 207063, '585da1421b69e6005612d776', '幽兴', NULL, '袁登道', '明', '皎日丽春华，繁霜泣秋草。谁知寒松树，独向云中老。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15191, 22, 388707, '585ec3341b69e600561a85c3', '种松谣', NULL, '张晋', '清', '我不愿种桃李花，春风已老空咨嗟。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15192, 14, 629682, '5860fbf461ff4b006ce95b12', '戏作种松', NULL, '苏轼', '宋', '我昔少年日，种松满东冈。初移一寸根，琐细如插秧。二年黄茅下，一一攒麦芒。三年出蓬艾，满山散牛羊。不见十馀年，想作龙蛇长。夜风波浪碎，朝露珠玑香。我欲食其膏，已伐百本桑。人事多乖迕，神药竟渺茫。朅来齐安野，夹路须髯苍。会开龟蛇窟，不惜斤斧疮。纵未得茯苓，且当拾流肪。釜盎百出入，皎然散飞霜。槁死三彭仇，澡换五谷肠。青骨凝绿髓，丹田发幽光。白发何足道，要使双瞳方。却后五百年，骑鹤还故乡。', 'shi', 415, '松', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15193, 6, 80352, '585d0b46ac502e0067220212', '栽松二首', NULL, '白居易', '唐', '【其一】INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15194, 21, 615733, '5860cdbc128fe10069e1a73a', '初冬梅花偷放颇多', NULL, '戴炳', '宋', '清樽才了黄花债，又被梅花恼杀人。碎点南枝无数雪，探支东帝几分春。精神全向疏中足，标格端于瘦处真。彻夜苦吟无好语，梦随双月步溪漘。', 'shi', 29, '梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15195, 22, 427679, '585f0a0e1b69e6006cd5e10e', '被花恼 · 题王石谷画友梅轩图', NULL, '顾太清', '清', '疏枝老干自斜横，开满冷花冰蕊。', 'ci', 29, '梅', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15196, 3, 359070, '585e90a2128fe1006def98b8', '梦横塘 · 辛未惊蛰，金陵书感', NULL, '周岸登', '清', '断云心远，丝雨梦轻，晚来飞电虚掣。', 'ci', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15197, 4, 73627, '585d045c128fe1006de59028', '咏廿四气诗 · 惊蛰二月节', NULL, '元稹', '唐', '阳气初惊蛰，韶光大地周。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15198, 5, 358902, '585e9048da2f6000658da0d1', '梦横塘 · 丁巳惊蛰日书感', NULL, '周岸登', '清', '病馀疏酒，梦里惊春，琐窗尘暗瑶瑟。', 'ci', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15199, 6, 480091, '585f8b221b69e6006cd95006', '惊蛰家人子辈为易疏帘', NULL, '范成大', '宋', '二分春色到穷阎，儿女祈翁出滞淹。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15200, 7, 15431, '585cc5e11b69e6006cc87151', '惊蛰日雷', NULL, '仇远', '元', '坤宫半夜一声雷，蛰户花房晓已开。野阔风高吹烛灭，电明雨急打窗来。顿然草木精神别，自是寒暄气候催。惟有石龟并木雁，守株不动任春回。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15201, 8, 542070, '586019d4b123db0065b9661a', '甲戌正月十四日书所见来日惊蛰节', NULL, '张元幹', '宋', '老去何堪节物催，放灯中夜忽奔雷。一声大震龙蛇起，蚯蚓虾蟆也出来。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15202, 9, 206640, '585da0bf570c350069348542', '癸丑正月风雨中偶成', NULL, '袁华', '明', '入春弥月雨霏微，惊蛰无雷雪又飞。抚节不愁花蕊晚，感时惟恐麦苗稀。当歌对酒愁难遣，问舍求田志己违。只尺相望不相见，空吟偪侧思依依。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15203, 10, 643519, '5db29353c05a800068f18fb3', '月令七十二候集解 · 惊蛰', NULL, '吴澄', '元', '惊蛰，二月节。', 'wen', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15204, 11, 626527, '5860f1b861ff4b006307645d', '游景仁东园', NULL, '苏辙', '宋', '新春甫惊蛰，草木犹未知。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15205, 12, 561433, '5860441061ff4b0063032d16', '有怀正仲还雁峰诗', NULL, '舒岳祥', '宋', '松声夜半如倾瀑，忆坐西斋共不眠。', 'shi', 49, '惊蛰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15206, 20, 441108, '585f2b5461ff4b00689b8299', '水调歌头 · 中秋', NULL, '米芾', '宋', '砧声送风急，蟠蟀思高秋。', 'ci', 21, '中秋', '', NULL, '', '', '', '');
