INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (15213, 13, 10999, '57b928855bbb50005b7976af', '城东早春', NULL, '杨巨源', '唐', '诗家清景在新春，绿柳才黄半未匀。', 'shi', 416, '柳', '', NULL, '', '', '', '');
