INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (16702, 90, 84400, '585d0f828d6d810065dcdd33', '望岳', NULL, '杜甫', '唐', '南岳配朱鸟，秩礼自百王。歘吸领地灵，鸿洞半炎方。邦家用祀典，在德非馨香。巡守何寂寥，有虞今则亡。洎吾隘世网，行迈越潇湘。渴日绝壁出，漾舟清光旁。祝融五峰尊，峰峰次低昴。紫盖独不朝，争长嶪相望。恭闻魏夫人，群仙夹翱翔。有时五峰气，散风如飞霜。牵迫限修途，未暇杖崇冈。归来觊命驾，沐浴休玉堂。三叹问府主，曷以赞我皇。牲璧忍衰俗，神其思降祥。', 'shi', 433, '初中鲁教版', '', NULL, '', '', '', '');
