INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (16758, 7, 74435, '585d051c570c35006931325f', '和乐天示杨琼', NULL, '元稹', '唐', '我在江陵少年日，知有杨琼初唤出。腰身瘦小歌圆紧，依约年应十六七。去年十月过苏州，琼来拜问郎不识。青衫玉貌何处去，安得红旗遮头白。我语杨琼琼莫语，汝虽笑我我笑汝。汝今无复小腰身，不似江陵时好女。杨琼为我歌送酒，尔忆江陵县中否。江陵王令骨为灰，车来嫁作尚书妇。卢戡及第严涧在，其馀死者十八九。我今贺尔亦自多，尔得老成余白首。', 'shi', 434, '初中语文版', '', NULL, '', '', '', '');
