INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (17301, 12, 597422, '58609ed7ac502e0067365277', '鸿门宴', NULL, '刘翰', '宋', '江东遥遥八千骑，大战小战七十二。刘郎晓鞭天马来，踧踏长安开帝里。子婴已降隆准公，君王置酒鸿门东。张良已去玉斗碎，三月火照咸阳红。绣衣归来日将夜，可惜雄心天不借。当时已失范增谋，尚引长戈到垓下。刁斗乍急营垒惊，夜深旗尾秋风横。玉帐佳人不成梦，月明四面闻歌声。拔剑相看泪如雨，我作楚歌君楚舞。明朝宝马一声嘶，江北江东皆汉土。', 'shi', 442, '高中语文版', '', NULL, '', '', '', '');
