INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18367, 5, 109156, '585d2db2128fe10069cd1c53', '苔钱', NULL, '郑谷', '唐', '春红秋紫绕池台，个个圆如济世财。雨后无端满穷巷，买花不得买愁来。', 'shi', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18368, 6, 37942, '585ce2a7570c350069301329', '咏苔', NULL, '耶律铸', '元', '露茵叠翠藉闲园，神篆斑斑世未传。推到东君翻古画，尽输春色买苔钱。', 'shi', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18369, 7, 600430, '5860a6af128fe1006bb5f1ee', '夏景雨过苔花润', NULL, '刘辰翁', '宋', '雨过残春远，晴天半入梅。草根馀落照，花润只深苔。山共朱帘卷，庭无蜡屐来。翠钱流地满，珠靥照人开。寂寂承残霤，青青绕废台。唾茸宫壁在，残月照馀哀。', 'shi', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18370, 8, 374990, '585eabf261ff4b0063fb127d', '琐窗寒 · 苔', NULL, '殷秉玑', '清', '几度春来，连番雨过，旧时庭宇。', 'ci', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18371, 9, 401860, '585eda4b128fe10069d6e3e7', '宴清都 · 咏苔', NULL, '董俞', '清', '个个如钱，丝丝似发，雨馀益增幽景。', 'ci', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18372, 10, 379418, '585eb38461ff4b006899f8b1', '临江仙 · 苔', NULL, '陶淑', '清', '满地蒙蒙铺未遍，望来非雾非烟。', 'ci', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18373, 11, 351667, '585e830c1b69e60056191d28', '齐天乐 · 秋苔', NULL, '杜贵墀', '清', '西风偷入无人径，重重小门深闭。', 'ci', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18374, 12, 242371, '585dd0f0128fe1006ba55d78', '醉落魄 · 咏苔', NULL, '张肯', '明', '径翠钿狼藉，绿圆点点浓如积。', 'ci', 452, '苔', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18375, 2, 87297, '585d1290128fe1006ba1a673', '骊山有感', NULL, '李商隐', '唐', '骊岫飞泉泛暖香，九龙呵护玉莲房。平明每幸长生殿，不从金舆惟寿王。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18376, 3, 10121, '57b8eaf28ac2470062df147d', '木兰词 · 拟古决绝词柬友', NULL, '纳兰性德', '清', '人生若只如初见，何事秋风悲画扇。', 'ci', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18377, 4, 39796, '585ce4c261ff4b00688e2b94', '寄梁王', NULL, '段宝', '元', '烽火狼烟信不符，骊山举戏是支梧。平章枉死红罗帐，员外虚题粉壁图。凤别岐山祥兆隐，麟游郊薮瑞光无。自从界限鸿沟后，成败兴衰不属吾。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18378, 5, 43314, '585ce90061ff4b00580c4028', '与李子构读开元天宝遗事', NULL, '陈孚', '元', '四十乾坤拱紫宸，东风只属倚阑人。玉凫波暖骊山晓，金犊烟横绣岭春。七夕有钗留羽客，千秋无镜泣孤臣。红尘一骑君休笑，中有渔阳万骑尘。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18380, 6, 112999, '585d3339128fe1006de724ad', '驾幸温泉', NULL, '卢象', '唐', '传闻圣主幸新丰，清跸鸣銮出禁中。细草终朝随步辇，垂杨几处绕行宫。千官扈从骊山北，万国来朝渭水东。此日小臣徒献赋，汉家谁复重扬雄。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18381, 7, 112514, '585d326c128fe1006de71d59', '奉和圣制登骊山高顶寓目应制', NULL, '刘宪', '唐', '骊阜镇皇都，銮游眺八区。原隰旌门里，风云扆座隅。直城如斗柄，官树似星榆。从臣词赋末，滥得上天衢。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18382, 8, 187893, '585d89d2128fe1006ba45992', '怀仙志', NULL, '胡平运', '明', '暮云淡荡暗东洲，一段柔香付水流。绣被梦残蝴蝶冷，玉箫声断凤凰愁。锦江送恨归巫峡，兰径迷芳逐虎丘。堪与骊山伤往事，几回烟月思悠悠。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18383, 9, 218304, '585dafdbac502e0067254d21', '登骊山有感', NULL, '陈琏', '明', '骊山矗霄汉，缭绕白云生。露径绿苔老，秋林红叶明。凭高肆遐瞩，山水互回萦。终南亘太华，浐灞通渭泾。三川何逶迤，千里犹掌平。秦中百万家，俯视犹列星。缅维天宝中，兹山擅佳名。复道岁游幸，栖阁高峥嵘。秋风起朝元，温泉出华清。如何乐未终，胡尘集咸京。一从西幸蜀，无复来霓旌。繁华竟何在，但见山青青。宴安古所戒，后世在当惩。我来重登览，触景感废兴。临文动悲诧，不尽千古情。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18384, 10, 263431, '585def4a128fe1006ba6393c', '上巳日浴温泉', NULL, '熊鼎', '明', '骊山宫殿锁温泉，天宝遗踪故宛然。绣谷春融丹井火，金波月满鉴池莲。玉颜承宠专恩泽，翠辇来游惜暮年。我亦逢时修禊事，白头空负丽人天。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18385, 11, 11862, '57ff7f01da2f60004fbe223c', '自京赴奉先县咏怀五百字', NULL, '杜甫', '唐', '杜陵有布衣，老大意转拙。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18386, 12, 19960, '585ccbe561ff4b0063eeafee', '钱塘春感六首', NULL, '王逢', '元', '日华初动衮衣明，剑佩千官隐绣楹。五色黼函开玉座，九重汤药下银罂。书题凤尾仙曹喜，恩浃螭坳学士荣。文化有馀戎事略，铜驼草露不胜情。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18387, 13, 75747, '585d06708d6d810065dc949a', '惆怅诗十二首', NULL, '王涣', '唐', '七夕琼筵随事陈，兼花连蒂共伤神。蜀王殿里三更月，不见骊山私语人。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18388, 14, 80275, '585d0b2f61ff4b00688f5a43', '权摄昭应早秋书事寄元拾遗兼呈李司录', NULL, '白居易', '唐', '夏闰秋候早，七月风骚骚。渭川烟景晚，骊山宫殿高。丹殿子司谏，赤县我徒劳。相去半日程，不得同游遨。到官来十日，览镜生二毛。可怜趋走吏，尘土满青袍。邮传拥两驿，簿书堆六曹。为问纲纪掾，何必使铅刀。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18389, 15, 85234, '585d1059570c350069318afc', '奉和骊山高顶寓目应制', NULL, '李峤', '唐', '步辇陟山巅，山高入紫烟。忠臣还捧日，圣后欲扪天。迥识平陵树，低看华岳莲。帝乡应不远，空见白云悬。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18390, 16, 95818, '585d1bd2128fe1006de650e4', '逢杨开府', NULL, '韦应物', '唐', '少事武皇帝，无赖恃恩私。身作里中横，家藏亡命儿。朝持樗蒲局，暮窃东邻姬。司隶不敢捕，立在白玉墀。骊山风雪夜，长杨羽猎时。一字都不识，饮酒肆顽痴。武皇升仙去，憔悴被人欺。读书事已晚，把笔学题诗。两府始收迹，南宫谬见推。非才果不容，出守抚茕嫠。忽逢杨开府，论旧涕俱垂。坐客何由识，惟有故人知。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18391, 17, 102589, '585d244b1b69e6006ccb65a9', '奉酬韦祭酒偶游龙门北溪忽怀骊山别业因以言志示弟淑并呈诸大僚之作', NULL, '崔日知', '唐', '夙龄秉微尚，中年忽有邻。以兹山水癖，遂得狎通人。迨我咸京道，闻君别业新。岩前窥石镜，河畔踏芳茵。既怜伊浦绿，复忆灞池春。连词谢家子，同欢冀野宾。趣闲鱼共乐，情洽鸟来驯。讵念昔游者，祇命独留秦。萧条颖阳恋，冲漠汉阴真。无由陪胜躅，空此玩书筠。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18392, 18, 146411, '585d59461b69e600561223df', '次李商隐无题韵四首', NULL, '江源', '明', '曾向骊山访旧踪，朝元芜没不闻钟。请看学道人何在，始信刀圭味不浓。玉宇春风回病草，丹台秋月照芙蓉。从今悟此长生术，休上蓬莱第一重。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18393, 19, 183214, '585d847661ff4b0058103af5', '骊山除夕对雪呈卢明府二首', NULL, '林大春', '明', '马首西入秦，骊山东向人。腊残惊旅鬓，日晚倦风尘。古殿连云尽，温泉带雪新。长安兹不远，明发汉家春。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18394, 20, 360820, '585e93ec128fe10069d5d14d', '百宜娇十姊妹花', NULL, '易顺鼎', '清', '绿股分钗，素肌同帐，蛎粉墙阴无数。', 'ci', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18395, 21, 344693, '585e75001b69e6006cd36aa7', '雒阳行', NULL, '吴伟业', '清', '诏书早洗雒阳尘，叔父如王有几人。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18396, 22, 370756, '585ea4ef61ff4b0063faee32', '华清泉歌', NULL, '唐仲冕', '清', '灵湫百丈阴火煮，浸玉跳珠互吞吐。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18397, 23, 500946, '585fbcebb123db0065b74c97', '题鲁山温泉', NULL, '晁冲之', '宋', '平生耳熟闻骊山，梦寐不到临潼关。', 'shi', 453, '骊山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18402, 1, 521329, '585feb2361ff4b006ce3e66c', '梨花', NULL, '高似孙', '宋', '殿头催引上清华，独奏春词喝赐茶。带月归来仙骨冷，梦魂全不到梨花。', 'shi', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18403, 2, 11696, '57b3b54c2e958a005621bb14', '东栏梨花', NULL, '苏轼', '宋', '梨花淡白柳深青，柳絮飞时花满城。', 'shi', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18404, 3, 10661, '57b99d77a633bd0061a0167b', '春怨', NULL, '刘方平', '唐', '纱窗日落渐黄昏，金屋无人见泪痕。', 'shi', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18405, 4, 48156, '585ced6761ff4b00580c6264', '梨花', NULL, '陆文圭', '元', '粉香初试晓妆匀，花貌参差是玉真。茅屋诗人嗟老去，东风勿送一枝春。', 'shi', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18406, 5, 225885, '585dba3361ff4b005810c62c', '月照梨花 · 梨花', NULL, '高濂', '明', '翠袖撩人，玉容无语。', 'ci', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18407, 6, 18363, '585cc9d961ff4b00688d5ebf', '梨花', NULL, '方回', '元', '仙姿白雪帔青霞，月淡春浓意不邪。天上嫦娥人未识，料应清雅似梨花。', 'shi', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18408, 7, 633546, '583805860ce463006b91635f', '无俗念 · 灵虚宫梨花词', NULL, '丘处机', '元', '春游浩荡，是年年、寒食梨花时节。', 'ci', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18409, 8, 383805, '585ebabf128fe1006df07c43', '疏影 · 梨花', NULL, '陈方恪', '清', '轻盈素靥。', 'ci', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18410, 9, 353947, '585e8727128fe1006def4e8a', '巫山一段云 · 梨花', NULL, '沈栗', '清', '腻粉匀梅白，凝脂分杏红。', 'ci', 458, '梨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18814, 9, 362370, '585e969b1b69e6005619b353', '谷雨', NULL, '林以宁', '清', '镜台流影射窗纱，风到檐前柳脚斜。竹架整书除脉望，春池洗砚乱蘋花。桑浓蚕子犹悬箔，日暖蜂干早放衙。童子佩壶寻涧水，涤瓯明日试新茶。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18815, 10, 139456, '585d51f28d6d810065df0a61', '谷雨', NULL, '方太古', '明', '春事阑珊酒病瘳，山家谷雨早茶收。花前细细风双蝶，林外时时雨一鸠。碧海丹丘无鹤驾，绿蓑青笠有渔舟。尘埃漫笑浮生梦，岘首于今薄试游。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18816, 11, 362371, '585e969c1b69e6006cd47c5b', '谷雨', NULL, '林以宁', '清', '草草深闺度岁华，生平不解问桑麻。沿篱野豆初牵蔓，绕砌山桃半欲花。细雨渍成杨柳色，暖风催放牡丹芽。村姬结束新螺髻，傍晓比邻唤采茶。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18817, 12, 439311, '585f25b761ff4b0058194113', '谷雨', NULL, '朱槔', '宋', '大点纷林际，虚檐写梦中。明朝知谷雨，无策禁花风。石渚收机巧，烟蓑建事功。越禽牢闭口，吾道寄天公。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18819, 13, 343002, '585e71f3128fe1006dee9983', '谷雨前一日小室闲吟', NULL, '朱中楣', '清', '小苑焚香逗绿纱，摊书随意注《南华》。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18821, 14, 73624, '585d045b1b69e6006cca57f2', '咏廿四气诗 · 谷雨三月中', NULL, '元稹', '唐', '谷雨春光晓，山川黛色青。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18823, 15, 424865, '585f04f31b69e6006cd5cf49', '题试茶图', NULL, '严虞惇', '清', '谷雨新晴采露芽，清泉活火试瓯华。十年樱笋江南梦，最爱苕溪隐士家。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18825, 16, 557396, '58603b898d6d810065ef4f71', '会稽绝句三首', NULL, '曾巩', '宋', '年年谷雨愁春晚，况是江湖两鬓华。欲载一樽乘兴去，不知何处有残花。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (18892, 17, 610725, '5860c190570c35006946b2d3', '鼓腹无所思朝起暮归眠渊明诗也以诗定韵为十诗', NULL, '滕岑', '宋', '立夏少半月，谷雨是今朝。梅子酸著齿，麦穗长半腰。天运不暂停，又将转斗杓。无复冬裘御，重取夏扇摇。', 'shi', 54, '谷雨', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19371, 8, 170405, '585d74a78d6d810065df83f6', '立夏日', NULL, '贝琼', '明', '江寒雨急仍北风，扣户喜闻南巷翁。锦城鲊送蒲茅白，玉碗酒泻桃花红。三月忽惊春似客，百年那得老还童。一双黄鹂寂无语，飞过小月高楼东。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19372, 9, 243922, '585dd3001b69e6005613b3b6', '立夏', NULL, '符锡', '明', '春光留不住，属目又朱明。雨长悬岩树，风喧接叶莺。市邻朝伐鼓，童释夜吹笙。转觉乡心碎，归帆几日程。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19561, 10, 376220, '585eae07da2f6000658e5757', '玉蝴蝶 · 立夏', NULL, '庄盘珠', '清', '唤起眉间幽恨，一帘芳草。', 'ci', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19562, 11, 379052, '585eb2de8d6d810065e75535', '天仙子 · 立夏', NULL, '陈世祥', '清', '酒恶更嗔花气袅。', 'ci', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19563, 12, 454296, '585f54edac502e00672f4118', '立夏日纳凉', NULL, '李光', '宋', '茅庵西畔小池东，乌鹊藏身柳影中。沙岸山坡无野店，不知此处有清风。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19564, 13, 237483, '585dca4661ff4b0063f46e4c', '阮郎归 · 立夏', NULL, '张大烈', '明', '绿阴铺野换新光，薰风初昼长。', 'ci', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19565, 14, 403250, '585edccd570c3500693c5e8c', '隔帘听 · 立夏日雨', NULL, '邹祗谟', '清', '何事欺花赚柳，恨煞春难住。', 'ci', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19566, 15, 168542, '585d7233ac502e006724c20c', '立夏后晴游我庄', NULL, '李梦阳', '明', '郊出不知昨夜雨，日高烟翠湿空林。杨花欲尽村村雪，梅子先传树树金。笑向市城开俗眼，喜从园野见吾心。绕亭溪啻千千竹，夏日黄鹂更好音。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19567, 16, 371842, '585ea6ae1b69e600561a1b86', '孟夏朔日立夏作', NULL, '徐坊', '清', '九日春光齐掣电，小园狼藉风花乱。不知今夕是何年，晓钟声动空凄恋。山中无历无春秋，节序惊心暗中换。莽莽都成夏木阴，啾啾已异春禽啭。送春归去发春愁，痛惜馀春泪凝霰。写忧我欲泛舟行，沿溪不见桃花片。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19568, 17, 573098, '58605f5961ff4b0068a24ec4', '初夏即事十二解', NULL, '杨万里', '宋', '从教节序暗相催，历日尘生懒看来。却是石榴知立夏，年年此日一花开。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19569, 18, 586296, '58608397ac502e006735a62e', '立夏', NULL, '赵友直', '宋', '四时天气促相催，一夜薰风带暑来。陇亩日长蒸翠麦，园林雨过熟黄梅。莺啼春去愁千缕，蝶恋花残恨几回。睡起南窗情思倦，闲看槐荫满亭台。', 'shi', 55, '立夏', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19570, 27, 420752, '585efd5b61ff4b00689a9d09', '晴兰', NULL, '缪公恩', '清', '谷风吹野养花天，九畹幽丛散暖烟。仙蕊露干香远馥，向阳几叶影翩翩。', 'shi', 414, '兰', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19571, 23, 474452, '585f7f2e61ff4b006ce0c1c2', '章台柳', NULL, '周密', '宋', '章华台外千株柳，翠影如云照碧天。霜叶露条应剪尽，可怜愁杀树头蝉。', 'shi', 416, '柳', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19572, 81, 10400, '57b8c73fdf0eea006333fc9b', '临江仙 · 夜登小阁，忆洛中旧游', NULL, '陈与义', '宋', '忆昔午桥桥上饮，坐中多是豪英。', 'ci', 90, '初中古诗词', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19573, 17, 483591, '585f92a461ff4b0063ff9e27', '杏花天 · 豫章重午', NULL, '侯寘', '宋', '宝钗整鬓双鸾斗。', 'ci', 73, '端午', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19574, 18, 68429, '585cffaeda2f600065837d5f', '浪淘沙令', NULL, '韩奕', '元', '细雨折红榴。', 'ci', 73, '端午', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19602, 7, 231498, '585dc211ac502e0067259e8b', '夏至', NULL, '梁以壮', '明', '夏至年来倍寂寥，新愁旧恨积难消。鹿茸初长眠红藓，人梦犹恬倚绿蕉。无定阴晴天昼永，有厓生寄世尘嚣。卜云五月能通达，一姤佳期始此朝。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19603, 8, 413829, '585eefd5128fe1006bac88e6', '夏至', NULL, '郑孝胥', '清', '手书日记罢趋衙，便觉闲廊足岁华。十日雨晴喧曙雀，半庭绿暗长秋花。故人频问诗情好，新局微闻国论哗。拂拭书窗入长夏，试评沉李与浮瓜。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19604, 9, 260704, '585deb57128fe1006ba61bea', '夏至斋居', NULL, '黄佐', '明', '桥门日日听鸣驺，长夏斋居亦似秋。雨歇风篁依砌舞，夜凉云汉入窗流。咸英乐自周家变，江海心从魏阙游。隐几梦回天咫尺，六龙飞处是方丘。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19605, 10, 220654, '585db322b123db0065aa736e', '夏至夜即事', NULL, '陈恭尹', '明', '初晴天气便炎蒸，小阁风多最上层。腊酒旧藏椎髻妇，春茶新惠住山僧。频探落月移湘簟，自惜流萤掩夜灯。一岁算来今夕短，老夫犹为几回兴。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19606, 11, 255709, '585de3deb123db0065ab93d5', '夏至矩洲书事', NULL, '黄衷', '明', '西林朱景初迎至，结夏清禅亦未过。红糁落花三径雨，绿翻荣稼一川波。将雏燕舞晴偏媚，求友莺声晚更和。贷粟溪农休涕泪，寰中乐事本无多。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19607, 12, 519512, '585fe75361ff4b006ce3cec6', '夏至日与太学', NULL, '陈与义', '宋', '微官有阀阅，三赋池上诗。林密知夏深，仰看天离离。官忙负远兴，觞至及良时。荷气夜来雨，百鸟清昼迟。微风不动蘋，坐看水色移。门前争夺场，取欢不偿悲。欲归未得去，日暮多黄鹂。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19608, 13, 211734, '585da74d128fe1006de8f33e', '夏至日喜雨漫吟', NULL, '郭之奇', '明', '昨夜天河浪几掀，朝来玉女倾洗盆。云生石路离离黑，雾压峰头冉冉惛。采芜怨女持筐返，徂隰悲农绕树喧。解颜相劝逢耕侣，不惮泥濡探水痕。欢呼远入幽人耳，萝薜萧森气染门。虽无尺地沾时泽，亦许苍凉出废园。我有馀心寄碧蒹，未秋得露倚流翻。因兹偶际天地解，遇雨之吉岂徒言。', 'shi', 58, '夏至', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19609, 45, 577637, '58606b018d6d810065efdf0b', '品令 · 茶词', NULL, '黄庭坚', '宋', '凤舞团团饼。', 'ci', 46, '茶', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19610, 19, 633643, '584699c861ff4b006ba86b35', '鹧鸪天 · 赏荷', NULL, '蔡松年', '金', '秀樾横塘十里香，水花晚色静年芳。', 'ci', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19611, 20, 10940, '57b9c1e21532bc00656cea2f', '绿意/疏影 · 咏荷叶', NULL, '张炎', '宋', '碧圆自洁，向浅洲远渚，亭亭清绝。', 'ci', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19612, 21, 11602, '57b99f7cc4c971006146b1d5', '衰荷', NULL, '白居易', '唐', '白露凋花花不残，凉风吹叶叶初干。', 'shi', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19613, 22, 11380, '57b90f31d342d3005ac79d94', '赠荷花', NULL, '李商隐', '唐', '世间花叶不相伦，花入金盆叶作尘。', 'shi', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19614, 23, 630671, '5860ff3d128fe10069e33c43', '荷华媚 · 荷花', NULL, '苏轼', '宋', '霞苞电荷碧。', 'ci', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19615, 24, 593220, '58609351128fe1006df9eb17', '洞仙歌 · 荷花', NULL, '刘光祖', '宋', '晚风收暑，小池塘荷净。', 'ci', 33, '荷', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19616, 46, 633445, '58294ee7d203090054ffdbca', '满庭芳 · 咏茶', NULL, '米芾', '宋', '雅燕飞觞，清谈挥麈，使君高会群贤。', 'ci', 46, '茶', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19617, 15, 10750, '57ba070fc4c971006149fc03', '凤箫吟 · 锁离愁', NULL, '韩缜', '宋', '锁离愁、连绵无际，来时陌上初熏，绣帏人念远，暗垂珠露，泣送征轮。', 'ci', 418, '草', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19618, 17, 638672, '5b7a8ef1fb4ffe0058b45c25', '此君轩记', NULL, '王国维', '清', '竹之为物，草木中之有特操者与？', 'wen', 383, '竹', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19619, 18, 12010, '580c3f8ebf22ec005828dc10', '於潜僧绿筠轩', NULL, '苏轼', '宋', '宁可食无肉，不可居无竹。', 'shi', 383, '竹', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19620, 19, 11585, '57b9fb698ac247006300e5a0', '大暑竹下独酌', NULL, '郑刚中', '宋', '新竹日以密，竹叶日以繁。', 'shi', 383, '竹', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19621, 20, 633547, '5838395a61ff4b006b44a3d1', '无俗念 · 竹', NULL, '丘处机', '元', '虚心翠竹，禀天然、一气生来清独。', 'ci', 383, '竹', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19622, 26, 578163, '58606c4d1b69e6005622f3fd', '人月圆 · 月华灯影光相射', NULL, '扬无咎', '宋', '月华灯影光相射。', 'ci', 17, '元宵', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19623, 4, 638353, '5b505cb467f356003546e41d', '立秋', NULL, '释道璨', '宋', '碧树萧萧凉气回，一年怀抱此时开。', 'shi', 61, '立秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19624, 5, 17880, '585cc92c1b69e6006cc8886e', '立秋', NULL, '方回', '元', '暑赦如闻降德音，一凉欢喜万人心。', 'shi', 61, '立秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (19625, 6, 399696, '585ed69b61ff4b0058183a98', '立秋', NULL, '惠远谟', '清', '草木欲摇落，翛然天地清。林塘消暑气，砧杵动秋声。叶不因风堕，虫知应节鸣。晚凉庭院静，新月傍檐明。', 'shi', 61, '立秋', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31677, 29, 11772, '57de9009d203090069e7efd8', '山中杂诗', NULL, '吴均', '南北朝', '山际见来烟，竹中窥落日。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31678, 30, 652868, '5f2d7681ea0d8d00089dbb94', '初入山作诗', NULL, '桓法闿', '南北朝', '寒谷夜将晨，置赏复寻真。方坛垂密叶，澈水渡朱鳞。杏林虽伏兽，芝田讵俟人。丹成方转石，炉变欲销银。当知胜地远，于此绝嚣尘。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31679, 31, 652900, '5f2d768694d48b0006b4354e', '从驾游山诗', NULL, '袁奭', '南北朝', '天游响仙跸，春望动神衷。涧水含初溜，山花发早丛。玉舆明淑景，珠旗转瑞风。平原与上路，佳气远葱葱。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31680, 32, 653339, '5f2d76b966beda0006d4ba66', '和宇文内史春日游山诗', NULL, '庾信', '南北朝', '游客值春辉，金鞍上翠微。风逆花迎面，山深云湿衣。雁持一足倚，猿将两臂飞。戍楼侵岭路，山村落猎围。道士封君达，仙人丁令威。煮丹于此地，居然未肯归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31681, 33, 653341, '5f2d76b935432a00065b25dd', '游山诗', NULL, '庾信', '南北朝', '聊登玄圃殿，更上增城山。不知高几里，低头看世间。唱歌云欲聚，弹琴鹤欲舞。涧底百重花，山根一片雨。婉婉藤倒垂，亭亭松直竖。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31682, 34, 657297, '5f2d788bcd056c00089eedc4', '咏山诗三首 其三', NULL, '释惠标', '南北朝', '丹霞拂层阁，碧水泛蓬莱。鳌岫含烟耸，莲崖照日开。松门夹细叶，石磴染新苔。能令平子见，淹留未肯回。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31683, 35, 12783, '585cc31961ff4b006cd01904', '赋得岩穴无结构诗', NULL, '王申礼', '隋', '岩间无结构，谷处极幽寻。叶落秋巢迥，云生石路深。早梅香野径，清涧响丘琴。独有栖迟客，留连芳杜心。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31684, 36, 13245, '585cc3adac502e00671fcfa2', '咏山', NULL, '刘斌', '隋', '灵山峙千仞，蔽日且嵯峨。紫盖云阴远，香炉烟气多。石梁高鸟路，瀑水近天河。欲知闻道里，别自有仙歌。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31685, 37, 13213, '58b778a2a22b9d005eccf86b', '还山宅', NULL, '杨师道', '隋', '暮春还旧岭，徙倚玩年华。芳草无行径，空山正落花。垂藤扫幽石，卧柳碍浮槎。鸟散茅檐静，云披涧户斜。依然此泉路，犹是昔烟霞。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31686, 38, 72892, '585d0398128fe1006de5897d', '春山夜月', NULL, '于良史', '唐', '春山多胜事，赏玩夜忘归。掬水月在手，弄花香满衣。兴来无远近，欲去惜芳菲。南望鸣钟处，楼台深翠微。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31687, 39, 100054, '585d212b128fe1006de67fdc', '早发故山作', NULL, '马戴', '唐', '云门夹峭石，石路荫长松。谷响猿相应，山深水复重。餐霞人不见，采药客犹逢。独宿灵潭侧，时闻岳顶钟。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31688, 40, 669423, '5f2d7dfeea0d8d00089dd667', '山行偶作', NULL, '马戴', '唐', '缘危路忽穷，投宿值樵翁。鸟下山含暝，蝉鸣露滴空。石门斜月入，云窦暗泉通。寂寞生幽思，心疑旧隐同。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31689, 41, 100169, '585d2147b123db0065a7d831', '山中作', NULL, '马戴', '唐', '屐齿无泥竹策轻，莓苔梯滑夜难行。独开石室松门里，月照前山空水声。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31690, 42, 74581, '585d053b61ff4b00688f2baf', '山中', NULL, '方干', '唐', '散拙亦自遂，粗将猿鸟同。飞泉高泻月，独树迥含风。果落盘盂上，云生箧笥中。未甘明圣日，终作钓渔翁。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31691, 43, 74658, '585d05501b69e6006cca5f93', '山中言事', NULL, '方干', '唐', '日与村家事渐同，烧松啜茗学邻翁。池塘月撼芙蕖浪，窗户凉生薜荔风。书幌昼昏岚气里，巢枝俯折雪声中。山阴钓叟无知己，窥镜挦多鬓欲空。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31692, 44, 95775, '585d1bc6570c35006931ee41', '送丘员外还山', NULL, '韦应物', '唐', '长栖白云表，暂访高斋宿。还辞郡邑喧，归泛松江渌。结茅隐苍岭，伐薪响深谷。同是山中人，不知往来躅。灵芝非庭草，辽鹤委池鹜。终当署里门，一表高阳族。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31693, 45, 106719, '585d2a71128fe1006ba27a79', '山中作', NULL, '冯道之', '唐', '草堂在岩下，卜居聊自适。桂气满阶庭，松阴生枕席。远瞻惟鸟度，旁信无人迹。霭霭云生峰，潺潺水流石。颇寻黄卷理，庶就丹砂益。此即契吾生，何为苦尘役。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31694, 46, 113234, '585d3372ac502e006723671a', '喜逢郑三游山', NULL, '卢仝', '唐', '相逢之处花茸茸，石壁攒峰千万重。他日期君何处好，寒流石上一株松。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31695, 47, 113742, '585d34338d6d810065de25af', '送吉中孚校书归楚州旧山', NULL, '卢纶', '唐', '青袍芸阁郎，谈笑挹侯王。旧箓藏云穴，新诗满帝乡。名高闲不得，到处人争识。谁知冰雪颜，已杂风尘色。此去复如何，东皋岐路多。藉芳临紫陌，回首忆沧波。年来倦萧索，但说淮南乐。并楫湖上游，连樯月中泊。沿溜入阊门，千灯夜市喧。喜逢邻舍伴，遥语问乡园。下淮风自急，树杪分郊邑。送客随岸行，离人出帆立。渔村绕水田，澹澹隔晴烟。欲就林中醉，先期石上眠。林昏天未曙，但向云边去。暗入无路山，心知有花处。登高日转明，下望见春城。洞里草空长，冢边人自耕。寥寥行异境，过尽千峰影。露色凝古坛，泉声落寒井。仙成不可期，多别自堪悲。为问桃源客，何人见乱时。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31696, 48, 660361, '5f2d79e6d14faa000835a1b3', '春山', NULL, '司空图', '唐', '可是武陵溪，春芳著路迷。花明催曙早，云腻惹空低。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31697, 49, 79015, '585d09be570c350069315723', '山下宿', NULL, '白居易', '唐', '独到山下宿，静向月中行。何处水边碓，夜舂云母声。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31698, 50, 80184, '585d0b12b123db0065a71a89', '出山吟', NULL, '白居易', '唐', '朝咏游仙诗，暮歌采薇曲。卧云坐白石，山中十五宿。行随出洞水，回别缘岩竹。早晚重来游，心期瑶草绿。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31699, 51, 112418, '585d3256da2f600065853305', '寻张逸人山居', NULL, '刘长卿', '唐', '危石才通鸟道，空山更有人家。桃源定在深处，涧水浮来落花。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31700, 52, 112557, '585d328cb123db0065a87656', '移居深山谢别亲故', NULL, '刘商', '唐', '不食黄精不采薇，葛苗为带草为衣。孤云更入深山去，人绝音书雁自飞。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31701, 53, 89508, '585d14e3128fe10069cc3f46', '远山', NULL, '吴融', '唐', '隐隐隔千里，巍巍知几重。平时未能去，梦断一声钟。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31702, 54, 86559, '585d11c8da2f600065840f59', '酬故人还山', NULL, '宋鼎', '唐', '举棹乘春水，归山抚岁华。碧潭宵见月，红树晚开花。肃穆轻风度，依微隐径斜。危亭暗松石，幽涧落云霞。思鸟吟高树，游鱼戏浅沙。安知馀兴尽，相望紫烟赊。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31703, 55, 100735, '585d220561ff4b0068901edb', '山中冬夜', NULL, '张乔', '唐', '寒叶风摇尽，空林鸟宿稀。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31704, 56, 671093, '5f2d7ebeb3ef60000642e212', '山中秋 夜', NULL, '张籍', '唐', '寂寂山景静，幽人归去迟。横琴当月下，压酒及花时。冷露湿茆屋，暗泉冲竹篱。西峰采药伴，此夕恨无期。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31705, 57, 101933, '585d237461ff4b0063f1759e', '送友人归山', NULL, '张籍', '唐', '出山成北首，重去结茅庐。移石修废井，扫龛盛旧书。开田留杏树，分洞与僧居。长在幽峰里，樵人见亦疏。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31706, 58, 102044, '585d2398128fe1006ba23f4b', '送韩侍御归山', NULL, '张籍', '唐', '闻君久卧在云间，为佐嫖姚未得还。新结茅庐招隐逸，独骑骢马入深山。九灵洞口行应到，五粒松枝醉亦攀。明日珂声出城去，家僮不复扫柴关。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31707, 59, 102202, '585d23ca61ff4b00689030aa', '秋山', NULL, '张籍', '唐', '秋山无云复无风，溪头看月出深松。草堂不闭石床静，叶间坠露声重重。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31708, 60, 636754, '5ab8b4a7ee920a396f387a68', '冬日归旧山', NULL, '李白', '唐', '未洗染尘缨，归来芳草平。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31709, 61, 89019, '585d1452da2f600065842631', '落日忆山中', NULL, '李白', '唐', '雨后烟景绿，晴天散馀霞。东风随春归，发我枝上花。花落时欲暮，见此令人嗟。愿游名山去，学道飞丹砂。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31710, 62, 662533, '5f2d7ae135432a00065b340a', '天津桥南山中各题一句', NULL, '李益', '唐', '野坐分苔席，山行绕菊丛。云衣惹不破，秋色望来空。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31711, 63, 81976, '585d0ce7b123db0065a72807', '寻山', NULL, '李频', '唐', '一径入双崖，初疑有几家。行穷人不见，坐久日空斜。石上生灵草，泉中落异花。终须结茅屋，向此学餐霞。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31712, 64, 668965, '5f2d7dc8e416aa0006a807a4', '小江驿送陆侍御归湖上山', NULL, '陈羽', '唐', '鹤唳天边秋水空，荻花芦叶起西风。今夜渡江何处宿，会稽山在月明中。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31713, 65, 105258, '585d27e6128fe10069cce925', '春山行', NULL, '贯休', '唐', '重叠太古色，蒙蒙花雨时。好峰行恐尽，流水语相随。黑壤生红黍，黄猿领白儿。因思石桥月，曾与故人期。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31714, 66, 93730, '585d1961128fe10069cc6549', '山中即事', NULL, '郎士元', '唐', '入谷多春兴，乘舟棹碧浔。山云昨夜雨，溪水晓来深。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31715, 67, 94042, '585d19c51b69e6006ccb05af', '秋夕遣怀', NULL, '姚合', '唐', '昨宵白露下，秋气满山城。风劲衣巾脆，窗虚笔墨轻。临书爱真迹，避酒怕狂名。只拟随麋鹿，悠悠过一生。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31716, 68, 94798, '585d1ab21b69e6006ccb0dc2', '山中五咏远山', NULL, '皇甫冉', '唐', '少室尽西峰，鸣皋隐南面。柴门纵复关，终日窗中见。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31717, 69, 94929, '585d1aca128fe1006ba1eeb0', '问李二司直所居云山', NULL, '皇甫冉', '唐', '门外水流何处，天边树绕谁家。山色东西多少，朝朝几度云遮。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31718, 70, 636489, '5aaf580c9f545417b4ccf1c8', '长安月夜与友人话故山', NULL, '赵嘏', '唐', '宅边秋水浸苔矶，日日持竿去不归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31719, 71, 106605, '585d2a4e8d6d810065ddc8a9', '山行', NULL, '项斯', '唐', '青枥林深亦有人，一渠流水数家分。山当日午回峰影，草带泥痕过鹿群。蒸茗气从茅舍出，缫丝声隔竹篱闻。行逢卖药归来客，不惜相随入岛云。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31720, 72, 114458, '585d35328d6d810065de2fc4', '春晚从李长史游开道林故山', NULL, '骆宾王', '唐', '幽寻极幽壑，春望陟春台。云光栖断树，灵影入仙杯。古藤依格上，野径约山隈。落蕊翻风去，流莺满树来。兴阑荀御动，归路起浮埃。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31721, 73, 97958, '585d1ebf8d6d810065dd5f75', '春晚山行', NULL, '殷遥', '唐', '寂历青山晚，山行趣不稀。野花成子落，江燕引雏飞。暗草薰苔径，晴杨扫石矶。俗人犹语此，余亦转忘归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31722, 74, 97991, '585d1ec861ff4b006cd2f9d3', '山中赠诸暨丹丘明府', NULL, '秦系', '唐', '荷衣半破带莓苔，笑向陶潜酒瓮开。纵醉远须上山去，白云那肯下山来。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31723, 75, 114743, '585d3599570c35006932dbff', '岁初归旧山', NULL, '钱起', '唐', '欲知愚谷好，久别与春还。莺暖初归树，云晴却恋山。石田耕种少，野客性情闲。求仲应难见，残阳且掩关。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31724, 76, 114885, '585d35cbb123db0065a8945b', '蓝田溪杂咏二十二首窗里山', NULL, '钱起', '唐', '远岫见如近，千里一窗里。坐来石上云，乍谓壶中起。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31725, 77, 99368, '585d2057da2f60006584910a', '秋山夕兴', NULL, '陶翰', '唐', '山月松筱下，月明山景鲜。聊为高秋酌，复此清夜弦。晤语方获志，栖心亦弥年。尚言兴未逸，更理逍遥篇。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31726, 78, 677803, '5f2d81c066beda0006d4df3c', '山中', NULL, '顾况', '唐', '野人爱向山中宿，况在葛洪丹井西。庭前有个长松树，夜半子规来上啼。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31727, 79, 104061, '585d26498d6d810065dda503', '山中', NULL, '曹松', '唐', '此地似商岭，云霞空往还。衰条难定鸟，缺月易依山。野色耕不尽，溪容钓自闲。分因多卧退，百计少相关。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31728, 80, 106979, '585d2aa8570c350069327631', '游山', NULL, '黄滔', '唐', '洞门穿瀑布，尘世岂能通。曾有游山客，来逢采药翁。异花寻复失，幽径蹑还穷。拟作经宵计，风雷立满空。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31729, 81, 116536, '585d37a961ff4b006cd3ddad', '宿石邑山中', NULL, '韩翃', '唐', '浮云不共此山齐，山霭苍苍望转迷。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31730, 82, 108773, '585d2d2061ff4b0063f1ccdb', '奉和夏日游山应制', NULL, '蔡文恭', '唐', '首夏林壑清，薄暮烟霞上。连岩耸百仞，绝壑临千丈。照灼晚花鲜，潺湲夕流声。悠然动睿思，息驾寻真赏。掞彼涡川作，怀兹洛滨想。窃吹等齐竽，何用承恩奖。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31731, 83, 109357, '585d2df7128fe1006de6f514', '前山', NULL, '裴夷直', '唐', '只谓一苍翠，不知犹数重。晚来云映处，更见两三峰。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31732, 84, 114018, '585d34928d6d810065de2991', '秋夜山中述事', NULL, '薛能', '唐', '初宵门未掩，独坐对霜空。极目故乡月，满溪寒草风。樵声当岭上，僧语在云中。正恨归期晚，萧萧闻塞鸿。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31733, 85, 676119, '5f2d80fc9ddf340006a6a9ef', '山行', NULL, '戴叔伦', '唐', '山行分曙色，一路见人稀。野鸟啼还歇，林花堕不飞。云迷栖鹤寺，水涩钓鱼矶。回首天将暝，逢僧话未归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31734, 86, 315517, '585e41e161ff4b0063f7f7b5', '入山三首其二', NULL, '孔武仲', '宋', '路出西林兴倍长，轻衫短盖入秋阳。层崖蔽日多清影，深谷迷人有异香。访古不辞穿绝磴，参禅直为遍诸方。此身似是辽东鹤，偶逐飞云到故乡。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31735, 87, 680128, '5f2d82cd94d48b0006b46147', '入山三首 其一', NULL, '孔武仲', '宋', '冠盖成阴中路回，独携莲社道人来。千岩万壑初相识，分付晴岚面面开。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31736, 88, 680531, '5f2d82fbfeb03800067b6cd9', '山中新晴', NULL, '文同', '宋', '山中新晴晓烟暖，散带颓冠漱岩畔。海盐未去猿鹤喜，柴桑初归松菊乱。林间馀雨时一滴，岭上飞云忽双断。安能举手恣扶摇，欲共高鸿拂霄汉。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31737, 89, 313717, '585e3ede61ff4b0058148e83', '山行', NULL, '方岳', '宋', '亦爱卢仝屋数间，野猿皋鹤共跻攀。才登楼见一溪月，不出门行十里山。有兴自携残稿醉，无人得似老夫闲。樵青莫掩柴扉路，留与春风作往还。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31738, 90, 313800, '585e3f08128fe1006ba8b268', '山行', NULL, '方岳', '宋', '岁晚谁同涧谷盘，一牛呼犊野烟寒。村如有雪荞花白，山未着霜桐叶丹。是处丰登茅店酒，老夫闲散竹皮冠。醉归更草郊居赋，传与诗人作画看。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31739, 91, 605142, '5860b3b2128fe1006bb64e37', '宿山中十首', NULL, '刘克庄', '宋', '就泉为碓屋，累石作书龛。有意耕汾曲，无心起水南。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31740, 92, 437946, '585f21ce128fe1006df1add6', '雪消溪涨山色尤可喜口占', NULL, '朱熹', '宋', '头上琼冈出旧青，马边流水涨寒汀。若为留得晶莹住，突兀长看素锦屏。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31741, 93, 437948, '585f21cf1b69e6006cd661e6', '登山有作次敬夫韵', NULL, '朱熹', '宋', '晚峰云散碧千寻，落日冲飙霜气深。霁色登临寒夜月，行藏只此验天心。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31742, 94, 526735, '585ff88361ff4b00630280d9', '山行', NULL, '陆游', '宋', '闲人日日得闲行，况值今朝小雨晴。水浅游鱼浑可数，山深药草半无名。临溪旋唤罾船渡，过寺初闻浴鼓声。小醉未应风味减，满盘青杏伴朱樱。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31743, 95, 519257, '585fe6de128fe10069dd7ee7', '出山二首', NULL, '陈与义', '宋', '山空樵斧响，隔岭有人家。日落潭照树，川明风动花。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31744, 96, 519258, '585fe6df61ff4b0063021c77', '入山二首', NULL, '陈与义', '宋', '出山复入山，路随溪水转。东风不惜花，一暮都开遍。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31745, 97, 519259, '585fe6e0570c35006942f25c', '入山二首', NULL, '陈与义', '宋', '都迷去时景，策杖烟漫漫。微雨洗春色，诸峰生晚寒。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31746, 98, 503987, '585fc41e61ff4b00581dc61e', '晓行山间', NULL, '真山民', '宋', '出门谁是伴，只约瘦藤行。一二里山径，两三声晓莺。乱峰相出没，初日乍阴晴。僧舍在何许，隔林钟磬清。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31747, 99, 504047, '585fc43aac502e0067327bd8', '山行', NULL, '真山民', '宋', '林梢初日弄阴晴，露浥溪花笑欲迎。涧暗只闻泉滴沥，山青剩见鹭分明。远峰忽转还如绕，险径徐行亦似平。莫谓诗成无与和，风篁也解作吟声。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31748, 100, 505746, '585fc7f48d6d810065ed5b3b', '山中', NULL, '翁卷', '宋', '山中凡事幸相宜，第一红尘免上衣。寻药每同丹客去，拾薪多趁牧儿归。鸣泉漱石寒蒲洁，宿雾蒸泥早蕨肥。不奈邻峰学禅伴，时时来此叩岩扉。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31749, 101, 587968, '586086d3b123db0065bad38e', '山中留客 / 山行留客', NULL, '张旭', '唐', '山光物态弄春晖，莫为轻阴便拟归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31750, 102, 587975, '586086d8128fe1006bb522a3', '段家堤西望晚山', NULL, '蔡襄', '宋', '月下西山千万重，日光山气郁葱笼。鲛绡数幅须移得，惆怅如今无画工。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31751, 103, 614247, '5860ca01da2f600065996c34', '山中即目二首', NULL, '戴复古', '宋', '岩路穿黄落，人家隐翠微。笼鸡为鸭抱，网犬逐鹑飞。竹好堪延客，溪清欲浣衣。禅扉在何许，僧笠戴云归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31752, 104, 761733, '5f2da8aaea0d8d00089e3151', '山行', NULL, '戴复古', '宋', '度岭休骑马，临渊看网鱼。木根高可坐，岩石细堪书。谷鸟鸣相答，山云卷复舒。儒衣人卖酒，疑是马相如。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31753, 105, 615792, '5860cde761ff4b0063064106', '秋日过屏山庵', NULL, '戴炳', '宋', '凄切抱叶蝉，间关栖树禽。入山本避喧，复爱聆此音。微飔动夕爽，薄云散秋阴。众籁阒以静，片月生东林。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31754, 106, 566940, '58604fe4ac502e006734b742', '山中', NULL, '黄庚', '宋', '万壑松声撼翠微，夜寒风露湿人衣。山翁踏月巡幽径，竹里笼开鹤未归。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31755, 107, 824020, '5f2e1981ea0d8d00089f5c6b', '山中', NULL, '马天来', '金', '青林寂寂鸟关关，画出风烟落照间。脱却草鞋临水坐，野云分我一边闲。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31756, 108, 820473, '5f2e17de166d7f000815d916', '山居杂诗六首 其三', NULL, '元好问', '金', '树合秋声满，村荒暮景闲。虹收仍白雨，云动忽青山。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31757, 109, 20342, '585ccc6bda2f60006581eaa7', '山居晚兴', NULL, '尹廷高', '元', '高住青峰不计层，闭门危坐绝交朋。竹声欲断微闻雨，村色初昏远见灯。宿鸟并枝闲寂寂，归云度壑慢腾腾。邻翁笑我生涯拙，纸帐梅花绝类僧。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31758, 110, 856270, '5f2e282fe416aa0006a9de68', '下山', NULL, '刘因', '元', '翠霞腾晕紫成堆，收尽云烟酒一杯。想见浮岚在眉宇，人人知道看山回。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31759, 111, 56138, '585cf48ada2f60006583282a', '圭塘杂咏柳下听莺', NULL, '许有孚', '元', '晚晴台上看巉岩，万壑千峰起翠岚。恰似云间招五老，今宵有梦定江南。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31760, 112, 29115, '585cd7d761ff4b00688dbe79', '山中', NULL, '宋无', '元', '半岭松声樵客分，一溪春草鹿成群。采芝人入翠微去，丹灶石坛空白云。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31761, 113, 51170, '585ceff6128fe1006ba09561', '郊饮醉归', NULL, '张养浩', '元', '昨朝醉田间，欲借山为枕。青山不肯前，却枕白云寝。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31762, 114, 34999, '585cdf0061ff4b0063ef3c1f', '杂兴', NULL, '周权', '元', '流水数家村，青山白云坞。春晚落红深，夜寒溪上雨。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31763, 115, 66807, '585cfdd7b123db0065a6b186', '梦登高山得诗', NULL, '萨都剌', '元', '杖藜踏破碧崔嵬，梦里清游乐未回。万壑泉声松外去，数行秋色雁边来。文章小杜人何在？风雨重阳菊自开。山路云深行客倦，竹鸡飞上独春台。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31764, 116, 57675, '585cf5d561ff4b0063effc65', '山中偶题', NULL, '黄溍', '元', '古苔隐石色，寒花明药丛。有时白涧雨，终日青松风。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31765, 117, 56682, '585cf50075c4cd65cbeef048', '送人还山', NULL, '善住', '元', '偶随流水出，闲趁白云归。步石苔侵屐，攀松露滴衣。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31766, 118, 69291, '585d006a570c350069310d22', '山中景', NULL, '释英', '元', '六月山深处，松风冷袭衣。遥知城市里，扑面火尘飞。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31767, 119, 69293, '585d006a128fe10069cb985f', '山中二绝', NULL, '释英', '元', '窗前瀑布寒，林外夕阳薄。清风何处来，扑扑松花落。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31768, 120, 14347, '585cc4d061ff4b0063ee7a19', '山居诗三首呈诸道侣', NULL, '丁鹤年', '元', '日日看山眼倍明，更无一事可关情。扫开积雪岩前走，领取闲云陇上行。不共羽人谈太易，懒从衲子话无生。划然时发苏门啸，遥答风声及水声。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31769, 121, 24660, '585cd23e128fe10069ca2447', '游三洞金盆诸峰绝句二十首', NULL, '叶颙', '元', '大山严而尊，小山婉而秀。往来两山间，岩霏湿吟袖。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31770, 122, 289484, '585e179d8d6d810065e2d902', '暮归山中', NULL, '蓝仁', '明', '暮归山色昏，濯足月在涧。衡门栖鹊定，暗树流萤乱。妻孥候我至，明灯供蔬饭。伫立松桂凉，疏星隔河汉。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31771, 123, 133928, '585d4c0d61ff4b006891845c', '行山中', NULL, '王同轨', '明', '雨余林气静，山晚日光斜。野店依孤树，村桥卧断楂。马嘶遥涧水，犬吠隔篱花。白首锄云者，春风自一家。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31772, 124, 187334, '585d894e61ff4b0058104323', '江上看山', NULL, '胡宗仁', '明', '江上看山分外青，更怜山畔有云行。因之认熟桥西路，孤杖无劳藉友生。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31773, 125, 251717, '585dde74128fe10069d0379c', '送徐巢友还山', NULL, '葛一龙', '明', '吾庐在空山，户牖白云满。有树常谡谡，余花亦纂纂。城市不可居，昼夜一何短。卖药挂驴背，行歌去人远。日落深涧中，洗足春泥暖。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31774, 126, 459189, '585f600261ff4b00689cf4b6', '游云居寺三绝', NULL, '李彭', '宋', '茗碗薰炉久不来，晓猿夜鹤总相猜。故将野老扶衰杖，踏破山家称意苔。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52649, 26, 637562, '5aedac100b616030db35a38c', '相见欢 · 金陵城上西楼', NULL, '朱敦儒', '宋', '金陵城上西楼，倚清秋。', 'ci', 128, '初二上册', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31775, 127, 459193, '585f6004da2f600065916218', '解嘲', NULL, '李彭', '宋', '平生痴绝百无忧，党友相嘲顾虎头。痴黠胸中各相半，要之与我不同流。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31776, 128, 272272, '585dfcbfda2f6000658913f5', '山中作三首', NULL, '樊阜', '明', '夕景延澹阴，微曛射林屋。无营见道真，尘纷悟蕉鹿。此意几人知，沉吟俯修竹。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (31777, 129, 272273, '585dfcc08d6d810065e1f676', '山中作三首', NULL, '樊阜', '明', '西风吹雨收，竹屋云阴散。酒醒心亦清，忘言玩爻彖。老鹤划然鸣，月上青山半。', 'shi', 31, '山', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52004, 19, 10367, '57b2702d165abd005433ebd4', '定风波 · 次高左藏使君韵', NULL, '黄庭坚', '宋', '万里黔中一漏天，屋居终日似乘船。', 'ci', 22, '重阳', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52005, 20, 11251, '57b97f010a2b58005fc6aca4', '重阳席上赋白菊', NULL, '白居易', '唐', '满园花菊郁金黄，中有孤丛色似霜。', 'shi', 22, '重阳', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52006, 21, 99057, '585d20051b69e6006ccb3db6', '重阳', NULL, '高适', '唐', '节物惊心两鬓华，东篱空绕未开花。', 'shi', 22, '重阳', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52508, 19, 10916, '57b8f65c7db2a20054265836', '踏莎行', NULL, '吴文英', '宋', '润玉笼绡，檀樱倚扇，绣圈犹带脂香浅。', 'ci', 73, '端午', '', NULL, '', '', '', '');
INSERT INTO "collection_works" ("id", "show_order", "work_id", "work_remote_id", "work_title", "work_full_title", "work_author", "work_dynasty", "work_content", "work_kind", "collection_id", "collection", "work_title_tr", "work_full_title_tr", "work_author_tr", "work_dynasty_tr", "work_content_tr", "collection_tr") VALUES (52509, 22, 651176, '5f2d75bb166d7f0008143059', '衡州九日诗', NULL, '江总', '南北朝', '秋日正凄凄，茅茨复萧瑟。姬人荐初酝，幼子问残疾。园菊抱黄华，庭榴剖珠实。聊以著书情，暂遣他乡日。', 'shi', 22, '重阳', '', NULL, '', '', '', '');
